/* Automatisch erzeugt – KI-übersetzt, nicht von Hand bearbeiten. */
window.MTEC_NEWS_I18N = {"_info": {"sprache": "bg", "hinweis": "KI-übersetzt aus dem Deutschen. _src = Prüfsumme des deutschen Originals; weicht sie ab, zeigt die Website das deutsche Original (scripts/update-news.mjs check warnt)."}, "2026-11-25-gta6-softlock-kapitel-3": {"titel": "GTA 6: играчи съобщават за блокиране в глава 3, превключването от Лусия към Джейсън остава заключено, пачът 01.002.002 не помага", "schlagzeile": "GTA 6: блокиране в глава 3 спира историята – това може да помогне", "kurz": "Няколко играчи на GTA 6 са заседнали в глава 3, защото вече не могат да превключат от Лусия към Джейсън. Според Polygon бъгът се появява след мисията „Missing Persons“ и блокира историята. Пачът 01.002.002 явно не е отстранил проблема.", "zusammenfassung": "Видео на потребителя в X SirGrotti показва, че опцията за смяна на персонажа е трайно сива. Тъй като следващата част от историята изисква Джейсън, напредъкът спира. В фен сайта GTA6Bugs това блокиране е най-гледаният запис според Polygon. Като решение Polygon предлага да се зареди ръчен запис отпреди пътуването до склада в Port Gellhorn. След това трябва да се изиграе мисията „Dealer's Choice“ с Джейсън, докато превключването отново стане възможно, и да се запише в нов слот. Други играчи съобщават за успех с друга мисия на Лусия или дуо мисия, или с обаждане на Дънк. Тези съвети обаче не помагат на всички. Според статията Rockstar още не е коментирала бъга. Който е в глава 3, е добре предпазливо да записва ръчно и редовно в отделни слотове.", "_src": "f58ec164"}, "2026-11-25-ea-fc-27-motson-ki-stimme": {"titel": "EA Sports FC 27 връща починалия коментатор Джон Мотсън чрез генеративен ИИ, ъпдейт на 26 ноември", "schlagzeile": "EA Sports FC 27 връща починал коментатор с помощта на ИИ", "kurz": "EA връща в EA Sports FC 27 гласа на футболния коментатор Джон Мотсън, починал през 2023 г. За целта съчетава стари записи с генеративен ИИ, като семейството е дало съгласие. Ъпдейтът трябва да излезе на 26 ноември.", "zusammenfassung": "Джон Мотсън беше първият истински глас на коментатор в поредицата – от FIFA 96 до FIFA 2005. Според Eurogamer и BBC EA използва съществуващи записи и ги допълва с ИИ, защото няма записи за по-новите футболисти. Старшият директор по дизайна Мат Прайър каза пред BBC, че без пълното съгласие на семейството проектът не би бил осъществен. EA заявява, че е платила на семейството за правата върху гласа и образа. Синът на Мотсън, Фред, каза, че за него означава много отново да чуе гласа на баща си в играта. Критики идват от инициативата Save Our Voices Now. Основателят ѝ смята, че ИИ клонингите не бива да се допускат без изричното съгласие на засегнатия човек, дори след смъртта му. Генеративният ИИ така или иначе е спорен в гейм индустрията. В Япония актьорски синдикат наскоро предложи правила срещу пресъздаването на гласове на починали без съгласие. Ъпдейтът с Мотсън засяга английския коментар.", "weitere_links": ["Insider Gaming"], "_src": "98755058"}, "2026-11-25-silksong-sea-of-sorrow-cherry-time": {"titel": "Team Cherry обяви шоуто „Cherry Time“ за 27 ноември с новини за DLC-то Sea of Sorrow на Silksong", "schlagzeile": "DLC за Silksong: Team Cherry обещава новини в петък", "kurz": "Team Cherry ще излъчи в петък, 27 ноември, презентация под името „Cherry Time“. Обещани са няколко анонса и новини за безплатното DLC Sea of Sorrow на Silksong. Студиото не казва какво точно ще покаже.", "zusammenfassung": "Team Cherry обяви шоуто в X с думите, че ще има „куп вълнуващи анонси“ и новини за Sea of Sorrow. Засега DLC-то е обявено за 2026 г. Според VGC феновете спекулират за всичко – от изненадващо пускане до отлагане за 2027 г. Възможна е и дата през декември. Sea of Sorrow ще бъде безплатно за всички собственици на Hollow Knight: Silksong и ще донесе нови зони и босове. Самата Silksong излезе през септември 2025 г. Дали Team Cherry ще покаже и нова игра, не е ясно. VGC не посочва точен час; премиерата ще е в YouTube.", "weitere_links": ["Eurogamer"], "_src": "a729fec7"}, "2026-11-25-diablo-4-season-16-inhalte-bleiben": {"titel": "Diablo 4: сезон 16 започва на 1 декември, популярно съдържание от сезон 15 като Стария Тристрам и Декард Каин остава завинаги", "schlagzeile": "Diablo 4 нарушава правилото си: популярно сезонно съдържание остава завинаги", "kurz": "За първи път Blizzard запазва трайно в Diablo 4 голяма част от съдържанието на един сезон. От юбилейния сезон 15 остават, наред с другото, Старият Тристрам и Декард Каин. Сезон 16 „Tyrael's Gambit“ започва на 1 декември.", "zusammenfassung": "Обикновено сезонното съдържание в Diablo 4 изчезва в края на сезона. Според Polygon обаче сезон 15 за 30-годишнината на поредицата, пълен с препратки към Diablo 2, е приет толкова добре, че Blizzard запазва част от него. Това включва пресъздадения Стар Тристрам и Декард Каин, чиито книги са достъпни от пиедестал в града. Битката с Великите злини вече ще може да се призовава като обикновен бос на леговище. Подземията Capstone от сезона минават на Torment 10 и нагоре. Подземията Waking Nightmares остават достъпни със специални ключове. В играта остават и някои уникални предмети Legacy като Annihilus и Hellfire Torch Charm. Сезон 16 продължава историята за смъртния култ Úllo Sar и носи нови предмети и битки. Blizzard подчертава, че ще продължи да поддържа Diablo 4, въпреки че Diablo 5 е обявена.", "_src": "a1157a18"}, "2026-11-25-xnulinux-macos-kernel-modul": {"titel": "xnulinux: проект с отворен код зарежда ядрото на macOS XNU като модул в Linux, процеси на macOS работят редом с Linux приложения", "schlagzeile": "macOS като Linux модул: xnulinux стартира ядрото на Apple без хипервайзор", "kurz": "Проектът с отворен код xnulinux зарежда ядрото на macOS като модул в обикновено Linux ядро. Така програми за macOS работят директно редом с Linux приложения, без хипервайзор между тях. Според heise засега това е само експеримент.", "zusammenfassung": "Разработчиците компилират XNU, ядрото на Darwin, от публикувания от Apple изходен код. Резултатът се зарежда като модул в непроменено ARM64 Linux ядро. При тестове с ядро на Ubuntu работният плот на macOS 27 се появявал след 31 до 48 секунди, според страницата на проекта. Проектът е тестван основно на Mac с Apple Silicon, на които Linux работи във виртуална машина. Нужни са също Xcode и собствена инсталация на macOS. Графично ускорение има при наличие на virtio-gpu устройство; иначе рендерира процесорът. За да работи, разработчиците са закърпили защити на macOS като AMFI и са разхлабили SIP. TweakTown съобщава и за демонстрация на мини компютъра DGX Spark на Nvidia, но само с рендериране от процесора. Лицензът на Apple позволява macOS само на хардуер на Apple. Според heise xnulinux не е подходящ за продуктивна употреба.", "_src": "ed051f7c"}, "2026-11-25-tsmc-texas-fab-22-milliarden": {"titel": "Данъчно заявление разкрива: TSMC обмисля фабрика за чипове за 22,6 млрд. долара край College Station, Тексас, строеж от 2027 до 2032 г.", "schlagzeile": "22,6 млрд. долара: TSMC обмисля втора голяма фабрика в САЩ – в Тексас", "kurz": "TSMC обмисля нова производствена площадка в Тексас, на около 120 километра северозападно от Хюстън. Това личи от публично заявление за данъчни облекчения, за което пише heise. Фабриката би струвала 22,6 млрд. долара и би произвеждала чипове по N2 и по-нови процеси.", "zusammenfassung": "Заявлението е по тексаската програма JETI и описва „TSMC Texas Advanced Semiconductor Manufacturing Campus“ край College Station. Според heise строежът би продължил от 2027 до 2032 г. Wccftech цитира от документите около 2100 планирани работни места. Ще се произвеждат чипове по 2-нанометрова технология и следващи; TSMC дава за пример ИИ ускорители. Теренът е само на около 30 километра от планираната „Terafab“ на компанията на Илон Мъск. От заявлението става ясно, че TSMC проучва и други площадки в САЩ, най-вече в Аризона. Данъчните облекчения са важен фактор, както и земята, токът, водата и работната ръка. TSMC вече има фабрика в Аризона и строи още там. Окончателно решение за мястото все още няма. За геймърите в краткосрочен план нищо не се променя; фабриката би произвеждала най-рано в началото на 2030-те.", "weitere_links": ["Wccftech"], "_src": "7a94a508"}, "2026-11-25-apex-anr-digital-foundry-test": {"titel": "Digital Foundry тества Apex Neural Rendering: генерирането на кадри с отворен код отчасти не отстъпва на DLSS, но има ghosting и грешки в интерфейса", "schlagzeile": "Съперник на DLSS на тест: генерирането на кадри на Apex отчасти не изостава", "kurz": "Digital Foundry сравни технологията с отворен код Apex Neural Rendering с генерирането на кадри DLSS на Nvidia. В някои игри ANR е също толкова бърз или по-бърз; при по-високи множители Nvidia води. Интересното е, че ANR позволява многокадрово генериране и на по-стари карти на AMD и Intel.", "zusammenfassung": "Според Wccftech тестът е направен на система с Ryzen 7 9800X3D и RTX 5070 Ti. В Spider-Man Remastered в 4K с генериране 2x ANR постига 130,5 fps срещу 124,9 fps за DLSS. В Cyberpunk 2077 с path tracing и генериране 3x DLSS е с около 10 процента по-бърз; в Crimson Desert с 4x ANR изостава само с 3,6 процента. При качеството на картината ANR показва повече ghosting, проблеми с елементи на интерфейса и по-слабо разпознаване на смяната на кадрите. В The Last of Us Part II обаче артефактите му при интерполация понякога се забелязват по-малко, отколкото при DLSS. Тъй като ANR работи с обикновени compute шейдъри, той върви и на карти без ИИ блокове. На Arc B580 и Radeon RX 6700 Cyberpunk 2077 с 3x достига 186 и 149 fps, но при латентност 67 и 82 ms. Radeon показва и неравномерно време на кадрите. Новост е инструмент на Apex Compute, който записва суровите данни за ъпскейлъри и генериране на кадри и позволява напълно еднакви сравнения. Според доклада сравнителният материал е около 1 TB данни. ANR е бета, която според досегашните данни по същество се разработва от един човек. Super Resolution и Ray Reconstruction на Apex все още са в разработка.", "_src": "d1d2d6d4"}, "2026-11-25-ps-plus-dezember-2026": {"titel": "PS Plus през декември 2026: Tony Hawk's Pro Skater 3+4, Dragon Ball Xenoverse 2 и Amnesia: The Bunker", "schlagzeile": "PS Plus през декември: Tony Hawk, Dragon Ball и ужас в бункер", "kurz": "Sony потвърди месечните игри в PS Plus за декември. Абонатите получават Tony Hawk’s Pro Skater 3+4, Dragon Ball Xenoverse 2 и Amnesia: The Bunker. Игрите са достъпни от първи декември до четвърти януари.", "zusammenfassung": "Sony обяви подбора в PlayStation Blog и в X. Tony Hawk's Pro Skater 3+4 е новата версия на двете скейтборд класики. Dragon Ball Xenoverse 2 е екшън RPG с битки в аниме стил, излязла през 2016 г. Amnesia: The Bunker е хорър игра на Frictional Games, чието действие се развива през Първата световна война. Според IGN заглавията могат да се добавят в библиотеката от вторник, 1 декември, до понеделник, 4 януари. Който още не е взел ноемврийските игри, има време до понеделник, 30 ноември. През ноември това бяха Dead Island 2, Tomb Raider IV–VI Remastered и Monster Train 2. Както винаги, за игра е нужен активен абонамент.", "weitere_links": ["X: PlayStation", "Eurogamer"], "_src": "791d559e"}, "2026-11-25-adobe-chrome-erweiterung-ssd-schreiblast": {"titel": "Сигнал от потребител: разширението Adobe Acrobat за Chrome уж е причинило около 300 GB запис за три дни в покой", "schlagzeile": "Пълни ли разширението на Adobe за Chrome твоя SSD? Потребител мери 300 GB", "kurz": "Потребител на Windows 11 е измерил около 300 GB записна активност на Chrome за три дни и я е свързал с разширението Adobe Acrobat. След премахването му записът в покой спада с над 80 процента. Става дума за единичен сигнал, Adobe не е коментирала.", "zusammenfassung": "Потребителят разказва в Reddit, че почти неактивният му компютър записвал необичайно много, макар кешът на Chrome да е само 3,5 GB. Според анализа му причината е service worker на Adobe, който отново и отново създавал около 1 GB кеш данни. Това ставало дори през нощта при затворени прозорци на Chrome. След премахване на разширението и изтриване на данните записът спаднал от около 730 до 135 MB за пет минути, според сигнала. Wccftech посочва, че използваният брояч на Windows включва и мрежови трансфери. Затова 300 GB не са надеждна стойност за реалните записи върху SSD. Още през май във форума на Adobe имало сигнали, че разширението създава маса лог файлове на фирмени компютри. Според Chrome Web Store разширението има огромен брой потребители. Който иска да провери, може в Windows да ползва Монитора на ресурсите (resmon) и в раздела Диск да види записа по процеси. В Chrome страницата chrome://serviceworker-internals показва регистрираните service workers. Наскоро и графичните драйвери на AMD и Nvidia попаднаха в заглавията заради прекомерен запис.", "_src": "e3af1d37"}, "2026-11-25-nvidia-rtx50-lieferung-minus-30-leak": {"titel": "Доклади: Nvidia ще доставя на партньорите си с 20–30 процента по-малко гейминг GPU; RTX 60 може да закъснее заради бума на ИИ и недостига на памет", "schlagzeile": "Изтичане: Nvidia реже ли доставките на RTX 50 с до 30 процента?", "kurz": "Nvidia щяла да отпусне на партньорите си с 20–30 процента по-малко гейминг GPU за периода ноември–януари. Това съобщава китайският форум на дистрибутори Board Channels, а го подхващат VideoCardz, TechPowerUp и PCGH. Тайванско икономическо издание говори и за възможно забавяне на серията RTX 60; нищо не е потвърдено.", "zusammenfassung": "Според Board Channels Nvidia вече е уведомила производителите на карти за съкращението. Докладът засега изрично се отнася до Китай, но TechPowerUp допуска разширяване и към други региони. Тайванският Commercial Times, позовавайки се на договорни производители, пише за силно удължени срокове на доставка на ИИ хардуер. Новите поръчки за B300 щели да отнемат 26–40 седмици, а за GB300 – 14–26 седмици. Затова свободните пластини в TSMC щели да отиват по-скоро за чипове за центрове за данни, отколкото за карти GeForce. Към това се добавя недостигът на памет, тъй като производителите пренасочват производството към сървърна DRAM и остава по-малко GDDR7. Според Commercial Times серията RTX 60 трябвало да влезе в масово производство в края на 2027 г.; този график може да се измести. Това съвпада с по-стари слухове за пускане едва през 2028 г. Още през януари Nvidia вероятно е намалила квотите на партньорите с 15–20 процента. За купувачите това би означавало още по-малко карти RTX 50 и по-скоро растящи цени. Nvidia не е потвърдила нито съкращението, нито забавяне.", "ursprungsquelle": "Board Channels (via VideoCardz); Commercial Times", "weitere_links": ["PC Games Hardware (PCGH)"], "_src": "45bc32c2"}, "2026-11-25-core-ultra-4000-specs-leak": {"titel": "Intel Core Ultra 4000 (Nova Lake-S): изтекъл документ изброява седем настолни процесора с до 28 ядра, 144 MB L3 кеш и 5,5 GHz", "schlagzeile": "Изтичане: Core Ultra 4000 със 144 MB кеш, но само 5,5 GHz?", "kurz": "Документ на Intel, публикуван от VideoCardz, показвал седем настолни процесора Nova Lake. Флагманът би бил Core Ultra 9 4970K BFC с 28 ядра, 144 MB L3 кеш и максимум 5,5 GHz. Данните са от квалификационни мостри и не са потвърдени.", "zusammenfassung": "Според таблицата големите модели имат 8 производителни, 16 ефективни и 4 нискоенергийни ядра. Наставката BFC обозначава вариантите с голям L3 кеш до 144 MB; моделите без BFC имат 30–36 MB. Под тях са Core Ultra 9 4950K с 5,4 GHz, два Core Ultra 7 с 24 ядра и 5,2 GHz и два Core Ultra 5 с 22 ядра и 5,1 GHz. Особен случай е Core Ultra 9 4900 BFC с 22 ядра и само 65 вата; всички останали модели са със 125 вата базова мощност. Всички чипове щели да поддържат DDR5-8000. ComputerBase отбелязва, че 5,5 GHz са по-малко от 5,7 GHz на сегашното поколение Core Ultra 200K. Тъй като при мострите Turbo 2.0 и 3.0 са еднакви, финалният модел може да спечели още малко, но това е спекулация. Чиповете вече били в степинг C1, тоест след по-големи преработки. В тази връзка Intel планирала настолно събитие в Берлин в края на февруари; ComputerBase смята пускане в средата или края на март за реалистично. Вариантите с до 52 ядра не са в този списък. Intel не е потвърдила нито данни, нито дати.", "ursprungsquelle": "VideoCardz (документ на Intel)", "weitere_links": ["TechPowerUp", "PC Games Hardware (PCGH)"], "_src": "d9d602cf"}, "2026-11-25-steam-wero-zahlung": {"titel": "Steam предлага в Германия европейската платежна услуга Wero; клиентите на Sparkasse получават и плащания с едно кликване", "schlagzeile": "Steam вече приема Wero: европейската платежна услуга се появи в магазина", "kurz": "Европейската платежна услуга Wero се появява в Германия като метод на плащане в Steam. Това съобщават Dr. Windows и блогът на Caschy. Клиентите на Sparkasse получават и новости като плащания с едно кликване.", "zusammenfassung": "Wero е общата платежна услуга на европейски банки и цели да е алтернатива на PayPal и кредитните карти. Според Dr. Windows Wero вече може да се избере като метод на плащане в Steam, поне в Германия. От публикациите не става ясно дали се предлага и в Австрия или други страни. От септември Wero обработва и периодични плащания като абонаменти. От началото на ноември има защита на купувача. Новост са плащанията с едно кликване, при които платежните данни се въвеждат при търговеца само веднъж. Клиентите на Sparkasse скоро трябва да могат да ползват Wero и през обикновеното приложение Wero. Не ни е известно официално съобщение от Valve.", "_src": "e9c8ad07"}, "2026-11-25-mario-kart-world-1-9-0": {"titel": "Mario Kart World 1.9.0 добавя осем ремикс писти, два нови маршрута в Knockout Tour и автоматични повторения", "schlagzeile": "Mario Kart World 1.9.0: осем ремикс писти и нови Knockout Tour маршрути", "kurz": "Nintendo пусна безплатната актуализация 1.9.0 за Mario Kart World. Тя добавя осем ремиксирани версии на вече съществуващи писти, два нови маршрута за Knockout Tour и автоматично запазва последните състезания. Това потвърждава самата Nintendo, както съобщава сред другите Video Games Chronicle.", "zusammenfassung": "Осемте писти са ремикси на вече съществуващи трасета, а не напълно нови местности: Airship Fortress 2, Desert Hills 2, Salty Salty Speedway 2, DK Pass 2, Koopa Troopa Beach 2, Shy Guy Bazaar 2, Mario Bros. Circuit 2 и Wario Stadium 2. Те са достъпни във VS състезания, бягане срещу времето, както и в онлайн и безжична игра. За Knockout Tour с 24 играчи идват Feather Rally от Mario Bros. Circuit до Boo Cinema и Lucky Cat Rally от Great ? Block Ruins до Sky-High Sundae. Могат да се изберат, след като вече е завършен друг рали. В главното меню вече има повторения: най-новите състезания и битки се запазват автоматично, по-старите се изтриват, когато мястото свърши. Прекъснати състезания и повторения от версия 1.8.0 или по-стара не се пренасят. Има и по-малки корекции в играта и поправки на грешки, например при някои преки пътища и ъгли на камерата. Според Nintendo актуализацията е нужна за интернет функциите и всички играчи трябва да имат една и съща версия. Nintendo of Europe обяви актуализацията и в сряда сутринта в X. В дневните тенденции на Google в Германия в сряда на видно място се появи „mario kart world“.", "weitere_links": ["Nintendo UK (официално)", "X: Nintendo of Europe"], "_src": "b23ebe03"}, "2026-11-25-gothic-3-classic-konsolen": {"titel": "THQ Nordic пуска Gothic 3 Classic за PS5 и Xbox Series; версията за Switch 2 се отлага за началото на 2027", "schlagzeile": "Gothic 3 за първи път на конзоли: Classic издание с фенски пач", "kurz": "Две десетилетия след тръскавия старт на PC, Gothic 3 за първи път излиза на конзоли. THQ Nordic продава Classic версията от 24 ноември за около 30 евро на PS5 и Xbox Series X/S. Техническата основа е Community Patch 1.75, а изданието за Switch 2 ще дойде едва в началото на 2027.", "zusammenfassung": "Адаптацията следва римейка на първия Gothic и портовете на Gothic и Gothic 2 за PlayStation и Xbox. THQ Nordic обещава менюта, съобразени с контролер, и по-плавно изображение, но не дава конкретни стойности за разделителна способност и кадри в секунда. На PS5 трябва да се поддържат вибрацията и адаптивните спусъци на DualSense. Който има Xbox версията и подходящ абонамент за Game Pass, може да стриймва играта и през Cloud Gaming. Версията за Switch 2 първоначално също беше планирана за старта и беше отложена за началото на 2027. Според heise не е известно дали членове на тогавашния екип на фенския пач са работили по конзолната версия. Оригиналът на Piranha Bytes излезе недовършен на PC през 2006 г. и по-късно беше направен играем предимно от общността. Самото студио Piranha Bytes беше затворено през 2024 г. в рамките на съкращенията на Embracer.", "_src": "e604a3db"}, "2026-11-25-rtx-5090-preise-unter-8000": {"titel": "ComputerBase: повече персонализирани модели GeForce RTX 5090 на склад, входна цена в сряда сутринта 7499 евро; RTX 5080 се доближава до 2000 евро", "schlagzeile": "Повече наличност, по-малко крайности: RTX 5090 в магазините под 8000 евро", "kurz": "В германската търговия отново има повече GeForce RTX 5090 на склад; най-ниската цена в сряда сутринта беше 7499 евро. В средата на октомври входната цена все още беше малко под 8000 евро. За истинско облекчение обаче не може да се говори: RTX 5080 се доближава до прага от 2000 евро.", "zusammenfassung": "През октомври Nvidia отрече, че GeForce RTX 5090 се спира, и посочи ограничения във веригата на доставки. Почти шест седмици по-късно ComputerBase вижда малък обрат в търговията. В сравнение със средата на октомври повече търговци отново могат да изпращат от склад по-голям избор от персонализирани модели. Входната цена в сряда сутринта беше 7499 евро, преди това малко под 8000 евро. За повечето купувачи картата остава недостижима, но поне ситуацията в страната не се е влошила допълнително. Твърдението на Nvidia, че RTX 5090 продължава да се предлага, следователно има известна основа. Същевременно втората Blackwell карта за играчи, GeForce RTX 5080, се доближава до 2000 евро; много модели вече не се намират под тази цена. Най-евтиният модел, обявен като наличен на склад, струваше към момента на новината 1968 евро, в eBay от 1948 евро. За GeForce RTX 5070 Ti най-добрите цени бяха 1379 евро. Тези суми са моментна снимка от сряда сутринта и могат бързо да се променят. ComputerBase подчертава изрично, че истинско облекчение изглежда иначе.", "_src": "ababedb8"}, "2026-11-25-windows-november-ntlm-anmeldung": {"titel": "Microsoft потвърждава проблеми с влизането след ноемврийските актуализации за сигурност: промените в подписа NTLM срещу CVE-2026-118737 пречат на някои продукти на трети страни", "schlagzeile": "Ноемврийски обновления: Microsoft потвърди проблеми с влизането заради NTLM", "kurz": "След ноемврийските актуализации за сигурност влизането може да се провали на някои устройства и програми. Microsoft потвърждава проблеми със съвместимостта, причинени от по-строг подпис NTLM. Засегнати са наред с другото проксита за удостоверяване, единично влизане и решения за пакетиране на приложения от трети страни. Окончателен пач още няма.", "zusammenfassung": "Според BleepingComputer актуализациите затварят и уязвимостта, водена като CVE-2026-118737, в средата за изпълнение Windows RPC. Microsoft описва промените като първа фаза на по-строг подпис на NTLM съобщения, който трябва да затрудни реле атаките. Същото затягане обаче може да накара да се провалят устройства или програми, които не прилагат напълно протокола NTLM. В обновен документ за поддръжка Microsoft посочва като примери проксита за удостоверяване, SSO решения и пакетиране на приложения. Пач за тези проблеми със съвместимостта още няма. Като временно решение Microsoft споменава опция в регистъра, която отново позволява неподписан NTLM; записът може по-късно да отпадне. Препоръчителният път остава преминаване към Kerberos или изчакване на актуализация от съответния производител. Независимо от това Microsoft потвърди и други странични ефекти на ноемврийските актуализации: проблеми с активирането на Windows и спадове в производителността на SQL Server. Фирмата разследва и сигнали, че след актуализациите може да се провали печатът на документи със сложно форматиране. Домашните потребители често не забелязват промените в NTLM, но в фирмени мрежи със стари проксита или SSO те могат да блокират влизането.", "weitere_links": ["Microsoft Support (KB5135557)"], "_src": "7324e995"}, "2026-11-25-huang-keine-nachfolgeregelung": {"titel": "Първа среща със служителите след завръщането: Дженсън Хуанг се извинява и отхвърля план за приемственост в Nvidia", "schlagzeile": "Отново CEO: Хуанг отхвърля план за приемственост в Nvidia", "kurz": "На първата си среща със служителите след възстановяването му като изпълнителен директор Дженсън Хуанг според медиите се е извинил на екипа. Същевременно е заявил, че Nvidia не се нуждае от класически план за приемственост. Това съобщава Golem.de, позовавайки се на CNBC.", "zusammenfassung": "Срещата се е състояла във вторник, ден след като управителният съвет отново е направил Хуанг изпълнителен директор. Според хора в залата, цитирани от CNBC и след това от Golem.de, Хуанг е казал, че е разочаровал служителите и иска да се справи по-добре при втория опит. „Нараних ви всички“, трябвало да е казал. По въпроса за приемствеността Хуанг е обяснил, че Nvidia има няколко способни ръководители за различни области и работи със собствен модел. Класически план за приемственост би създал само ненужна йерархия. Към момента на репортажа на CNBC Nvidia не беше дала становище. Разказите идват от анонимни участници, не от официален стенограм. След оставката на Хуанг на 12 ноември инвеститорите спекулираха за бъдещото ръководство. Това, че Хуанг остава начело и не посочва определен наследник, малко намалява тази несигурност.", "weitere_links": ["CNBC"], "_src": "ebbea18a"}, "2026-11-25-infostealer-2-milliarden-zugangsdaten": {"titel": "Изследователят по сигурност Jeremiah Fowler намира незащитена база с около 2 милиарда данни за вход от инфостилъри", "schlagzeile": "2 милиарда данни за вход са изложени в мрежата – включително бисквитки и сесии", "kurz": "Изследователят по сигурност Jeremiah Fowler е открил незащитена база с около 2 милиарда записа с данни за вход. Освен имейл адреси и пароли тя съдържала и бисквитки, сесийни токени и други данни за достъп. Това съобщава Neowin, опирайки се на доклада на Fowler за ExpressVPN.", "zusammenfassung": "Базата е била достъпна без парола на зле конфигуриран сървър. Според Fowler данните идват от инфостилъри, зловреден софтуер, който източва запазените в браузърите данни за вход. Освен имейли и пароли там е имало бисквитки, сесийни токени и друга информация за достъп, което може да позволи вход в акаунти дори със двуфакторно удостоверяване, докато сесията е валидна. Fowler е сигнализирал за откритието и базата впоследствие е била затворена. Не е ясно кой е управлявал сървъра и колко дълго данните са били достъпни. Не е потвърдено, че всички записи са актуални или автентични; при такива изтичания записите често са стари, дублирани или неизползваеми. Който използва една и съща парола в няколко услуги, трябва да я смени и да следи акаунтите си. Fowler е публикувал разследването чрез ExpressVPN; Neowin се опира на този доклад.", "weitere_links": ["Доклад на Jeremiah Fowler (ExpressVPN)"], "_src": "407c822c"}, "2026-11-25-gta6-pc-port-3007-repos-prolog": {"titel": "Take-Two нарежда Leonida заедно с 3007 GitHub хранилища да бъдат спрени чрез DMCA; неофициалният порт ZETTROX на PC стига до края на пролога", "schlagzeile": "GTA 6 на PC: Take-Two блокира 3007 хранилища, фенски порт минава пролога", "kurz": "След DMCA заявка от Take-Two GitHub е блокирал проекта за рекомпилация Leonida и цялата мрежа от 3007 хранилища. Неофициалните PC портове на базата на изтеклия Xbox билд въпреки това продължават. Публичният билд ZETTROX според PCGH вече минава пролога, но само при 1 до 3 кадъра в секунда.", "zusammenfassung": "Според DMCA заявката, публикувана от GitHub, Take-Two е насочила мерките срещу хранилището Leonida и над 2900 разклонения, съобщава heise. Take-Two вижда в това производно произведение, което нарушава условията на Rockstar, забраняващи сред другото декомпилация и обратно инженерство. Това, че Leonida сама не е съдържала игрови файлове, в заявката е наречено „съзнателно подвеждащо“, защото законно купените Xbox игри остават шифровани. Основа на всички проекти е изтеклият на 20 ноември Xbox билд, изпълнимият файл последва на 23 ноември. Според PCGH тракерът PortWatch VI вече води шест билда като „играеми“, въз основа на данни от разработчици и пряко излъчване, без независими тестове. Водещият ZETTROX е публичен от сряда, 2:12 ч., и трябва да преминава пролога от килията до лодкарското преследване. Тествано е на GeForce RTX 3050, но в игровия свят има само 1 до 3 кадъра в секунда, сенките остават черни и липсва осветление с лъчево проследяване. Според проекта е нужен процесор с AVX2 и видеокарта с Shader Model 6.6 и mesh шейдъри; при Nvidia вече стига GeForce RTX 2000. В правно отношение случаят е деликатен, защото всички проекти предполагат разпаковано копие на изтеклия билд. Официална PC версия Rockstar не е обявил; GamesBeat, позовавайки се на анонимни източници, говори за старт през първото тримесечие на 2027.", "weitere_links": ["PC Games Hardware (PCGH)", "VideoCardz"], "_src": "2e6b658d"}, "2026-11-25-trendforce-dram-2027-abflachen": {"titel": "TrendForce понижава прогнозите за приходи за 2027: DRAM остава оскъден, ръстовете на цените трябва да се заравнят, цените на NAND да паднат", "schlagzeile": "RAM остава оскъден през 2027, но TrendForce очаква по-слаби повишения", "kurz": "Аналитичната компания TrendForce е понижила прогнозите си за приходи през 2027 за оперативна и флаш памет. Причината са намалени поръчки от китайски облачни доставчици. DRAM трябва да остане оскъден през 2027, но тримесечните повишения на договорните цени да намалеят и да се успокоят през втората половина на годината.", "zusammenfassung": "Според съобщението от 25 ноември китайските облачни доставчици са намалили поръчките си за памет за 2027. За NAND флаш, използван в SSD, TrendForce затова очаква цикъл на спад на цените, защото същевременно предлагането расте значително. Прогнозата за приходи от NAND за 2027 пада до около 419,3 милиарда долара, което пак би било с 29 процента повече от предходната година. При DRAM някои китайски доставчици са съкратили търсенето на сървърна памет извън дългосрочните договори, но северноамериканските облачни компании бързо са поели освободените количества, според TrendForce. Пазарът на оперативна памет затова остава недостатъчно снабден през 2027. Договорните цени обаче трябва да растат по-слабо от тримесечие на тримесечие и могат да се успокоят през втората половина на годината. Прогнозата за приходи от DRAM пада до 1,15 трилиона долара, ръст от 69 процента. За компютри и смартфони евтините складови наличности според TrendForce са изчерпани и устройствата могат да поскъпнат през 2027. Производителите затова може да вграждат по-малко памет, за да държат разходите под контрол. За надграждащите SSD могат да поевтинеят през 2027; при RAM по-скоро се очертават по-бавни повишения, отколкото срив на цените. Става дума за пазарна прогноза: магазинните цени следват договорните със закъснение.", "datum_hinweis": "Часът е приблизителен, TrendForce посочва само датата 25.11.2026", "weitere_links": ["X: jukan05 (подсказка)"], "_src": "0eecccf3"}, "2026-11-25-ubuntu-ki-launcher": {"titel": "Canonical дава подробности за планирания стартер на Ubuntu с изкуствен интелект: локално, по желание, въвеждане с текст и глас; тестова версия през януари", "schlagzeile": "Ubuntu планира AI стартер вместо решетка с приложения – локално и по желание", "kurz": "Canonical иска да замени решетката с приложения на Ubuntu с нов стартер, който отваря програми, намира файлове и при нужда предлага функции с изкуствен интелект. Интелектът трябва да работи локално и да се активира само при изрично желание. През януари Canonical иска да предостави първа версия за изпробване.", "zusammenfassung": "Подробностите идват от публикация на разработчика на Canonical Дидие Рош във форума на Ubuntu, съобщава omgubuntu.co.uk. Стартерът трябва да стане обща входна точка: класически за пускане на програми и търсене на файлове, но при желание и за задачи, въведени като текст. Планирано е и гласово въвеждане. Като неподлежащи на преговори принципи Canonical посочва съгласие, поверителност, сигурност и локална обработка. Функциите с изкуствен интелект трябва да се задействат само ако бъдат изрично поискани; който не ги иска, използва стартера като обикновено меню с приложения. Прототип със симулирани задачи се беше появил още през октомври в Snap Store, още без истински функции. Повече за архитектурата и тестова версия Canonical иска да покаже през януари. Мненията на потребителите трябва след това да определят посоката. Дали и кога стартерът ще стане стандарт в стабилна версия на Ubuntu, остава открито.", "_src": "b529be90"}, "2026-11-25-rtx-5090-gb202-woelbung-reparatur": {"titel": "igor'sLAB: изкривен чип GB202 на RTX 5090 унищожава термопаддовете – четвърти ремонт с графенов пад", "schlagzeile": "Изкривен GB202: igor'sLAB ремонтира RTX 5090 за четвърти път", "kurz": "igor'sLAB е ремонтирал за четвърти път Gigabyte Aorus GeForce RTX 5090 Master, защото температурата на горещата точка отново се е покачвала. Измерено е ясно изкривяване на чипа GB202 до 71,76 микрометра. С графенов пад горещата точка при първия натоварващ тест е останала около 82 до 83 градуса.", "zusammenfassung": "При два предишни ремонта с падове с фазова промяна (PTM) проблемите с горещата точка на картата всеки път са се връщали след няколко месеца. При отварянето Игор Валосек е намерил неравномерно разпределени остатъци от PTM и изпъкнала навън повърхност на чипа. Между средата и ръба е измерил 42,70 микрометра надвишение, общо 71,76 микрометра разлика във височината върху около 714 квадратни милиметра. Като обяснение посочва термомеханично нестабилна контактна зона, която с времето разрушава пада, но сам я определя като правдоподобна и не окончателно доказана. При четвъртия опит е поставил графенов пад с дебелина 0,3 милиметра върху GPU и термо пъти върху паметта и част от захранването. При около 17-минутен натоварващ тест с около 600 вата мощност на платката температурите са останали стабилни. Горещата точка в края е била около 82 до 83 градуса, драйверът е показвал 71 до 72 градуса, а GDDR7 паметта средно 67 градуса. Дали ремонтът ще издържи дългосрочно, остава открито: това е първи функционален тест, не дългосрочно доказателство. Освен това става дума за една единствена карта, не може да се пренася върху всички RTX 5090. За купувачите на употребяван хардуер случаят обаче показва, че растящи стойности на горещата точка при карти от висок клас могат да бъдат предупредителен знак.", "_src": "6d4c796c"}, "2026-11-25-windows11-weniger-ram-ignite": {"titel": "Ignite 2026: Microsoft е намалил общо с над 860 MB нуждите от памет на Microsoft 365, Defender, OneDrive и Purview", "schlagzeile": "Windows 11 пести RAM: услугите на Microsoft заемат до 860 MB по-малко", "kurz": "На Ignite 2026 Microsoft обясни, че собствените приложения и фонови услуги под Windows 11 заемат осезаемо по-малко оперативна памет от преди. Microsoft 365 се нуждае от 360 MB по-малко, Defender, OneDrive и Purview допълват спада, общо над 860 MB. Това съобщава Windows Latest.", "zusammenfassung": "Microsoft представи тези числа на конференцията Ignite 2026. Те се отнасят до паметта, заемана от приложения и услуги на Microsoft под Windows 11, не до RAM, изискван от самата система. Само Microsoft 365 трябвало да дава около 360 MB икономия, Defender, OneDrive и Purview остатъка до общо над 860 MB. Това са данни на производителя, не независим тест на типични компютри. Реалната икономия зависи от това кои приложения работят и от конфигурацията. Microsoft не е уточнил тук до каква степен всеки компютър вече се възползва чрез вече внедрени актуализации. На машини с малко памет обаче всяка стотица мегабайти може да се усети. Windows Latest се опира на изказванията от Ignite.", "_src": "12087b52"}, "2026-11-25-gta6-digital-foundry-xbox-vor-ps5": {"titel": "Digital Foundry: GTA 6 държи по-стабилно 30 кадъра в секунда на Xbox Series X, отколкото на стандартното PS5", "schlagzeile": "GTA 6 върви по-стабилно на Xbox Series X, отколкото на PS5 – Digital Foundry", "kurz": "Според анализ на Digital Foundry GTA 6 поддържа по-надеждно 30 кадъра в секунда на Xbox Series X, отколкото на обикновеното PS5. Двете конзоли използват до голяма степен едни и същи графични настройки. На анализа се опират VGC, Insider Gaming и Neowin.", "zusammenfassung": "Digital Foundry е сравнил конзолните версии на GTA 6. На Xbox Series X играта по-често и по-дълго би държала заложените 30 кадъра в секунда, докато стандартното PS5 би имало повече спадове в честотата. Графичните настройки били до голяма степен еднакви; разликата щяла да идва предимно от това как всяка конзола държи темпото. Това не е тест на PS5 Pro, която тук не е обхваната по същия начин. По-рано Sony представяше PS5 като най-добрия начин да се играе GTA 6, включително заради функциите на DualSense. Анализът на Digital Foundry смекчава този аргумент единствено по критерия стабилност на картината. Както често при такива сравнения, резултатът може да зависи от сцените, а други редакции не са задължително измерили същото. Статията се опира на анализа на Digital Foundry, не на числа, публикувани от Rockstar или от производителите на конзолите.", "weitere_links": ["Insider Gaming", "Neowin"], "_src": "5bad6f5a"}, "2026-11-25-amd-inception-hackergruppe": {"titel": "Хакерската група Inception твърди, че е откраднала вътрешни данни на AMD; ReversingLabs вижда Nintendo, Activision Blizzard, Riot и Twitch като възможни цели", "schlagzeile": "Хакерска група твърди, че има данни на AMD – във визьора и Nintendo?", "kurz": "Група с име Inception твърди, че е получила вътрешни данни на AMD. Изследователи от ReversingLabs са открили други домейни на кампанията, които сочат към Nintendo, Activision Blizzard, Riot и Twitch. Това съобщава PCGH. Не е потвърдено, че наистина са откраднати данни.", "zusammenfassung": "Inception твърди, че има вътрешни данни на AMD. Към момента на статията на PCGH AMD не беше потвърдила публично, че атака е успяла, нито какви данни биха били засегнати. ReversingLabs е прегледала инфраструктурата на кампанията и е намерила други имена на домейни, които навяват мисълта за Nintendo, Activision Blizzard, Riot Games и Twitch като възможни цели или теми. Това не доказва, че тези компании наистина са били взломени. Подобни твърдения често циркулират преди проверими доказателства, понякога само за да привлекат внимание. Докато AMD, Nintendo или другите посочени фирми не потвърдят, случаят трябва да се третира като твърдение. PCGH се опира на работата на ReversingLabs и на собствените изявления на групата.", "_src": "8567dabe"}, "2026-11-25-pop-os-26-04-lts": {"titel": "System76 пуска Pop!_OS 26.04 LTS, базиран на Ubuntu 26.04 LTS, с COSMIC 1.12, Linux 7.2 и Mesa 26.2", "schlagzeile": "Pop!_OS 26.04 LTS е тук: работният плот COSMIC носи VRR и отдалечен достъп", "kurz": "System76 пусна Pop!_OS 26.04 LTS. Linux дистрибуцията се основава на Ubuntu 26.04 LTS и включва работния плот COSMIC 1.12, написан на Rust. Сред новостите са отдалечен работен плот, VRR и по-добра поддръжка на графични таблети.", "zusammenfassung": "Досега новата версия според 9to5Linux беше достъпна само предварително инсталирана на компютрите на System76, сега всички могат да я изтеглят. Под капака работят ядрото Linux 7.2 и графичният стек Mesa 26.2. Има ISO образи за системи Intel и AMD, за системи Nvidia и за ARM64. За играчите са интересни подобрен цял екран, по-добър режим Steam Big Picture, поддръжка на променлива честота на опресняване (VRR) и протоколът Wayland Pointer Constraints. Добавят се регулация на силата на звука по приложения, поддръжка на графични таблети и екранна клавиатура, която може да се управлява и с геймпад. Нови приложения са преглед на изображения, системен монитор и USB инструментът Popsicle. С „Theme Constellations“ могат заедно да се сменят фон, акцентни цветове, икони и шрифтове. Директно надграждане от Pop!_OS 24.04 LTS трябва да бъде отворено едва през декември. Дотогава за новата версия е нужна нова инсталация.", "weitere_links": ["Phoronix", "OMG! Ubuntu"], "_src": "1b5ff53a"}, "2026-11-25-lords-of-the-fallen-2-april-2027": {"titel": "CI Games отлага Lords of the Fallen 2 за април 2027, точната дата ще бъде обявена през декември", "schlagzeile": "Lords of the Fallen 2 е отложена: нова дата през април 2027", "kurz": "Lords of the Fallen 2 ще излезе едва през април 2027. Това е съобщил в X шефът на CI Games Марек Тимински. Точната дата студиото ще обяви през декември.", "zusammenfassung": "Отлагането е обявено от изпълнителния директор на CI Games в X и предадено от Eurogamer. Играта първоначално трябваше да излезе по-рано; сега студиото иска повече време, за да я довърши. Тимински е казал, че точна дата през април 2027 ще бъде посочена през декември. Не е представена нова рамка за премиера на отделните платформи извън този месец. Става дума за официално съобщение на издателя, не за слух. Остава открито какво допълнителното време реално ще промени в играта, защото студиото не е публикувало при този повод подробен списък със съдържание.", "_src": "9b787c71"}, "2026-11-25-microsoft-code-red-m365": {"titel": "След големия срив на Microsoft 365 Microsoft обявява вътрешно „Code Red“: инцидентите трябва да се отстраняват в рамките на един час", "schlagzeile": "„Code Red“ в Microsoft: най-висока тревога след срива на 365", "kurz": "Microsoft е обявил вътрешно най-високото ниво на тревога „Code Red“. Причината е световният срив на Microsoft 365 в средата на ноември, чиято реакция ръководството е преценило като твърде бавна. Занапред инцидентите трябва да се отстраняват най-много за един час.", "zusammenfassung": "heise се опира на вътрешни циркуляри, до които е достигнал Reuters. Причината за срива не била проблем със сигурността, а актуализация на Windows, внедрена през юли, която във връзка с мрежова модернизация е предизвикала проблеми с мащабирането. Отстраняването продължило толкова дълго, защото диагностичните данни били разпръснати в няколко системи. По време на срива техниците на Microsoft разменили над 11 000 съобщения в единадесет чата в Teams. Занапред ръководството изисква инцидентите да се отстраняват най-много за един час. Агенти с изкуствен интелект трябва да помогнат за събирането на разпръснатите диагностични данни. Трябва да се изготвят и нови планове за целенасочено сваляне на натоварването и изолиране на географски региони. От по-ранен вътрешен циркуляр според Reuters се е виждало, че спешна актуализация е имала нужда от пет до шест дни, за да стигне до всички системи на компанията. При спешни пропуски в сигурността Microsoft иска занапред да се вмества в един час – от откриването на проблема през написването на пача до завършената инсталация на всички системи. „Разбира се, още не сме стигнали дотам“, е казал Джейсън Хендерсън, президент на M365 Core, цитиран от Reuters. Успоредно ръководството на Microsoft съкращава много работни места. Информацията идва от вътрешни изтичания, не от подробно официално изявление на Microsoft.", "weitere_links": ["Neowin"], "_src": "d784db6c"}, "2026-11-25-witcher4-sony-marketing-deal": {"titel": "CD Projekt Red сключва партньорство със Sony: маркетинг за The Witcher 4, игри в PlayStation Plus; Cyberpunk 2 има 199 разработчици", "schlagzeile": "The Witcher 4: Sony си осигурява маркетингова сделка – както при GTA 6", "kurz": "CD Projekt Red е подписала нови партньорски договори със Sony Interactive Entertainment. Те засягат присъствието на игрите в PlayStation и в PlayStation Plus, както и съвместния маркетинг на The Witcher 4. Финансовият директор Пьотр Нелюбович обяви това при публикуването на резултатите, както съобщава сред другите VGC.", "zusammenfassung": "„Точно днес подписахме нови партньорски споразумения със Sony Interactive Entertainment, които обхващат присъствието на нашите игри в PlayStation и в абонаментите PlayStation Plus, както и сътрудничеството ни за предстоящата маркетингова кампания на Witcher 4“, е казал Нелюбович, цитиран от VGC. Конкретната форма на тази кампания още не е ясна. VGC очаква The Witcher 4 да бъде показван на презентации на PlayStation, с акцент върху работата върху хардуера на PlayStation и евентуални функции, характерни за контролера. Сравнима сделка между Rockstar и Sony за GTA 6 позволи на Sony да представи PS5 като най-добрия начин да се играе. Това не означава изключителност: The Witcher 4 остава планиран и за други платформи, а излизането все още се цели за 2028, така че маркетинговата кампания трябва да започне едва по-късно. Освен това CDPR е посочила, че екипът на Cyberpunk 2 вече брои 199 души и трябва още да нарасне догодина, според друга статия на VGC. Подробностите по договора със Sony не са оповестени.", "weitere_links": ["IGN", "Insider Gaming", "VGC (Cyberpunk 2)"], "_src": "2292b27a"}, "2026-11-25-intel-desktop-event-berlin-leak": {"titel": "VideoCardz: Intel уж пита пресата за свободни дати за четиридневно „Next-gen desktop event“ в края на февруари в Берлин – Nova Lake още се очаква на CES 2027", "schlagzeile": "Изтичане: Планира ли Intel настолно събитие в Берлин в края на февруари?", "kurz": "Според VideoCardz Intel пита медии за наличност за четиридневно настолно събитие в края на февруари в Берлин. Не е ясно дали това е основното представяне на следващото настолно поколение. Nova Lake трябва все още да бъде представен на CES 2027 през януари; събитието не е потвърдено.", "zusammenfassung": "VideoCardz се позовава на други медии, които Intel бил потърсил, без да посочи втори публичен източник и без потвърждение от Intel. Не се знае дали това е основното премиерно събитие или едно от няколко регионални. Според VideoCardz Nova Lake трябва все още да дебютира на CES 2027 през януари; събитието в Берлин би било следователно след официалното обявяване, може би при наличност в магазините или при вдигане на ембаргото върху тестовете. При публикуването на резултатите за октомври Intel потвърди, че Nova Lake ще бъде първият клиентски продукт върху 18A-P, и обеща повече информация на CES. VideoCardz свързва февруарското събитие с настолния график, споменат още през юли, с 28-ядрени процесори между края на януари и март. Нищо от това не е потвърдено: датата, продължителността и точната роля на събитието остават открити, както и връзката с Nova Lake, която е само тълкуване на VideoCardz.", "ursprungsquelle": "VideoCardz (ексклузивен материал)", "weitere_links": ["X: VideoCardz"], "_src": "150bc259"}, "2026-11-24-rx-9060-xt-taktrekord-4837-mhz": {"titel": "Мениджърът на AMD Джак Хюин и овърклокърът Бил Алвърсън вдигат Radeon RX 9060 XT до 4837 MHz с течен азот – нов рекорд за честота на GPU, но още непотвърден", "schlagzeile": "Почти 5 GHz: шефът на AMD вдига Radeon RX 9060 XT до рекордна честота", "kurz": "Ръководителят на графичното и PC подразделение на AMD Джак Хюин заедно с овърклокъра Бил Алвърсън е вдигнал Radeon RX 9060 XT до 4837 MHz с течен азот. Това би била най-високата честота, постигана някога от графичен чип. До границата от 5 GHz остават само 163 MHz, но резултатът още не е официално потвърден.", "zusammenfassung": "Според PCGH опитът за рекорд се е състоял още на 15 ноември пред публика в новооткрития Micro Center в Остин, а Хюин го е оповестил в X едва на 24 ноември. Според снимката в OC World Record Museum на SkatterBencher GPU-Z е показвал минус 49 градуса по Целзий, напрежение на ядрото 1,434 V и едва 62 W консумация на картата. Преднината пред предишния рекорд от 4789 MHz от юни е само 48 MHz. Това вече е третият рекорд за честота тази година, всеки път с RX 9060 XT и с участието на Алвърсън. Музеят не води като потвърден нито този резултат, нито двата рекорда от юни, защото липсват линк към източник и валидация от GPU-Z. Това няма нищо общо с ежедневния овърклок: AMD посочва boost до 3130 MHz за чипа RDNA 4, а с въздушно или водно охлаждане според PCGH обикновено са реалистични 3,3 до 3,5 GHz. Границата от 4 GHz за първи път беше премината през юли 2023 г. от GeForce RTX 4090. От юни насам според музея отново Radeon оглавява списъка с рекорди. Wccftech допълва, че предишният рекордьор Splave също е присъствал на събитието в Остин.", "weitere_links": ["Wccftech"], "_src": "641b29ea"}, "2026-11-24-cdpr-q3-witcher4-sprung-wie-gta6": {"titel": "CD Projekt Red очаква скок между The Witcher 3 и The Witcher 4, подобен на този между GTA 5 и GTA 6; тримесечни резултати с 208 млн. злоти приходи", "schlagzeile": "CD Projekt: The Witcher 4 ще скочи колкото GTA 6 спрямо GTA 5", "kurz": "По време на разговора за тримесечните резултати съизпълнителният директор на CD Projekt Михал Новаковски направи голямо сравнение: между The Witcher 3 и The Witcher 4 ще има скок, подобен на този между GTA 5 и GTA 6. GTA 6 обаче не е променила плановете и бюджетите за The Witcher 4 и Cyberpunk 2. През третото тримесечие групата е реализирала 208 млн. злоти приходи и 109 млн. злоти печалба.", "zusammenfassung": "Според Eurogamer Новаковски е казал, че студиото е разгледало GTA 6 и е видяло разликите, но не иска да прави подробно сравнение. След единадесет години The Witcher 4 ще изглежда значително по-добре и ще бъде подобрена практически във всяко отношение. Проектите се движат от амбиция, а не от бюджет, но бюджетите не са безгранични. GTA 6 е довела до спад от поне 25 процента при играчите на студиото на PlayStation и Xbox, а на PC, където GTA 6 още липсва, ефект не се вижда. В дългосрочен план студиото не очаква съществено влияние през четвъртото тримесечие, според Eurogamer. В маркетинга CD Projekt не иска да копира подхода на Rockstar, но смята пробива към масовия пазар за решаващ. Според официалното съобщение след девет месеца групата има 643 млн. злоти приходи и 358 млн. злоти печалба, а паричните резерви са нараснали до над 1,3 млрд. злоти. Само през третото тримесечие над 177 млн. злоти са вложени в разработката на нови проекти. The Witcher 3: Wild Hunt Remastered е достигнала при старта до 138 000 едновременни играчи в Steam, а Cyberpunk 2077 след Edgerunners 2 – над 187 000. Планирани са разширението Songs of the Past за 2027 г. и The Witcher 4 за 2028 г. Управителният съвет планира авансов дивидент от 1,20 злоти на акция, който още зависи от одитора и надзорния съвет.", "weitere_links": ["CD PROJEKT RED"], "_src": "c3d3360d"}, "2026-11-24-geforce-621-40-whql-ssd-fix": {"titel": "Nvidia пуска GeForce 621.40 WHQL и включва в редовния Game Ready драйвер поправката срещу прекомерните записи върху SSD във файла nvlog.nvlgstg", "schlagzeile": "GeForce 621.40 WHQL: Nvidia отново се захваща с лавината от записи върху SSD", "kurz": "Nvidia пусна Game Ready драйвера GeForce 621.40 WHQL. Най-важната промяна е поправка срещу масовите записи в лог файла nvlog.nvlgstg, които ненужно натоварват SSD дисковете. Грешката трябваше да бъде отстранена още с хотфикса 621.35, но при някои потребители се появи отново.", "zusammenfassung": "Според PCGH драйверът е наличен от 24 ноември за Windows 10 и 11 (64 бита), пакетът е около 1,04 GB и се изтегля през Nvidia App или от сайта на Nvidia. В бележките към версията Nvidia посочва Warhammer 40,000: Dawn of War 4, Assetto Corsa Rally и Where Winds Meet. Според PCGH обаче оптимизациите за игрите вече бяха в драйвера 621.24 от 12 ноември, а новото са главно поправките на грешки. Nvidia води грешката със SSD под номер 7116722. Според някои потребителски сигнали след хотфикса 621.35 записите са се връщали след няколко часа. Nvidia поправя и проблеми с Optix denoiser в Chaos Vantage при високи резолюции, както и грешни цветове при DJI D-Log видеа във формат H.265 в Снимки и Media Player на Windows. Дали лавината от записи ще изчезне с 621.40 на всички засегнати системи, тепърва ще се види, пише PCGH. Засегнатите потребители трябва да следят стойностите на записа на SSD след обновяването.", "weitere_links": ["TechPowerUp", "Wccftech"], "_src": "149efe71"}, "2026-11-24-gta6-pc-port-leonida-discord-aus": {"titel": "След страницата в GitHub офлайн е и Discord сървърът на неофициалния PC порт на GTA 6 Project Leonida, явно по искане на Rockstar и Take-Two; ръководителят на проекта се отказва", "schlagzeile": "GTA 6 на PC: Rockstar действа срещу фен порт, шефът на Leonida се отказва", "kurz": "Проектът Leonida, който искаше да пренесе изтеклата Xbox версия на GTA 6 на PC, след страницата си в GitHub загуби и своя Discord сървър. Според съобщения това е станало по искане на Rockstar и Take-Two. Основателят на проекта обяви, че се оттегля, но други групи продължават работа.", "zusammenfassung": "Според VGC се твърди, че Discord сървърът е бил спрян след искане на Rockstar и Take-Two, а официално изявление от компаниите няма. Insider Gaming съобщава, че основателят е писал в социалните мрежи за двегодишна забрана в Discord и е заявил, че е на 15 години и иска да се съсредоточи върху училището. Като други проекти за рекомпилация Leonida не трябваше да съдържа собствен exe, а да изисква легално копие. Благодарение на публикуваната от лийкъра Cyberleek разработческа версия на Xbox изданието заедно с exe файла обаче мнозина биха могли да заобиколят това изискване. Според PC Gamer ръководителите на проекта са се оттеглили, а други искат да го продължат. Няколко групи използват за програмирането AI чатботове като Claude, а първите видеа показват интрото с графични грешки, според VGC. VGC приема спиранията като знак, че Take-Two активно следи подобни проекти. Rockstar все още не е обявила официална дата за GTA 6 на PC. Който изтегля изтекли файлове, рискува зловреден софтуер и правни последици.", "weitere_links": ["Insider Gaming", "PC Gamer"], "_src": "a350078a"}, "2026-11-24-windows-family-safety-mtp-bluetooth-aus": {"titel": "Microsoft обявява края на приложението Family Safety в Windows и на MTP през Bluetooth; обикновеният трансфер на файлове през Bluetooth остава", "schlagzeile": "Windows 11: Microsoft премахва Family Safety и MTP през Bluetooth", "kurz": "Microsoft обявява за остарели още две функции на Windows: приложението Family Safety за Windows и Media Transfer Protocol през Bluetooth. Самата услуга Family Safety остава. Който изпраща файлове през Bluetooth по класическия начин, не е засегнат.", "zusammenfassung": "Според Neowin приложението Microsoft Family Safety за Windows трябва да изчезне от бъдещите версии на Windows в края на 2027 г., а новите инсталации вече няма да го съдържат. Дотогава тече преходен период, в който Microsoft ще изтегли и страницата в Microsoft Store. Родителите могат да продължат да управляват Family Safety чрез приложението Microsoft Family за смартфони или уеб портала. Второто премахване засяга MTP през Bluetooth, с който Windows управлява съдържание на смартфони, камери или медийни плейъри и синхронизира медийни библиотеки. Microsoft препоръчва вместо това MTP през USB. Според Neowin съветникът за трансфер на файлове през Bluetooth използва Object Push Profile и затова продължава да работи. Засегнати са само устройства, които разчитат на MTP през Bluetooth за управление на файлове или синхронизация на медия. Статията не посочва точна дата за премахването на MTP през Bluetooth.", "_src": "07483cc8"}, "2026-11-24-firefox-161": {"titel": "Mozilla пуска Firefox 161.0 с по-добър импорт от Chrome, изключения за Firefox VPN, клавишна комбинация за копиране на URL и раздел Classic Themes", "schlagzeile": "Firefox 161: по-лесно преминаване от Chrome и VPN изключения за сайтове", "kurz": "Mozilla пусна Firefox 161.0 за Windows, macOS и Linux. Сравнително малката актуализация подобрява импорта на данни от Google Chrome и позволява Firefox VPN да се изключва за определени сайтове. Добавени са и клавишна комбинация за копиране на текущия URL и по-добра подредба на темите и групите раздели.", "zusammenfassung": "Според Dr. Windows страницата с теми в браузъра получава собствен раздел за Classic Themes. Преминаващите от Chrome вече би трябвало да пренасят по-надеждно отметки и други данни от браузъра. Firefox VPN може да се изключи за отделни сайтове, например когато услуга блокира VPN връзки. URL адресът на текущия раздел вече може да се копира с клавишна комбинация. Групите раздели се показват и в менюто на приложението и така се намират по-лесно. Има и разширения на уеб платформата за разработчици. Според Dr. Windows Firefox 162 трябва да излезе на 8 декември 2026 г. като последна функционална актуализация за годината.", "weitere_links": ["LWN.net"], "_src": "2e828e9a"}, "2026-11-24-inno3d-rtx-5060-ti-single-slot-preis": {"titel": "Inno3D GeForce RTX 5060 Ti PRO с еднослотово охлаждане се появява в японски магазин за 169 400 йени, около 1064 долара", "schlagzeile": "Еднослотова RTX 5060 Ti за над 1000 долара: картата на Inno3D е в продажба", "kurz": "GeForce RTX 5060 Ti PRO на Inno3D, дебела само около 20 милиметра, се появи в продажба за първи път. Японски магазин иска 169 400 йени, около 1064 щатски долара. Така еднослотовата карта струва значително повече от обикновените модели RTX 5060 Ti.", "zusammenfassung": "Според Wccftech Inno3D е показала картата на сайта си още преди близо три месеца, без да посочи цена или наличност. Обявата в магазина Elsa Online е забелязана от известния хардуерен следотърсач momomo_us. Охлаждането използва парна камера и радиален вентилатор, който изхвърля топлината през задната част на кутията. Технически картата отговаря на обикновена RTX 5060 Ti 16 GB с 4608 CUDA ядра, 16 GB GDDR7, boost 2572 MHz и 180 W, а захранването идва през 8-пинов конектор. Същият магазин предлага обикновени RTX 5060 Ti с около 20 000 йени по-евтино. Заради силно поскъпналата памет RTX 5060 Ti 16 GB и без това вече струва над 800 долара вместо първоначалните 429 долара, според Wccftech. Inno3D насочва модела PRO към професионалисти и компактни работни станции, а не към типични геймърски компютри. Цена в евро все още не е известна.", "weitere_links": ["TechPowerUp"], "_src": "f36e15e3"}, "2026-11-24-red-dead-film-serie-rechte": {"titel": "Доклад: Rockstar предлага правата за филм и сериал по Red Dead Redemption и иска поне около 100 млн. долара; GTA остава извън сделката", "schlagzeile": "Доклад: Rockstar иска да продаде Red Dead Redemption като филм или сериал", "kurz": "Според доклад на The Ankler Rockstar Games търси купувач за правата за филм и сериал по Red Dead Redemption. Говори се за минимална цена от около 100 млн. долара. Според доклада Rockstar не планира адаптация на Grand Theft Auto.", "zusammenfassung": "Eurogamer се позовава на специализираното издание The Ankler, което от своя страна твърди, че е разговаряло с агенти. Rockstar не е потвърдила доклада. За сравнение докладът посочва 250-те млн. долара, които Amazon плати през 2017 г. само за сериалните права върху Властелинът на пръстените. Не е ясно защо Rockstar е отворена за Red Dead, но не и за GTA. Адаптациите на игри в момента се справят добре, примери са сериалът Fallout и The Last of Us на HBO. В процес на подготовка са между другото сериали по Tomb Raider, God of War и Far Cry, както и филм по Call of Duty за 2028 г. Според Eurogamer GTA 6 е реализирала 3,79 млрд. долара приходи през първия ден при 32,5 млн. продадени копия.", "weitere_links": ["Video Games Chronicle (VGC)", "Insider Gaming"], "_src": "03a22bc3"}, "2026-11-24-steam-markt-umbau-watchlist": {"titel": "Valve преработва началната страница на Steam Community Market: персонализирани списъци с тенденции, списък за наблюдение за няколко игри и промяна на цената без повторно обявяване", "schlagzeile": "Пазарът в Steam е преработен: списък за наблюдение и смяна на цената", "kurz": "Valve преработи началната страница на Steam Community Market. Вместо общ списък с популярни предмети тя вече показва тенденции от игрите, които човек сам играе. Нови са също списък за наблюдение и директната промяна на продажните цени.", "zusammenfassung": "Според PC Gamer Valve е обявила промените в понеделник, като това е вече второто преработване на пазара тази година след бета през май. Новата начална страница трябва да се зарежда по-бързо. Предишният раздел Popular Items показваше предимно кутии от Counter-Strike 2, а новите списъци Trending Items се основават на собствените игри на потребителя. В списъка за наблюдение могат да се следят отделни предмети, цели видове предмети или конкретни търсения в няколко игри. Цената на обявените оферти вече може да се промени, без те да се свалят и обявяват отново. Продажбите от приложението на Steam за смартфони могат да се потвърдят чрез изскачащ прозорец. Освен това началната страница показва напредъка на значките, а резултатите от търсенето са налични и като списък.", "_src": "bb7e53a4"}, "2026-11-24-gta6-deluxe-soundtrack-23-songs": {"titel": "Rockstar пуска делукс издание на албума със саундтрака на GTA 6 с 23 допълнителни парчета, сред които от HEALTH, Denzel Curry и Playboi Carti", "schlagzeile": "GTA 6: албумът със саундтрака получава 23 допълнителни песни в делукс изданието", "kurz": "Rockstar Games представи делукс издание на албума със саундтрака на GTA 6 с 23 допълнителни парчета. То е налично в стрийминг услугите. Сред изпълнителите са HEALTH, Denzel Curry и Playboi Carti.", "zusammenfassung": "Според Eurogamer пълният списък с парчетата е на официалния музикален сайт на Rockstar. Някои от артистите имат роля и в самата игра: дуото Justice е съавтор на оригиналния саундтрак и няколко от неговите парчета звучат в играта. Sexyy Red и Denzel Curry озвучават герои в по-късните глави. Появяват се също Kodak Black и Freddie Gibbs. Според Eurogamer в радиостанциите се чуват и гласовете на Кийт Ричардс, Лана Дел Рей и The Alchemist. По телевизионните предавания и рекламите в играта са работили като сценаристи между другото Зак Фокс и Weird Al Yankovic.", "_src": "c284c73f"}, "2026-11-24-proton-11-0-3": {"titel": "Valve пуска Proton 11.0-3 като нова стабилна версия с множество поправки за игри и обновени клонове на DXVK и VKD3D-Proton", "schlagzeile": "Proton 11.0-3: Valve прави още Windows игри играеми под Linux", "kurz": "Valve пусна Proton 11.0-3 като нова стабилна версия на своя слой за съвместимост за Windows игри под SteamOS и Linux. Обновлението събира много поправки, които досега бяха само в Proton Experimental. Някои игри стават играеми за първи път или отново.", "zusammenfassung": "Според GamingOnLinux обновлението се появява автоматично като актуализация на Proton 11 в изтеглянията на Steam. Отново играеми са между другото Lords of the Fallen, Lunacid и Command & Conquer: Red Alert Counterstrike и The Aftermath, а Deus Ex: Mankind Divided би трябвало отново да работи с графика на AMD. Crysis и Crysis Wars вече стартират и на по-нови процесори на AMD с CPUID faulting. Поправени са също сривове в RaceRoom Racing при влизане в класирани състезания и в Terminator: Dark Fate - Defiance, както и проблеми със звука в няколко по-стари игри. Поддръжката на контролери със Steam Input е подобрена във Far Cry New Dawn, The Binding of Isaac: Rebirth и Split/Second, а в Dragon Age: Inquisition контролерите отново работят. Лаунчерът на Final Fantasy XIV вече работи и на Steam Frame на Valve. Под капака DXVK и VKD3D-Proton са обновени до най-новото състояние на клоновете си за Proton 11, обновен е и dxvk-nvapi. Има първа, все още експериментална поддръжка на 32-битов OpenXR. GamingOnLinux очаква Proton 12 едва догодина, след излизането на Wine 12.", "weitere_links": ["Phoronix"], "_src": "0697b312"}, "2026-11-24-rtx-lens-12v-2x6-pin-ueberwachung": {"titel": "Инструментът с отворен код RTX Lens следи тока на всеки отделен пин на 12V-2×6 при съвместими видеокарти, измервателни адаптери и захранвания и може да изключи Windows при продължително предупреждение", "schlagzeile": "RTX Lens: безплатен инструмент следи всеки пин на видеокартата", "kurz": "Безплатният инструмент с отворен код RTX Lens събира данни от сензорите на видеокартата, конектора 12V-2×6 и захранването и показва тока на всеки пин. Ако зададено от потребителя предупреждение се задържи, той може да изключи Windows по контролиран начин. Решаващите стойности обаче идват само от подходящ хардуер; обикновените GeForce карти сами не стигат.", "zusammenfassung": "Фонова услуга чете сензорите непрекъснато, при желание записва игрови сесии или бенчмаркове и реагира на свободно задавани прагове. Причината е трайният проблем с претоварени конектори 12V-2×6: общата мощност не показва как токът се разпределя между шестте линии от 12 V. ComputerBase посочва собствената си GeForce RTX 5090, при която един пин за известно време отпадна напълно, докато други се приближаваха до границата от 10 ампера. Стойности за отделните пинове има само с подходящи сензори: директно се поддържат Asus ROG Astral RTX 5080 и RTX 5090, измервателният адаптер Thermal Grizzly WireView Pro II и захранванията MSI MPG Ai1300TS и Ai1600TS. С Astral или WireView могат дори да се сравнят двата края на кабела. Обикновените GeForce карти дават само честота, температура, обороти на вентилаторите и натоварване. Аварийното изключване изключва Windows, но само не прекъсва захранването. Към проекта има съпътстващи приложения за Android и iOS (APK се инсталира ръчно, iPhone през AltStore) и уиджет само за четене за Xeneon Edge на Corsair. RTX Lens работи на 64-битов Windows 11 и Windows 10 от build 17763 и е в GitHub под LGPL 3.0. Той не замества правилно включения кабел; това е инструмент за наблюдение, а не прекъсвач.", "_src": "0589ef97"}, "2026-11-24-megaspeed-us-handelsembargo": {"titel": "САЩ включват Megaspeed и други фирми в експортния списък: пълно търговско ембарго срещу седем компании в Сингапур, Тайланд и Малайзия от сряда", "schlagzeile": "Аферата Nvidia: САЩ налагат търговско ембарго на Megaspeed", "kurz": "САЩ включват седем компании от Сингапур, Тайланд и Малайзия в черния списък на експортните си правила, шест от тях са част от мрежата Megaspeed. От сряда на тях не могат да се доставят американски стоки или продукти, произведени с определена американска технология. Megaspeed е организирала AI чипове на Nvidia за клиенти в Китай.", "zusammenfassung": "Според heise в сряда влиза в сила пълно американско търговско ембарго, а не само ограничение за определен хардуер. То засяга шест фирми на Megaspeed и дъщерното дружество на Alibaba Apex Enterprise Solutions, което е предоставило на Megaspeed милиардите долари, с които от юни 2024 са купувани AI процесори от Nvidia. Стоки, които вече са на път, още могат да бъдат доставени, но фирмите не могат да предават това, което вече притежават. Могат да се искат изключения, но обикновено се отхвърлят. Обвинението е, че Megaspeed е хостнала чиповете в центрове за данни и е отдавала изчислителната мощ под наем, особено на клиенти в Китай, и така е заобиколила забраната за износ. Министерството на правосъдието на САЩ проверява освен това дали Megaspeed е подпомагала и контрабандата на AI чипове към Китай; Megaspeed посочва вътрешно разследване. Според heise Nvidia е спряла продажбата на засегнатите чипове на Megaspeed през юни 2025. Случаят е свързан с аферата около Дженсън Хуанг, който призна връзка с бившата шефка на Megaspeed Алис Хуанг, която според американските служби работи за китайска разузнавателна служба, което Пекин отрича. Според heise на Alibaba още е дадена възможност да вземе отношение. Ембаргото няма пряко значение за геймърските видеокарти; то засяга AI ускорители.", "_src": "b299fec4"}, "2026-11-24-mesa-nvk-raytracing-ttu": {"titel": "Mesa NVK: първата поддръжка на инструкциите Tree Traversal Unit на RT ядрата в шейдър компилатора NAK е още една стъпка към Vulkan ray tracing", "schlagzeile": "Mesa NVK: отвореният драйвер на Nvidia се приближава до ray tracing", "kurz": "В Mesa 27.0-devel е внесена първата поддръжка на инструкциите Tree Traversal Unit на RT ядрата на Nvidia в шейдър компилатора NAK на драйвера с отворен код NVK. Това е още една стъпка, за да може NVK по-късно да поддържа Vulkan ray tracing. Още не е завършено.", "zusammenfassung": "Според Phoronix промяната е внесена в неделя в Mesa 27.0-devel. Инструкциите TTU управляват RT ядрата при GPU на Nvidia. Промяната засяга обработката в шейдър компилатора NAK и вътрешните функции на междинното представяне NIR. Целта е NVK да поддържа разширенията на Vulkan VK_KHR_ray_query и VK_KHR_ray_tracing_pipeline. Срок не е определен; Phoronix само се надява работата да приключи през 2027. За Linux геймърите с карта на Nvidia дотогава проприетарният драйвер остава изборът, ако им трябва ray tracing.", "_src": "57fe9bd8"}, "2026-11-24-ladybird-alpha-macos-linux": {"titel": "Ladybird достига алфа статус: независим браузър със собствен двигател за macOS и Linux, с автоматични актуализации в непрекъснат канал", "schlagzeile": "Ladybird е в алфа: браузър с напълно собствен двигател", "kurz": "Независимият браузър Ladybird излезе като първа алфа за macOS и Linux. Работи на двигател, изграден от нулата, а не произлизащ от Chromium, WebKit или Gecko. Някои уебсайтове още не работят, сривове са очаквани и изрично не се дават обещания за сигурността.", "zusammenfassung": "Според Neowin и OMG! Ubuntu браузърът е стигнал до алфа след четири години разработка. Разработчиците го наричат скромен, но използваем. Неработещи страници могат да се докладват директно в браузъра; след срив може да се прочете докладът и да се реши дали да се изпрати. Новост е непрекъснат канал с автоматични актуализации; досега потребителите трябваше сами да компилират новите версии от изходния код. За уеб разработчици има поддръжка на WebDriver и на протокола Firefox DevTools. Разработчиците призовават изследователите по сигурност да атакуват браузъра и не обещават нищо за сегашната сигурност, затова той още не е за чувствителна ежедневна употреба. Съобщението не споменава версия за Windows. Neowin напомня, че проектът е затворил публичните pull request заради лошо използване на ИИ.", "weitere_links": ["OMG! Ubuntu"], "_src": "47e4fe1e"}, "2026-11-24-teams-voice-phishing-erkennung": {"titel": "Microsoft Teams ще проверява външни обаждания с ИИ за опити за измама чрез „Voice Phishing Detection“; според плана от януари 2027", "schlagzeile": "Teams ще засича измамни обаждания с ИИ – неясноти за поверителността", "kurz": "Според пътната карта на Microsoft 365 Teams ще използва ИИ, за да проверява външни обаждания един към един за измамни схеми и да предупреждава чрез „Voice Phishing Detection“. Функцията е планирана за януари 2027 на настолни системи, Android и iOS. Неясно е дали анализът се върши локално или в облака и какво се съхранява.", "zusammenfassung": "Досега Teams има засичане на спам за подозрителни обаждащи се. Новата функция трябва да отиде по-далеч и да анализира самия разговор, например когато някой се представя за IT администратор и поиска данни за вход. Neowin се позовава на запис в пътната карта на Microsoft 365 и на документацията на Teams за политики за обаждания. Администраторите трябва да могат да задават как се предупреждават потребителите, но според Microsoft настройката още няма ефект. Microsoft не е обяснила дали анализът става на устройството или на сървъри. Неясни са и съхранението на данни от разговорите и съвместимостта с криптирани от край до край обаждания. Neowin посочва още, че нападатели биха могли да приспособят методите си към засичането с ИИ. Засега това е само запис в пътна карта; срокът и обхватът може да се променят.", "_src": "72ba9edc"}, "2026-11-24-gta6-exe-leak-leonida-pc-port": {"titel": "Изтекчикът Cyberleek уж е публикувал изпълнимия файл на Xbox версията на GTA 6; проектът за порт с помощта на ИИ Leonida стига с него само до черен екран и след това е свален", "schlagzeile": "Изтичане: exe на GTA 6 в мрежата – портът Leonida стига само до черно", "kurz": "Изтекчикът Cyberleek уж е публикувал на 23 ноември и изпълнимия файл на Xbox версията на GTA 6. Проектът Leonida искал да стартира играта под Windows чрез прекомпилиране, но стигнал само до черен екран и после бил свален заедно с Discord и GitHub. Играем порт за PC следователно няма, а предложенията за изтегляне крият рискове от зловреден софтуер и правни рискове.", "zusammenfassung": "Според PCGH вече е циркулирал пакет от около 209 GiB, на който при старта на конзолата на 19 ноември е липсвал exe файлът. Cyberleek първо вързал публикуването към цели за пазарна капитализация на своя крипто токен, не постигнал нито една и въпреки това публикувал файла като защитен с парола ZIP. Xbox exe файлът не може да се стартира директно под Windows; смята се за материал за разработчици на емулатори и проекти за прекомпилиране. Проектът Leonida иска да изпълнява x86-64 кода директно на PC процесори и да пресъздаде системната среда на Xbox: според собствените му данни шейдърите са преведени от RDNA 2 към SPIR-V, а командите на Xbox Direct3D 12 трябва да се пренасочат към Vulkan. Според PCGH все още липсват mesh shader draws, indirect draws и ray tracing. Първите опити за стартиране завършили с черна картина и прекъсващ звук. Един от основните разработчици очаквал поне седмица работа, докато играта може да тръгне; този срок е чиста самооценка. Според PCGH целият проект междувременно е свален; неизвестно е дали Rockstar е подала DMCA искане. Хранилището не съдържало файлове на играта или ключове, но според README изисквало копие на Xbox версията, която според досегашните данни идва от изтичането. Според PCGH участващите разработчици са използвали интензивно AI агенти за програмиране. Който изтегля изтекли файлове, рискува зловреден софтуер и правни последствия; официална дата за PC от Rockstar още няма. Умишлено не свързваме източници за изтегляне.", "ursprungsquelle": "Изтекчикът „Cyberleek“ (exe публикуван на 23.11.2026); разработчиците на проекта „Leonida“ с помощта на ИИ чрез X и Discord", "weitere_links": ["Golem.de"], "_src": "3e3ca74b"}, "2026-11-24-call-of-duty-minus-42-prozent-gta6": {"titel": "Alinea Analytics: приложението Call of Duty губи 42 процента от дневните си играчи след старта на GTA 6, от 7,6 на 4,4 милиона", "schlagzeile": "GTA 6 удря Call of Duty: анализатори виждат 42% по-малко играчи", "kurz": "Според Alinea Analytics броят на дневните играчи на приложението Call of Duty е паднал с 42 процента след старта на GTA 6, от 7,6 на 4,4 милиона. На PS5 спадът е най-голям – 44 процента. Това са оценки на аналитична фирма; официални данни от Activision няма.", "zusammenfassung": "IGN съобщава за анализ на Alinea Analytics, който CharlieIntel разпространи и в X. Приложението Call of Duty включва Warzone, Black Ops 7 и Modern Warfare 4. Сравнени са дневните играчи преди и след рекордния уикенд на GTA 6. Съобщението не казва как са събрани данните; това са оценки. IGN отбелязва, че аудиториите вероятно се припокриват силно. Маркетинг директорът на Activision Тайлър Бал каза през есента, че GTA 6 по-скоро ще привлече внимание към цялата индустрия. Краткосрочно Alinea показва обратното, но може да се нормализира. IGN спекулира още, че излизане за PC в началото на 2027 и онлайн режим може отново да ударят Call of Duty; това е само контекст без официални дати.", "_src": "f967c32d"}, "2026-11-24-gta6-39-millionen-ps5-spieler": {"titel": "Sony: над 39 милиона играчи на PS5 за четири дни, рекорд за едновременни играчи при игра за PlayStation – средно 17,4 часа", "schlagzeile": "GTA 6: Sony отчита 39 млн. играчи на PS5 и нов рекорд", "kurz": "В публикация в блога на PlayStation Sony съобщава за над 39 милиона отделни играчи на GTA 6 на PS5 от старта. Така това е най-големият старт в историята на PlayStation. GTA 6 постави и рекорд за едновременни играчи при игра за PlayStation.", "zusammenfassung": "Числата дава мениджърът по съдържание на Sony Тим Тури в публикация в блога; пишат за това PC Gamer, IGN и VGC. Според Sony над 39 милиона отделни играчи са играли GTA 6 на PS5 от старта на 19 ноември. Средно те са изкарали 17,4 часа за четири дни. Sony добавя, че GTA 6 е достигнала най-голям брой едновременни играчи сред всички игри за PlayStation и е надминала предишни рекорди при мултиплейър, free-to-play и сингъл игри. Sony не посочва конкретното число на едновременните играчи; оценката на PC Gamer за до три-четири милиона е само екстраполация. Това са данни на производителя за играчи, не за продадени копия, и важат само за PS5; съобщението не дава числа за Xbox. Rockstar още е зад над 230-те милиона копия на GTA 5, а играта също ще излезе някога за PC.", "weitere_links": ["IGN", "Insider Gaming"], "_src": "9ad8cf1c"}, "2026-11-24-azure-apim-luecke-zugangsdaten": {"titel": "Microsoft предупреждава: уязвимост в Azure API Management Classic е била използвана за кражба на съхранявани API данни за достъп – норвежки власти виждат атаки срещу енергийни компании", "schlagzeile": "Дупка в Azure: нападатели откраднаха API данни на клиенти", "kurz": "Microsoft предупреди клиентите, че уязвимост в нивата Classic на Azure API Management е била използвана за извличане на съхранявани данни за достъп. Според Microsoft уязвимостта е била затворена с мярка за смекчаване на следващия ден след откриването ѝ. Вече откраднатите данни не стават невалидни с това, затова засегнатите трябва да ги подновят.", "zusammenfassung": "Според BleepingComputer са засегнати нивата Developer, Basic, Standard и Premium на APIM Classic, но не и нивото Consumption и всички нива на APIM v2. Неупълномощено лице е можело да достъпва функции за управление, ако инстанциите не са били конфигурирани според препоръчаните практики за сигурност. Към възможно разкритите данни спадат тайни в Named Values, client secrets на доставчици на идентичност и на OpenID Connect, абонаментни ключове и токени за управленски API. Microsoft затвори пътя за достъп на 19 ноември и смени собствените си ключове, но подчертава, че това не обезсилва автоматично данните на клиенти, които може да са изтекли преди това. Клиентите трябва веднага да подновят потенциално засегнатите данни, да проверят логовете и да следят за подозрителна активност. Норвежката агенция за сигурност NSM свързва уязвимостта с атаки срещу енергийните компании Equinor и Skagerak Energi и съветва да се проверят версиите на средата за изпълнение на собствените инстанции. Microsoft заяви, че поправката е внедрена във всички хоствани от Microsoft инстанции без действие от клиента; защо NSM въпреки това съветва проверка, остана неясно. Администратор описа в Reddit, че е бил злоупотребен стар API без логове; BleepingComputer не можа да потвърди това независимо. Съобщението следва инцидента с Entra Connect Health, за който вече писахме.", "_src": "7b116c8b"}, "2026-11-24-mesa-27-radeonsi-radeon-kernel-treiber": {"titel": "Mesa 27.0: RadeonSI изключва по подразбиране поддръжката на стария Radeon драйвер на ядрото – засегнати са видеокарти GCN 1.0 и GCN 1.1", "schlagzeile": "Mesa 27.0: старите Radeon трябва да минат на драйвера AMDGPU", "kurz": "В Mesa 27.0 поддръжката на стария Radeon драйвер на ядрото от RadeonSI е изключена по подразбиране. Засегнати са ранните карти GCN 1.0 и GCN 1.1, които допреди около година още ползваха този драйвер по подразбиране. Който обновява Mesa, трябва да мине на Linux 7.1 или по-нов с AMDGPU.", "zusammenfassung": "Според Phoronix разработчикът на AMD Pierre-Eric Pelloux-Prayer е внесъл промяната в Mesa 27.0-devel. Драйверът на ядрото AMDGPU междувременно е достигнал функционално равенство за старите карти. Който ползва GCN 1.2 или по-нови, не е засегнат, както и картите преди GCN, които продължават да ползват драйвера R600. За тези, които обновяват Mesa, но запазват много старо ядро, засега има променливата на средата AMD_DEBUG=use_radeon. В Mesa 27.1 или по-късно тази поддръжка може да бъде премахната изцяло. Засегнати са Radeon HD 7000 и някои наследници. Промяната е засега само в разработческия клон; излизането на Mesa 27.0 още предстои.", "_src": "8cd3b57c"}, "2026-11-24-steam-awards-2026-nominierungen": {"titel": "Valve започва номинациите за Steam Awards 2026 по случай десетата годишнина: нови категории и Зала на славата с десетте досегашни игри на годината", "schlagzeile": "Steam Awards 2026: номинациите са отворени, GTA 5 срещу Elden Ring", "kurz": "Valve започна фазата на номинации за Steam Awards 2026, която продължава до 30.11. За десетата годишнина има три нови категории и Зала на славата, в която десетте досегашни игри на годината се състезават помежду си. Гласуването започва със зимната разпродажба на 17.12.", "zusammenfassung": "Новите категории са „Just Five More Minutes“, „Defies Description“ и „This is My Job Now“. Според PC Gamer в Залата на славата са GTA 5 (2016), The Witcher 3 (2017), PUBG (2018), Sekiro (2019), Red Dead Redemption 2 (2020), Resident Evil Village (2021), Elden Ring (2022), Baldur's Gate 3 (2023), Black Myth: Wukong (2024) и Hollow Knight: Silksong (2025). Тази категория е ограничена до десетте заглавия. Във всички останали категории може да се номинира всяка игра, излязла през 2026. Steam показва списък с изиграни и популярни игри, но могат да се въвеждат и свои предложения. Както обикновено, номинирането носи значки в Steam. Номинираните ще бъдат обявени в началото на зимната разпродажба на 17 декември, когато започва гласуването.", "_src": "93143796"}, "2026-11-23-oledtextfix-farbsaeume": {"titel": "Инструментът с отворен код OLEDTextFix трябва чрез GPU наслагване да намалява цветните ореоли по текста на QD-OLED и WOLED монитори под Windows", "schlagzeile": "Цветни ръбове по буквите? Безплатен инструмент за OLED мониторите", "kurz": "Безплатната програма с отворен код OLEDTextFix трябва да намалява под Windows цветните ореоли около буквите на QD-OLED и WOLED монитори. За целта тя обработва готовото изображение на работния плот на GPU и го поставя като наслагване върху екрана. heise я изпробва: на 27-инчови WQHD монитори помага видимо, но струва ток и има недостатъци.", "zusammenfassung": "Причината за ореолите е подредбата на субпикселите, защото Windows ClearType е създаден за LCD с разположени една до друга RGB ивици. При QD-OLED зеленото обикновено е над червеното и синьото, а WOLED използва и бял субпиксел. OLEDTextFix прихваща картината чрез интерфейса DXGI Desktop Duplication, измества цветовите канали според субпикселите и показва резултата като пропускащо кликове наслагване. Не са нужни намеси в драйвери, рендериране на шрифтове или регистъра. За QD-OLED има готови профили, например за 27 инча с WQHD и 32 инча с 4K, плюс филтрите Sharp, Balanced и Smooth. Според разработчика ореолите намаляват с малко под 60 до над 70 процента на тъмен фон, но само с около 17 до 18 процента на светъл. В теста на heise ефектът почти не се забелязваше на 4K монитора и беше по-ясен на 27-инчовия WQHD, но ореолите по вертикалните линии отчасти останаха. При движение ореолите за кратко се връщат, защото наслагването закъснява с около един кадър. Менюто „Старт“, лентата на задачите и известията отчасти остават некоригирани. Консумацията на тестовата система в покой се повиши от около 23 на 25 до 32 вата, а при движение на мишката до 56 вата. Инструментът работи от Windows 10 версия 2004 нагоре, изисква GPU с поддръжка на DirectX 11 и не е подписан, затова SmartScreen може да предупреди. Разработчикът го определя като експериментален, WOLED профилите още не са тествани на реални панели, а Ctrl+Alt+F изключва ефекта веднага.", "weitere_links": ["PC Games Hardware (PCGH)"], "_src": "813795e2"}, "2026-11-23-xbox-helix-multiplayer-gratis-leak": {"titel": "Доклад: Microsoft е обмисляла премахване на платения онлайн мултиплейър за следващия Xbox (Project Helix) – при новото ръководство въпросът отново е отворен", "schlagzeile": "Изтичане: Щеше ли онлайн мултиплейърът на следващия Xbox да е безплатен?", "kurz": "Според редактора на Windows Central Джез Кордън Xbox е проучвал премахването на платения онлайн мултиплейър за следващата конзола Project Helix. Това е било част от по-ранна концепция Helix да бъде пълноценен геймърски компютър. При шефката на Xbox Аша Шарма Helix трябва да е по-скоро класическа конзола, така че платената бариера може да остане.", "zusammenfassung": "Insider Gaming обобщава доклада на Windows Central, който се позовава на източници. Според него първоначално Helix е трябвало да бъде по същество пълноценен геймърски компютър, на който да вървят и всички досегашни Xbox конзолни игри. Подобно на преносимите Xbox Ally потребителите е щяло да могат да инсталират собствен софтуер, включително Steam. В този модел платената бариера за онлайн мултиплейър е щяла да отпадне. Според доклада това е бил планът при предишното ръководство с Фил Спенсър и Сара Бонд. Откакто Аша Шарма ръководи Xbox, разговорите са се променили и Helix се възприема по-скоро като класическа конзола, която може да пуска и PC игри. Това съвпада със собственото изявление на Microsoft в юбилейното списание, че Helix е конзола, която може и PC игри, а не PC за конзолни игри. Така платеният мултиплейър, включен в почти всички нива на Game Pass, може да остане. Той е важен източник на приходи още от появата на Xbox Live през 2002 г., а високите цени на компонентите правят допълнителните приходи по-важни. Нищо от това не е официално потвърдено.", "ursprungsquelle": "Windows Central (Джез Кордън), чрез Insider Gaming", "_src": "cfd7e861"}, "2026-11-23-lexar-expo-ull-39-prozent": {"titel": "Lexar рекламира до 39 процента повече fps с AMD EXPO ULL при DDR5-6000 CL28 – PCGH смята стойността за трудно защитима", "schlagzeile": "39% повече fps само от RAM профил? PCGH се съмнява в данните на Lexar", "kurz": "Lexar обещава за своя кит ARES RGB 2nd Gen DDR5-6000 CL28 с профила EXPO ULL до 38,86 процента повече fps. PCGH смята това за почти невъзможно. Собствените тестове на редакцията показаха при самата смяна на профила едва около три до четири процента.", "zusammenfassung": "Сравнението прави впечатление: Lexar не мери спрямо JEDEC памет, а спрямо нормалния EXPO профил със същата скорост и същата CAS латентност. EXPO ULL съхранява основно по-стегнати субтайминги, без да вдига честотата или основните тайминги. Lexar е тествала с Ryzen 5 9600X, Asus TUF Gaming B850M-Plus WiFi 7 и GeForce RTX 5080 в Counter-Strike 2, Valorant и Delta Force. В зависимост от играта средните fps трябва да растат с 1,25 до 38,86 процента, а 1% lows с 1,67 до 22,13 процента, като върховите стойности и в двата случая са от Delta Force. Lexar не посочва резолюция, графични настройки, тестови сцени, абсолютни fps и пълните тайминги. През юли PCGH отчете с Ryzen 5 9600X и RTX 5090 в дванадесет игри ръст на индекса от около три до четири процента. Hardware Unboxed измери с Ryzen 7 9700X до 15 процента в Baldur's Gate 3, а Igor's Lab 5,8 процента в Assetto Corsa Competizione. PCGH не оспорва, че по-стегнатите субтайминги носят производителност в игрите, а само мащаба. Китът е преминал сертификацията EXPO 1.2, което говори за стабилност, но нищо не казва за производителността. Ако планирате ъпгрейд, по-добре се ориентирайте по независими тестове, отколкото по данни на производителя.", "_src": "8cef570a"}, "2026-11-23-gta6-hacker-auflagen-frei": {"titel": "Хакерът на GTA 6 от 2022 г. е освободен при условия: съдът ограничава онлайн дейността му за пет години, Telegram и Discord са забранени", "schlagzeile": "Хакерът на GTA 6 е на свобода – с пет години онлайн ограничения", "kurz": "Британецът, който през 2022 г. хакна Rockstar Games и публикува ранни видеа от GTA 6, е освободен при условия. Съдът му наложи петгодишна мярка, която ограничава онлайн дейността му, включително забрана за Telegram и Discord. Според BBC съдията го предупредил, че това не бива да се повтаря.", "zusammenfassung": "Сега 21-годишният мъж се призна за виновен в съда миналата седмица за хакването на Rockstar и други компании. Според VGC, което се позовава на BBC, сега той е получил т.нар. Serious Crime Prevention Order, която за пет години ограничава ползването му на интернет. Част от нея е забрана да използва Telegram и Discord. Според IGN е освободен при условия, защото вече е излежал голяма част от наказанието си. Мъжът е бил част от хакерската група Lapsus$, която атакува и Uber, Nvidia и британския мобилен оператор EE. Заради диагноза тежък аутизъм първоначално е бил настанен в охранявана болница, а по-късно е обявен за годен да бъде съден. През септември 2022 г. той публикува около час недовършен материал от GTA 6, който за първи път показа и главната героиня Лусия. Според BBC съдията го нарекъл „много талантлив млад човек“. Публикациите се различават в подробностите за предишното му задържане и настаняване.", "weitere_links": ["IGN"], "_src": "86064ace"}, "2026-11-23-samsung-odyssey-g6-1100hz": {"titel": "Samsung Odyssey G6: 27-инчов геймърски монитор с IPS панел трябва да постига 600 Hz в WQHD и 1100 Hz при намалена резолюция", "schlagzeile": "Samsung Odyssey G6 с 1100 Hz – но IPS панелът буди съмнения", "kurz": "Новият Samsung Odyssey G6 е 27-инчов монитор с WQHD резолюция и до 600 Hz. В режим „Dual Mode“ при намалена резолюция трябва да достига дори 1100 Hz. В САЩ се очаква да излезе през декември за около 900 долара.", "zusammenfassung": "Панелът е IPS LCD с 2560 × 1440 пиксела; според Samsung превключва от сиво към сиво за 1 милисекунда. С „Dual Mode“ може бързо да се превключва между родната резолюция при 600 Hz и по-ниска резолюция при 1100 Hz. Публикациите не посочват еднозначно коя точно резолюция важи в режима с 1100 Hz. Срещу размазване и пресвръх Samsung разчита на технология, наречена „Odyssey Clear Motion“; как точно работи, още не е ясно. Мониторът поддържа HDR10+ Gaming, съвместим е с G-Sync и поддържа FreeSync Premium. Има един DisplayPort 2.1 и два HDMI 2.1, а стойката е регулируема по височина и позволява завъртане във вертикален режим. heise е скептичен: за 1100 Hz един пиксел трябва да превключва за около 0,9 милисекунди, а при 600 Hz за около 1,7 милисекунди. Редакцията досега не е измерила IPS панел със средно време за реакция под една милисекунда. Това вероятно е постижимо само със силен overdrive, който може да създава светли ореоли по движещи се ръбове. По време за реакция OLED мониторите имат ясно предимство. Samsung още не е обявил цена в евро, а независими тестове предстоят.", "weitere_links": ["Neowin"], "_src": "0f0d7d08"}, "2026-11-23-gta6-patch-01-002-002": {"titel": "Ъпдейт 01.002.002 за GTA 6 поправя дефектни автоматични записи, заседнало време и неактивиращи се сюжетни обаждания на PS5 и Xbox Series X/S", "schlagzeile": "Първи пач за GTA 6: Rockstar поправя автозаписа и блокажите в сюжета", "kurz": "Rockstar пусна ъпдейт 01.002.002 за GTA 6. Той поправя между другото дефектния автоматичен запис, времето, което дълго не се сменя, и телефонни обаждания, които можеха да блокират напредъка в сюжета. Изтеглянето е около 604 MB на PS5 и около 1,6 GB на Xbox Series X/S.", "zusammenfassung": "Това е първият ъпдейт след премиерата на 19 ноември; според Eurogamer бележките към пача са на сайта на Rockstar. Според тях са поправени времето, което дълго не се сменяше, дефектният автоматичен запис и няколко обаждания, които не се активираха, включително такива, които движат сюжета или отключват мисии. Освен това играчите понякога не можеха да се отърват от нивото на издирване, да използват щангата във фитнеса или да получат от партньорите си чанти за продажба на прекупвачи. Особено грешката с автозаписа предизвика недоволство, няколко играчи и стриймъри съобщиха за изгубен напредък. В най-известния случай според Eurogamer са изгубени около дванадесет часа на PS5. VGC съветва въпреки пача за всеки случай редовно да записвате ръчно. Според Eurogamer Rockstar не е адресирал силната винетка по краищата на картината, която мнозина критикуват.", "weitere_links": ["Eurogamer", "Insider Gaming"], "_src": "aa3457f1"}, "2026-11-24-asus-8-gb-ram-einsteiger-pcs": {"titel": "Съпредседателят на ASUS Hsu при разговора за резултатите от третото тримесечие: входните компютри може отново да излизат само с 8 GB RAM заради растящите цени на паметта", "schlagzeile": "Криза с RAM: ASUS очаква връщане към 8 GB при евтини PC", "kurz": "Съпредседателят на ASUS S.Y. Hsu казва, че входните и средните компютри може отново да се предлагат само с 8 вместо 16 GB RAM заради по-високите разходи за памет. ASUS е работила по това с Microsoft, а Microsoft е адаптирала Windows съответно.", "zusammenfassung": "Изявлението е от разговора за резултатите на ASUS за третото тримесечие на 2026; TechPowerUp го цитира чрез StockAnalysis. Според Hsu ASUS е утвърдила 16 GB като стандарт, за да осигури добро потребителско изживяване. Заради растящите разходи за памет базата може отново да падне до 8 GB. При новата операционна система Microsoft е направила корекции, така че дори 8 GB да дават приемливо изживяване. Съобщението не посочва конкретни модели, цени или дата на пускане; това е очакване, а не обявяване на продукт. TechPowerUp напомня, че през май 2026 Microsoft за кратко е посочила 32 GB като препоръка на уебсайта си и после е премахнала бележката. За купувачите това означава: при покупка на евтин готов компютър или лаптоп си струва да се погледне количеството RAM, особено ако паметта е запоена. Съобщението пасва на неотдавнашни доклади за дългосрочно резервирани DRAM капацитети при големите производители.", "_src": "bcecd2c8"}, "2026-11-23-dlss5-where-winds-meet-regler": {"titel": "Where Winds Meet поддържа DLSS 5 като трета игра – за първи път с три свободно настройваеми плъзгача за невронното рендериране на Nvidia", "schlagzeile": "DLSS 5 по ваш вкус: Where Winds Meet за първи път има плъзгачи", "kurz": "Безплатната игра Where Winds Meet поддържа от 23 ноември DLSS 5 на Nvidia с карти GeForce RTX 50. Като първа игра тя предлага освен вкл./изкл. и три плъзгача от 0 до 100. ComputerBase хвали ефекта, но критикува стойностите по подразбиране.", "zusammenfassung": "След NBA 2K27 и Hogwarts Legacy Where Winds Meet е третата игра с официална поддръжка на DLSS 5. Понеже е безплатна, всеки собственик на GeForce RTX 50 може да изпробва невронното рендериране. Студиото посочва за целта драйвера Game Ready 621.24; точно за тази версия наскоро имаше сигнали за прекомерни записи върху SSD, за които Nvidia пусна впоследствие хотфикс 621.35. Трите плъзгача се казват Tone Intensity за светлина и цветове, Structure Intensity за повърхности и сенки и Character Intensity за кожа, лица и ръце. По подразбиране са на 100, 100 и 40. ComputerBase вижда значително по-обемно осветление, по-резки текстури и по-малко гумени лица, макар на места картината да изглежда пренаострена. Най-голямата критика е, че със стойностите по подразбиране осветлението става осезаемо по-студено и топлите цветове отчасти се губят. Редакцията препоръчва 70 до 80 за Tone и Structure и 40 до 50 за Character. Както в другите игри с DLSS 5, героите в движение понякога имат светъл контур; според ComputerBase Nvidia знае за проблема. DLSS 5 струва много производителност, но благодарение на високата базова производителност на играта RTX 5070 остава играема в WQHD според теста.", "weitere_links": ["Where Winds Meet (официално съобщение)"], "_src": "73e480bf"}, "2026-11-23-huang-wieder-nvidia-ceo": {"titel": "Бордът на Nvidia връща Дженсън Хуанг като президент, CEO и член на борда с незабавен ефект – разследванията продължават", "schlagzeile": "Обрат в Nvidia: Дженсън Хуанг отново е CEO", "kurz": "Бордът на директорите на Nvidia единодушно и с незабавен ефект отново назначи Дженсън Хуанг за президент, CEO и член на борда. След консултации с високопоставени представители на правителството на САЩ бордът не вижда риск за националната сигурност. В зависимост от момента акцията поскъпна с 25 до 35 процента след новината.", "zusammenfassung": "Хуанг подаде оставка в средата на ноември след разкрития за извънбрачни връзки, включително с мениджърката от Megaspeed Алис Хуанг, на която се приписват връзки с китайското разузнаване. Според съобщението на Nvidia бордът е провел няколко разговора с него и след това се е убедил в откровеността и способността му да ръководи. Председателят на борда Харви Джоунс нарича Хуанг правилния човек да ръководи Nvidia. Самият Хуанг казва, че поема отговорността „с най-голямо смирение“. Колет Крес, която временно беше CEO, остава финансов директор. Аферата обаче не е приключила: независима комисия продължава да разследва предполагаемата намеса на чуждо разузнаване, а Хуанг обещава пълно съдействие. Освен това Nvidia създава собствена комисия за национална сигурност и експортен контрол и търси Chief Compliance Officer. Според ComputerBase в началото на декември Хуанг трябва да отговаря и на въпроси в няколко комисии на Конгреса на САЩ. Само сутринта New York Times съобщи, че американските разузнавателни служби са събрали данни за по-дълготрайни контакти на Алис Хуанг с китайското Министерство на държавната сигурност. Въпреки това борсата реагира еуфорично: в зависимост от източника и момента преди това силно поевтинялата акция беше нагоре с 25 до 35 процента. За клиентите на GeForce в краткосрочен план нищо не се променя, но завръщането засега слага край на несигурността на върха на компанията.", "weitere_links": ["ComputerBase", "heise online", "Neowin", "ComputerBase (доклад на NYT за Алис Хуанг)"], "_src": "5756a084"}, "2026-11-23-rtx-60-erst-2028-leak": {"titel": "Изтичане от Moore's Law Is Dead: предполагаеми дати за край на живота на настоящите видеокарти сочат GeForce RTX 60 едва около прехода 2027/28", "schlagzeile": "Изтичане: Дали GeForce RTX 60 ще дойде едва през 2028 г.?", "kurz": "Youtube авторът Moore's Law Is Dead посочва предполагаеми дати за спиране на настоящите карти GeForce и Radeon. Според тях повечето модели ще излязат от пазара едва около прехода 2027/28. PCGH извежда от това възможен старт на RTX 60 едва в края на 2027 или началото на 2028 г.; нищо не е потвърдено.", "zusammenfassung": "В ново видео Moore's Law Is Dead се позовава на вътрешни източници и посочва конкретни дати за край на жизнения цикъл. Прави впечатление, че скъпите модели трябва да бъдат спрени по-рано от евтините. RTX 5090 трябва да получи статус EOL още през януари 2027 г., скъпи варианти на RTX 5080 също в началото на 2027 г. RTX 5080, RTX 5070 Ti и RTX 5070 обаче ще се предлагат до началото на 2028 г., а RTX 5060 дори до края на 2028 г. При AMD скъпите варианти на RX 9070 XT ще останат до края на първото тримесечие на 2027 г., а базовите версии до началото на 2028 г. Тъй като Nvidia досега е правила смените на поколенията доста плътно, според PCGH старт на RTX 60 около прехода 2027/28 или в началото на 2028 г. би бил възможен. Така RTX 50 Super рефреш става по-малко вероятен, макар PCGH да не иска да го изключи напълно. При AMD датите казват по-малко, защото производителят често продава няколко поколения паралелно; първи карти RDNA 5 през 2027 г. остават възможни. Moore's Law Is Dead има смесена история на попадения, а списъкът не е независимо потвърден. Официална информация от Nvidia или AMD няма.", "ursprungsquelle": "Moore's Law Is Dead (видео в YouTube); анализ на PCGH и 3DCenter", "_src": "81ecf5b9"}, "2026-11-23-microsoft-warnt-weitere-ausfaelle": {"titel": "Президентът на Microsoft Брад Смит очаква още големи ИТ сривове през следващите месеци заради ускореното пачване срещу атаки с помощта на AI", "schlagzeile": "Microsoft предупреждава: следващите месеци носят нови големи ИТ сривове", "kurz": "Президентът на Microsoft Брад Смит очаква още големи ИТ смущения през следващите месеци. Причината според него е, че компаниите трябва да затварят пробиви по-бързо заради атаки с помощта на AI и могат да тестват по-малко. Въпреки това потребителите трябва да инсталират обновленията възможно най-бързо.", "zusammenfassung": "Според Neowin и Dr. Windows Смит е говорил в предаването на CBS „Face the Nation“, а първи е съобщил Newsweek. По същество той казва, че цялата информационна инфраструктура в света в момента се обновява почти в движение. AI прави много по-лесно откриването и поправянето на грешки в софтуера, но атакуващите използват същите инструменти. Затова компаниите пачват по-бързо от преди, което увеличава риска нещо да се счупи, особено при стари системи. Който трябва да пачва толкова бързо, не може да тества промените толкова щателно, казва Смит. Въпреки това той съветва обновленията за сигурност на смартфони и компютри да се инсталират веднага. Подобно се изказаха американският финансов министър Скот Бесънт и според Dr. Windows координаторът на американското разузнаване Джей Клейтън. Фонът е серия от сривове, включително големия срив на Microsoft от последните дни и проблеми при Gmail, App Store на Apple, банки, авиокомпании и PlayStation Network. Според правителството на САЩ и Microsoft няма данни за кибератака. За потребителите на компютри това означава навременно инсталиране на обновленията и редовно архивиране на важните данни.", "weitere_links": ["Dr. Windows"], "_src": "ceec1410"}, "2026-11-23-vkd3d-2-2": {"titel": "Излезе VKD3D 2.2: реализацията на Direct3D 12 върху Vulkan на Wine вече поддържа Shader Model до 6.2", "schlagzeile": "VKD3D 2.2: DirectX 12 преводачът на Wine вече поддържа Shader Model 6.2", "kurz": "Проектът Wine пусна VKD3D 2.2, своята реализация на Direct3D 12 върху Vulkan. Новата версия поддържа Shader Model до 6.2 и използва Vulkan разширението за shader float controls. VKD3D 2.2 трябва да влезе в Wine 12.0.", "zusammenfassung": "VKD3D превежда интерфейсите Direct3D 12 на Microsoft към Vulkan, за да могат съвременни Windows игри и програми да работят под Wine на Linux. Според Phoronix версия 2.2 носи поддръжка до Shader Model 6.2. Добавени са използване на Vulkan разширението за shader float controls, подобрения в обработката на HLSL шейдъри и в компилатора на VKD3D, както и различни поправки. Изтеглянето е достъпно в WineHQ. Версията излиза малко преди release кандидатите на Wine 12.0, очаквани от декември, а стабилната версия трябва да последва в началото на 2027 г. За контекст: Steam Play и Proton обикновено използват за Direct3D 12 отделното разклонение VKD3D-Proton. Който играе на Linux през Steam, не непременно ще усети VKD3D 2.2 пряко. Най-много вероятно ще спечелят потребителите на чист Wine и на базирани на него инструменти.", "weitere_links": ["WineHQ"], "_src": "c3743cac"}, "2026-11-23-samsung-speicher-bis-2029-verplant": {"titel": "Доклад: Samsung вече е разпределил голяма част от производството си на памет за 2027 до 2029 г. чрез дългосрочни договори", "schlagzeile": "Безкрайна RAM криза? Samsung уж е разпределил паметта си до 2029 г.", "kurz": "Голяма част от производствения капацитет за памет на Samsung за 2027 до 2029 г. вече би трябвало да е резервирана чрез дългосрочни договори. Някои клиенти дори преговаряли за доставки до 2031 г. Това не говори за поевтиняване на RAM.", "zusammenfassung": "ComputerBase се позовава на актуални публикации; Samsung официално не е потвърдил новите данни. От резултатите на Samsung за третото тримесечие на 2026 г. е известно, че компанията е сключила дългосрочни договори за доставки с десет големи клиенти и е продала целия си обем HBM за 2027 г. Капацитетът на пластини за обикновена DRAM също трябва да е до голяма степен изчерпан за 2027 г. Според доклада в момента индустрията може да покрие едва 60 до 70 процента от търсенето на памет. До 2030 г. Samsung иска да разпредели 60 до 70 процента от средно- и дългосрочния си капацитет чрез многогодишни договори, за да направи приходите по-предвидими. Клиентите се застраховат срещу колебания с авансови плащания и ценови механизми. Един от двигателите на недостига е HBM за AI ускорители, който изисква значително повече площ на пластините от обикновената DRAM. Новите заводи ще донесат облекчение едва след няколко години. При NAND флаш паметта може да е различно: TrendForce очаква спад на цените през първото тримесечие на 2027 г., отчасти заради по-малко поръчки на корпоративни SSD от китайски облачни доставчици. За сглобяващите компютри това означава, че RAM вероятно ще остане скъпа, а при SSD има повече надежда.", "_src": "c81e91bc"}, "2026-11-23-bartlett-lake-msi-z690-z790": {"titel": "Процесорите Intel Bartlett Lake-S с до дванадесет P-ядра според потребителски тестове работят на дънни платки MSI с чипсет Z690 и Z790 без модифициран BIOS", "schlagzeile": "12 P-ядра без мод: Bartlett Lake тръгва на MSI Z690/Z790", "kurz": "Чиповете Intel Bartlett Lake-S с до дванадесет производителни ядра и без E-ядра всъщност не бяха предназначени за геймърски дънни платки. Според потребителски тестове те стартират без модификации на платки MSI с чипсет Z690 и Z790 с актуален BIOS. Единственото известно ограничение е заключена честота на RAM.", "zusammenfassung": "Bartlett Lake-S се произвежда по процес Intel 7, използва сокет LGA1700 и разчита изцяло на P-ядра Raptor Cove. Intel предлага чиповете за вградения сегмент; досега нямаше подходяща поддръжка на BIOS и микрокод за потребителски платки. Първо Uniko's Hardware тества Core 9 273PE с 12 P-ядра и Core 7 253PE с 10 P-ядра на MSI Z790 MPOWER, но с модифициран BIOS. Според TechPowerUp потребителят в X LovK2X вече е пуснал квалификационна мостра на Core 9 273PE без промени на MSI MEG Z690I. По информация всички платки MSI от сериите Z690 и Z790 поддържат чиповете с най-новия BIOS; заключена е само честотата на паметта, всичко останало може да се настройва. Neowin пише, че MSI тихомълком е добавила поддръжката чрез обновяване на BIOS. Официално потвърждение от MSI или Intel няма. Досега са тествани основно квалификационни мостри; чиповете не са обикновени настолни модели в търговската мрежа. Концепцията все пак е интересна: без E-ядра Thread Director не трябва да разпределя нишки между различни типове ядра, което може да даде предимства в игрите. Колко бързи са всъщност чиповете спрямо Core i9-13900K и Core i9-14900K, тепърва ще покажат тестовете.", "weitere_links": ["Neowin"], "_src": "30ce96e0"}, "2026-11-23-gta5-rdr2-steam-boom": {"titel": "От пускането на GTA 6 за конзоли броят на играчите на GTA 5 Enhanced и Red Dead Redemption 2 в Steam расте рязко, а PC версия на GTA 6 все още не е обявена", "schlagzeile": "GTA 6 само за конзоли: PC играчите щурмуват GTA 5 и Red Dead 2 в Steam", "kurz": "Откакто GTA 6 излезе на 19 ноември за конзоли, значително повече хора играят GTA 5 и Red Dead Redemption 2 в Steam. Според PC Games пикът на GTA 5 Enhanced е нараснал от около 78 000 до почти 138 000 едновременни играчи. PC версия на GTA 6 все още не е обявена.", "zusammenfassung": "PC Games сравни броя на играчите на игрите на Rockstar в Steam преди и след пускането на GTA 6. На 14 ноември пикът на GTA 5 Enhanced беше малко над 78 000 едновременни играчи, а в дните след 19 ноември – 137 993. По-старата Legacy версия на GTA 5 също е нараснала с около 38 процента. Red Dead Redemption 2 се е повишил от около 40 000 до почти 70 000 едновременни играчи, или с около 75 процента. Така уестърнът за кратко се върна в топ 25 на Steam. Според PC Games и GTA 4 има повече играчи. Защо числата растат, не е доказано. PC Games предполага, че PC играчи без GTA 6 посягат към по-старите игри на Rockstar, но това е интерпретация, а не доказателство. Rockstar досега не е обявил PC версия на GTA 6.", "_src": "4e013a76"}, "2026-11-23-windows-server-2028-ohne-32-bit": {"titel": "Windows Server 2028 вече не съдържа по подразбиране подсистемата WoW64 за 32-битови програми, тя може да се добави като Feature on Demand, Windows 11 засега не е засегнат", "schlagzeile": "Край на 32-битовите приложения? Windows Server 2028 ги пропуска по подразбиране", "kurz": "Windows Server 2028 ще излезе без подсистемата WoW64, която позволява 32-битови програми да работят на 64-битов Windows. Който има нужда, може да я инсталира допълнително. За Windows 11 Microsoft досега не е обявил такава стъпка.", "zusammenfassung": "Според Windows Latest Microsoft представи промяната на Ignite 2026. Windows Server 2028 трябва да излезе през есента на 2027 година заедно с Windows 11 27H2. Там WoW64 става Feature on Demand, която администраторите могат да добавят отново за стари 32-битови бизнес приложения. Microsoft обосновава стъпката със сигурността, преди всичко срещу 32-битов зловреден софтуер. Същевременно Microsoft иска да доставя Windows Server сигурен по подразбиране и да прилага базовите настройки за сигурност веднага след инсталацията, като започва със Server Core. SMB1 и VBScript ще бъдат премахнати, обмисля се и отказ от стария BIOS. Като фон Microsoft посочва AI инструменти, които откриват уязвимости с високо темпо, и много стари компоненти, които не могат да бъдат защитени без пренаписване. Windows 11 засега запазва WoW64. Тъй като Server и Windows 11 споделят един и същ код, Windows Latest смята подобна стъпка по-късно за възможна, но това е само оценка. Много програми все още използват 32-битови части, според Windows Latest например услуга на Steam. Кои програми на твоя PC са 32-битови, показва Диспечерът на задачите в изгледа Подробности в колоната Платформа.", "_src": "af5a85c4"}, "2026-11-23-activision-patent-voice-chat-npc": {"titel": "Патентна заявка на Activision описва как реакциите на играчите в гласовия чат се записват и използват, за да реагират компютърно управляваните герои като хора", "schlagzeile": "Патент на Activision: ще се учат ли NPC от твоя гласов чат?", "kurz": "Activision е подала патентна заявка, според която реакции на играчи от гласовия чат биха обучавали невронна мрежа. Така компютърно управлявани герои биха могли да ликуват или да ругаят като истински играчи. Дали Activision някога ще използва това в игра, не е ясно.", "zusammenfassung": "Заявката е озаглавена „Methods and Systems for Applying Machine Learning to Generate Gameplay Audio“ и е публикувана от американското патентно ведомство на 12 ноември. Сайтът Patentlyze обърна внимание на нея, а TechPowerUp съобщава за това. Системата разпознава важни моменти в играта като убийство или собствена смърт и записва гласовия чат малко преди и след тях. Като пример описанието посочва по десет секунди. Като възможни източници заявката назовава отделни гласови приложения като Discord, като играта и чатът се съпоставят чрез времеви печати. С помощта на тези двойки момент и реакция невронна мрежа трябва да научи как звучат правдоподобни реакции. Обидното съдържание трябва да се филтрира предварително, а профил на играча да избира например подходящия език. Според Patentlyze заявката е продължение на заявка от декември 2023 година, по която според патентната база данни Justia патент е издаден още през август 2026 година. Според Patentlyze заявката не описва как играчите трябва да дават съгласие. Патентът не е обявяване на продукт, а Activision не е споменала планове за игра.", "weitere_links": ["Patentlyze", "Justia Patents (Activision)"], "_src": "651066d6"}, "2026-11-23-gta6-gedenkstaette-entwickler": {"titel": "В GTA 6 мемориал почита починали близки на разработчици от Rockstar, а играчите могат да посетят мястото", "schlagzeile": "Трогателно: GTA 6 крие мемориал за починалите близки на създателите си", "kurz": "Мемориал в GTA 6 носи имената на починали близки на разработчици от Rockstar. Двама разработчици сами направиха това публично. Играчите могат да посетят мястото в Leonida.", "zusammenfassung": "Служител от осигуряването на качеството в Rockstar написа в Instagram, че майка му е увековечена в мемориала. Тя е починала осем месеца преди излизането на GTA 6. Според публикацията му тя му купила Vice City като дете, което в крайна сметка го отвело до Rockstar. Продуцентски дизайнер сподели в X, че там са и баща му и дъщеря му, които е загубил по време на разработката. Според IGN мястото се казва Deep Roots Memorial Sanctuary и се намира северно от Hamlet. На една стена са изписани още имена. Дали всички имена принадлежат на близки на разработчиците, не е ясно. Самият Rockstar не е коментирал. Който посети мястото, няма да намери великденско яйце, а тихия спомен на екипа.", "_src": "6bd0be55"}, "2026-11-23-linux-7-4-rc4": {"titel": "Linux 7.4-rc4 е тук, Torvalds нарича тестовата версия огромна, а тя съдържа и идентификаторите на процесорите Razor Lake и Coral Rapids на Intel", "schlagzeile": "Linux 7.4-rc4 е „огромен“ – и вече познава Razor Lake на Intel", "kurz": "Linus Torvalds публикува четвъртата тестова версия на Linux 7.4. Той я нарича огромна, а половината от промените засягат драйвери. Новост са например идентификаторите на бъдещите процесори Razor Lake и Coral Rapids на Intel.", "zusammenfassung": "Torvalds пише в обявата си, че rc4 е огромен, което не е изненада. Около половината от многото малки поправки засягат драйвери, преди всичко графика и мрежа, но също USB, NVMe и звук. Останалото се разпределя между основни компоненти, управление на паметта, файлови системи и архитектури. Според Phoronix генерирани от AI доклади за грешки и пачове продължават да увеличават обема в този цикъл. Нови са идентификаторите на фамилия и модел за клиентските процесори Razor Lake и сървърните Coral Rapids на Intel. Такива идентификатори са подготовка и още не казват нищо за датите на пускане. Освен това ядрото вече премахва NVMe пространствата от имена паралелно, което трябва да ускори операциите. Според Phoronix финалният Linux 7.4 се очаква в края на декември. Това е тестова версия и не е предназначена за ежедневна употреба.", "weitere_links": ["LWN.net"], "_src": "606846f3"}, "2026-11-23-windows-wlan-treiber-user-mode": {"titel": "Microsoft иска през 2027 година да премести драйверите за Wi-Fi от ядрото на Windows в потребителски режим, за да не срива вече дефектен драйвер цялата система", "schlagzeile": "Край на сините екрани заради Wi-Fi? Microsoft изважда драйверите от ядрото", "kurz": "От 2027 година драйверите за Wi-Fi в Windows трябва да работят в потребителски режим вместо в ядрото. Мениджър на Microsoft потвърди това на Ignite 2026, съобщава Windows Latest. Ако такъв драйвер се срине, Windows трябва да продължи да работи.", "zusammenfassung": "Днес драйверите за Wi-Fi работят в ядрото, така че грешка може да срине целия компютър със син екран. Затова Microsoft обяви през май инициатива за по-добро качество на драйверите. На Ignite 2026 продуктовият мениджър на Windows Mehmet Kucukgoz каза според Windows Latest, че се работи по Wi-Fi и промяната трябва да излезе през 2027 година. Основата е User-Mode Driver Framework, който съществува от 2004 година и вече се използва например за сензори, четци на пръстови отпечатъци, USB, Ethernet и входни устройства. Новото е поддръжката на DMA в потребителски режим, която според Microsoft трябва да позволи повече видове устройства без загуба на производителност. Не всеки драйвер може да бъде преместен, признава самият Microsoft. За драйверите, които остават в ядрото, Microsoft работи по по-сигурни опции на компилатора, изолация на драйверите и пренасочване на DMA. Точна дата или коя версия на Windows ще получи промяната, не се знае. Дали драйверите за Wi-Fi в потребителски режим ще добавят осезаемо забавяне, тепърва ще стане ясно. Производителите на Wi-Fi чипове трябва да адаптират драйверите си. Наскоро Microsoft отвори пътя извън ядрото и за антивирусния софтуер.", "_src": "37cb6578"}, "2026-11-23-gta6-darts-koerpertypen-rockstar": {"titel": "Rockstar обяснява в интервюта защо в GTA 6 няма дартс и че многото типове тела на героите са изисквали отделен екип за анимация", "schlagzeile": "Без дартс в GTA 6: според Rockstar просто не е стигнало времето", "kurz": "Дартс липсва в GTA 6, защото според Rockstar не е имало достатъчно време и пари, за да бъде направен достатъчно добре. Това каза пред VGC Rob Nelson, съръководител на студиото Rockstar North. В друго интервю Rockstar обяснява, че многото форми на телата на героите са изисквали отделен екип.", "zusammenfassung": "Дартс можеше да се играе в GTA 4, GTA 5 и GTA Online, а боулинг в GTA 4. Rob Nelson каза пред VGC, че дартс е било спорно решение. Дори Rockstar няма неограничени пари или неограничено време, а понякога трябва да признаеш, че не можеш да докараш нещо до желаното ниво. От Red Dead Redemption 2 насам Rockstar прави мини игрите като дейности, които трябва да се усещат като продължение на игровата механика. Като примери Nelson посочва билярд с истинска физика, вдигане на тежести и баскетбол. По-добре е нещо да се пропусне, отколкото да не е направено достатъчно добре, каза Nelson. В интервю за IGN, за което пише PC Gamer, ръководителят на анимацията Mark Tennant говори за многото типове тела на героите. За да работят анимациите между герои с различен ръст, например при качване в превозни средства или в ръкопашен бой, Rockstar е разработил нови техники. За целта е създаден отделен екип, който е работил тясно с екипите по графика и риггинг. Rockstar не каза дали дартс може да бъде добавен по-късно. Интервюто за VGC излезе още на 19 ноември, а IGN го подхвана на 22 ноември.", "weitere_links": ["IGN", "PC Gamer (типове тела)"], "_src": "5ac7f2a4"}, "2026-11-23-dota2-patch-7-42": {"titel": "Valve пуска пач 7.42 за Dota 2 с повече базово здраве, пасивен опит и предмет, който призовава мега крийпове по всички линии", "schlagzeile": "Dota 2 пач 7.42: нов предмет праща мега крийпове по всички линии", "kurz": "Valve пусна пач 7.42 за Dota 2. Нов предмет от Tormentor призовава мега крийпове по всички твои линии. Според PC Gamer няколко промени могат да скъсят мачовете.", "zusammenfassung": "Според бележките на Valve пач 7.42 е наличен от 18 ноември, а PC Gamer подреди най-важните промени. Tormentor вече винаги пуска консумативния предмет Greater Horn of Battle. Той призовава вълна мега крийпове по всяка твоя линия. Според PC Gamer играчите са забелязали, че стойностите не съвпадат напълно с истинските мега крийпове. Базовото здраве на всички герои се повишава от 120 на 200, а всяка точка сила дава малко по-малко здраве. Така героите са по-издръжливи в началото на мача, но по-късно малко по-уязвими. Освен това всички герои получават пасивно по 50 точки опит в минута след старта. Същевременно опитът, нужен за ниво 30, се увеличава. PC Gamer сравнява новия предмет с подобни цели в League of Legends и Deadlock. Дали мачовете наистина ще станат по-кратки, тепърва ще се види.", "weitere_links": ["Dota 2 (бележки към пач 7.42)"], "_src": "9466bf29"}, "2026-11-23-tlou2-twelve-weeks-mod": {"titel": "Фен модът Twelve Weeks добавя към The Last of Us Part II Remastered на PC безплатен мултиплейър режим 4 срещу 4 в стила на Factions", "schlagzeile": "The Last of Us Part II получава мултиплейър на PC – чрез безплатен фен мод", "kurz": "Безплатният фен мод Twelve Weeks добавя отборен мултиплейър към The Last of Us Part II Remastered на PC. Играе се 4 срещу 4 в стила на режима Factions от 2013 година. Преди около два месеца Sony спря друг мултиплейър мод преди излизането му.", "zusammenfassung": "Според създателите си Twelve Weeks е неофициален фен проект без връзка със Sony или Naughty Dog. Нужно е собствено копие на The Last of Us Part II Remastered в Steam, а според създателите модът не съдържа файлове на играта. Два отбора от WLF и Серафити се изправят един срещу друг в режимите Supply Raid и Interrogation. Има също крафтинг, ръкопашен бой и система от кланове, в която всеки мач е един ден от дванадесет седмици. В началото има дванадесет карти от кампанията, а карти от Part I ще последват по-късно чрез импорт от собствената игра. Сървъри има в Европа и на западното крайбрежие на САЩ, а кодът на сървъра е в GitHub. Модът работи на Windows 10 и 11, както и на Linux и Steam Deck. Според Wccftech създателите признават, че при програмирането са разчитали силно на AI инструмента Claude Code. Модът се разработва от втората половина на септември. Преди около два месеца Sony спря преди излизането мултиплейър мода на модъра Speclizer, който печелеше от него чрез Patreon. Дали Sony ще предприеме действия и срещу Twelve Weeks, не е ясно.", "weitere_links": ["Twelve Weeks (страница на проекта)", "Nexus Mods"], "_src": "1283fede"}, "2026-11-23-gta6-pc-cpu-60fps-hochrechnung": {"titel": "Оценка на Hardware Unboxed: 60 fps в PC версия на GTA 6 биха изисквали около два пъти по-висока производителност на процесора от PS5, а дори Ryzen 7 5800X3D може да не стигне на косъм", "schlagzeile": "GTA 6 с 60 fps на PC: стига ли ти Ryzen 7 5800X3D? Оценка се съмнява", "kurz": "Hardware Unboxed е изчислил колко процесорна мощ би била нужна на PC версия на GTA 6 за 60 fps. Тъй като на конзолите играта е ограничена от процесора при 30 fps, би била нужна около двойната производителност на процесора на PS5. На хартия Ryzen 7 5800X3D би достигнал само около 54 fps.", "zusammenfassung": "GTA 6 работи с 30 fps на PS5, PS5 Pro и Xbox Series X|S, според Rockstar заради тежката симулация на процесора на конзолата. Hardware Unboxed изчисли на тази база в X какво би било нужно на един PC за 60 fps, а PCGH разясни сметката. За двойно повече кадри в секунда при същото натоварване е нужна приблизително двойна производителност на процесора. Каналът оценява, че Ryzen 7 5800X3D е с около 80 процента по-бърз от процесора на PS5, което дава около 54 fps. Според игровия индекс на 3DCenter летвата биха прескочили всички X3D модели за AM5, някои Ryzen 9000 без 3D кеш и най-бързите процесори Raptor Lake и Arrow Lake. По-бърза видеокарта не помага, когато ограничава процесорът. Оценката обаче има ясни граници: тя се базира на измервания от други игри. Тя е вярна само ако конзолата наистина е постоянно ограничена от процесора, а PC версия би могла да предлага плъзгачи като гъстота на населението. Специалистът по бенчмаркове CapFrameX е по-оптимистичен в X и смята, че Ryzen 7 9800X3D е около 2,5 пъти по-бърз от процесора на PS5. Rockstar досега не е обявил PC версия на GTA 6. Затова преди покупка на процесор си струва да изчакаш истински тестове.", "weitere_links": ["CapFrameX в X (оценка)"], "_src": "4dddfd2c"}, "2026-11-23-ki-server-preisaufschlaege": {"titel": "Доклад на Financial Times: Dell, HPE, Lenovo и Supermicro искат след подписване на договорите надценки от 25 до 45 процента за AI сървъри, причината са по-високите цени на паметта", "schlagzeile": "Поръчани, но неплатени: AI сървърите поскъпват със закъснение с до 45%", "kurz": "Големи производители на сървъри искат надценки от 25 до 45 процента за AI сървъри месеци след подписването на договорите. Това съобщава Financial Times, а ComputerBase го обобщава. Основната причина са рязко поскъпналите памети.", "zusammenfassung": "Според Financial Times Dell, HPE, Lenovo и Supermicro искат от клиенти, понякога малко преди доставката, значително повече пари. Хора от бранша говорят за надценки от 25 до 45 процента. Един познавач на бранша описва сегашния стандарт като договор с ориентировъчна цена, която може да расте до доставката. Според анализ на JPMorgan паметта е поскъпнала с над 400 процента от началото на 2024 година. GPU сървърите са поскъпнали с поне 20 до 30 процента, а CPU сървъри с много памет понякога струват поне три пъти повече. Засегнати са и трейдинг фирми като Jane Street, Optiver и Hudson River Trading, които най-често приемат цените, защото се нуждаят от изчислителната мощ. Пример е текущо дело в Ирландия: според съдебни документи трейдинг фирмата XTX Markets е договорила с Dell фиксирана цена от 549 милиона долара. След това Dell е поискал още 62 до 70 милиона долара. Не е ясно кои клаузи в договорите позволяват такива допълнителни искания. Производителите не са коментирали пред FT. За купувачите на PC докладът показва колко силно пазарът на памети в момента се движи от центровете за данни.", "_src": "3005dcd0"}, "2026-11-22-gta6-jason-steve-mcqueen": {"titel": "Шефът на наратива в Rockstar: мълчаливият характер на Jason в GTA 6 е вдъхновен от Стив Маккуин в „Бягството“ и от проучвания за бивши Army Rangers", "schlagzeile": "Защо Jason говори толкова малко в GTA 6: Rockstar посочва Стив Маккуин за модел", "kurz": "Jason Duval, един от двамата главни герои в GTA 6, нарочно говори малко. Според шефа на наратива в Rockstar Rupert Humphries вдъхновението е Стив Маккуин във филма „Бягството“ (The Getaway). Към това се добавят проучвания за бивши Army Rangers.", "zusammenfassung": "Humphries е Senior Vice President по наратива в Rockstar и е коментирал по имейл пред Destructoid, а Eurogamer и PC Gamer подхванаха темата. Когато екипът искал да разкаже история за двойка в бягство, разгледал подобни филми. Особено се откроил „Бягството“ (The Getaway) на Сам Пекинпа от 1972 г. със Стив Маккуин. Маккуин бил известен с това, че зачерквал реплики от сценария и изразявал нещата само с присъствието си. Rockstar искала да види колко близо може да се доближи до това един герой от игра, особено след като много от предишните главни герои били обратното. Това съвпаднало с проучванията за ветерани и особено бивши Army Rangers, които в играта се наричат „Marauders“. Според Humphries такива хора говорят или реагират само когато е необходимо и въпреки това се налагат силно. Сценаристът Michael Wiafe посочва криминалната история на Флорида като очевидна отправна точка за героите. Главните герои на хартия са престъпници, но и свестни хора, а играта не търси оправдания за тях. Сценаристката Elizabeth Gauvey-Kern казва, че историята прави тежки обрати, но целта на Jason и Lucia остава същата. Някои фенове бяха критикували Jason като твърде безличен преди премиерата, докато Destructoid намира сдържаността му в готовата игра за логична.", "weitere_links": ["Destructoid (оригинално интервю)", "PC Gamer"], "_src": "20c23428"}, "2026-11-22-crystalmark-cpuix": {"titel": "Създателят на CrystalDiskMark работи по CrystalMark CPUix – CPU бенчмарк за процесори от i386 до днес", "schlagzeile": "От i386 до днес: създателят на CrystalDiskMark прави нов CPU бенчмарк", "kurz": "Noriyuki Miyazaki, разработчик на CrystalDiskInfo и CrystalDiskMark, работи по нов CPU бенчмарк с името CrystalMark CPUix. Той трябва да сравнява процесори от i386 до съвременните модели с единна оценка. Официалният сайт посочва като дата 31 март 2027 г.", "zusammenfassung": "Според ComputerBase Miyazaki обяви проекта в X по повод 28-ата годишнина на софтуерното си студио Crystal Dew World. CPUix трябва да оценява производителността от процесорите i386 до най-новите CPU по единен мащаб. i386 е от 1985 г., затова Miyazaki говори за процесори на около 40 години. За целта бенчмаркът трябва да работи и под Windows 95 и Windows NT 3.51. За разработката и тестовете Miyazaki по собствените му думи е купил компютър на над 30 години – NEC PC-9821 с процесор Pentium. Той иска да набави още стар и нов хардуер, за да тества CPUix през много поколения. На снимка смътно се вижда ранна версия на програмата. Повече подробности за методите на тестване или оценката все още няма. CrystalDiskMark се смята за стандартния бенчмарк за SSD, а CrystalDiskInfo според ComputerBase наскоро достигна 100 милиона изтегляния. Предишният инструмент за информация за процесора CrystalCPUID обаче беше спрян преди години. Дали датата през март 2027 г. ще бъде спазена, предстои да видим.", "_src": "895f1249"}, "2026-11-22-intel-arc-g3-play-leak": {"titel": "Доклад: Intel планира „Arc G3 Play“ – по-евтин чип за преносими конзоли на базата на Panther Lake с едва четири графични ядра Xe3", "schlagzeile": "Изтичане: „Arc G3 Play“ на Intel ще позволи преносими конзоли под 800 долара?", "kurz": "Според VideoCardz Intel работи по трети процесор за преносими конзоли с името Arc G3 Play. Той трябва да има само четири графични ядра Xe3 и да позволи устройства с Panther Lake под 800 долара. Intel не е обявявала чипа.", "zusammenfassung": "Arc G3 Play ще бъде позициониран под вече наличните Arc G3 и Arc G3 Extreme. Според VideoCardz Arc G3 използва графичния блок Arc B370 с 10 ядра Xe3, а Arc G3 Extreme – Arc B390 с 12 ядра. Така вариантът Play ще има само една трета от графичните ядра на топ модела. При процесора има две възможни конфигурации: през август се говореше за четири производителни и четири икономични Low-Power ядра. По-нов е запис в HWiNFO с името PTL-080, който според източника на изтичания Jaykihn използва осем ефективни ядра без производителни ядра. И двата варианта ще имат осем процесорни ядра, като VideoCardz смята по-новата версия 0+8+0+4 за по-вероятна. За по-стария вариант беше посочен диапазон на мощност от 8 до 25 вата, докато съществуващите модели работят с до 30 и 35 вата. Дали тези стойности важат за новата конфигурация, е неясно. Intel цели по-нисък ценови сегмент, за да могат производителите да предлагат преносими конзоли с Panther Lake под 800 долара. Колко геймърска производителност остава при четири графични ядра, не е известно. За сравнение: GPD Win Mini Ultra с Arc G3 Extreme струва 1699 долара. Нито името, нито данните, нито датата са потвърдени от Intel.", "ursprungsquelle": "VideoCardz (ексклузивно); разпределение на ядрата според Jaykihn в X и записа PTL-080 в HWiNFO", "_src": "6941347c"}, "2026-11-23-badbox-3-tv-boxen": {"titel": "Фирмата за сигурност Human Security разкрива рекламната измама Badbox 3.0: заразени евтини Android TV приемници са генерирали в пика около 40 милиарда рекламни заявки на ден и са служили като прокси", "schlagzeile": "Евтин TV бокс като рекламен бот: Badbox 3.0 фалшифицира милиарди реклами", "kurz": "Заразени евтини TV боксове тайно са пускали реклами и са фалшифицирали рекламни места. Това показва доклад на фирмата за сигурност Human Security за Badbox 3.0. В пика са генерирани около 40 милиарда рекламни заявки на ден.", "zusammenfassung": "Human Security публикува доклада на 18 ноември, а ComputerBase го обобщава. Зловредният софтуер пускал реклами във фонов режим, без те да се виждат на телевизора. При част от заявките се представял за истинско стрийминг приложение, което изобщо не работело на бокса. Боксовете служели и като междинна станция за чужд интернет трафик, при което се виждал IP адресът на собственика. Засегнати са устройства с отворената Android основа AOSP без сертификация Play Protect. На устройства от китайския производител TXCZ изследователите намерили фабрично инсталиран лаунчер със системни права, а в доклада се появява и домейн на производителя. Докладът не казва колко устройства са заразени, нито колко голяма е щетата. Според Human Security някои контролни домейни са били изключени още в края на октомври при акция на Google и партньори. Ако използваш много евтин TV бокс без марка, провери дали е сертифициран с Play Protect. Badbox е вече третата вълна на тази схема, а Google съди операторите на Badbox 2.0 през 2025 година.", "weitere_links": ["Human Security (съобщение)"], "_src": "cd132686"}, "2026-11-22-ram-preise-2027-prognose": {"titel": "Анализ на корейската финансова компания BNK: пълните складове на търговци и производители може да свалят значително цените на RAM от средата на 2027 г.", "schlagzeile": "Надежда за ъпгрейди: анализатори очакват по-евтина RAM от средата на 2027 г.", "kurz": "Южнокорейската финансова компания BNK Investment & Securities очаква значителен спад в цените на паметовите чипове от средата на 2027 г. Причината са препълнените складове на търговци и производители, които са трупали запаси от страх от недостиг. Това е прогноза, а не вече намалени цени в магазините.", "zusammenfassung": "Според PC Games анализаторът на BNK Lee Min-hee смята, че търсенето от крайните клиенти вече е преминало своя връх. За тази година той очаква търсенето на DRAM, измерено в обем памет, да нарасне с 24 процента, а доставеният обем – с 38 процента. Според анализа това би бил най-силният ръст от 2016 г. насам. Тъй като много компании очакват още по-ограничени доставки през 2027 г., при търговци и купувачи са се натрупали излишни запаси. BNK очаква тези запаси да бъдат изчерпани до третото тримесечие на 2027 г., което означава по-малко нови поръчки и натиск върху цените. Най-вече комплектите DDR5 и SSD дисковете може да поевтинеят. Анализ на Bank of America отчита и вече 20 процента по-ниски цени на NAND в краткосрочната търговия. Подобни спадове обаче не стигат веднага до дисковете в магазините. Заради високите разходи за памет производителите на компютри и смартфони напоследък оборудваха устройствата с по-малко памет или вдигнаха цените. За производители на памет като SK Hynix падащите цени биха означавали по-ниски маржове. Прогнозите на анализаторите са несигурни, в краткосрочен план RAM и SSD остават скъпи.", "_src": "692ccfda"}, "2026-11-22-tsmc-lieferstopp-16nm-regel": {"titel": "Ново американско експортно правило третира чиповете по 16/14 nm като потенциално контролирани: TSMC е спряла засега доставки към няколко разработчици на чипове", "schlagzeile": "Новото правило на САЩ удря и чиповете за телефони: TSMC е спряла доставки", "kurz": "Ново правило на американския експортен орган BIS третира предпазно чиповете, произведени по 16 и 14 nm и по-фини процеси, като AI чипове за центрове за данни. Според Nikkei Asia заради това TSMC засега е спряла няколко доставки към китайски и други разработчици на чипове, докато проверява изискванията. Засегнати може да са и чипове за смартфони, телевизори и автомобили.", "zusammenfassung": "Според Tom's Hardware правилото на Bureau of Industry and Security (BIS) важи от 19 ноември като временна наредба. В основата му е презумпция: договорните производители и фирмите за опаковане трябва по подразбиране да класифицират чиповете по 16 или 14 nm и по-фини процеси като високопроизводителни чипове под експортен контрол. Който иска да избегне това, се нуждае от потвърждение за изчислителната мощ на чипа от одобрен разработчик на чипове. Става дума за производствени процеси, използвани от около десет години и налични в много ежедневни устройства. Nikkei Asia цитира няколко мениджъри от бранша, според които ефектът е много по-широк от първоначално очакваното. TSMC е задържала няколко доставки към китайски и некитайски клиенти, докато трае проверката. Самото правило не нарежда спиране на доставките; паузата е реакция на компанията, чийто точен обхват не е официално потвърден. Публично изявление на TSMC засега няма. Освен това САЩ вече изискват експортни лицензи за AI чипове за Индонезия, Малайзия, Сингапур, Бразилия и Тайланд, защото тези страни се смятат за транзитни точки за доставки към Китай. Наредбата забранява и на китайски компании да наемат изчислителна мощ в чуждестранни центрове за данни, за да получат достъп до модерни американски чипове. За PC геймърите в краткосрочен план нищо не се променя, но по-дълги забавяния при чиповете за потребителска електроника може да натоварят веригите на доставки и цените.", "weitere_links": ["Nikkei Asia"], "_src": "df9f4a77"}, "2026-11-22-cachyos-eac-linux-v2": {"titel": "CachyOS November 2026 поддържа Easy Anti-Cheat Linux v2 със собствено подписано ядро и носи нов инструмент за възстановяване", "schlagzeile": "CachyOS подготвя Linux за Easy Anti-Cheat v2 – със собствено геймърско ядро", "kurz": "Популярната геймърска Linux дистрибуция CachyOS поддържа Easy Anti-Cheat Linux v2 с ноемврийската си версия. За целта има отделно подписано ядро със собствен запис за зареждане. Сред изискванията са Secure Boot и TPM 2.0.", "zusammenfassung": "Според GamingOnLinux EAC Linux v2 позволява стартиране на игри само ако може да провери как е заредена системата. Необходими са Secure Boot с ядро, подписано с ключ, приет от Epic, TPM 2.0, активиран IOMMU и ядро в режим lockdown, което зарежда само подписани модули. CachyOS предоставя за целта ядрото linux-cachyos-eac и съответно подписан systemd-boot. EAC ядрото получава собствен запис за зареждане, а нормалните записи се запазват. Така то се стартира само когато искате да играете игра с EAC. Скриптът eac-setup настройва това за systemd-boot, Limine и rEFInd, GRUB се поддържа само експериментално. DKMS модулите не работят с EAC ядрото, затова модулите за Nvidia, ZFS и r8125 се предлагат като отделни пакети. Който използва BitLocker или отключва диска си чрез TPM, трябва първо да прочете ръководството в уикито на CachyOS. Ново е и средство за възстановяване, с което Btrfs снимки могат да се тестват и възстановяват без live USB памет. Package Installer 2.0 по желание поддържа AUR, Flatpak и AppImage. Включени са Linux 7.3.5, Mesa 26.3.1 и драйверът на Nvidia 620.73.04. Фонът е новият лаунчер на Epic с поддръжка на Linux, с който трябва да дойде EAC Linux v2. Кои игри реално ще разрешат EAC v2 под Linux, продължават да решават съответните студиа.", "weitere_links": ["Phoronix", "9to5Linux"], "_src": "d72a03b3"}, "2026-11-22-gta6-circana-ueber-haelfte": {"titel": "Circana: в деня на премиерата 61 процента от активните играчи на PS5 в САЩ и 56 процента от активните играчи на Xbox в света са играли GTA 6", "schlagzeile": "GTA 6 в деня на премиерата: играл е повече от всеки втори активен конзолен играч", "kurz": "Според пазарния анализатор Circana на 19 ноември GTA 6 са играли 61 процента от активните играчи на PS5 в САЩ и 56 процента от активните играчи на Xbox по света. Средно те са прекарали над осем часа в играта. Fortnite е втори с 10 процента.", "zusammenfassung": "Данните идват от Player Engagement Tracker на Circana, анализаторът Mat Piscatella ги публикува в Bluesky, съобщава Eurogamer. Измерено е какъв дял от активните този ден играчи са стартирали GTA 6. Играчите на PS5 са прекарали средно 513 минути, тоест над осем часа и половина, а тези на Xbox – 494 минути. Piscatella нарече и дела на потребителите, и времето за игра „абсолютно луди“. Fortnite е имал този ден втория най-висок дял – 10 процента на двете платформи. Преди премиерата бъдещите играчи на GTA 6 са играли основно Fortnite, Call of Duty, GTA 5, Roblox и NBA 2K27, според Circana. Важно: данните за PS5 се отнасят само за САЩ, а тези за Xbox – за всички региони. Това не са данни за продажби, а дялове от активните играчи за един ден. Rockstar по-рано съобщи за 32,5 милиона продадени копия преди старта и 3,79 милиарда долара приходи през първия ден. Същевременно потребители в Metacritic дават ниски оценки на играта заради 30 fps на конзолите и политически обвинения.", "_src": "cab143f6"}, "2026-11-22-geforce-621-35-schreibflut-weiter": {"titel": "Тест на редактор от Neowin: хотфиксът GeForce 621.35 само намалява натоварването със запис върху SSD, след часове на празен ход драйверът отново записа 36 GB", "schlagzeile": "Хотфиксът GeForce 621.35 помага наполовина: отново 36 GB върху SSD в покой", "kurz": "Хотфиксът GeForce 621.35 трябваше да спре постоянния запис на драйвера на Nvidia върху SSD. Тест на редактор от Neowin показва, че проблемът се връща след по-дълга работа, макар и по-слабо. Засега това е единичен доклад от тест, а Nvidia не е коментирала.", "zusammenfassung": "Robbie Khan е тествал на компютър с Windows 11, RTX 4090 и SSD Samsung 990 Pro с 2 TB. Той сравнил драйверите 621.24, 621.01 и хотфикса 621.35 и наблюдавал записа на процеса NVDisplay.Container.exe, както и SMART стойностите на SSD. През първия час след инсталацията хотфиксът записал само 90,8 KB, така че проблемът изглеждал решен. За девет часа на празен ход с монитор в режим на готовност обаче се натрупали 40,85 GB записи. Според HWiNFO64 реалните host writes на SSD са се увеличили с около 36 GB за това време. За сравнение: с драйвер 621.24 те бяха около 1,18 TB за около пет дни. Хотфиксът значително намалява проблема, но в този тест не го отстранява. С по-стария драйвер 621.01 проблемът при Khan не се появил, процесът записал само 12,55 MB за 55 минути. Затова Neowin и Wccftech продължават да препоръчват връщане към 621.01. Wccftech подчертава, че става дума за единичен случай и други системи може да се държат различно. Който иска да провери дали собственият му компютър е засегнат, може да следи записа на NVDisplay.Container.exe в Диспечера на задачите или host writes на SSD в HWiNFO. Изявление на Nvidia или нов драйвер засега няма.", "weitere_links": ["Wccftech"], "_src": "8db2c56e"}, "2026-11-22-gta6-psn-sperre-fkk-foto": {"titel": "Играч на GTA 6 съобщава за 30-дневна блокировка на социалните функции в PSN, след като изпратил чрез съобщение в PlayStation голо снимка, направена в играта", "schlagzeile": "Снимка от нудисткия плаж в GTA 6: играч съобщава за 30 дни блокировка в PSN", "kurz": "Играч на GTA 6 разказва, че Sony му е блокирала социалните функции в PlayStation Network за 30 дни. Той изпратил на приятел чрез съобщение в PSN снимка, направена с камерата в играта в нудистката зона. Кодексът за поведение на Sony не прави изключение за съдържание от игри за възрастни.", "zusammenfassung": "Според Eurogamer играчът е направил случая публичен в петък вечерта в X и изрично е предупредил другите. Той показал екранна снимка на известието от PlayStation Safety. Според него съдържание, изпратено чрез „Съобщения в PlayStation“, е нарушило кодекса за поведение. Профилът е изключен от социалните функции за 30 дни заради „порнографско или неприлично съдържание“. Според известието при нови нарушения може да последва временна или постоянна блокировка за цялото PlayStation. Кодексът за поведение на Sony забранява споделянето на неприлично, порнографско или незаконно съдържание. Както отбелязва Dexerto, няма изключение за изображения от игри, дори от такива с възрастово ограничение 18+. Sony не е коментирала конкретния случай, информацията се основава на думите на играча. Само преди няколко дни играчи на Xbox съобщиха за блокировки, след като клипове с голи сцени от GTA 6 бяха качени автоматично. Който иска да споделя снимки от играта, трябва внимателно да гледа какво се вижда на тях.", "_src": "27f43473"}, "2026-11-22-glinet-goodcloud-malware": {"titel": "Използвана уязвимост в облачното отдалечено управление на GL.iNet: нападатели са инсталирали зловреден софтуер на рутери и KVM устройства, следват фърмуерни ъпдейти", "schlagzeile": "Зловреден софтуер на рутери GL.iNet: атаката дошла през облачното управление", "kurz": "Чрез уязвимост в облачните услуги за отдалечено управление на GL.iNet неизвестни лица са инсталирали зловреден софтуер на някои рутери и KVM устройства на производителя. Облачната уязвимост е затворена, но вече заразените устройства остават заразени. Собствениците трябва да проверят устройствата си и да инсталират новия фърмуер.", "zusammenfassung": "Според собственото си известие за сигурност GL.iNet е открила инцидента на 20 ноември. Неупълномощена трета страна е използвала уязвимост в облачното отдалечено управление, за да получи достъп до устройства и да инсталира зловреден софтуер. Според производителя пътят на атаката е блокиран и нови заразявания по него вече не са възможни. Тези мерки обаче не премахват зловредния софтуер от вече заразени устройства, подчертава GL.iNet. Като индикатор производителят посочва работещ процес с текста „crond -i /tmp/.log“, който може да се намери в менюто LuCI на рутера под Процеси или чрез SSH. Който открие записа, трябва да смята устройството за заразено и да инсталира новия фърмуер или да го върне към фабричните настройки. За KVM устройствата вече има бета фърмуер с корекциите, а стабилни версии за рутери и KVM бяха обявени за 22 ноември. GL.iNet препоръчва ъпдейта и без признаци на заразяване. При заразени KVM устройства трябва да се провери и свързаният компютър. GL.iNet не е съобщила колко устройства са засегнати, откога е използвана уязвимостта и какво точно прави зловредният софтуер. Потребители във форума на производителя съобщават и за други задни вратички, които официалната проверка не открива, производителят засега не е потвърдил това.", "weitere_links": ["GL.iNet (известие за сигурност)"], "_src": "83cec918"}, "2026-11-22-outlook-ausfall-abschlussbericht": {"titel": "Окончателен доклад на Microsoft за срива на Outlook на 12 ноември: някои имейли до неактивни лични пощи не са доставени, засегнати са и защитите на Defender", "schlagzeile": "Срив на Outlook: Microsoft признава, че някои имейли така и не пристигнаха", "kurz": "Microsoft публикува окончателния доклад за големия срив на Outlook и Exchange Online на 12 ноември. При частни потребители с дълго неактивни пощенски кутии някои имейли са изтекли, а подателите са получили известия за недоставяне. Засегнати са били и защитни функции на Defender for Office.", "zusammenfassung": "Според Neowin причината е софтуерен дефект от юли 2026 г., който заедно с намален сървърен капацитет и допълнителен трафик от Teams е предизвикал верижна реакция. В някои моменти над 80 процента от мрежовите шлюзове не са отговаряли, а услугите са се върнали след около 12 часа. Microsoft е удължила срока за повторни опити за доставка от 24 на 48 часа. Според Microsoft нито един корпоративен имейл не е изгубен окончателно. При частните потребители обаче забавени имейли до пощи, неактивни повече от 30 дни, са изтекли. Microsoft не казва колко имейла са засегнати. Освен това автоматичното премахване на злонамерени имейли след доставка е било забавено, а Safe Links понякога е предлагал опция проверката да бъде пропусната. Администраторите временно не са можели да управляват карантината и списъците за блокиране, забавени са били и функции на Purview. До края на 2026 г. Microsoft иска да ограничи резервния трафик на Teams до засегнатите региони и да ускори известията за сривове. До първото тримесечие на 2027 г. шлюзовете трябва да бъдат разделени на отделни групи за всяка услуга. Според доклада първото известие към клиентите е дошло около 20 минути след началото на срива.", "_src": "50d409a9"}, "2026-11-22-phison-ssd-npu-weltraum": {"titel": "Phison показва на SC26 SSD със собствен NPU за AI софтуер и космически SSD с 488 TB за център за данни в орбита", "schlagzeile": "SSD със собствен AI чип: Phison пуска PyTorch директно на диска", "kurz": "На изложението за суперкомпютри SC26 Phison показа корпоративен SSD с вграден NPU и 64 GB собствена памет, на който AI рамки като PyTorch и vLLM трябва да работят директно. Към това се добавя новата серия Pascari Space за сателити и центрове за данни в орбита. И двете са насочени към фирми, а не към домашни компютри.", "zusammenfassung": "Според TechPowerUp SSD-то с NPU има 64 GB памет със 130 GB/s и поддържа PyTorch, vLLM, OpenVINO и llama.cpp. Идеята е SSD-то само да търси и обработва данните и да връща към сървъра само релевантните резултати. Phison обещава така от 10 до 100 пъти по-малко трафик на данни в зависимост от задачата. Необичайно е, че Phison посочва производителността на NPU в DMIPS вместо в TOPS. Контролерът, интерфейсът, форматът и типът памет още не са известни, става дума за концепция в процес на разработка. Показан е и дизайн, който комбинира бърза pSLC и евтина QLC флаш памет зад 16-канален контролер и трябва да направи излишни отделните кеш дискове. Според прессъобщение от 17 ноември Phison пуска и серията Pascari Space за космически апарати и центрове за данни в космоса. За първия възел StarVault-001 на компанията Lonestar Data Holdings, чието изстрелване е планирано за първото полугодие на 2027 г., Phison доставя 488 TB необработен капацитет, от които около 370 TB са използваеми. Phison не е обявила цени за нито един от продуктите. За геймърите засега нищо не се променя, но технологията показва накъде се развива съхранението на данни в AI центровете.", "weitere_links": ["Phison (прессъобщение Pascari Space)", "VideoCardz"], "_src": "daa0f725"}, "2026-11-22-windows11-bluetooth-mikrofon-48khz": {"titel": "Insider версия на Windows 11: съвместими LE Audio слушалки възпроизвеждат стерео 48 kHz и при активен микрофон вместо телефонно качество", "schlagzeile": "Край на звука като по телефон? Windows 11 тества по-добро Bluetooth аудио", "kurz": "Който играе на компютър с Bluetooth слушалки и използва микрофона, често чува само приглушен звук като при телефонен разговор. Тестова версия на Windows 11 вече позволява на съвместими слушалки да възпроизвеждат стерео 48 kHz при активен микрофон. За това обаче са нужни по-нови LE Audio устройства и подходящи компютри.", "zusammenfassung": "Windows Latest откри функцията в актуална Insider версия, така че тя все още е тест. Досега Windows превключва от Bluetooth профила A2DP към профила за свободни ръце HFP, когато микрофонът е активен, а той звучи значително по-зле. Това засяга например чатове в Discord или гласов чат в игри, докато върви музика или звукът на играта. В тестовата версия изходните настройки на Bluetooth устройството имат в „Формат при активен микрофон“ новата опция „2 канала, 16 бита, 48000 Hz“. С нея звукът трябва да продължи в пълно стерео качество. Нужни са слушалки с Bluetooth LE Audio и възпроизвеждане 48 kHz, както и компютър със Super Wideband Stereo. Дали компютърът поддържа LE Audio, показва превключвателят „Използвай LE Audio, когато е налично“ в настройките на Bluetooth, но това не е гаранция за новата опция. По-старите слушалки не печелят нищо. Не е ясно дали Microsoft ще разшири подобрението до повече устройства. Windows Latest очаква функцията за всички около март 2027 г., Microsoft не е посочила дата.", "_src": "d518f4ad"}, "2026-11-22-isaac-ki-musik-entfernt": {"titel": "The Binding of Isaac: Nicalis премахва необявена AI музика от Repentance+ след критика от създателя Едмънд Макмилън и вълна от негативни отзиви в Steam", "schlagzeile": "AI музика в Binding of Isaac: създателят не знаел, пач изтрива песните", "kurz": "Новата актуализация на The Binding of Isaac: Repentance+ съдържаше музика, създадена с AI инструмента Suno, без това да е посочено. След вълна от негативни отзиви в Steam Nicalis премахна файловете с пач. Създателят Едмънд Макмилън казва, че не е знаел нищо за това.", "zusammenfassung": "Според IGN актуализацията излезе на 19 ноември заедно с нови версии за Switch 2, PS5 и Xbox Series X/S. Засегнатите парчета бяха част от дневно предизвикателство с тематика GTA, съвпадащо със старта на GTA 6. Ден по-късно потребител в Reddit откри препратки към AI инструмента Suno в метаданните на няколко парчета, включително линкове към страници на Suno. Valve изисква разработчиците да посочват използването на AI на страницата в Steam, което тук не беше направено. След това само около 8 процента от последните отзиви в Steam бяха положителни. Макмилън написа, че „няма представа“ как музиката е попаднала в билда, и обяви премахването ѝ. Няколко часа по-късно Nicalis пусна пач, който премахва „генерираните музикални файлове“. Той вече е наличен за PC, а според Nicalis е изпратен за Xbox, Switch и PlayStation. Кога ще излезе там, не е ясно. Nicalis не е дала обяснение как се е стигнало до това. Последните отзиви в Steam остават „Изключително негативни“.", "_src": "d791da42"}, "2026-11-22-windows-antivirus-ausserhalb-kernel": {"titel": "Windows endpoint security platform е общодостъпна: антивирусните програми могат да изпълняват ключови защитни функции извън ядрото на Windows", "schlagzeile": "Урок от хаоса с CrowdStrike: антивирусите могат да излязат от ядрото на Windows", "kurz": "Microsoft направи Windows endpoint security platform общодостъпна за Windows 11. С нея софтуерът за сигурност може да изпълнява важни защитни функции в потребителски режим вместо в ядрото, така че грешките по-рядко да сриват целия компютър. Bitdefender, CrowdStrike, ESET, Sophos и други искат да използват интерфейсите.", "zusammenfassung": "Microsoft обяви това на Ignite на 17 ноември, а Windows Latest вече обобщи подробностите. Поводът е 19 юли 2024 г., когато дефектна актуализация на CrowdStrike блокира около 8,5 милиона устройства с Windows със сини екрани. Новата платформа предоставя на програмите за сигурност интерфейси на Windows в потребителски режим, чрез които те могат да наблюдават и блокират събития. Първата версия обхваща файловата система, процесите, регистъра и Object Manager. Ако защитна програма или правило причини проблеми при стартиране, Windows трябва да използва вградени механизми за възстановяване, според Microsoft. Според Microsoft Learn платформата е част от Windows 11 25H2 и 26H2 от октомврийските актуализации. В началото тя е достъпна само за членове на Microsoft Virus Initiative, а програмите трябва и да бъдат специално подписани. Bitdefender и Sophos планират първите продукти за четвъртото тримесечие на 2026 г., други производители отчасти едва за 2027 г. CrowdStrike вижда платформата като допълнение, така че софтуерът за сигурност няма да изчезне напълно от ядрото. Античийт програмите с драйвери в ядрото също не са пряко засегнати от промяната.", "weitere_links": ["Microsoft Windows IT Pro Blog", "Microsoft Learn (Windows endpoint security platform)"], "_src": "4894b14e"}, "2026-11-22-gta3-ps2-exklusiv-deal": {"titel": "Бивши мениджъри на Sony и Take-Two разказват как GTA 3 стана ексклузивна за PS2: пари, отстъпка за всеки диск и колеблив в началото американски клон", "schlagzeile": "GTA 3 ексклузивно за PS2: Sony плати и даде отстъпка, а САЩ се колебаеха", "kurz": "В интервю за The Game Business бивши мениджъри разказват как преди 25 години GTA 3 стана ексклузивна за PlayStation 2. Sony искаше така да отблъсне новия Xbox и плати на Take-Two пари плюс отстъпка от производствените разходи за всеки диск. Точно американският екип на Sony първоначално е спирал сделката.", "zusammenfassung": "Кристофър Дринг от The Game Business е разговарял с бивши мениджъри на PlayStation и Take-Two, а Insider Gaming обобщава интервюто. Според бившия мениджър на Take-Two Кели Съмнър Sony е потърсила ексклузивно заглавие, за да отблъсне Microsoft. Освен „значителна“ сума пари Take-Two е получила преди всичко отстъпка от 2,50 до 3 долара за всяка произведена бройка. Това е донесло на Take-Two „десетки и десетки милиони долари“. Британският екип на Sony под ръководството на Крис Диъринг веднага е разбрал играта, докато американският клон „се е влачил“. Бившият мениджър на PlayStation Шухей Йошида казва, че GTA 3, Vice City и San Andreas са оформили цялата индустрия. Студиа като Naughty Dog, Insomniac и Sucker Punch след това преминават от екшън с герои към по-сериозни и реалистични игри като Uncharted, Resistance и Infamous. Трите части за PS2 по-късно излизат и за Xbox, а от GTA 4 нататък поредицата излиза едновременно на всички платформи. Интервюто не посочва конкретни суми по сделката. Става дума за спомени на участниците, документи не са публикувани.", "weitere_links": ["The Game Business (интервю)"], "_src": "ebb75fc0"}, "2026-11-22-windows7-msi-claw-8": {"titel": "Модъри стартират Windows 7 на преносимата конзола MSI Claw 8 AI+ с Intel Lunar Lake, след като заобикалят грешки във фърмуера ACPI на MSI", "schlagzeile": "Windows 7 на MSI Claw 8 AI+: модъри надвиват грешките във фърмуера на MSI", "kurz": "Ентусиастът на Windows Bob Pony подкара Windows 7 на преносимата геймърска конзола MSI Claw 8 AI+ с чипа Lunar Lake на Intel. В началото системата забиваше със син екран, за който той обвинява грешки във фърмуера ACPI на MSI. Дали драйверите, управлението и игрите работят, не е ясно.", "zusammenfassung": "VideoCardz съобщава за публикация на Bob Pony от 21 ноември. Claw 8 AI+ използва Core Ultra 7 258V с 4 производителни и 4 енергоефективни ядра, както и интегрираната графика Arc 140V. MSI официално доставя устройството с Windows 11, а Lunar Lake излезе на пазара дълго след края на поддръжката на Windows 7. Според Bob Pony Windows 7 първоначално спирал със син екран 0xA5, който сочи проблеми с ACPI. Като причина той посочва празно поле _CID и дублирани стойности _UID при две устройства във фърмуера на MSI. Втори разработчик на име EAZY BLACK помогнал грешките да бъдат заобиколени, след което системата стартирала. Засега демонстрацията не показва нищо повече от стартирането. Bob Pony не е казал дали под Windows 7 работят графичните драйвери, бутоните на контролера, Wi-Fi или енергоспестяващите функции. По-рано той спомена неофициалния проект WDDM2Win7, който трябва да добави DirectX 12 и модерни видеокарти към Windows 7. Дали двете могат да се комбинират, не е ясно. Това не е за ежедневна употреба: Windows 7 от години не получава актуализации за сигурност.", "_src": "6e154b01"}, "2026-11-22-neuralink-gta6": {"titel": "Участник в проучване на Neuralink играе GTA 6 с мисълта си: видео показва шофиране, летене и престрелки с мозъчния имплант", "schlagzeile": "GTA 6 само с мисли: пациент на Neuralink кара, лети и се бие в Леонида", "kurz": "Neuralink публикува видео, в което участник в клиничното ѝ изпитване играе GTA 6 с мозъчния имплант. Виждат се разходки с лодка, полети и престрелки. Neuralink подчертава, че устройствата са експериментални и не са одобрени.", "zusammenfassung": "Според IGN около двуминутното видео показва как участникът води героя Джейсън през Леонида само с импланта. Той разказва, че преди е играл с пръчка в устата на iPad, от което са го боляли челюстта и цялото тяло. С чипа веднага е могъл да управлява компютър и говори за „портал към света“. Neuralink уточни, че участниците са част от много малко клинично изпитване. Устройствата са експериментални и не са одобрени нито от американската FDA, нито от други органи. Показаните преживявания може да не важат за всички участници или за бъдещи резултати. Според IGN видеото не обяснява как точно управлението се предава технически към конзолата. Още през 2024 г. първият пациент на Neuralink игра с импланта Civilization 6, а по-късно и Slay the Spire. Кадрите не са проверени независимо, става дума за рекламно видео на компанията.", "_src": "8ee04f1e"}, "2026-11-21-entra-connect-health-datenleck": {"titel": "Microsoft потвърждава използвана уязвимост в Entra Connect Health: изтекли имейл адреси на администратори и данни за тенанти", "schlagzeile": "Пробив в Microsoft Entra: нападатели взеха имейли на администратори", "kurz": "Нападатели са използвали уязвимост в облачната услуга Microsoft Entra Connect Health и са се сдобили с имейл адреси на администратори и конфигурационни данни за тенанти на фирми. Microsoft затвори пробива на 19 ноември и уведоми засегнатите клиенти. Паролите и ключовете не би трябвало да са засегнати.", "zusammenfassung": "BleepingComputer съобщава за известие, което Microsoft е изпратила на администратори; при запитване Microsoft потвърди уязвимостта. Entra Connect Health следи от облака локалната инфраструктура за идентичност на фирмите. Уязвимостта е била в API на услугата, появила се е на 23 юли и е открита на 9 ноември. Според Microsoft е имало неоторизиран достъп за четене, но не са установени промени в конфигурацията. Изтекли са между другото имейл адреси на технически контакти и администратори, ID на тенанти, имена на домейни, данни за държава, нива на лиценз и състоянието на синхронизацията на директорията. API връщал и изтекъл сертификат, който вече не се използва. Според Microsoft пароли, хешове на пароли, токени и валидни ключове не са засегнати. Microsoft не казва колко организации са засегнати, нито кой стои зад атаката. Клиентите не трябва да инсталират нищо, но Microsoft предупреждава за целенасочени фишинг атаки срещу откраднатите администраторски адреси. Препоръчва се устойчиво на фишинг многофакторно удостоверяване за привилегировани акаунти и преглед на журналите за одит и вход в Entra. PowerShell скрипт на Microsoft показва кои видове данни може да са засегнати.", "_src": "e9ebf74a"}, "2026-11-21-nioh-3-complete-edition-korea": {"titel": "Корейският орган за рейтинг оцени необявено Nioh 3 Complete Edition", "schlagzeile": "Изтичане: Идва ли скоро Complete Edition на Nioh 3?", "kurz": "Корейският орган за възрастов рейтинг GRAC е оценил Nioh 3 Complete Edition, която Koei Tecmo дори още не е обявила. Според записа става дума за сборник с допълнителното съдържание на екшън RPG играта. Дата на излизане не е известна.", "zusammenfassung": "Insider Gaming откри записа, а Eurogamer го подхвана. Изданието е подадено на 2 ноември и на 17 ноември получава рейтинг 19+ заради натуралистично насилие. Според машинно преведеното описание това е сборник с допълнителното съдържание на мрачната екшън RPG игра от епохата Сенгоку. Записът посочва и чуждестранен рейтинг, според Insider Gaming японски CERO 17+. GRAC публикува рейтингите веднага, затова игрите често се появяват там преди официалното обявяване. При предшественика между рейтинга на основната игра през януари 2020 г. и Complete Edition през ноември същата година минаха около десет месеца. Nioh 3 излезе на 6 февруари и според Eurogamer е продадена в над един милион копия. Второто DLC, „Bloody Insurrection“, е обявено за февруари 2027 г., а Eurogamer смята за възможно съвместно излизане с Complete Edition. Това са спекулации; Koei Tecmo засега не се е изказала. Обикновено Complete Edition съдържа основната игра и цялото допълнително съдържание, но съдържанието не е потвърдено.", "ursprungsquelle": "Game Rating and Administration Committee (GRAC, Корея), открито от Insider Gaming", "weitere_links": ["Eurogamer"], "_src": "4cbc4b54"}, "2026-11-21-hwinfo-rest-api": {"titel": "HWiNFO 8.61 Beta получава вграден REST API сървър: показания на сензорите в браузъра на телефон, таблет или втори екран, без лиценз ограничено до 12 часа", "schlagzeile": "HWiNFO праща сензорите на телефона – безплатно, но само за 12 часа", "kurz": "Инструментът за диагностика HWiNFO получи вграден REST API сървър в бета версия 8.61. Температури, честоти и консумация могат да се показват в браузъра на всяко устройство в домашната мрежа, включително в собствени табла. Без лиценз сървърът работи само 12 часа.", "zusammenfassung": "Разработчиците представиха функцията във форума на HWiNFO, съобщава VideoCardz. Сървърът предоставя всички показания на сензорите с мерни единици, описания и йерархия във формат JSON, по HTTP или HTTPS. Собствени табла могат да се изградят с обикновен HTML и JavaScript, а в комплекта има готов интерфейс в стила на познатия прозорец със сензори. Функцията се включва в прозореца със сензори чрез бутона „Remote Center“, където се задават IP адрес, порт и HTTPS. Филтър определя кои стойности се показват, наблюдават и записват. Така стар таблет или малък втори екран може да стане дисплей за температурите на процесора и видеокартата. Уловката: без лиценз сървърът спира след 12 часа. Според VideoCardz лицензът струва 29 долара, а за три години 52 долара. Бетата подобрява и поддръжката на графиката на Intel и добавя първоначална поддръжка на Coral Rapids на Intel. Документация и примерни табла има в GitHub. Сървърът е добре да е достъпен само в собствената мрежа.", "weitere_links": ["Форум на HWiNFO (обявление)", "Документация на REST API на HWiNFO (GitHub)"], "_src": "52bab466"}, "2026-11-21-nova-lake-s-28c-h-16c": {"titel": "Nova Lake: 28-ядрен тестов образец за настолни компютри работи на 5,2 GHz, а спецификация на Advantech посочва 16-ядрен чип за лаптопи с 25 вата", "schlagzeile": "Изтичане: Nova Lake с 28 ядра и 5,2 GHz – и 16-ядрен чип за лаптопи", "kurz": "В базата данни OpenBenchmarking се появи тестов образец на Intel Nova Lake-S с 28 ядра и 5,2 GHz. Паралелно спецификация на Advantech посочва чип Nova Lake-H с 16 ядра, 4,8 GHz и TDP 25 вата. Intel не е потвърдила нищо от това.", "zusammenfassung": "И двете находки са на известния хардуерен следотърсач momomo_us, а TechPowerUp и Wccftech ги подхванаха. Настолният чип се появява като „Intel 0000“ със съкращението NVL, а броят ядра съответства на очакваното разпределение от 8 производителни, 16 ефективни и 4 нискоенергийни ядра. Тестван е на референтна платка на Intel с ранен BIOS, 32 GB памет и Ubuntu 26.04, включително с Quake II RTX, Unigine и OpenCL натоварвания. TechPowerUp предупреждава, че тестовите образци работят с друг фърмуер, лимити на мощността и профили на честотата от търговските версии. Записът не уточнява дали 5,2 GHz е постоянна честота или само пикова стойност. Според спецификацията на Advantech чипът за лаптопи е на платка за роботика и индустрия и е записан като „Core Ultra Series 4“. Посочени са 8 производителни, 4 ефективни и 4 нискоенергийни ядра, базова честота 2,0 GHz, турбо 4,8 GHz и 18 MB кеш. Към това се добавят поддръжка на DDR5-8000 до 128 GB и интегрирана графика с 2,3 GHz. Конкретно име на модела липсва. Самата Intel все още не е дала данни за честотите и спецификациите на серията Nova Lake.", "ursprungsquelle": "momomo_us в X (находки: OpenBenchmarking.org и спецификация на Advantech)", "weitere_links": ["Wccftech (Nova Lake-H, спецификация на Advantech)"], "_src": "c12c2fd6"}, "2026-11-21-gta6-ps5-absturz-ce-108255-1": {"titel": "GTA 6 забива при някои играчи на PS5 с грешка CE-108255-1, Rockstar все още не е коментирала", "schlagzeile": "GTA 6 забива на някои PS5 – грешка CE-108255-1 спира историята", "kurz": "Някои играчи съобщават, че GTA 6 редовно забива на PS5 с код на грешка CE-108255-1. В някои случаи това им пречи да напреднат в историята, също на PS5 Pro и понякога на Xbox Series X. Rockstar засега не е потвърдила проблемите, а пач няма.", "zusammenfassung": "Eurogamer е събрал сигнали от Reddit и от Dexerto. Един играч пише, че играта първоначално върви безупречно, а след около 40 минути се връща към началния екран на PS5. Друг не може да мине ранна мисия, защото играта забива всеки път на едно и също място. Собственици на PS5 Pro съобщават за забивания още в пролога. Има и отделни сигнали за забивания след около 15 минути на Xbox Series X. Колко играчи са засегнати, не е ясно; става дума за отделни сигнали. Rockstar не е коментирала забиванията и при грешки на конзолата насочва към Sony или Microsoft. Sony описва CE-108255-1 само общо като грешка на приложението и съветва да се провери за обновления на играта. Други общи съвети са обновяване на системата, възстановяване на лицензите, изчистване на кеша и възстановяване на базата данни в безопасен режим. Ако играта е на външен SSD, може да помогне преместването ѝ във вътрешната памет. Според Eurogamer някои засегнати вече са опитали всичко това без успех.", "_src": "028ab63a"}, "2026-11-21-silverstone-nova-lake-netzteil": {"titel": "Silverstone пуска захранването HELA 1350Rz с три захранващи кабела за процесора и го обяснява с голямата консумация на Intel Nova Lake-S", "schlagzeile": "Три CPU кабела за Nova Lake: Silverstone готви захранване за апетита на Intel", "kurz": "Silverstone представи захранването HELA 1350Rz с мощност 1350 вата, което изрично поддържа идващите процесори Intel Nova Lake-S. То идва с три захранващи кабела за процесора, което е необичайно за захранвания за домашни компютри. Silverstone обяснява това с голямата консумация на новите чипове.", "zusammenfassung": "Според продуктовата страница HELA 1350Rz има три 4+4-пинови CPU кабела, за да покрие „високите енергийни нужди“ на Nova Lake-S, съобщават VideoCardz и Wccftech. Обичайно настолните захранвания имат един или два такива кабела. Захранването е сертифицирано по ATX 3.1, достига 80 Plus Platinum и има два конектора 12V-2x6 за видеокарти. Цена не е посочена. Intel все още не е обявила официално консумацията на Nova Lake-S. По-ранни непотвърдени доклади говореха за до 474 вата в краткосрочния турбо лимит PL2 при топ модела с 52 ядра. За сравнение: настоящият Core Ultra 9 285K е на 250 вата. Според по-ранни доклади някои дънни платки Z990 ще имат два или три захранващи конектора за процесора, като третият се смята за незадължителен за овърклокъри. Който купува захранване днес, не е задължително да има нужда от ново за Nova Lake; решаващи са дънната платка и моделът процесор.", "weitere_links": ["Wccftech"], "_src": "a0000314"}, "2026-11-21-zen6-1usmus-widerspruch": {"titel": "Разработчикът на инструменти за Ryzen 1usmus опровергава слуховете за отлагане на Zen 6 до лятото, производство по N2X и над 6 GHz", "schlagzeile": "Изтичане: Zen 6 все пак не чак през лятото? Ryzen експерт опровергава", "kurz": "Разработчикът 1usmus нарича три актуални слуха за Zen 6 на AMD за AM5 „неточни“. Според него Zen 6 не се отлага за лятото, първите чипове не използват TSMC N2X и не надхвърлят 6 GHz. AMD не е коментирала.", "zusammenfassung": "1usmus е известен с инструменти като Ryzen DRAM Calculator и Hydra и публикува оценката си в X на 20 ноември; Wccftech я подхвана в събота. С това той опровергава публикация в Chiphell, за която писахме на 19 ноември. В нея се твърдеше, че AMD е преместила настолната серия Olympic Ridge на оптимизирания за високи честоти 2-nm вариант N2X и затова отлага старта за след Computex 2027. Според 1usmus първите процесори Zen 6 за AM5 не използват N2X. Wccftech тълкува това така, че първо ще се използват N2 или N2P, а N2X би могъл да дойде най-много по-късно; това е тълкуване, а не твърдение на 1usmus. Отлагане до лятото също не било вярно. Конкретна дата той не дава. Слуховете за честоти над 6 GHz също определя като неверни. 1usmus не представя доказателства, така че е твърдение срещу твърдение. Официално AMD е обявила само участие в CES 2027, без да назовава продукти.", "ursprungsquelle": "1usmus в X", "weitere_links": ["1usmus в X (сигнал, 20.11.2026)"], "_src": "80df7c8c"}, "2026-11-21-debian-13-8": {"titel": "Излезе Debian 13.8 „Trixie“: 122 корекции на грешки и 150 обновления за сигурност в нови инсталационни образи", "schlagzeile": "Debian 13.8 е тук: 150 обновления за сигурност за „Trixie“", "kurz": "Проектът Debian пусна осмата точкова версия на Debian 13 „Trixie“. Тя събира 122 корекции на грешки и 150 обновления за сигурност в нови инсталационни образи. Съществуващите системи нямат нужда от нов образ, достатъчно е обичайно обновяване.", "zusammenfassung": "Debian 13.8 излиза два месеца след версия 13.7, съобщават 9to5Linux и Phoronix, позовавайки се на официалното обявление. Точковите версии не носят нови функции, а събират корекции за сигурност и грешки, публикувани преди това поотделно. Новите образи са предназначени главно за нови инсталации, за да не се налага след това да се теглят стотици обновления. Инсталационни образи има за шест архитектури, сред които amd64, arm64 и 64-битов RISC-V. Live образи излизат само за 64-битови компютри, между другото с KDE Plasma 6.3, GNOME 48 и Xfce 4.20. Който вече ползва Debian 13, обновява както обикновено чрез пакетния мениджър, например с „apt update“ и „apt full-upgrade“. Обявлението на Debian изброява подробно кои пакети са засегнати. Проектът съветва всички потребители на Debian 13 да обновят инсталациите си.", "weitere_links": ["Debian (обявление)", "Phoronix"], "_src": "f081abc5"}, "2026-11-21-gta6-xbox-quick-resume-60fps": {"titel": "Бъг в Quick Resume на Xbox Series X отключва GTA 6 над 60 fps, но тогава играта върви двойно по-бързо", "schlagzeile": "GTA 6 с над 60 fps на Xbox – чрез бъг, но на бързи обороти", "kurz": "Потребител в Reddit е открил бъг във функцията Quick Resume на Xbox Series X, който премахва ограничението от 30 fps на GTA 6. Уловката: понеже скоростта на играта е обвързана с кадрите, играта тогава върви твърде бързо. Видеоклиповете в играта пък се възпроизвеждали нормално.", "zusammenfassung": "Wccftech съобщава за инструкциите на потребителя в Reddit Meowwie64. Нужни са Xbox Series X, екран със 120 Hz и версия 1.002.001 на играта. GTA 6 се стартира на 60 Hz, след интрото се превключва на 120 Hz, през менюто Guide се пуска друга игра и после се връща чрез Quick Resume. След това GTA 6 върви без ограничение на кадрите. Понеже анимациите и скоростта на играта са обвързани с кадрите, над 30 кадъра в секунда играта съответно се ускорява. Според споделените видеа видеоклиповете в играта работят и при над 60 fps. Дали трикът работи на Series S или с по-късни пачове, не е ясно. Rockstar е проектирала GTA 6 за 30 fps на всички конзоли, включително PS5 Pro. Wccftech предполага, че причината е непостоянната честота на кадрите, тъй като дори 30 fps не винаги се задържат; Rockstar не е коментирала. Основата е публикация в Reddit и видеа, трикът не е проверен независимо. Истински играемо не е, но показва, че конзолата в някои сцени постига повече кадри.", "_src": "e4e8b50f"}, "2026-11-21-amdlss5-2-5-frame-generation": {"titel": "Неофициален мод AMDLSS5 2.5: невронното рендиране в стил DLSS 5 работи до 60 процента по-бързо на Radeon, плюс генериране на кадри до 6 пъти", "schlagzeile": "Мод за Radeon AMDLSS5 2.5: по-бърза AI графика и до 6x Frame Generation", "kurz": "Версия 2.5 на неофициалния мод AMDLSS5 носи нов Vulkan двигател за невронно рендиране в стил DLSS 5 на картите Radeon. Мрежата изчислявала до 60 процента по-бързо, а игрите вървят около 10 процента по-бързо според разработчика. Новото е генериране на кадри с умножение от два до шест пъти.", "zusammenfassung": "Модът излезе безплатно в GitHub, съобщават VideoCardz и Wccftech. Новият двигател е изграден върху отворената среда DLSSNR-AMD на разработчика Mochizuki. 60-те процента се отнасят до времето за изчисление на невронната мрежа, а не до общата честота на кадрите. Разработчикът е мерил в Resident Evil Requiem с Radeon RX 9070 XT: около 10 процента повече кадри в секунда от версия 2.0 и около 0,5 GB по-малко видеопамет. Генерирането на кадри е от Apex Compute и работи и в игри без собствено умножение на кадри. Наслагване показва допълнителното забавяне на входа. Новоподдържани са между другото Baldur's Gate 3, Microsoft Flight Simulator 2024 и The Last of Us Part I. Официално се поддържат картите Radeon RX 9000, RX 7800 XT се смята за съвместима, другите модели RX 7000 само експериментално, а RX 6000 и по-старите изобщо не. Разработчикът признава визуални дефекти в някои игри. AMD не предлага сравнима функция, а VideoCardz не е тествал мода сам. Както при всички модове: на собствен риск и по-добре не в онлайн игри с античийт.", "weitere_links": ["AMDLSS5 2.5 (GitHub, бележки към версията)", "Wccftech"], "_src": "fc16f92c"}, "2026-11-21-gpd-win-mini-ultra-preis": {"titel": "GPD обяви цената на Win Mini Ultra: 1699 долара за версията с Intel Arc G3 Extreme, 32 GB RAM и 1 TB SSD", "schlagzeile": "GPD Win Mini Ultra: конзолата с Intel Arc G3 Extreme струва 1699 долара", "kurz": "GPD обяви цената на Win Mini Ultra: 1699 долара с 32 GB RAM и 1 TB SSD чрез Indiegogo. Вътре работи чипът на Intel за преносими устройства Arc G3 Extreme. Кампанията започва през декември, а версия с 64 GB ще се продава само в търговската мрежа.", "zusammenfassung": "GPD сама публикува цената в X, а TechPowerUp и VideoCardz съобщават за нея. Win Mini Ultra е малко сгъваемо преносимо устройство с пълна клавиатура. То използва Intel Arc G3 Extreme с интегрирана графика Arc B390, два порта USB4 v2 с 80 Gbit/s и слот за PCIe 5.0 SSD. Към това се добавят тригери с ефект на Хол и поддръжка на VRR. Цената от 1699 долара важи за версията в Indiegogo с 32 GB RAM и 1 TB SSD, с включена доставка. Кампанията трябва да започне през декември, а доставките – веднага след това. Според GPD вариант с 64 GB RAM няма да се продава чрез Indiegogo, а само в търговската мрежа. GPD все още не е обявила европейски цени. Компанията обяснява високата цена с поскъпването на паметта и предупреждава, че по-късно може да стане по-скъпо. Колективното финансиране винаги носи риск от забавяния.", "weitere_links": ["VideoCardz"], "_src": "4d3af437"}, "2026-11-21-geforce-hotfix-621-35-ssd": {"titel": "Nvidia пуска GeForce Hotfix 621.35 срещу прекомерните записи върху SSD на драйверите 621.14 и 621.24", "schlagzeile": "GeForce Hotfix 621.35 спира потока от записи върху SSD", "kurz": "Nvidia пусна корекционния драйвер GeForce 621.35. Той отстранява грешката, заради която драйверите 621.14 и 621.24 записваха огромни количества данни върху SSD в покой. Корекцията е по избор и е достъпна само чрез клиентската поддръжка на Nvidia.", "zusammenfassung": "Според Nvidia драйверът съдържа точно една корекция: във фонов режим можеше да има прекомерни записи във файла nvlog.nvlgstg. Причината беше процесът NVDisplayContainer.exe, който записваше постоянно дори на неактивни компютри. Според TechPowerUp в крайни случаи това стигаше до 30 GB на час, докато по-старият драйвер 621.01 записваше само около 2 MB за пет минути. Корекцията се базира на актуалния драйвер Game Ready 621.24 от 12 ноември. Както всички корекции, тя е минала през съкратен контрол на качеството и се предлага само на страницата за поддръжка на Nvidia. Досегашните временни решения бяха връщане към 621.01 или спиране на услугата NVIDIA Display Container LS. Засегнатите трябва да инсталират корекцията, а останалите могат да изчакат следващия WHQL драйвер. Няколко дни по-рано AMD имаше подобен проблем с драйверите Radeon и също пусна корекции по избор.", "weitere_links": ["VideoCardz", "NVIDIA Customer Care в X"], "_src": "6e1b1d53"}, "2026-11-21-gta6-review-bombing-ultimate-laeden": {"titel": "GTA 6: потребителската оценка в Metacritic пада до около 5 от 10, играчите критикуват затворени магазини за Standard Edition", "schlagzeile": "GTA 6: критиците дават 99, играчите само 5 – и гняв заради заключени магазини", "kurz": "Докато GTA 6 има оценка 99 от критиците в Metacritic, потребителската оценка падна до около 5 от 10. Част от оценките изглеждат като умишлено review bombing. Освен това купувачите на Standard Edition са недоволни, защото четири магазина остават напълно затворени за тях.", "zusammenfassung": "Според Insider Gaming потребителската оценка в Metacritic е била 5,1 от 10 след над 10 000 оценки, почти половината от тях отрицателни. Оценката на критиците за версията за PS5 остава 99 от 152 ревюта. Много ниски оценки се състоят само от едно изречение или атакуват сюжета и героите по политически причини, отчасти с расистки и сексистки коментари. Има обаче и критики към производителността, грешките, загубения напредък и близостта до Red Dead Redemption 2. Metacritic още преди премиерата е премахнал фалшиви потребителски ревюта, съобщи VGC. Втори спорен въпрос: Ultimate Edition за 99,99 долара отключва четири магазина, сред които фризьорски салон и студио за татуировки. Според IGN притежателите на Standard Edition за 79,99 долара се натъкват на заключени врати и дори не могат да влязат в обзаведените магазини. Rockstar беше обявила съдържанието предварително, но много играчи очакваха поне достъп без възможност за покупка. В социалните мрежи се чуват думи като алчност. Rockstar засега не е коментирала нито едното, нито другото. Потребителските оценки силно се колебаят през първите дни, затова числата са моментна снимка.", "weitere_links": ["IGN (заключени магазини)", "VGC (премахнати фалшиви ревюта)"], "_src": "a80f0d8b"}, "2026-11-21-trump-rechenzentren-ausland": {"titel": "Тръмп заплашва американските компании с висок данък, ако строят центрове за данни в чужбина – без подробности", "schlagzeile": "Тръмп иска да откаже US компаниите от центрове за данни в чужбина", "kurz": "Президентът на САЩ Доналд Тръмп обяви, че няма повече да позволява на американски компании да строят центрове за данни в чужбина или ще ги облага с висок данък. Той не даде подробности, ставка или правно основание. Засегнати биха били компании като Microsoft, Amazon, Google и Oracle, които имат центрове за данни и в Европа.", "zusammenfassung": "Изявлението беше направено в петък на пресконференция в Белия дом, съобщават AP, The Verge и Dr. Windows. Тръмп каза, че на американските компании няма да бъде позволено да строят центрове за данни извън САЩ. Който все пак го направи, ще трябва да плаща огромен данък. По собствените му думи не е информирал екипа си предварително. Колко висока ще е таксата и как ще бъде въведена, остава неясно. Компании като Microsoft, Amazon, Google, Meta и Oracle вече имат много центрове за данни в чужбина, включително в Европа. Dr. Windows посочва, че разходите в крайна сметка може да се прехвърлят върху клиентите. Неясно е и какво би означавало това за модели като Delos Cloud, където Microsoft е доставчик на технология. Съмнително е дали планът ще мине политически, тъй като скоро в Конгреса ще положи клетва демократично мнозинство. Засега това е само обявление, а не закон или наредба.", "weitere_links": ["AP News", "The Verge"], "_src": "04b11ca3"}, "2026-11-21-nvidia-sec-bilanzpruefung": {"titel": "Reuters: Комисията по ценни книжа и борси на САЩ проверява възможни счетоводни въпроси в Nvidia, акциите губят 23 процента за седмица", "schlagzeile": "SEC проверява счетоводството на Nvidia – акциите с рекорден седмичен спад", "kurz": "Според Reuters Комисията по ценни книжа и борси на САЩ (SEC) проверява възможни счетоводни въпроси в Nvidia. Не е ясно кои сделки са засегнати, а нито SEC, нито Nvidia коментираха. Акциите загубиха 23 процента тази седмица – най-много от октомври 2008 г. насам.", "zusammenfassung": "Reuters се позовава на двама души, запознати със случая, а ComputerBase и Wccftech подхванаха информацията. Проверката се води от служители на отдела за правоприлагане на SEC. Не е известно кои сделки са във фокуса и откога тече проверката. SEC отказа коментар, а Nvidia първоначално не отговори. The Wall Street Journal още във вторник съобщи за проверка на SEC, без да знае нейния предмет. Според ComputerBase вниманието е насочено най-вече към промяна в отчитането на приходите по региони: от миналата година Nvidia разпределя приходите според седалището на клиента, а не според адреса за фактуриране, и така Сингапур изчезна от разбивката. Не е доказано, че това е свързано с проверката. Инвеститорите критикуват и финансирането и гаранциите, с които Nvidia подкрепя компании за изкуствен интелект и облачни доставчици. Според Reuters временният главен изпълнителен директор Колет Крес обяви, че компанията ще бъде по-избирателна в тази област. Акциите загубиха 14 процента само в петък и 23 процента за седмицата. Разследването не означава обвинение или нарушение; засега няма резултати.", "weitere_links": ["Wccftech"], "_src": "4b615fd6"}, "2026-11-21-deltarune-kapitel-6-durchspielbar": {"titel": "Тоби Фокс: глава 6 на Deltarune може да се изиграе от началото до края, локализацията и първите тестове вървят, работата по глава 7 е започнала", "schlagzeile": "Deltarune: глава 6 е изцяло играема, глава 7 вече се разработва", "kurz": "Разработчикът Тоби Фокс съобщава, че глава 6 на Deltarune може да се изиграе от началото до края като пълна чернова. Локализацията и първите тестове са започнали, но някои важни сцени още се нуждаят от работа. Дата няма, Фокс се надява на 2027 г.", "zusammenfassung": "Информацията идва от есенния бюлетин на Тоби Фокс, обобщен от Insider Gaming. Според Фокс всички карти, събития и битки на глава 6 вече съществуват, само едно незадължително събитие още се проточва. Локализацията и предварителните тестове вече би трябвало да са започнали. Някои важни сцени обаче още не са завършени като представяне, затова до пълното тестване ще мине още малко време. Фокс отново подчертава, че глава 6 е по-скоро кратка. Членовете на екипа, които са приключили с глава 6, вече работят по глава 7. Фокс пише, че с тази глава за първи път има усещането, че знае какво прави. Няма дата на излизане за нито една от двете глави; за глава 6 Фокс се надява на 2027 г.", "_src": "faa98515"}, "2026-11-21-gta6-3-79-mrd-rekord": {"titel": "Rockstar: GTA 6 реализира 3,79 милиарда долара през първия ден и е продала 32,5 милиона копия преди премиерата", "schlagzeile": "Официално: GTA 6 реализира 3,79 милиарда долара в първия ден", "kurz": "Rockstar Games съобщава за приходи от 3,79 милиарда долара за GTA 6 през първия ден на продажбите. Преди премиерата са продадени 32,5 милиона копия. Според компанията това е най-голямото развлекателно издание на всички времена във всички медии.", "zusammenfassung": "Данните са от прессъобщение на Rockstar Games и Take-Two, съобщават Eurogamer и AP. Става дума за световните продажби на дребно до края на 19 ноември по оценки на компанията. Според Rockstar 32,5 милиона предварително продадени копия за PS5 и Xbox Series X/S са рекорд за всички платформи. За сравнение: преди 13 години GTA 5 реализира около 800 милиона долара през първия си ден. Данните са значително над оценката на Sensor Tower, която предполагаше около 25 милиона игри и 2,36 милиарда долара. Rockstar не казва колко копия са продадени след премиерата без предварителна поръчка. Рекорди има и в интернет трафика: американският доставчик Comcast отчита най-натоварения ден в историята си, с пик с 31 процента над нормален ден. Според Comcast в пиковите часове 24 процента от интернет трафика са се падали на изтегляне и игра на GTA 6. Rockstar все още не е обявила версия за PC.", "weitere_links": ["Business Wire (прессъобщение на Rockstar/Take-Two)", "AP News", "IGN (рекорд на Comcast)"], "_src": "ac69773b"}, "2026-11-21-persona-schnellere-entwicklung": {"titel": "Atlus обещава по-кратко чакане между бъдещите части на Persona, за Persona 6 все още почти няма подробности", "schlagzeile": "Persona 6 не е краят: Atlus не иска феновете да чакат толкова дълго", "kurz": "Atlus иска да съкрати интервалите между големите части на Persona. Това каза продуцентът на P-Studio Казухиса Вада в интервю. За самата Persona 6 все още има само тийзър и никаква дата.", "zusammenfassung": "Вада говори в интервю за списанието на Sega Samania, а Eurogamer съобщава въз основа на превод на GamesRadar+. Persona 6 не е краят и екипът работи феновете да не чакат следващата игра толкова дълго, колкото досега. Големи ролеви игри като Persona се разработват пет години или повече, затова между номерираните части често има дълги паузи. Вада не казва как Atlus смята да промени това. Неясно е дали следващата основна част вече се разработва паралелно, или само процесите ще бъдат оптимизирани. За Persona 6 той можа да каже малко, но екипът иска да създаде нещо по-добро от всякога. Засега има само кратък тийзър от Xbox Games Showcase 2026. Atlus не е обявила дата или подробности за платформите.", "_src": "719cd5d5"}, "2026-11-21-microsoft-pc-assist": {"titel": "Microsoft пуска приложението PC Assist за Windows 11: добър преглед на системата, но много функции само отварят Get Help или Bing", "schlagzeile": "Microsoft PC Assist: ново приложение за Windows с добри идеи и много Bing", "kurz": "С PC Assist Microsoft предлага ново приложение по избор за Windows, което трябва да решава проблеми и да следи производителността, хранилището и мрежата. Windows Latest хвали прегледите, но критикува, че инструментите за отстраняване на проблеми само отварят приложението Get Help, а инструментите препращат към Bing. По подразбиране инсталаторът иска да зададе Bing като търсачка.", "zusammenfassung": "Windows Latest тества PC Assist във версия 0.4.4.0, а приложението се изтегля отделно от сайта на Microsoft. При инсталацията е предварително избрана опция, която задава Bing като начална страница и търсачка в няколко браузъра. Microsoft посочва това на страницата за изтегляне и обявява и рекламни известия в приложението. За да се стартира, приложението изисква .NET 10 Desktop Runtime. Според теста разделите за производителност, хранилище и мрежа показват ясно натоварването, големите и дублираните файлове и потреблението на данни по приложения. Инструментите за отстраняване на проблеми със звука, мрежата, принтерите или Bluetooth обаче само отварят вече наличното приложение Get Help. Всички десет инструмента, като преводач, времето или тест на скоростта, отварят съответната страница на Bing в браузъра. Интерфейсът работи отчасти чрез WebView2, а тъмен режим и свободно оразмерим прозорец липсват. Microsoft рекламира приложението в Bing като ИИ асистент, но при теста Windows Latest не откри ИИ функция в него. Приложението е по избор и не се инсталира автоматично.", "_src": "13b96d1c"}, "2026-11-20-cairn-ki-agenten-zero-day": {"titel": "Amazon: предполагаеми китайски нападатели са накарали автономни ИИ агенти на платформата Cairn да открият zero-day уязвимост в MONAI Label и да превземат сървър", "schlagzeile": "„Вземи shell достъп“: ИИ агенти откриват zero-day и превземат сървър", "kurz": "Според Amazon нападатели са използвали платформа за автономни ИИ агенти, наречена Cairn, за да открият и използват неизвестна дотогава уязвимост. Агентите са получили само задачата да получат shell достъп. За единадесет минути са намерили път в софтуер за медицински изображения, а по-късно са превзели сървъра.", "zusammenfassung": "Amazon Threat Intelligence е открила кампанията, защото нападателите са оставили своята инстанция на Cairn отворена в интернет без парола, съобщава BleepingComputer. Cairn всъщност е легитимен инструмент за тестове за проникване, който координира няколко ИИ агента. Атаките са се провели от 8 до 10 септември и са били насочени главно към образователни институции в Източна Азия извън Китай. Агентите са открили path traversal уязвимост в MONAI Label – приложение с отворен код за етикетиране на медицински изображения. Според Amazon от проучването на интерфейса до използването на уязвимостта са минали единадесет минути. По-късно чрез уязвимостта са записали задна вратичка в стартов файл на Python и са получили root права. Не всичко е успяло: 16-часов опит със 148 действия срещу Redis сървър се е провалил, както и шест часа налучкване на пароли срещу университетски GPU сървър. Amazon приписва нападателите на Китай с умерена сигурност въз основа на езика, времевите отпечатъци и целите. Уязвимостта в MONAI Label е поправена с обновление от 18 ноември. Amazon предупреждава, че ИИ агентите откриват и използват уязвимости по-бързо, отколкото екипите по сигурност могат да реагират.", "_src": "c3315844"}, "2026-11-20-nvidia-kalifornien-nyt-huang": {"titel": "Главният прокурор на Калифорния връчва на Nvidia призовка за разследване на възможни доставки за Китай; същевременно статия на New York Times обвинява бившия шеф Дженсън Хуанг в десетилетия унижаване на служители", "schlagzeile": "Nvidia: Калифорния разследва, NYT отправя тежки обвинения към Хуанг", "kurz": "Главният прокурор на Калифорния Роб Бонта проверява дали чипове или поверителни данни на Nvidia са стигнали до Китай и дали инвеститорите са били подведени. Успоредно с това New York Times пише за десетилетия вербален тормоз от страна на бившия шеф Дженсън Хуанг. Говорител на Хуанг отхвърля обвиненията.", "zusammenfassung": "Бонта е връчил на Nvidia призовка за разследване на 19 ноември, съобщи неговата служба в прессъобщение. Въпросът е дали модерни чипове или поверителна информация на Nvidia може да са стигнали до Китай и дали Nvidia е информирала погрешно инвеститорите и обществото за този риск. Поводът е аферата на подалия оставка шеф с мениджърка, която според подозренията на американските служби за сигурност е била вербувана от китайското разузнаване, пише heise. Според heise Nvidia първоначално не е реагирала. В петък последва статия на New York Times, за която пишат PC Gamer и Eurogamer. В нея над дузина настоящи и бивши служители обвиняват Хуанг, че десетилетия е обиждал служители пред колегите им и ги е заплашвал с драстични фантазии за насилие. Бивш шеф на човешките ресурси е бил уволнен през 2005 г. след критики към това поведение и е постигнал поверително споразумение за над един милион долара. Говорителят на Хуанг нарича разказа измислици, които хиляди поддръжници във фирмата опровергават. Според PC Gamer публична петиция за завръщането на Хуанг вече има над 200 000 подписа. Председателят на борда по-рано е заявил, според публикации, че компанията не възнамерява да върне Хуанг като главен изпълнителен директор. Обвиненията на вестника не са проверени от съд, а разследването в Калифорния тепърва започва.", "weitere_links": ["heise online", "California Department of Justice (прессъобщение)", "Eurogamer"], "_src": "ec7eb499"}, "2026-11-20-openai-amd-chipdesign-ki": {"titel": "Модели на OpenAI са преработили кода на схеми от GPU и CPU проекти на AMD; според OpenAI до 14 процента подобрение в PPA, като част от промените вече са в чип, предаден за производство", "schlagzeile": "ИИ като съавтор: OpenAI изстисква до 14% повече от графичен чип на AMD", "kurz": "OpenAI е накарала своите ИИ модели да работят по схемни проекти на AMD. При флагмански GPU те са постигнали до 14 процента по-добри стойности на PPA, а при бъдещ процесор – едноцифрен процент. Според OpenAI AMD вече е внедрила някои промени в чип, който е изпратен за производство.", "zusammenfassung": "Данните идват от технически доклад на OpenAI, за който пишат ComputerBase, PC Gamer, PCGH и Wccftech. PPA означава консумация, производителност и площ – трите показателя, по които се измерва всяка промяна в дизайна на чип. Затова 14-те процента не означават автоматично 14 процента повече производителност в игри, а OpenAI не уточнява как се е променила всяка от трите стойности. Не е ясно и за кой GPU на AMD става дума. Моделите са работили директно върху кода на SystemVerilog, тоест описанието на схемите, а резултатите са проверени с инструменти за проектиране на Synopsys. Според OpenAI резултатът съответства на около година оптимизационна работа, свършена за по-малко от пет месеца. При ключови блокове на бъдещ флагмански процесор на AMD подобренията са в едноцифрения процентен диапазон. AMD е внедрила някои промени в чип, наскоро изпратен за производство, а други ще влязат в бъдещи продукти. Дали бъдещи архитектури като RDNA 5 или Zen 6 ще се възползват, е предположение на ComputerBase и не е потвърдено. Преди това OpenAI е изпробвала метода върху собствения си ИИ ускорител Jalapeño, където например площта на векторния блок е намаляла с около 13 процента. Заедно със Synopsys OpenAI сега разработва специализиран модел за инструменти за проектиране на чипове. Собствено изявление на AMD с подробности засега няма.", "weitere_links": ["PC Gamer", "PC Games Hardware", "Wccftech"], "_src": "652d4ddb"}, "2026-11-20-sockel1700-undervolting-cep": {"titel": "Gigabyte потвърждава пред PCGH: с новите BIOS версии за сокет 1700 undervolting остава възможен при K процесорите и предстоящите преиздания на Raptor Lake, а CEP може да се изключи ръчно", "schlagzeile": "Сокет 1700 на Intel: undervolting остава възможен с новия BIOS – с уговорка", "kurz": "Новите BIOS версии за дънни платки със сокет 1700 включват по подразбиране защитата CEP на Intel, която отнема производителност при undervolting. Според Gigabyte тя обаче може да се изключи при K процесорите от сериите Core i-12000 до 14000 и предстоящите refresh процесори. Който има процесор без K и прави undervolting, е по-добре да остане на стария BIOS.", "zusammenfassung": "PCGH е попитал Gigabyte за последствията от новия микрокод 0x137, който идва с BIOS обновления за предстоящи процесори на Intel. При по-ранни версии с този микрокод потребители се оплакваха от постоянно активна Current Excursion Protection, накратко CEP. Функцията намалява честотата, когато напрежението на ядрото падне под минимален праг, и трябва да предотвратява сривове. Който умишлено захранва процесора си с по-ниско напрежение, за да пести енергия и топлина, губи заради това производителност. Според Gigabyte CEP засега остава включена по подразбиране, но може да се изключи ръчно. Това важи за K моделите от сериите Core i-12000, 13000 и 14000, както и за предстоящите refresh процесори. За модели без суфикс K PCGH съветва любителите на undervolting да продължат да ползват стария BIOS. Изявлението важи при условие, че Intel не въведе нови изисквания. Intel все още не е потвърдила официално очакваните за 2027 г. преиздания на Raptor Lake за евтини компютри с DDR4. Според PCGH който не иска сам задълбочено да тества стабилността, е по-добре обслужен с активна CEP. Изявлението е на Gigabyte, при други производители на дънни платки може да е различно.", "_src": "18d970a1"}, "2026-11-20-dnd-beyond-optimizely-malware": {"titel": "D&D Beyond за кратко е разпространявал зловреден код на 16 ноември чрез компрометираната услуга Optimizely; платежните данни не са засегнати според оператора", "schlagzeile": "D&D Beyond е разпространявал зловреден код – чрез чужд инструмент за сайтове", "kurz": "Официалната платформа на Dungeons & Dragons D&D Beyond е сред близо 200 сайта, в които нападатели са вкарали зловреден код чрез услугата Optimizely. Кодът е можел да прихваща въведени данни за карти и да подменя крипто адреси. Според оператора плащанията минават през отделен доставчик и не са засегнати.", "zusammenfassung": "На 16 ноември нападатели са използвали пропуск в регистрацията на акаунти в Optimizely Web Experimentation, широко използван инструмент за тестване на сайтове, съобщават GameStar и GamesRadar+. Така са вкарали зловреден JavaScript в проекти на клиенти, който сайтовете на тези клиенти след това са доставяли на посетителите. Според изследователите по сигурността от Report URI засегнати са 178 организации, сред които D&D Beyond и магазинът за Magic Secret Lair. Кодът е можел да чете данни за карти от платежни формуляри, да подменя адреси на крипто портфейли и да зарежда известни експлойти на по-стари iPhone и iPad. Optimizely заявява, че е затворила пропуска до три часа след откриването му, а засегнати са по-малко от пет процента от клиентите. D&D Beyond е премахнал услугата, а изпълнителният продуцент Брайън Пери подчертава, че плащанията се обработват от отделен доставчик на платежни услуги. D&D Beyond ще се свърже директно с играчите, които трябва да предприемат действия. За Secret Lair Wizards of the Coast съобщава, че не са засегнати клиентски данни. За всеки случай GameStar препоръчва излизане и повторно влизане в профила, нова парола и актуални системи на Apple. Колко посетители реално са изпълнили кода, не е известно.", "weitere_links": ["GamesRadar+"], "_src": "c5b7e321"}, "2026-11-20-ruby-kritische-luecken": {"titel": "Ruby поправя седем уязвимости в обработката на низове и регулярни изрази, шест позволяват изпълнение на код; обновления до 4.0.10, 3.4.13 и 3.3.14, засегнати са и Rails приложения, GitHub и GitLab", "schlagzeile": "Ruby: опасни уязвимости в шаблоните за търсене – и Rails трябва да се обнови", "kurz": "Проектът Ruby е поправил седем уязвимости в сигурността, шест от които могат да позволят на нападатели да изпълнят собствен код. За пет има демонстрационни експлойти. Разработчиците трябва да обновят до Ruby 4.0.10, 3.4.13 или 3.3.14.", "zusammenfassung": "Според heise уязвимостите са в обработката на низове и регулярни изрази, тоест шаблони за търсене. Опасно става най-вече когато приложение позволява на потребителите сами да задават шаблони, например в уеб приложение на Rails. Тогава подправен шаблон може още при компилирането да освободи паметта два пъти или да запише извън буфер и така да вкара код. Други грешки засягат преобразуването между главни и малки букви. Бюлетинът на GitHub оценява няколко уязвимости като критични. За единствената уязвимост с вече присвоен CVE номер оценката е доста по-сдържана – CVSS 7,4 и локален вектор на атака. Грешките са поправени на 18 ноември. Четири от тях са докладвани от изследователя Щефан Лип и ИИ компанията Anthropic, а един поправящ commit дори посочва ИИ модел като съавтор. Според heise засегнати са и големи Ruby приложения като GitHub и GitLab. Който сам използва Ruby или Rails, трябва бързо да обнови. За обикновените потребители на Windows и геймърите няма пряка нужда от действия.", "_src": "25afad94"}, "2026-11-20-gta6-xbox-auto-upload-sperren": {"titel": "Играчи на Xbox получават двудневни блокировки, след като автоматично качени клипове от GTA 6 с плажни сцени явно са били маркирани от автоматичната модерация", "schlagzeile": "Снимал GTA 6 на плажа, блокиран в Xbox: автоматичното качване като капан", "kurz": "Някои играчи на Xbox получиха двудневна блокировка след излизането на GTA 6. Причината явно са автоматично качени клипове с плажни сцени и герои в бански. Който иска да избегне това, може да изключи автоматичното качване в настройките.", "zusammenfassung": "Засегнати са писали в Reddit, а Pure Xbox и Dr. Windows са отразили случаите. Първоначално блокировките изглеждаха произволни; по-късно се оказа, че клиповете са записани на плажовете на Леонида. На Xbox записите по подразбиране се качват автоматично на сървърите. Там Microsoft ги проверява за забранено съдържание като реч на омразата, наркотици, прекомерно насилие, голота и сексуално съдържание. Един засегнат пише, че клипът му не е показвал никаква голота, а само обикновени плажни сцени. Pure Xbox отбелязва, че GTA 6 на други места действително съдържа голота; дали отделни клипове са показвали такива сцени, не е ясно. Решенията изглеждат автоматизирани и според Pure Xbox не могат да се обжалват. Microsoft досега не се е изказала публично, а колко играчи са засегнати, не е известно. Автоматичното качване се изключва от Настройки, Предпочитания, Запис и споделяне. Според публикациите блокировките траят два дни, а профилите не се изтриват.", "weitere_links": ["Pure Xbox"], "_src": "b7031703"}, "2026-11-20-windows11-26h2-automatisch": {"titel": "От тази седмица Microsoft автоматично инсталира Windows 11 26H2 на лични и неуправлявани компютри с Windows 11 24H2 и 25H2", "schlagzeile": "Windows 11 26H2 вече идва автоматично – без да натискате „Обнови“", "kurz": "Microsoft вече разпространява Windows 11 26H2 автоматично към лични компютри и такива, които не се управляват от ИТ отдел. Засегнати са устройства с Windows 11 24H2 и 25H2. Досега обновлението идваше само ако потребителят сам го потърси.", "zusammenfassung": "Според запис в таблото за състоянието на Windows, за който съобщава BleepingComputer, Microsoft е започнала на 18 ноември следващата фаза на разпространението. От края на октомври всички съвместими устройства можеха да получат 26H2 ръчно чрез Windows Update. Сега автоматичната доставка постепенно се разширява, първо за неуправлявани устройства с Windows 11 24H2 и 25H2. Дали и кога даден компютър ще получи обновлението, зависи от настройките му за Windows Update. Който го иска веднага, търси актуализации в Настройки и Windows Update и включва опцията за получаване на най-новите актуализации. Windows 11 26H2 е общодостъпен от септември и се инсталира като малък пакет за активиране, което трябва да е бързо. Той съдържа всички функции, обявени от Microsoft за 24H2 и 25H2. Поддръжката на 26H2 приключва през октомври 2029 г. Миналия месец Microsoft също призова неподдържаните версии да бъдат обновени, защото след смяна на сертификатите догодина те вече няма да получават обновления за сигурността. Тази седмица Microsoft освен това потвърди проблеми с hotpatch обновленията, които обаче засягат само управлявани фирмени устройства.", "_src": "89f06a41"}, "2026-11-20-total-war-40k-sternensysteme": {"titel": "Total War: Warhammer 40,000 разделя кампанията на звездни системи със собствени мини кампании, истории и цели за победа; Creative Assembly показва флоти и армии на Space Marines в стрийм", "schlagzeile": "Total War: Warhammer 40,000 разделя галактиката на мини кампании", "kurz": "Creative Assembly показа кампанията на Total War: Warhammer 40,000 в едночасов стрийм. Всяка звездна система е отделна, завършена кампания с история и цели за победа. Единиците и уменията се пренасят в следващата система.", "zusammenfassung": "Според Eurogamer разработчиците обясняват структурата с това, че размерът на цялата галактика не може да се покаже на една-единствена карта на Total War. Затова всяка система има собствена начална ситуация, собствен сюжет и собствени цели за победа. Стриймът се фокусира върху системата Praevoss с няколко планети, на три от които може да се кацне и да се водят битки. Една от показаните цели изискваше да се удържи планета със Space Marines и едновременно да се унищожи орк нашествие. Много време беше отделено на космическите флоти, които превозват войски, могат да се подобряват и подкрепят армиите например с орбитални бомбардировки. Армиите на Space Marines са малко на брой, скъпи и мощни единици. Загубата на цяла армия трябва умишлено да боли, защото във вселената на Warhammer тя се равнява на цял орден. След една система се продължава нататък, като единиците и отключените умения се запазват. Играта трябва да излезе през 2027 г., точна дата все още няма. Колко звездни системи и игрални фракции ще има при старта, не става ясно от статията.", "_src": "337fc242"}, "2026-11-20-vulkan-1-4-369-amd-raytracing": {"titel": "Vulkan 1.4.369 въвежда експерименталното разширение на AMD VK_AMDX_multi_level_acceleration_structure за допълнителни нива в ускоряващите структури при трасиране на лъчи", "schlagzeile": "Vulkan 1.4.369: разширение на AMD ще ускори ray tracing в големи светове", "kurz": "Новото обновление Vulkan 1.4.369 съдържа експериментално разширение на AMD за трасиране на лъчи. То позволява до две допълнителни нива в ускоряващата структура. Това трябва да намали времето за изграждане и употребата на памет в сложни, анимирани игрални светове.", "zusammenfassung": "Khronos Group публикува спецификацията на 20 ноември, а Phoronix обърна внимание на новостта. Трасирането на лъчи изисква ускоряваща структура – своеобразно дърво за търсене на всички обекти в сцената, което при движение трябва постоянно да се изгражда наново или обновява. Досега за това са предвидени две нива, което според документа с предложението принуждава разработчиците да ограничават сложността на световете си с трасиране на лъчи. Основните проблеми са дългото време за изграждане и обновяване и високата употреба на памет, особено при много анимирана геометрия. Разширението VK_AMDX_multi_level_acceleration_structure позволява до две допълнителни нива на инстанции. Така може по-точно да се управлява кои части от големи светове трябва да се изграждат наново заедно. Тъй като геометрията може да се използва многократно, употребата на памет също трябва да спадне. Префиксът AMDX показва, че разширението е все още експериментално и може да се промени. Дали и кога ще влезе в драйвери и игри, не е ясно. В края на октомври Microsoft също представи в предварителна версия на DirectX новости за ускоряващите структури при трасиране на лъчи с клъстерна геометрия и разделени TLAS. Иначе Vulkan 1.4.369 съдържа главно уточнения и поправки в спецификацията.", "weitere_links": ["Khronos Vulkan-Docs (GitHub, v1.4.369)", "DirectX Developer Blog (предварителна версия за ray tracing, 28.10.2026)"], "_src": "61e18ad7"}, "2026-11-20-f5-big-ip-kritische-luecken": {"titel": "F5 пуска спешни корекции за пет критични препълвания на буфер в BIG-IP APM и iRules, чрез които нападатели могат да изпълняват код без удостоверяване", "schlagzeile": "F5 BIG-IP: пет критични уязвимости, без заобиколно решение – пачвайте веднага", "kurz": "F5 предупреждава за пет критични уязвимости в BIG-IP, чрез които нападатели без удостоверяване могат да сринат системи или да изпълнят код. Няма заобиколно решение, само корекции. Според F5 уязвимостите засега не се използват.", "zusammenfassung": "Според BleepingComputer засегнати са Access Policy Manager на BIG-IP, с който фирмите контролират достъпа до своите приложения, и скриптовата функция iRules. Петте уязвимости с идентификатори CVE-2026-121805, CVE-2026-120292, CVE-2026-120285, CVE-2026-116953 и CVE-2026-123637 са препълвания на буфер в стека. Нападатели без удостоверяване могат с тях да сринат централния процес за трафик, а при подходяща конфигурация и да изпълнят собствен код. Освен това има корекция за уязвимост в SAML с висока степен на опасност, която може да предизвика отказ от услуга. F5 не посочва други мерки освен корекциите, пуснати в сряда. Според Shadowserver над 177 000 инстанции на BIG-IP са достъпни в интернет, а над 14 600 адреса показват признаци на Access Policy Manager. Колко от тях вече са коригирани, не е известно. Според F5 новите уязвимости засега не се използват, но устройствата на F5 редовно са цел на престъпници и държавни нападатели. Американската агенция CISA води от 2021 г. седем активно използвани уязвимости на F5. За домашните потребители това не е тема, но за фирмените администратори обновяването е с най-висок приоритет.", "_src": "458304ca"}, "2026-11-20-rocm-10-2-radeon-780m": {"titel": "AMD ROCm 10.2 официално поддържа още 18 процесора Ryzen с Radeon 780M, 760M и 740M за PyTorch и vLLM под Windows и Linux", "schlagzeile": "Локален ИИ без видеокарта: ROCm вече официално поддържа Radeon 780M", "kurz": "С ROCm 10.2 AMD разшири официалната поддръжка до още 18 процесора Ryzen с вградена графика. Така на много лаптопи и мини компютри с Radeon 780M могат да се ползват ИИ инструменти като PyTorch и vLLM без бърникане. Това важи за Windows и Linux.", "zusammenfassung": "ROCm е софтуерната платформа на AMD за изчисления върху графичния блок; PCGH се позовава на AMD и Phoronix. Новоподдържани са например Ryzen 9 180, Ryzen 7 165, Ryzen 7 155, Ryzen 5 125, както и модели като Ryzen 7 253 и техните Pro варианти. Основата е официалното одобрение на графичната архитектура gfx1103, на която се базират Radeon 780M, 760M и 740M. Досега потребителите на такива устройства често трябваше сами да компилират софтуера или да търсят заобиколни пътища. Поддържат се интерфейсът HIP, както и PyTorch и vLLM, които ROCm 10.2 обновява до версии 2.15 и 0.32. AMD подобрява и комуникацията между до осем карти Radeon в PCIe системи. Одобрението обаче не казва нищо за скоростта. Вградената графика споделя паметта с процесора, затова нейният обем и честотна лента ограничават кои езикови модели работят смислено. За по-малки модели тези устройства вече са официално опция. Обновлението няма нищо общо с производителността в игри.", "_src": "302faa15"}, "2026-11-20-usa-ki-chips-china-genehmigt": {"titel": "Министерството на търговията на САЩ е одобрило износа на 879 000 ИИ чипа на Nvidia и AMD за Китай, включително за Alibaba и Tencent, които Пентагонът води като военни компании", "schlagzeile": "879 000 ИИ чипа за Китай: САЩ одобриха продажби на Nvidia и AMD", "kurz": "Правителството на САЩ е позволило на Nvidia и AMD да продадат 879 000 ИИ чипа на Китай. Сред тях има доставки за Alibaba и Tencent, които са в списъка на китайските военни компании на Министерството на войната на САЩ. Двата производителя са поискали 3,4 милиона чипа.", "zusammenfassung": "Данните са публикувани от Брайън Маст, председател на Комисията по външни работи на Камарата на представителите на САЩ, съобщава ComputerBase. Той е изискал заявленията за износ от отговорната агенция на Министерството на търговията, BIS. Според тях Nvidia и AMD са поискали разрешения за общо 3,4 милиона чипа, а са одобрени 879 000. Отхвърлени са например заявления на Nvidia за 610 000 чипа за Alibaba и 508 000 за собственика на TikTok ByteDance. Други продажби на Alibaba и Tencent обаче са одобрени, въпреки че двете компании са класифицирани като свързани с китайската армия. Маст вижда в това противоречие с целите на американската експортна политика. При някои заявления на Nvidia той освен това подозира, че посредници биха препродали чиповете на забранени компании, а производителите са оценявали този риск като нисък във всяко заявление. От тази седмица действа и ново правило на САЩ, което забранява на китайски компании отдалечен достъп до чипове в чуждестранни центрове за данни. Tencent и Alibaba очакват заради това по-малко изчислителна мощ и по-бавно разширяване. Одобреният износ не означава автоматично доставка, защото Пекин също трябва да разреши вноса, а понякога е отказвал. Кои точно модели чипове са засегнати, не става ясно от публикациите.", "weitere_links": ["Golem.de"], "_src": "10add17c"}, "2026-11-20-moore-threads-lushan-teaser": {"titel": "Moore Threads загатва за настолна видеокарта „Lushan“ с най-голямата според производителя видеопамет сред потребителските GPU; представяне на 29 декември", "schlagzeile": "Китайската видеокарта Lushan ще има повече видеопамет от всяка друга", "kurz": "Китайският производител Moore Threads обявява нова настолна видеокарта с кодово име Lushan. Тя трябва да предлага най-голямата видеопамет в историята на потребителските видеокарти и да е предназначена както за игри, така и за локален ИИ. Тийзърът не разкрива колко точно памет ще има.", "zusammenfassung": "Според Wccftech продуктов мениджър на Moore Threads е публикувал тийзъра в социалните мрежи на 18 ноември, а IT Home го е подхванал. Lushan ще бъде представена изцяло на 29 декември на собствената конференция за разработчици MUSA. Картата е позиционирана както за взискателни компютърни игри, така и за локално изпълнение на ИИ езикови модели. Точно за това е важна много видеопамет, защото иначе по-големите модели не се побират в паметта на картата. Според преведения тийзър изчислителната мощ за ИИ ще нарасне 64 пъти, споменават се също нова архитектура за рендериране, наречена UNITE, и собствен блок за трасиране на лъчи. За какво се отнася коефициентът 64, не е ясно. Moore Threads все още не посочва точното количество памет, честотната лента, цената и наличността. Че Lushan ще получи повече памет от 32-та гигабайта на RTX 5090, е само очевидно предположение. Предишните карти MTT S80 и S90 са се подобрили значително с обновления на драйверите, но по производителност не са във висшия клас. Картите на Moore Threads досега почти не се предлагат в Европа. Надеждни данни ще има едва след представянето в края на декември.", "_src": "9e1861de"}, "2026-11-21-windows-rdma-usb4-ki": {"titel": "Microsoft представя RDMA през USB4 за Windows: няколко компютъра ще могат заедно да изпълняват голям ИИ модел чрез USB4 кабел", "schlagzeile": "Windows свързва компютри с USB4 кабел – за ИИ модели, които не се побират в един", "kurz": "Microsoft обяви предварителна версия за разработчици на RDMA през USB4 за Windows. Така няколко компютъра, свързани с USB4 кабел, ще могат заедно да изпълняват голям ИИ модел, като обединяват памет и графична мощ. Необходимата тестова версия на Windows скоро трябва да излезе за Insiders в канала Experimental.", "zusammenfassung": "Microsoft представи технологията в публикация в блога си на 19 ноември, съобщават Neowin и VideoCardz. RDMA позволява директен обмен на данни между паметта на две системи, без обичайния мрежов стек. Досега под Windows за това бяха нужни специални мрежови карти от сървърния сегмент, а сега трябва да стигат обикновени USB4 портове, включително Thunderbolt 4 и 5. Според Microsoft закъснението при малки съобщения пада до около 28 до 50 микросекунди, около четири пъти по-малко от UDP по същата връзка. При тестове три мини компютъра с Ryzen AI Max+ 395 и по 128 GB памет изпълниха модела Qwen3-235B с около 18,5 токена в секунда. Intel показа GPT-OSS-120B на три и четири системи с Core Ultra Series 3. Всеки компютър трябва да е свързан директно с всеки друг, а свързването във верига значително намалява производителността. Доставчикът на драйвера за USB4 и адаптиран llama.cpp вече са достъпни с отворен код. Според Neowin предварителната версия изисква запис в регистъра и тестово подписване, което означава временно изключване на Secure Boot. Функцията е изключена по подразбиране и засега е насочена към разработчици.", "weitere_links": ["Microsoft Tech Community (блог)", "Microsoft в GitHub", "VideoCardz"], "_src": "8b01c683"}, "2026-11-20-fastunlock-windows-sperrbildschirm": {"titel": "Незакърпена уязвимост в Windows 11 FastUnlock: чрез Разказвача може да се изпълни код на заключения екран, ако нападателят има физически достъп", "schlagzeile": "FastUnlock: нова уязвимост в Windows заобикаля заключения екран чрез Разказвача", "kurz": "Изследовател по сигурността публикува незакърпена уязвимост в Windows 11, с която на заключен компютър могат да се стартират програми. Нужни са физически достъп и потребителски акаунт, свързан с акаунт в Microsoft. Корекция все още няма.", "zusammenfassung": "FastUnlock беше публикувана от бившия служител на Microsoft, известен като MSNightmare или Nightmare Eclipse, който редовно оповестява уязвимости без предупреждение. Атаката започва на заключения екран с „Забравих своя ПИН“, след което с клавиша Windows и U се отваря Разказвачът. Според изследователя преработеният му интерфейс погрешно работи и в контекста на заключения екран и през скрити прозорци води чак до Настройки. Оттам могат да се стартират програми, например от USB флашка, под ограничения акаунт WsiAccount, а не като администратор. Компанията за сигурност ThreatLocker е възпроизвела и потвърдила метода. Според изследователя тя е тествана на Windows 11 26H2 с ноемврийските актуализации. Изследователят говори за заобикаляне на BitLocker; The Hacker News и Cybersecuritynews уточняват, че шифроването не се разбива. Атаката работи, защото дискът, отключен автоматично чрез TPM, вече е четим на заключения екран. Според изследователя потребителите само с локални акаунти не са засегнати. До излизането на корекция експертите препоръчват ПИН за BitLocker при стартиране и изключване или хибернация вместо заключване, когато устройствата остават без надзор. Засега няма признаци за реални атаки, нито изявление или CVE от Microsoft.", "weitere_links": ["The Hacker News", "Tom's Hardware", "ThreatLocker"], "_src": "9655aaf1"}, "2026-11-20-gta6-remote-play-dlss5-mod": {"titel": "Модър стриймва GTA 6 към PC чрез PS5 Remote Play и там вдига картината до 60 fps с неофициална интеграция на DLSS 5 и Frame Generation", "schlagzeile": "GTA 6 с 60 fps на PC: модър прекарва стрийма от PS5 през DLSS 5", "kurz": "Модър пуска GTA 6 на PS5, стриймва картината към PC чрез Remote Play и там с RTX 5080 удвоява кадрите до около 60 fps. За целта използва експериментална, неофициална интеграция на DLSS 5. Управлението обаче остава на 30 fps и дори става по-мудно.", "zusammenfassung": "Според ComputerBase модърът Phosphen е публикувал в GitHub инсталационен скрипт, който инсталира софтуера с отворен код Veyra с подходящи настройки. PS5 предава играта чрез Remote Play в 1080p и 60 Hz към компютъра с Windows; тъй като конзолата изчислява само 30 кадъра в секунда, всеки втори кадър е повторение. Veyra премахва тези повторения и генерира нови междинни кадри с Frame Generation, без да е нужна карта за заснемане. За визуалното подобрение Veyra според проекта използва среда за невронно рендиране, подписана от Nvidia, но самата интеграция идва от общността и не е сертифицирана. Според измерванията на модъра върху около 80 секунди материал средната кадрова честота се е повишила от 29,5 на 59 fps, а обработката на RTX 5080 отнема около 12 милисекунди на кадър. Тези стойности не са независимо проверени. Уловката: командите продължават да минават през конзолата при 30 fps, а стриймът и последващата обработка увеличават закъснението. Освен това стриймът е ограничен до 1080p и е компресиран, DLSS не може надеждно да възстанови изгубени детайли, а без данни за дълбочина и движение от енджина при бързи движения има риск от артефакти. Става дума за технически експеримент, а не за PC версия на GTA 6.", "weitere_links": ["VideoCardz"], "_src": "1204794c"}, "2026-11-20-legion-go-beam-leak": {"titel": "Слух: Lenovo подготвяла с Legion Go Beam по-евтина преносима конзола с фиксирани контролери, широки рамки на екрана и без тъчпад", "schlagzeile": "Изтичане: Lenovo Legion Go Beam щяла да е евтин хендхелд без тъчпад", "kurz": "Изтекли продуктови снимки показват още необявена преносима конзола с името Legion Go Beam. Тя изглежда като олекотена версия на Legion Go S с фиксирани контролери и без тъчпад. Lenovo не е потвърдила устройството, технически данни няма.", "zusammenfassung": "Трите снимки бяха публикувани от Windows Latest и подети от ComputerBase, TechPowerUp и VideoCardz. На тях се вижда бяла преносима конзола със зелени акценти, която напомня на Legion Go S, но е по-заоблена и с различно разположени аналогови стикове. Видими са два високоговорителя отпред, четири бутона на горния ръб и два допълнителни бутона отзад. Рамките над и под екрана са осезаемо по-широки, отколкото при Legion Go S, затова Notebookcheck предполага екран във формат 16:9 вместо 16:10. Отгоре се виждат само един USB-C порт, жак за слушалки и четец за microSD; не е ясно дали липсва втори USB-C порт или просто е на друго място. Процесор, памет, екран, батерия и операционна система не са известни. Заради малките вентилационни отвори и името The Verge спекулира за устройство, предназначено основно за облачен гейминг или стрийминг; доказателства за партньорство с Microsoft или Nvidia няма. Видимите икономии подсказват позициониране под Legion Go S, а цена и дата липсват. Представяне на CES през януари се смята за възможно, тъй като Lenovo провежда там своя Tech World на 6 януари. Всичко идва от един-единствен източник на снимки и не е потвърдено.", "ursprungsquelle": "Windows Latest (ексклузивни продуктови снимки)", "weitere_links": ["Windows Latest", "TechPowerUp", "VideoCardz"], "_src": "802ceaec"}, "2026-11-20-gta6-sensor-tower-2-36-mrd": {"titel": "Пазарният анализатор Sensor Tower оценява GTA 6 след първия ден, включително предварителните поръчки, на около 24,6 млн. продадени копия и 2,36 млрд. долара приходи", "schlagzeile": "GTA 6: оценка сочи 24,6 млн. продадени копия и 2,36 млрд. долара", "kurz": "Според Sensor Tower до вечерта на премиерния ден GTA 6 е продадена в около 24,6 милиона копия и е донесла около 2,36 милиарда долара. Цифрата включва предварителните поръчки и е оценка, която Take-Two не е потвърдила. За сравнение: GTA 5 донесе около 800 милиона долара в първия си ден през 2013 г.", "zusammenfassung": "Sensor Tower е предоставила оценката на Deadline, съобщава и BBC. В сряда преди премиерата стойността беше около 17,1 милиона копия и 1,65 милиарда долара, а в четвъртък сутринта 19,1 милиона и 1,84 милиарда. Около три четвърти от продажбите се падали на PS5, а останалите на Xbox; на PC GTA 6 все още не е излязла. Sensor Tower говори за най-успешния старт на развлекателен продукт изобщо. Според компанията тя се опира, наред с друго, на данни от разписки за покупки по имейл и на публични профили в игровите платформи. Уговорката е важна: 2,36 милиарда долара не са генерирани за 24 часа след старта, а включват всички предварителни поръчки. Take-Two обикновено публикува собствени данни за продажбите с тримесечните си резултати, затова официално потвърждение все още липсва. Според Sensor Tower GTA 6 ще намали времето за игра в други заглавия за един играч с около 10 процента. Предишните оценки на компанията също се промениха няколко пъти през последните дни.", "weitere_links": ["BBC", "PC Games"], "_src": "2163f633"}, "2026-11-20-vmware-vcenter-zero-day": {"titel": "Broadcom затваря критична уязвимост във VMware vCenter Server, която според Mandiant предполагаеми китайски държавни хакери използват за атаки от септември", "schlagzeile": "VMware vCenter: спешна корекция за уязвимост, използвана от септември", "kurz": "Broadcom затвори критична уязвимост във VMware vCenter Server, чрез която нападатели могат да получат администраторски права без вход. Според Mandiant предполагаема китайска хакерска група я използва от началото на септември. Администраторите трябва незабавно да инсталират корекцията.", "zusammenfassung": "Уязвимостта е с обозначение CVE-2026-123890 и се намира във VMware Directory Service на vCenter Server, с който компаниите управляват виртуалните си машини. Според BleepingComputer нападател с мрежов достъп може да заобиколи удостоверяването и да получи сесия като администратор. Broadcom я отстранява в бюлетина за сигурност VMSA-2026-0009 от 19 ноември заедно с още четири уязвимости в SDDC Manager и VMware Tools за Windows. Broadcom определя актуализацията като спешна, официални заобиколни решения няма, а мрежовите ограничения и защитните стени могат само да намалят риска. Mandiant и Threat Intelligence Group на Google приписват атаките на групата Armory Castle, по-рано известна като UNC5221. Според тях нападателите първо са проникнали през друга уязвимост в BeyondTrust Remote Support и след това са се придвижили към вътрешни Linux системи и VMware инфраструктурата. Със собствени инструменти са създали администраторски акаунти, откраднали са базата данни на директорията и с откраднати ключове за подписване са можели да фалшифицират токени за вход и така да заобиколят и многофакторното удостоверяване. Накрая са стигнали до ESXi хостове и данни от виртуални машини. Самата Broadcom не е потвърдила използването, но Mandiant го е документирала. За домашните потребители това не е тема, но за корпоративните администратори актуализацията е с най-висок приоритет.", "_src": "96532db8"}, "2026-11-20-crusader-kings-3-gratis-wochenende": {"titel": "Crusader Kings 3 може да се играе безплатно в Steam до понеделник, 23 ноември; успоредно с това основната игра струва 14,99 евро с 70 процента отстъпка до 30 ноември", "schlagzeile": "Crusader Kings 3 безплатно през уикенда – после със 70 процента отстъпка", "kurz": "Средновековната стратегия на Paradox Crusader Kings 3 може да се изпробва безплатно в Steam до понеделник. Който иска да я купи след това, плаща до 30 ноември 14,99 вместо 49,99 евро. Безплатният уикенд идва малко след новото разширение Silk & Silver.", "zusammenfassung": "Според Polygon безплатният уикенд продължава до понеделник, 23 ноември, 10 ч. тихоокеанско време, тоест 19 ч. в Австрия и Германия. На страницата в Steam играта в момента е с опция за безплатна игра и уикенд оферта. Според Steam отстъпката от 70 процента важи до 30 ноември, а в австрийския магазин цената пада от 49,99 на 14,99 евро. Става дума за ограничен във времето безплатен уикенд, а не за постоянен подарък. Crusader Kings 3 излезе през септември 2020 г. и позволява да водите средновековен благороднически род през поколенията. В центъра са дипломацията, бракосъчетанията, наследяването и интригите, а войната е само една част от играта. Когато владетелят умре, продължавате с наследника. Малко преди безплатния уикенд, на 17 ноември, излязоха платеното разширение Silk & Silver и безплатната актуализация 1.21 „Florin“.", "weitere_links": ["Steam (Crusader Kings III)"], "_src": "8678efa8"}, "2026-11-20-steam-machine-ohne-reservierung": {"titel": "Valve прекратява резервациите за Steam Machine: моделът с 512 GB се продава свободно, листата на чакащите за 2 TB се затваря, цените може да се повишат", "schlagzeile": "Steam Machine вече без резервация – Valve предупреждава за по-високи цени", "kurz": "Valve вече продава Steam Machine с 512 GB без резервация до изчерпване на количествата. Листата на чакащите за модела с 2 TB вече не приема нови желаещи. Заради рязко поскъпващата памет и SSD дисковете Valve казва, че все още не знае колко устройства ще може да произведе и на каква цена.", "zusammenfassung": "Заради кризата с паметта Valve досега продаваше Steam Machine само чрез система за резервации със случаен избор. Според PC Gamer всички резервации за модела с 512 GB вече са изпълнени и дори има остатъчна наличност, която може директно да се добави в количката. Когато тази производствена партида се изчерпи, устройството ще бъде отбелязано като изчерпано, докато не са готови нови бройки. При модела с 2 TB листата на чакащите надхвърля текущото производство. Който вече е в листата, запазва мястото си, но нови записвания не са възможни, а Valve подчертава, че никой в листата няма гарантирано устройство. Който вместо това купи модела с 512 GB, губи мястото си в листата за 2 TB. Valve пише, че разходите за памет и съхранение продължават да растат с безпрецедентни темпове. Затова компанията все още не знае колко Steam Machine ще може да произведе и на каква цена ще бъдат предлагани. Дори да бъдат произведени повече устройства, според Valve това ще стане в по-малки количества от планираното. Нова информация за наличността на модела с 2 TB Valve иска да даде през януари. Конкретно поскъпване Valve засега не е обявила.", "weitere_links": ["TechPowerUp", "GamingOnLinux"], "_src": "6a525997"}, "2026-11-20-gta6-cyberleek-xbox-build": {"titel": "Хакерската група CyberLeek твърди, че е пуснала чрез торент почти готова Xbox версия на GTA 6 – без стартовия файл, който щял да последва по-късно", "schlagzeile": "Изтичане: хакери твърдят, че са пуснали почти готова Xbox версия на GTA 6", "kurz": "Групата CyberLeek, която още преди премиерата изтече кадри от геймплея на GTA 6, твърди, че е публикувала версия за разработчици на играта от ноември 2026 г. Според медиите липсва изпълнимият файл, така че засега играта не може да се стартира. Дали файловете са истински, не е потвърдено.", "zusammenfassung": "Според Eurogamer, VGC и PC Gamer CyberLeek предлага на собствения си сайт изтегляне от около 209 GB, уж Xbox версията от ноември 2026 г. и следователно много близка до търговската. Eurogamer е видял страницата за изтегляне, но не е могъл да провери дали съществуват реални файлове на играта. Според групата един файл липсва умишлено: основният изпълним файл, който щял да се появи едва след обратно броене. Той щял да дойде по-рано, ако крипто токен на групата достигне определена стойност; много от досегашните изтичания на групата бяха свързани с подобни крипто схеми. CyberLeek твърди също, че общността ще емулира играта на PC до седмица, и при нужда заплашва с PS5 версия. Дали това ще проработи технически, е напълно неясно. Rockstar беше нарекла предишните изтичания на групата сърцераздирателни, а Take-Two се опита чрез съдебна призовка да получи от Discord следи за самоличността. Засега няма изявление на Rockstar или Take-Two за новото изтичане. Важно: изтеглянето на пиратски копия е незаконно, а уж изтекли файлове са популярен начин за разпространение на зловреден софтуер. GTA 6 официално излезе само за PS5 и Xbox Series, а Rockstar все още не е обявила PC версия.", "ursprungsquelle": "CyberLeek (собствен сайт/изявление)", "weitere_links": ["Video Games Chronicle (VGC)", "PC Gamer", "Neowin"], "_src": "5da86e6a"}, "2026-11-20-intel-it-entlassungen": {"titel": "Intel продължава съкращенията: според Business Insider нова вълна засяга глобалния ИТ отдел, броят на засегнатите не е известен", "schlagzeile": "Intel съкращава още: този път удар бил глобалният ИТ отдел", "kurz": "Според Business Insider Intel е започнал нова вълна от съкращения, този път в глобалния си ИТ отдел. Intel не казва колко работни места ще отпаднат. От края на 2024 г. персоналът вече е намалял с около 27 800 души.", "zusammenfassung": "Според Business Insider съкращенията в ИТ организацията на Intel са започнали на 16 ноември, съобщават Tom's Hardware и Wccftech. Отделът има около 2607 служители в 55 обекта в 53 държави. Предполагаеми служители говорят за двуцифрен процент, тоест поне около 260 работни места; тези данни не са независимо потвърдени. Intel не посочва нито цифри, нито засегнати екипи и само заявява, че редовно преглежда персонала си спрямо стратегическите приоритети. Това не е първата вълна тази година: през юли беше засегнато звеното за центрове за данни и ИИ, а между юли и октомври Intel подаде в Калифорния девет уведомления за съкращения, обхващащи общо 222 служители. В края на септември Intel все още имаше 81 100 служители, а в края на 2024 г. те бяха 108 900. Главният изпълнителен директор Лип-Бу Тан води от встъпването си строг курс на икономии. За клиентите в краткосрочен план нищо не се променя, но съкращенията показват колко силно Intel иска да продължи да намалява разходите.", "weitere_links": ["Wccftech"], "_src": "5d1e45e7"}, "2026-11-20-xbox-aco-shader-compiler": {"titel": "Microsoft предлага на разработчиците експериментално в Xbox GDK от октомври 2026 г. шейдърния компилатор ACO на AMD от Linux проекта Mesa, първите тестове показват 2 до 16 процента подобрение", "schlagzeile": "Xbox тества Linux шейдърен компилатор: до 16 процента повече производителност", "kurz": "Microsoft предоставя на разработчиците на игри за Xbox Series X и S експериментален шейдърен компилатор, базиран на ACO от графичния Linux проект Mesa. При първите тестове подобренията са между 2 и 16 процента. Съществуващите игри няма автоматично да станат по-бързи.", "zusammenfassung": "Новостта е описана в документацията на Microsoft за Game Development Kit от октомври 2026 г., а ComputerBase, Wccftech и TechSpot са я подели. ACO означава AMD Compiler и е разработен за Linux с участието на Valve; той се използва по подразбиране във Vulkan драйвера RADV за графики на AMD, а оттам и в Steam Deck. Шейдърите са малки програми, които изчисляват светлина, повърхности и ефекти и преди изпълнение трябва да се преведат в машинни инструкции за GPU. ACO е пригоден за архитектурите на AMD и пасва на графиката RDNA 2 в Xbox Series X и S. Microsoft не се нуждае от самия Linux драйвер, тъй като компилаторът се интегрира в базираната на DirectX 12 среда за разработка на Xbox. Според Microsoft могат да спечелят както времето за компилиране, така и производителността по време на работа, в зависимост от енджина, съдържанието и тесните места при шейдърите. Microsoft не посочва конкретни игри, методи на измерване или сравнения на FPS. Затова по-бърз компилатор не означава автоматично 16 процента повече кадри в секунда. Разработчиците трябва сами да изпробват ACO и да пуснат адаптирани версии на игрите си, за да има полза за играчите. Дали и кога ACO ще стане стандарт в инструментите на Xbox, не е ясно.", "weitere_links": ["Microsoft Learn (GDK, What's new)", "Wccftech", "TechSpot"], "_src": "fa977df9"}, "2026-11-20-windows11-kb5132057-suche": {"titel": "Незадължителната актуализация KB5132057 за Windows 11 носи изцяло пренаписано, нативно търсене в Windows, модерен прозорец „Изпълнение“ и възможност за изключване на прозореца за Залепващи клавиши", "schlagzeile": "Актуализация на Windows 11: ново търсене без Edge отдолу и модерно „Изпълнение“", "kurz": "Microsoft разпространява незадължителната актуализация KB5132057 за Windows 11 25H2 и 26H2. Тя постепенно носи изцяло преработено търсене в Windows, модерен прозорец „Изпълнение“ и други новости. Който изчака, ще получи всичко с Patch Tuesday на 8 декември.", "zusammenfassung": "Според Windows Latest търсенето в лентата на задачите досега се базираше на WebView2, тоест по същество на Edge, а сега е пренаписано нативно в WinUI. В теста на Windows Latest то е използвало с 15 до 20 процента по-малко памет и е реагирало по-бързо. Новото търсене показва резултатите в един списък и може директно да изпълнява действия, например да включва Bluetooth или тъмния режим; според Microsoft първоначално е достъпно на английски. Обновеният прозорец „Изпълнение“ трябва да се включи от Настройки, Система, Разширени, а бутонът „Преглед“ отпада. Удобно за геймърите: прозорецът за Залепващи клавиши, който се появява след петкратно натискане на Shift, вече може да се изключи директно. Windows Hello може за кратко да увеличи яркостта на екрана на тъмно, а търсенето в „Този компютър“ във File Explorer вече използва индекса за търсене. В режим Xbox бързите настройки вече са достъпни и в изгледа на задачите за игри. Добавени са и корекции, например за Miracast с твърде ниска резолюция и за фалшивото предупреждение, че някой друг още използва компютъра. Много функции се разпространяват постепенно и не се виждат веднага след инсталирането. Според Windows Latest пакетът е почти 5 GB, а като известен проблем Microsoft посочва SQL връзки, които остават отворени.", "weitere_links": ["Windows Latest"], "_src": "e89583d7"}, "2026-11-19-amd-hunterbrook-aktie": {"titel": "Акциите на AMD временно падат с 15 процента след доклад на късия продавач Hunterbrook; обвинение: фърмуер на AMD се появява в сървърни ъпдейти на китайска фирма от американския Entity List", "schlagzeile": "Доклад на къс продавач за Китай: акциите на AMD за кратко падат с 15 процента", "kurz": "Акциите на AMD паднаха в четвъртък с около 15 процента за около 30 минути, след което се възстановиха. Поводът беше доклад на Hunterbrook, който самият залага на спад на акциите на AMD. Докладът изрично посочва, че не доказва нарушение на експортния контрол.", "zusammenfassung": "Hunterbrook Media обвинява AMD, че има собствен проблем с Китай, и прави сравнение с аферата Megaspeed при Nvidia. Същността на доклада: китайският производител на сървъри IEIT Systems е в американския Entity List от март 2025 г. и не може да прави бизнес с американски фирми без лиценз. Въпреки това IEIT оттогава е вградила поне шест по-нови версии на стартовия фърмуер на AMD в свои BIOS ъпдейти, последно през октомври 2026 г. Hunterbrook откри почти идентични файлове при три неизброени в списъка фирми, които според фирмени документи са свързани с IEIT: Aivres, Kaytus и Maginfra. Докладът не изяснява как IEIT е получила кода и дали има лицензи; TechPowerUp смята за възможно например предаване чрез трети страни или извличане от публично разпространяван фърмуер. Hunterbrook описва и бизнеса на AMD в Китай, включително 67 милиона долара приходи от лицензи през 2025 г. от две вписани съвместни дружества и 22,4 процента от оборота с клиенти в Китай и Хонконг. Важен е конфликтът на интереси: Hunterbrook е обявил къса позиция в AMD и печели от спад на цената. Наличните публикации не съдържат позиция на AMD. Според TechPowerUp цената се възстанови след краткия срив. За купувачите на компютри засега нищо не се променя, обвиненията засягат сървъри и експортни правила.", "weitere_links": ["Wccftech"], "_src": "a08f2a52"}, "2026-11-19-ubisoft-halbjahr-verlust-motherbrain": {"titel": "Ubisoft отчита нетна загуба от 254,5 млн. евро и с 16,5 процента по-ниски net bookings за първото полугодие на 2026/27 г., съкращава 166 работни места в Монреал и Квебек и създава AI дъщерната фирма Motherbrain", "schlagzeile": "Ubisoft: 254 млн. евро загуба, 166 съкращения – и собствено AI студио", "kurz": "Ubisoft е на загуба от 254,5 милиона евро за първото полугодие на финансовата година, а net bookings са спаднали с 16,5 процента. Малко преди това компанията потвърди съкращаването на 166 места в студиата в Монреал и Квебек, които работят по Assassin's Creed и Far Cry. Едновременно отделът за генеративен AI Motherbrain става самостоятелна дъщерна фирма.", "zusammenfassung": "Според Insider Gaming net bookings за полугодието са 644,7 милиона евро след 772,4 милиона година по-рано. Второто тримесечие с 388,9 милиона евро се оказа по-добро от собствената прогноза за около 370 милиона, най-вече благодарение на Assassin's Creed Black Flag Resynced. Слаби обаче бяха по-старите игри, чиито приходи паднаха с 40,8 процента, и текущите разходи на играчите – с минус 33,4 процента. За цялата година Ubisoft запазва целите си: спад на net bookings с висок едноцифрен процент и изходящ паричен поток от най-много 500 милиона евро. От финансовата 2027/28 г. компанията иска отново да има оперативна печалба. Според GamesIndustry.biz 166-те места в Монреал и Квебек са около 4 процента от персонала там и засягат проекти, които са спрени или силно преработени, отчасти и съвместното дружество Vantage Studios с Tencent. Ubisoft обяснява това с променени производствени приоритети и обещава обезщетения и подкрепа. Съкращенията са част от обявеното през януари преструктуриране, което вече доведе до затваряне на студиа и шест спрени проекта. Новото е Motherbrain: според VGC екипът зад AI експеримента Teammates вече е отделна дъщерна фирма за AI базирана геймплей механика. Дали от това ще излязат собствени игри, или технологията ще влезе в други заглавия на Ubisoft, не е ясно.", "weitere_links": ["Eurogamer", "VGC"], "_src": "16685f62"}, "2026-11-19-zen6-desktop-nach-computex": {"titel": "Слух: настолните процесори Zen 6 на AMD (Olympic Ridge) ще излязат едва след Computex 2027 заради преминаване към TSMC N2X", "schlagzeile": "Изтичане: Zen 6 за настолни PC се отлага до след Computex 2027", "kurz": "Според лийкър от китайския форум Chiphell AMD е прехвърлила настолните си процесори Zen 6 към процеса N2X на TSMC. Това щяло да избута премиерата след Computex в началото на юни 2027 г. AMD не е потвърдила.", "zusammenfassung": "Информацията идва от потребителя на Chiphell Zhang Zhonghao и е подета от Wccftech и TechPowerUp. Според нея Olympic Ridge, кодовото име на настолната серия, вече няма да ползва N2 или N2P, а N2X – 2-нанометров вариант, насочен към високи честоти. Тази смяна щяла да избута премиерата след Computex 2027. Самият Wccftech спекулира за юли или август 2027 г., но подчертава, че това е собствено предположение въз основа на предишни премиери. Досега се очакваше премиера през първото тримесечие на 2027 г. с представяне на CES; AMD потвърди участието си в CES, но не назова продукти. Според TechPowerUp сървърните чипове Zen 6 ще продължат да ползват N2 и N2P. Все така се очаква Zen 6 да остане на сокет AM5 и да предлага до 12 ядра на CCD. Нищо от това не е потвърдено и двете медии изрично третират отлагането като слух. Ако е вярно, Intel с Nova Lake в началото на 2027 г. ще има за няколко месеца новото настолно поколение само за себе си.", "ursprungsquelle": "Zhang Zhonghao във форума Chiphell", "weitere_links": ["TechPowerUp"], "_src": "1b942d45"}, "2026-11-19-gta6-japan-zensur": {"titel": "Японската версия на GTA 6 смекчава кръвта, осакатяванията и голотата без възможност за връщане", "schlagzeile": "GTA 6 в Япония: по-малко кръв, без обезглавявания, бански под душа", "kurz": "Японската версия на GTA 6 е осезаемо смекчена откъм насилие и голота. Кръвта и раните са приглушени, обезглавяванията липсват, а Джейсън и Лусия се къпят под душа по бански. За разлика от други региони това не може да се промени в настройките.", "zusammenfassung": "Според VGC скрийншоти и видеа от Япония показват, че кръвта и gore съдържанието са силно намалени. Японският сайт GameSpark публикува подробен преглед на промените, включително по-малко кръв при ранени и победени противници и напълно премахнати обезглавявания. Версията се намесва и в голотата: под душа главните герои носят бански, докато в други региони са голи. Откъм геймплей играта според досегашните сведения остава също толкова жестока, промените са козметични. В други региони играчите сами могат да намалят кръвта и gore в настройките на дисплея и да изключат осакатяванията; в Япония няма начин те да се увеличат. Цензурата беше очаквана, защото японската версия е с малко по-малък размер на файловете. Според VGC обаче същото важи за Нова Зеландия и Австралия, без засега да са известни драстични промени там. Според наличните публикации самата Rockstar не е коментирала разликите. Няма индикации за орязана версия за играчите в Германия и Австрия.", "_src": "a5f61d49"}, "2026-11-19-fallout-wasteland-full-of-cats": {"titel": "Австралийската възрастова класификация вписва необявената игра от типа hidden object „A Wasteland Full of Cats“ на студио Devcats, според описанието в партньорство с Bethesda и поредицата Fallout", "schlagzeile": "Изтичане: идва ли Fallout игра, в която търсиш котки из картини?", "kurz": "При австралийския орган за възрастова класификация се появи игра на име „A Wasteland Full of Cats“. Според описанието в нея се търсят избягали котки от Vault из пустошта, а разработчик е бразилското студио Devcats в партньорство с Bethesda. Играта не е обявена.", "zusammenfassung": "Вписването откриха потребители в субредита на Fallout, а PC Gamer писа за него. Според описанието на органа играчът е една от котките във Vault: след инцидент всички котки избягват в пустошта и трябва да бъдат намерени и върнати с помощта на няколко персонажа. Споменават се 14 локации и 33 стаи плюс Vault с познати места от поредицата Fallout, както и леки пъзели, които отключват скрити нива. Devcats е известно с поредицата „Full of Cats“ – прости hidden object игри, в които се търсят котки в рисунки. Вписването изрично говори за партньорство с Bethesda и марката Fallout. Bethesda и Devcats засега не са коментирали; платформи, цена и дата не са известни. PC Gamer смята вписването за достоверно, защото органът не е известен с шеги, но оставя отворено дали всичко ще се потвърди. Във всеки случай не става дума за голяма нова Fallout игра, а по-скоро за малко отклонение от поредицата.", "ursprungsquelle": "Australian Classification Board (открито в субредита на Fallout)", "_src": "b64de8d8"}, "2026-11-19-gta6-neuseeland-trick": {"titel": "Ampere Analysis: около 2,1 млн. Xbox играчи от САЩ и Великобритания са използвали „трика с Нова Зеландия“, за да играят GTA 6 по-рано; Sensor Tower оценява около 20 млн. предварителни поръчки", "schlagzeile": "GTA 6: над 2 млн. Xbox фенове се „преместиха“ в Нова Зеландия за ранен старт", "kurz": "Според Ampere Analysis около 1,5 милиона Xbox потребители в САЩ и 600 000 във Великобритания са сменили региона на конзолата си на Нова Зеландия, за да пуснат GTA 6 по-рано. Тъй като играта се отключи навсякъде в полунощ местно време, Нова Зеландия беше първа. При PlayStation трикът беше много по-сложен и по-рядък.", "zusammenfassung": "Rockstar отключи GTA 6 по целия свят на 19 ноември в полунощ местно време за всеки регион. На Xbox е достатъчно да се смени регионът в настройките, за да се влезе в новозеландския магазин и да се играе с много часове по-рано. Освен в САЩ и Великобритания Ampere Analysis отчита около 200 000 играчи в Канада, 200 000 в Бразилия и 100 000 в Мексико. При PlayStation е нужен нов акаунт с регион Нова Зеландия и съответен кредит; според Ampere там трика са ползвали само около 100 000 играчи в САЩ. Формално методът нарушава условията за ползване, но Microsoft и Sony досега не са предприели мерки. Туристическата агенция на Нова Зеландия дори приветства виртуалните гости с намигване в Instagram. Според IGN Германия Sensor Tower оценява, че до 16 ноември GTA 6 е била предварително поръчана около 17 милиона пъти и вероятно е достигнала около 20 милиона преди старта. Rockstar и Take-Two още не са обявили официални данни за продажбите. Всички числа идват от аналитични фирми и са оценки.", "weitere_links": ["IGN", "IGN Deutschland"], "_src": "0a2150e5"}, "2026-11-19-rtx-spark-mini-pcs": {"titel": "Първите мини компютри с Nvidia RTX Spark N1X от Asus, Dell и MSI са в продажба; Asus иска 9299 евро за ProArt GR1X със 128 GB и 4 TB", "schlagzeile": "RTX Spark идва като мини PC – Asus иска до 9299 евро", "kurz": "След лаптопите Arm платформата RTX Spark на Nvidia вече се предлага и като компактни настолни компютри от Asus, Dell и MSI. Всички използват по-големия чип N1X с до 128 GB споделена памет. Asus ProArt GR1X струва 9299 евро в топ конфигурация и като особеност предлага втори M.2 слот.", "zusammenfassung": "Nvidia представя мини компютрите като постоянно включени машини за локални AI агенти, генериране на изображения и видео и дообучаване на модели под Windows. Според Thurrott всички устройства имат N1X с 20 процесорни и 6144 графични ядра, до 128 GB унифицирана памет и 10-гигабитов Ethernet. За разлика от DGX Spark няколко устройства не могат да се свързват заедно. ComputerBase тества MSI EdgeMesa N AI+ със 128 GB и 4 TB SSD за 7999 евро; Asus иска 9299 евро за същата конфигурация. Срещу това Asus използва собствен дизайн на платката с втори M.2 слот във формат 2280, което позволява до 12 TB SSD памет. Asus охлажда и с мед и пет топлинни тръби, което вдига теглото до 1,48 килограма срещу 0,55 килограма при MSI. Acer, Gigabyte, HP и Microsoft със Surface RTX Spark Dev Box ще последват с подобни устройства. Thurrott оцени платформата критично в теста на лаптопа и вижда поне по-смислена употреба в настолния формат. Устройствата не са за класически гейминг, а за AI разработчици и творци.", "weitere_links": ["Thurrott.com"], "_src": "8e057bd7"}, "2026-11-19-amd-adrenalin-26-11-2": {"titel": "AMD Adrenalin 26.11.2 WHQL поправя бъга със записа върху SSD вече и за Radeon RX 5000 и RX 6000 под Windows 10, добавя ROCm 10.2 и оправя изключващия се Smart Access Memory", "schlagzeile": "Драйвер Radeon 26.11.2: бъгът със SSD е поправен и за RX 5000 и RX 6000", "kurz": "AMD пусна WHQL драйвера Adrenalin 26.11.2. Той вече поправя прекомерните записи върху системния диск в покой и за Radeon RX 5000 и RX 6000 под Windows 10. RX 7000 и RX 9000 получиха поправката още с 26.11.1.", "zusammenfassung": "Бъгът беше в драйверната услуга AMD External Events Utility и според PCGH в най-лошия случай можеше да причини няколкостотин гигабайта записи на ден. С 26.11.2 вече са покрити всички RDNA видеокарти от 2019 г. насам. Драйверът поправя и проблема Smart Access Memory да се изключва след инсталация под Windows 10. Други поправки засягат изтичане на памет от RX 5000 нагоре, при което програмите с времето стартират все по-бавно, сривове при стрийминг с OBS Studio на RX 9000 и таймаути на драйвера в War Thunder на RX 5000. Ново е поддръжката на ROCm 10.2, Phantom Blade Zero и разширението на Crimson Desert Charting the Unknown. Остават известни проблеми: Crimson Desert може да не стартира на RX 6000 и тогава AMD препоръчва да се остане на 26.11.1. Assassin's Creed Black Flag Resynced може да се срива на RX 7000. Който ползва RX 5000 или RX 6000 под Windows 10, трябва да инсталира ъпдейта заради бъга със SSD.", "weitere_links": ["PC Games Hardware"], "_src": "2de804a0"}, "2026-11-19-windows7-treiber-rtx50-rx9000": {"titel": "Ентусиасти пренасят актуални графични драйвери на AMD, Nvidia и Intel за Windows 7; за първи път Radeon RX 7000/9000, GeForce RTX 40/50 и по-нова графика на Intel трябва да работят под Windows 7", "schlagzeile": "Шест години без поддръжка: RTX 5090 и RX 9070 XT работят под Windows 7", "kurz": "Малка група частни разработчици е преработила графични драйвери за Windows 10 на AMD, Nvidia и Intel така, че да работят под Windows 7. Така за първи път карти като Radeon RX 9070 XT или GeForce RTX 5090 могат да се ползват със старата система. Това е неофициален проект с много малко тестове досега.", "zusammenfassung": "Според PCGH разработчиците са пренесли драйвера на AMD Adrenalin 25.8.1, вариант на 26.5.2 за Polaris и Vega, драйвер на Intel от юни 2024 г. и драйвера GeForce 582.35. За целта драйверите са прехвърлени от модела WDDM 2.x към по-стария драйверен модел на Windows 7. Официално AMD спря поддръжката на Windows 7 след серията RX 6000, Nvidia преди поколението RTX 40, а Intel не поддържа под Windows 7 дори графиката на поколението Core i-8000. Според PCGH зад проекта стоят двама гръцки разработчици от Hackintosh сцената, а X акаунтът TheBobPony служи за говорител. Пренасянето е направено на ръка и без AI. Досега е тествано само с UHD 770 на Core i5-14500, GeForce RTX 5060 и Radeon RX 9060 XT. Няма обещания за качеството на драйверите, а PCGH подготвя собствен тест. Windows 7 не получава редовни ъпдейти за сигурност от 2020 г., затова системата не е добър избор за ежедневно сърфиране. Проектът е интересен най-вече за ретро фенове и майстори със стари игри или програми.", "_src": "305b45de"}, "2026-11-19-powershell-7-windows": {"titel": "Microsoft ще включва PowerShell 7 от следващата версия на Windows и обявява Windows PowerShell 5.1 за остарял; Windows 11 26H2 и Server 2025 са последните версии с вграден 5.1", "schlagzeile": "Windows получава вграден PowerShell 7 – краят на 5.1 започна", "kurz": "Microsoft иска да включва PowerShell 7 от следващата версия на Windows и обяви стария Windows PowerShell 5.1 за остарял. Засега той остава наличен като незадължителна функция и продължава да получава ъпдейти за сигурност. Кога ще изчезне напълно, още не е решено.", "zusammenfassung": "Продуктовият мениджър на PowerShell Джейсън Хелмик представи плановете в блога на PowerShell; Microsoft не посочва конкретен номер на версията на Windows. Според heise Windows Server 2025 и Windows 11 26H2 са последните версии с трайно вграден PowerShell 5.1. В следващата версия 5.1 става Feature on Demand, която обаче при нови инсталации ще е включена по подразбиране. Остарял не означава край на поддръжката: нови функции няма да има, но ъпдейтите за сигурност продължават според жизнения цикъл на съответната версия на Windows. За окончателното премахване Microsoft иска да реши въз основа на данни за използването и да го обяви предварително. Двете версии могат да работят паралелно, но пълна съвместимост не е гарантирана, защото 5.1 се базира на .NET Framework, а 7 на междуплатформения .NET. Затова администраторите трябва да проверят кои скриптове и задачи все още извикват powershell.exe вместо pwsh.exe. PowerShell 7 идва като MSIX пакет, в който още липсват функции, например изпълнение под акаунта SYSTEM. За обикновените потребители отначало малко се променя, но за администраторите и любителите на скриптове това е ясна задача.", "_src": "84a98f9d"}, "2026-11-19-anno117-patch-3-0-1": {"titel": "Anno 117: Pax Romana получава ъпдейт 3.0.1 с по-добра производителност на PS5, по-малко сривове, поправки и повече място за пристанища в Aegyptus", "schlagzeile": "Anno 117: нов пач изглажда версията за PS5 – със странични ефекти", "kurz": "Ъпдейт 3.0.1 за Anno 117: Pax Romana е наличен от 18 ноември за PC, PS5 и Xbox Series X/S. Той трябва да направи по-редки екстремните спадове на кадрите на PS5, да облекчи процесора и да поправи много грешки. Самата Ubisoft обаче предупреждава за някои нови проблеми.", "zusammenfassung": "Според PC Games пачът засяга и наскоро излязлото разширение „Erwachen des Deltas“. По отношение на производителността Ubisoft обещава по-редки силни спадове на кадрите на PS5 и по-ниско натоварване на процесора, което трябва да помогне най-вече при големи записи. Добавени са поправки срещу проблеми с паметта и замръзвания на конзолите, както и срещу сривове с определени видеокарти Intel Arc. Сред десетки други поправки PC Games посочва грешни маршрути на корабите и проблеми със специалистите. В геймплея три острова в северната част на Aegyptus получават повече крайбрежие за пристанищни сгради, което улеснява изграждането на търговски възли. Освен това менюто за строеж в Latium е преработено, цистерните в Aegyptus показват зоната си на напояване, а бонусите на няколко хамбара вече не се натрупват. Едновременно Ubisoft изброява известни нови грешки, които могат да се появят с пача. Който има големи записи, трябва да следи промяната при хамбарите, защото тя може да повлияе на снабдяването.", "_src": "5e4ba383"}, "2026-11-19-microsoft-agent-framework-malware": {"titel": "Нападатели вкарват инфостийлър във версии 1.26.1 и 1.26.2 на Python пакета на Agent Framework на Microsoft; застрашени са данни за вход в Azure, Git, Docker и Hugging Face", "schlagzeile": "Зловреден код в AI фреймуърка на Microsoft: засегнатите трябва да действат", "kurz": "Две версии на Python пакета на Agent Framework на Microsoft съдържаха инфостийлър. Той краде данни за вход в услуги като Azure, Git, Docker и Hugging Face. Който е инсталирал версии 1.26.1 или 1.26.2, трябва да изолира системите си и да смени всички данни за достъп.", "zusammenfassung": "С Agent Framework разработчиците създават собствени AI агенти на Python, .NET и Go; според heise пакетите се изтеглят средно около 200 000 пъти месечно. Зловредния софтуер откриха фирмата за сигурност OX Security и сайтът Opensource Malware. В Python пакета имаше файл agent_framework_meta.pth, чийто единствен ред се изпълнява при всяко стартиране на Python. Така зловредният код можеше да се загнезди в няколко Python проекта. Microsoft върна първата заразена версия 1.26.1 към чистата 1.26.0, но след това нападателите успяха да качат 1.26.2 с друг механизъм за стартиране и същия инфостийлър. OX Security подозира, че нападателите са се сдобили с достъп на Microsoft до хранилището с пакети; това не е потвърдено. Microsoft каза пред The Register, че разследва атаката, и временно направи някои GitHub хранилища частни. Засегнатите трябва да спрат работещите проекти, да изолират заразените системи, да сменят всички използвани там данни за достъп и да проверят засегнатите услуги за чужда активност. Обикновените потребители на Windows нямат пряка нужда да действат; засегнати са разработчиците с пакета.", "weitere_links": ["Neowin"], "_src": "14bd4fee"}, "2026-11-19-edge-lockdown-webgpu": {"titel": "Microsoft тества в Edge Canary режим на заключване, който изключва WebGL, WebGL2 и WebGPU, за да затрудни атаките през GPU процеса", "schlagzeile": "Edge тества режим Lockdown: WebGL и WebGPU се изключват за защита", "kurz": "Microsoft разработва за браузъра Edge незадължителен режим на заключване по модела на Apple. В първата тестова версия той блокира графичните интерфейси WebGL, WebGL2 и WebGPU, през които нападатели биха могли да излязат от пясъчника. Браузърни игри и интерактивни карти тогава може да не работят правилно.", "zusammenfassung": "Според BleepingComputer режимът надгражда разширения режим за сигурност на Edge, който вече изключва JIT компилацията в JavaScript машината V8. Той е предназначен за особено застрашени потребители като журналисти, мениджъри, изследователи по сигурността и администратори, които приемат проблеми със съвместимостта срещу повече защита. Първите мерки са насочени към GPU процеса – компонент с повече права, който обработва сложни графични задачи между кода на браузъра, библиотеки и драйвери. По оценка на Microsoft режимът би блокирал около 60 процента от наблюдаваните на практика атаки за ескалация на привилегии срещу потребители на Edge. Може да се тества в Edge Canary чрез флага edge-sdsm-plus и строгия режим за сигурност с блокирана WebGL и WebGPU графика. Тогава в адресната лента се появява указание, когато дадена страница е засегната. Microsoft планира да разшири режима в следващи версии и да позволи изключения за доверени сайтове. За обикновените потребители и геймъри нищо не се променя, докато сами не включат режима. Кога ще стигне до стабилната версия на Edge, не е ясно.", "_src": "59aaf15d"}, "2026-11-19-gta6-ps5-pro-cpu-30fps": {"titel": "Техническият шеф на Rockstar Марк Чеймбърс: процесорът на PS5 Pro е твърде слаб, за да изчислява симулацията на GTA 6 при по-висока кадрова честота; няма 60 fps режим на настоящите конзоли", "schlagzeile": "Rockstar обяснява 30 fps: процесорът на PS5 Pro не стига за GTA 6", "kurz": "Rockstar потвърди, че GTA 6 остава на 30 кадъра в секунда и на PS5 Pro. Според техническия шеф Марк Чеймбърс процесорът на конзолата е само малко по-силен от този на стандартната PS5 и не стига, за да изчислява сложната симулация с повече кадри. Затова режим за производителност на настоящите конзоли няма да има.", "zusammenfassung": "Чеймбърс, Technology Production Director в Rockstar, говори пред Kotaku, а Wccftech подхвана изказванията. Според него базовата версия използва отражения и глобално осветление с рейтрейсинг. На PS5 Pro се добавят сенки с рейтрейсинг и по-остра картина чрез ъпскейлъра PSSR на Sony. По-мощният графичен чип на Pro се използва значи за качество на картината, но процесорът е само леко по-добър от този в стандартната PS5. Той не е достатъчно мощен, за да върти сложната симулация на играта при по-висока кадрова честота. С това Rockstar отказва исканията за режим с 40 или 60 fps и намалена графика. Wccftech вижда в това и отговор на обвиненията в лоша оптимизация и посочва остарелите процесори Zen 2 в настоящите конзоли. Според теста на Wccftech PS5, Xbox Series X и Series S не винаги държат стабилно 30 fps. По-висока кадрова честота вероятно ще има едва с PC версия или със следващото поколение конзоли; Rockstar все още не е дала дата за PC версия.", "_src": "a8a35595"}, "2026-11-19-trendforce-nand-2027": {"titel": "TrendForce очаква договорните цени на NAND да паднат с 0 до 5 процента от първото тримесечие на 2027 г. и във всички категории от второто; причината са съкратени поръчки на SSD от китайски облачни доставчици", "schlagzeile": "Анализатори: SSD паметта ще поевтинее отново през 2027 г.", "kurz": "Според TrendForce пазарът на NAND ще премине в свръхпредлагане през 2027 г. Договорните цени се очаква да паднат с 0 до 5 процента през първото тримесечие на 2027 г., а от второто тримесечие във всички продуктови категории. За потребителите това е прогноза, а не намаление на цените в магазина.", "zusammenfassung": "TrendForce обяснява обрата най-вече с Китай: тамошните облачни доставчици са съкратили поръчките си за сървърни SSD за 2027 г. повече, отколкото американските доставчици поръчват допълнително. Същевременно предлагането на NAND битове се очаква да нарасне с 25 до 30 процента през 2027 г., например заради повече QLC памет и чипове с повече слоеве. Според прогнозата инвестициите в бранша ще нараснат с 26,7 процента до 29,9 милиарда долара. TrendForce вече намали очаквания ръст на договорните цени за четвъртото тримесечие на 2026 г. до 8–13 процента, а спот цените наскоро паднаха с над 20 процента. За крайните устройства обаче TrendForce очаква по-скоро растящи цени през 2027 г., защото евтините запаси от памет се изчерпват, а производителите намаляват обема на паметта. heise вижда в това първи признаци, че цените на SSD може да паднат в началото на 2027 г. Според TrendForce остава несигурно колко бързо Китай ще намали запасите, как ще се променят правилата за износ на GPU и какви последици ще има политиката на САЩ след междинните избори за планираните центрове за данни. Цените в магазините и без това реагират на договорните цени със закъснение. Прогнозата не казва нищо за RAM паметта (DRAM).", "weitere_links": ["heise online"], "_src": "ed53a871"}, "2026-11-19-nvidia-gentlemen-ransomware": {"titel": "Ransomware групата The Gentlemen включва Nvidia в сайта си за изтичания и заплашва да публикува данни на 28 ноември; Nvidia разследва възможен инцидент при външен партньор", "schlagzeile": "Изнудвачи заплашват Nvidia с изтичане на данни – отброяването е до 28 ноември", "kurz": "Ransomware групата The Gentlemen от сряда посочва Nvidia на своя сайт за изнудване в даркнета и заплашва да публикува уж откраднати данни, като отброяването изтича в края на следващата седмица. Досега групата не е показала доказателства за атака. Nvidia заявява, че разследва възможен инцидент при външен доставчик и не е открила признаци собствените ѝ системи да са компрометирани.", "zusammenfassung": "Според BleepingComputer The Gentlemen е добавила Nvidia към сайта си за изтичания и е пуснала отброяване, което приключва на 28 ноември. Списъци с файлове, обем на данните или други проверими доказателства все още липсват. Говорител на Nvidia каза пред BleepingComputer, че компанията разследва инцидент, който може да е засегнал външен партньор. Няма данни системите или мрежите на самата Nvidia да са засегнати, а компанията продължава да следи ситуацията. Nvidia не казва за кой партньор става дума. PCGH посочва наблюдение на портала Ransomnews: от 6 октомври групата води в сайта си тайванския доставчик Jentech Precision Industrial, който се представя като партньор в екосистемата Nvidia MGX и произвежда охладителни компоненти за AI системи. Дали има връзка, не е ясно. The Gentlemen действа от 2025 г., работи като ransomware-as-a-service и залага на двойно изнудване, тоест кражба на данни плюс криптиране. В сайта за изтичания вече фигурират над 1100 предполагаеми жертви, което не означава доказани атаки. Nvidia вече потвърди пробив от Lapsus$ през 2022 г., а през май тази година и изтичане на данни при регионален партньор на GeForce NOW. Засега не може да се прецени дали на 28 ноември наистина ще се появят данни.", "weitere_links": ["PC Games Hardware"], "_src": "170f0926"}, "2026-11-19-intel-foundry-microsoft-emib-18a-p": {"titel": "Intel Foundry печели Microsoft като първи обявен клиент за EMIB опаковане и неназован първи клиент за 18A-P; добивът на 18A вече бил над 70 процента", "schlagzeile": "Фабриките на Intel: Microsoft поръчва опаковане, има и първи клиент за 18A-P", "kurz": "Според Intel Microsoft е първата компания, която публично използва технологията за опаковане EMIB на Intel Foundry за собствени чипове за Azure. Към това се добавя първи външен клиент за процеса 18A-P, чието име не е съобщено. Изпълнителният директор Лип-Бу Тан посочи добив на 18A от над 70 процента.", "zusammenfassung": "EMIB означава Embedded Multi-die Interconnect Bridge: малки мостови чипове, чрез които два по-големи кристала комуникират в един корпус. Според съобщението на Intel Microsoft ще използва EMIB за чипове за Azure със собствен дизайн; какво точно ще бъде свързано, още не е ясно. Споразумението осигурява на Microsoft и многогодишен капацитет от процесори Xeon, включително бъдещото сървърно поколение Diamond Rapids. Лип-Бу Тан спомена първия външен клиент за 18A-P на конференция, без да назове име; техническият директор на Intel Пушкар Ранаде го потвърди в X с кратко „Yes“. Добивът на 18A вече е над 70 процента, каза Тан. ComputerBase го оценява критично: 18A е в серийно производство от около година, а по-ранното обещание за подобрение от около 7 процента на месец не съвпада напълно с тази стойност. Анонимността на клиента за 18A-P е обичайна в бранша, но Intel вече е имала няколко партньори във фаундри бизнеса, от които в крайна сметка не излезе много. За PC геймърите новината е най-вече индикатор: ако собственото производство заработи, Intel може да прави бъдещите си настолни процесори с по-малка зависимост от TSMC.", "weitere_links": ["Wccftech"], "_src": "dbd459f0"}, "2026-11-19-gta6-release-de-cix-psn": {"titel": "GTA 6 излезе за PS5 и Xbox Series X/S; предварителното изтегляне постави рекорд в DE-CIX, а вечерта преди това много потребители на PS5 съобщиха за проблеми с PSN", "schlagzeile": "GTA 6 е тук: рекорд в DE-CIX, а PSN се затрудняваше още предната вечер", "kurz": "От полунощ GTA 6 официално може да се играе в Германия и Австрия на PlayStation 5 и Xbox Series X/S. Още предварителното изтегляне постави нов рекорд за трафик в интернет възела DE-CIX. Вечерта преди това много потребители на PS5 съобщиха за проблеми с влизането и изтеглянето в PlayStation Network.", "zusammenfassung": "Според техническия директор на DE-CIX Томас Кинг трафикът е достигнал 22,3 терабита в секунда във Франкфурт и 33,01 терабита в секунда във всички локации по света, и двете стойности са рекорди, съобщава heise, позовавайки се на dpa. Във Франкфурт пикът е бил с около 19 процента над предишния рекорд от януари 2026. В сряда вечерта, според Polygon, се натрупаха сигнали за проблеми с PSN, като „Sony services are busy“ или грешки при връзка при вход и изтегляне, докато официалната страница за статус на Sony на моменти показваше мрежата като нормална. Sony не е посочила официална причина в използваните източници. Според heise който е сменил региона на своя Xbox на Нова Зеландия, е можел да играе още в сряда; при PS5 ранното отключване зависи от региона на магазина, от който е купена играта. PlayStation Europe и Xbox обявиха старта и в X. Стандартното издание струва 80 евро, а Ultimate Edition 100 евро. На всички конзоли играта върви с максимум 30 кадъра в секунда, а Rockstar все още не е обявила версия за PC. Според heise GTA 6 все още има 99 от 100 точки в Metacritic.", "weitere_links": ["Polygon (срив на PSN)", "PlayStation Europe в X"], "_src": "52075601"}, "2026-11-19-microsoft-to-do-eingestellt-2027": {"titel": "Microsoft спира приложението за задачи To Do на 30 юни 2027; бизнес и образователните акаунти минават към Planner, частните потребители остават без заместител", "schlagzeile": "Microsoft погребва To Do: частните потребители остават без заместител през 2027", "kurz": "Microsoft ще спре приложението за задачи To Do на всички платформи в края на юни 2027. За бизнес и образователни акаунти ще го замени Microsoft Planner. Частните потребители, дори с абонамент за Microsoft 365, няма да получат приложение наследник, а само функция за експорт.", "zusammenfassung": "Microsoft потвърди края в отделен документ за поддръжка, съобщават Dr. Windows и Neowin. Засегнати са приложенията за Windows, Mac, iOS, Android и уеб, както и личните акаунти, включително Microsoft 365 Personal и Family. Microsoft изрично препоръчва на частните потребители да потърсят друго приложение за задачи. Функция за експорт ще се появи преди крайния срок; кои данни ще поддържа, още не е ясно. За бизнес и образователни клиенти Microsoft ще пусне от декември 2026 обновен изглед „Моите задачи“ в Planner. Но и там няма да има автоматично прехвърляне, а функции като споделени списъци, групи от списъци или прикачени файлове отчасти липсват в Planner. Според Neowin не се планират нативни приложения Planner за Windows и Mac. До крайния срок To Do ще продължи да работи нормално. To Do стартира през 2017 като наследник на Wunderlist, който Microsoft купи през 2015 и спря през 2020.", "weitere_links": ["Neowin", "Windows Latest"], "_src": "7560a295"}, "2026-11-18-nginx-zehn-luecken": {"titel": "Актуализации за сигурност за nginx Open Source и nginx Plus затварят десет уязвимости, пет от тях с CVSS 9.2; в някои случаи нападатели биха могли да изпълнят код", "schlagzeile": "Уеб сървърът nginx: десет пробива, пет критични, обновете веднага", "kurz": "За широко използвания уеб сървър nginx излязоха актуализации за сигурност, които затварят десет уязвимости. Пет от тях имат тежест 9.2 по CVSS 4.0, а някои вероятно позволяват изпълнение на зловреден код. Администраторите трябва да обновят незабавно.", "zusammenfassung": "Актуализациите засягат както nginx Open Source, така и комерсиалната версия nginx Plus, съобщава heise. Някои от грешките са в кода от години, две от тях дори от 2007. Четири от десетте уязвимости са от типа use-after-free, при който вече освободена памет се използва отново. Това може да позволи на нападатели да изпълняват собствен код на чужди сървъри. В комбинация с други известни уязвимости така може да се получат root права, затова се говори за „nginx2root“. Останалите грешки варират от препълване на буфер и повреда на паметта до безкрайни цикли и заобикаляне на проверката Server Name Indication. Регистрирани са под десет CVE номера, сред които CVE-2026-113425 и CVE-2026-125283. За геймърите у дома nginx рядко има пряко значение, но много сайтове, панели за гейм сървъри и домашни сървъри разчитат на него. Който сам поддържа nginx, трябва да обнови пакетите от своята дистрибуция или директно от nginx.", "_src": "fa48bee5"}, "2026-11-18-nvidia-treiber-ssd-schreiblast": {"titel": "Потребители съобщават, че актуалните драйвери на GeForce записват в покой до 30 GB на час на SSD чрез NVDisplay.Container.exe; AMD разширява поправката си за RX 5000 и RX 6000 с Adrenalin 26.11.2", "schlagzeile": "След AMD и Nvidia: драйверът на GeForce пълни SSD дисковете с данни", "kurz": "След драйвера на Radeon сега се съобщава, че и драйверът на GeForce в покой записва необичайно много данни на системния диск, в отделни случаи до 30 GB на час. Споменават се версии 621.14 и 621.24. Nvidia все още не е коментирала; според потребители като временно решение помага връщането към 621.01.", "zusammenfassung": "Според сигнали от потребители виновен е процесът NVDisplay.Container.exe, който принадлежи на услугата „NVIDIA Display Container LS“. Той многократно презаписва лог файл с име nvlog.nvlgstg в папката ProgramData/NVIDIA Corporation, вместо само да го допълва, съобщават ComputerBase и TechPowerUp. Затова обемът на записа зависи от размера на файла и не е еднакъв при всички. В едно сравнение процесът е записал в покой под 2 MB за пет минути с драйвер 621.01 и около 515 MB с 621.14; с 621.24 са измерени дори 30 GB на час. Други потребители със същите драйвери не виждат почти никаква активност, така че проблемът не се проявява навсякъде. Може да се провери в раздела Диск на Монитора на ресурсите в Windows. Спирането на услугата и изтриването на файла помага само до следващото стартиране на услугата, а трайно изключена услуга може да пречи на контролния панел на Nvidia и на Nvidia App. Nvidia не посочва поведението сред известните проблеми и досега не е коментирала. Успоредно с това AMD разшири с Adrenalin 26.11.2 поправката за собствения си проблем със записа на SSD и за Radeon RX 5000 и RX 6000 под Windows 10, съобщава Neowin. Новият драйвер на AMD добавя и поддръжка за Phantom Blade Zero и поправя, наред с другото, изтичане на памет.", "weitere_links": ["TechPowerUp", "PC Games Hardware", "Neowin (AMD Adrenalin 26.11.2)"], "_src": "8101af43"}, "2026-11-18-8bitdo-gamecube-controller-switch2": {"titel": "8BitDo представя GC Bluetooth Gamepad, безжичен контролер в стил GameCube за Switch, Switch 2 и Windows PC за 49,99 долара", "schlagzeile": "GameCube усещане за Switch 2 и PC: 8BitDo пуска безжичен GC контролер", "kurz": "Производителят на аксесоари 8BitDo представи безжичен контролер, вдъхновен от геймпада на GameCube. Той работи със Switch, Switch 2 и компютри с Windows и струва 49,99 долара. Доставките трябва да започнат на 10 декември 2026.", "zusammenfassung": "Според производителя GC Bluetooth Gamepad следва класическия дизайн на GameCube и подредбата на бутоните, включително познатата лилаво-оранжева цветова схема. Свързва се чрез Bluetooth 5.0, чрез безжичен адаптер 2,4 GHz или с USB-C кабел. На първия Switch и на Switch 2 работят и трите начина, а на компютър само кабелът и адаптерът 2,4 GHz. Nintendo вече продава собствен безжичен GameCube контролер за Switch 2, но според Polygon той не работи по подразбиране с първия Switch или с Windows. Версията на 8BitDo е и с 20 долара по-евтина от модела на Nintendo. Контролерът е интересен главно за класиките на GameCube в Nintendo Switch Online, за играчите на Smash Bros. и за емулация на компютър. Дали усещането е като при оригинала, ще покажат едва тестовете. Източникът не посочва цена в евро.", "_src": "004c0c68"}, "2026-11-18-nand-spotpreise-minus-20": {"titel": "Доклад: спот цените на NAND за потребителска памет падат с около 20 процента за месец; Bank of America очаква нов спад на договорните цени с 5 до 10 процента през първото тримесечие на 2027", "schlagzeile": "Светлина в кризата с паметта: цените на NAND падат с около 20 процента", "kurz": "Спот цените на NAND флаш паметта, от която се правят SSD дисковете, са спаднали с около 20 процента за един месец, според корейски икономически доклад. Bank of America очаква договорните цени на потребителската NAND памет да паднат с още 5 до 10 процента през първото тримесечие на 2027. В магазините това ще се усети със закъснение.", "zusammenfassung": "Данните са от Seoul Economic Daily, а Wccftech ги подхваща. Според доклада NAND пластините от 512 Gbit са поевтинели с 32 процента спрямо предходното тримесечие, а продуктите от 1 Tbit с 19 процента. Като причини се посочват слабото потребителско търсене, тъй като купувачите отлагат покупки при много високи цени, и производители, които намаляват паметта в устройствата си. Към това се добавя конкуренцията на китайския производител YMTC, който през второто тримесечие е имал около 14 процента от приходите от NAND. Според доклада Bank of America очаква договорните цени на потребителската NAND памет да паднат с още 5 до 10 процента през първото тримесечие на 2027. Важно: спот и договорните цени стигат до цените на SSD в магазините едва след седмици или месеци, защото между тях стоят складови наличности. При сървърните SSD е обратното: TrendForce очаква договорните им цени да се повишат с 15 до 20 процента през четвъртото тримесечие. Оперативната памет (DRAM) не е обхваната от доклада; там засега няма подобен сигнал. За сравнение: само преди няколко дни се съобщаваше, че някои SSD струват три пъти повече от миналогодишната си цена.", "_src": "0cf65aa9"}, "2026-11-18-devolver-gta6-loeschen-volvy": {"titel": "Devolver Digital раздава Steam ключове за Volvy's Adventure: Reslimed на играчи, които споделят видео как изтриват предварително изтеглената GTA 6", "schlagzeile": "Изтрий GTA 6, спечели инди игра: Devolver се заяжда с премиерата", "kurz": "Издателят Devolver Digital пуска платформената си игра Volvy's Adventure: Reslimed в същия ден като GTA 6. Който сподели видео как изтрива предварително изтеглената GTA 6, може да спечели Steam ключ. Играта обаче излиза само за PC.", "zusammenfassung": "Акцията върви в X: потребителите трябва да споделят публикацията на Devolver с видео как изтриват изтеглената GTA 6 и хаштага #MakeRoomForVolvy, съобщава Eurogamer. Според Eurogamer предварителното изтегляне на GTA 6 е 212 GB. Поантата: Volvy's Adventure излиза само в Steam, така че освобождаването на място на PS5 или Xbox не помага с нищо. Самата Devolver уточнява, че се раздават само Steam ключове. Има и пародиен трейлър, който според PC Gamer пресъздава кадър по кадър трейлъра за премиерата на GTA 6. Играта се разработва от doinksoft, известни с Gunbrella и Gato Roboto. Volvy дълго беше повтаряща се шега в презентациите на Devolver, а сега е главен герой в собствена игра. Devolver обяви още през 2025, че ще издаде игра в деня на премиерата на GTA 6, и местеше плана при всяко отлагане. Преди участие е добре условията да се проверят директно при Devolver.", "weitere_links": ["PC Gamer"], "_src": "3dcb7448"}, "2026-11-18-nvidia-exportkontroll-ausschuss": {"titel": "Nvidia създава в борда на директорите постоянен комитет за национална сигурност, експортен контрол и глобални търговски рискове", "schlagzeile": "След аферата Megaspeed: Nvidia създава собствен комитет за експортен контрол", "kurz": "Nvidia създаде в борда на директорите постоянен комитет за национална сигурност и експортен контрол. Той трябва да следи на най-високо ниво правилата и програмите за съответствие, свързани с търговски рискове. Nvidia не посочва конкретен повод.", "zusammenfassung": "Новият орган се казва National Security and Export Control Oversight Committee. Председател е членът на борда Сюзан Нора Джонсън, а в него влизат още Стивън С. Нийл и Джон О. Дабири. Комитетът ще заседава поне веднъж на тримесечие, включително на закрити заседания. Съществуващите отдели за национална сигурност и търговско съответствие занапред ще докладват директно на комитета и на временния изпълнителен директор Колет Крес. Външни експерти по право, политика за сигурност и международна търговия ще оказват подкрепа. Обявлението идва след оставката на Дженсън Хуанг и разследването срещу компанията за центрове за данни Megaspeed, която се подозира, че е пренасочвала чипове на Nvidia към Китай; Megaspeed отрича. Не е потвърдено дали тези събития са довели до създаването на комитета; според ComputerBase Nvidia не е отговорила на запитване на Reuters по темата. Не са обявени нови ограничения за продукти или промени в експортните процедури. Председателят на борда Харви Джоунс говори за особена отговорност като водещ доставчик на изчислителни технологии.", "_src": "93ae3e25"}, "2026-11-18-gta6-cheats-erst-nach-story": {"titel": "GTA 6 отключва чийтовете едва след края на основната история; активните чийтове блокират запазването, както и трофеите и постиженията", "schlagzeile": "GTA 6: чийтове едва след историята, и то без запазване", "kurz": "В GTA 6 чийтовете могат да се използват едва след като основната история е завършена, съобщават Eurogamer и GameStar. Всеки чийт трябва допълнително да се отключи чрез задача. Докато чийт е активен, не може да се запазва, а трофеите и постиженията са изключени.", "zusammenfassung": "Eurogamer твърди, че е проверил това със записи от различни моменти в историята. Едва след финалните надписи в менюто за прогрес на картата се появява скрит дотогава раздел с чийтове. Там те са подредени по категории, според GameStar общо 61 в пет категории, всеки с описание и задачата, нужна за отключването му, например 100 тренировки за бронежилетка. Както в GTA 5, се въвеждат чрез телефона, като се задържат раменните бутони и се натискат комбинации от кръстачката. При активиране играта предупреждава, че в тази сесия не може да се запазва и че трофеите и постиженията са изключени. За разлика от GTA 5, според Eurogamer отново има чийт за пари, което вероятно обяснява заключването до края на историята, тъй като парите играят роля в сюжета. Това е отклонение от предишните части и от Red Dead Redemption 2, където около половината чийтове бяха достъпни от самото начало. В използваните източници няма официално обяснение от Rockstar за това решение. Според GameStar съответните задачи, изпълнени по време на историята, вече се зачитат за отключването.", "weitere_links": ["GameStar", "GamePro"], "_src": "b2b8c9b0"}, "2026-11-18-gta6-streaming-rekord": {"titel": "GTA 6 чупи рекорди в стрийминга: според Streams Charts 3,29 млн. едновременни зрители в Twitch и около 7,9 млн. във всички платформи преди световния старт", "schlagzeile": "GTA 6 счупи световния рекорд в стрийминга още преди старта", "kurz": "Още преди GTA 6 да може да се играе в повечето държави, играта счупи рекорда за зрители на живо. Според Streams Charts почти 7,9 милиона души са гледали едновременно в Twitch, YouTube, Kick и други платформи, от тях 3,29 милиона само в Twitch.", "zusammenfassung": "GTA 6 излиза поетапно по региони: в Нова Зеландия вече можеше да се играе на 18 ноември, а по-късно и в Сингапур и Хонконг. Според предварителни данни на аналитичната услуга Streams Charts, цитирани от Polygon, играта е достигнала пик от 7 886 402 едновременни зрители във всички платформи. Twitch води с 3,29 милиона, следван от YouTube с 3,19 милиона и Kick с 1,48 милиона. Според тези данни GTA 6 е и най-гледаната категория игри в историята на Twitch, пред League of Legends с 3,11 милиона и Fortnite с 3,04 милиона. Според Streams Charts предишният рекорд за старт на игра във всички платформи е на затворената бета на Valorant от 2020 г. с 1,74 милиона зрители; тогава обаче за гледане се раздаваше достъп до бетата. Eurogamer съобщи за 6,38 милиона зрители в ранния следобед, така че броят продължи да расте през деня. Тъй като още региони тепърва ще бъдат отключени, стойностите може да се увеличат още. Това са предварителни измервания на външна компания, а не официални данни от Twitch или Rockstar. Официалният старт на PS5 и Xbox Series е на 19 ноември.", "weitere_links": ["Eurogamer"], "_src": "9a3f4ea0"}, "2026-11-18-jedec-ddr6-vorschau": {"titel": "JEDEC представи първите данни за DDR6: старт от 12,8 GT/s, 96-битова шина за данни, модули с дължина 74 mm, възможни формати RDIMM, UDIMM и CAMM", "schlagzeile": "DDR6 придобива форма: 50% повече пропускателна способност и много по-къси модули", "kurz": "Организацията за стандарти JEDEC за първи път официално представи ключовите данни за бъдещата памет DDR6. RDIMM модулите ще стартират от 12,8 GT/s, шината за данни расте от 64 на 96 бита, а пропускателната способност трябва да се увеличи с над 50% при старта. Става дума изрично за планове в разработка, а не за готов стандарт.", "zusammenfassung": "На 18 ноември JEDEC Solid State Technology Association публикува предварителен преглед на стандарта DDR6, който се разработва в комитета JC-42. Според JEDEC DDR6 RDIMM модулите ще стартират от 12,8 GT/s спрямо 9,2 GT/s при DDR5; пътната карта стига до 14,4 GT/s и повече. Шината за данни се разширява от 64 на 96 DQ, тоест с 50%. Заедно с по-високите скорости на трансфер това трябва да донесе над 50% допълнителна пропускателна способност при старта. Самата JEDEC подчертава, че тази цел не означава съответно увеличение на производителността в приложенията. Новост е архитектура с псевдоканали, а броят на банките се удвоява. DRAM чиповете трябва да достигнат плътност до 128 Gbit. Интересно за сглобяващите компютри: с дължина 74 mm модулите са значително по-къси от DDR5 модулите от 133 mm. JEDEC посочва RDIMM, UDIMM и CAMM като възможни формати, тоест не само CAMM. Към това се добавят гъвкави варианти на ECC и по-добра ефективност благодарение на входове/изходи с VSS терминиране и режими с ниска консумация за центрове за данни. Фокусът е ясно върху сървърите и центровете за данни за ИИ. Според JEDEC всички данни все още могат да се променят в процеса на стандартизация. Съобщението не посочва дата нито за окончателния стандарт, нито за първите продукти.", "weitere_links": ["TechPowerUp"], "_src": "15fdb014"}, "2026-11-18-rockstar-gewerkschaft-abstimmung": {"titel": "Около 1600 служители на Rockstar в Обединеното кралство гласуват за признаване на синдикат; гласуването приключва на 26 ноември", "schlagzeile": "1600 служители на Rockstar гласуват за синдикат в Обединеното кралство", "kurz": "Докато излиза GTA 6, над 1600 служители на Rockstar в Обединеното кралство гласуват за признаване на синдикат. Срокът е 26 ноември. Все още нищо не е решено; при „да“ това би бил най-големият синдикат в игрите в страната, според PC Gamer.", "zusammenfassung": "PC Gamer и Polygon разказват за гласуването, което съвпада с деня на рецензиите и старта на GTA 6. В мнение за The Guardian програмистът по анимация в Rockstar и синдикален представител Нестор Уриарте пише, че зад рекордните числа стоят хиляди хора, които трябва да видят справедлив дял от успеха. С признато представителство искат по-добре да защитят заплати, условия и бонуси, както и да договарят използването на ИИ в разработката. Уриарте посочва трайни притеснения за извънреден труд, възможна разлика в заплащането по пол и неясни правила за бонуси; същевременно подчертава, че инициативата идва от служители в студиото, не отвън. Дали ще има мнозинство, ще стане ясно чак след 26 ноември. Успоредно трибунал в Глазгоу разглежда обвинения, че Rockstar е ощетила или уволнила хора, участвали в организирането; спорът не е окончателно решен. Уриарте сочи и съкращенията във Firaxis в същата група. В наличните материали няма становище на Rockstar по текущото гласуване.", "weitere_links": ["Polygon"], "_src": "242f70b2"}, "2026-11-18-gta6-technik-fsr4-series-s": {"titel": "Rockstar потвърждава техниката на GTA 6: 1440p с увеличаване до 4K на PS5, PS5 Pro и Series X, 720p с FSR 4 до 1080p на Series S, с цел 30 кадъра в секунда", "schlagzeile": "GTA 6: 1440p на PS5 и Series X, Series S тръгва от 720p с FSR 4", "kurz": "Rockstar потвърди пред Wccftech техниката на GTA 6 на конзолите. PlayStation 5, PS5 Pro и Xbox Series X рендират вътрешно при 1440p и увеличават до 4K; Series S тръгва от 720p и е първата игра на конзолата с AMD FSR 4 за 1080p. Целта е 30 кадъра в секунда; според анализите само PS5 Pro държи тази граница постоянно.", "zusammenfassung": "Данните идват от Rockstar и са преповторени от ComputerBase и Tom's Hardware. На PS5 и Series X се използва собствено TAA решение, на PS5 Pro PSSR на Sony, на Series S FSR 4. След това на всички платформи се наслагва потребителски интерфейс в 4K. Глобално осветление с проследяване на лъчи е предвидено и за Series S, съобразено с хардуера на всяка машина. ComputerBase посочва сенки с проследяване на лъчи само за PS5 Pro. Според таблицата целта от 30 к/с не винаги се държи на по-евтиния Xbox и на обикновения PS5; PS5 Pro трябва да я удържа. Пред Kotaku директорът по техническо производство Марк Чеймбърс каза, според VGC, че „базовата презентация“ на PS5 Pro включва отражения и глобално осветление с проследяване на лъчи и по-голямата острота от PSSR. Процесорът на PS5 Pro е малко по-добър от този в обикновения PS5, но не е достатъчно мощен, за да върти сложната симулация с по-висока кадрова честота. Намаляването на графиката заради 60 к/с в тази дума не звучи като планиран път. Rockstar определя често по-тъмните ръбове като художествено решение; винетирането засега не може да се изключи. Грешка, която понякога го правеше прекалено силно, студиото по собствени думи вече е поправило. PC версия със собствени графични настройки остава без дата. Изявленията потвърждават по-ранни сведения, че GTA 6 остава на 30 к/с и на PS5 Pro.", "weitere_links": ["Tom's Hardware", "Video Games Chronicle"], "_src": "f08fa2d7"}, "2026-11-18-am5-agesa-vcore-14-ryzen-8000": {"titel": "AGESA 1.3.0.1f Patch A ограничава напрежението на ядрата до 1,4 волта при избрани процесори Ryzen 8000; MSI и Asus вече разпространяват съответни BIOS версии", "schlagzeile": "Нов AM5 BIOS: Vcore е ограничена до 1,4 V при някои Ryzen 8000", "kurz": "Нова актуализация AGESA ограничава напрежението на ядрата до 1,4 волта при избрани процесори Ryzen 8000. MSI споменава промяната в бележките към изданието, но не казва кои модели са засегнати. Asus вече разпространява бета BIOS и предупреждава да не се внасят стари профили.", "zusammenfassung": "Фърмуерът се нарича AGESA 1.3.0.1f Patch A, съобщава PCGH. В бележките на MSI пише, че максималната Vcore ще бъде ограничена до 1,4 волта за избрани процесори от серията Ryzen 8000. Кои са моделите и дали указанието идва от AMD, остава отворено. Правилото важи за захранването на ядрата и се отличава от вече известния лимит от 1,3 волта за SoC напрежението. Не е ясно и дали са ограничени само ръчно зададените стойности, или също автоматичното регулиране и Precision Boost Overdrive. Влияние върху ежедневната производителност не е доказано; при ръчен овърклок таванът може да се усети. Актуализацията добавя и нова POST индикация за тренировката на DDR5 памет: при инициализация двуцифреният дисплей минава от 00 до 09 веднъж в секунда и после започва отначало. Това не е процент, но помага да се види дали платката още тренира, или е забила. Asus вече предлага фърмуера като бета за избрани платки X870, X870E и X670E и изрично предупреждава да не се внасят запазени UEFI профили от по-стари версии на AGESA. Който има стабилна система, няма нужда да минава към бета само заради POST индикацията.", "_src": "f31019a5"}, "2026-11-18-gta6-tests-metacritic-99": {"titel": "Излязоха рецензиите на GTA 6: Metacritic в момента е 99 точки, премиерата за PlayStation 5 и Xbox Series X|S е на 19 ноември 2026, а дата за PC все още няма", "schlagzeile": "GTA 6 стартира: рецензиите го хвалят, Metacritic в момента е 99", "kurz": "Рецензиите на Grand Theft Auto 6 вече са тук; в Metacritic играта в момента има 99 точки и е наравно с Zelda: Ocarina of Time. Официалният старт за PlayStation 5 и Xbox Series X|S е на 19 ноември 2026; в Нова Зеландия вече може да се играе. Rockstar все още не е обявила дата за PC версията.", "zusammenfassung": "Много големи издания дават максимални оценки, съобщава сред другите Polygon. OpenCritic в момента е 98 точки. Тези стойности могат още да се променят, когато дойдат още рецензии. Хвалят се преди всичко плътността на света Леонида, връзката между Джейсън и Лусия и нивото на детайл; отделни критики има към бавно начало, неудобно управление или тромава битка. Президентът на Rockstar Сам Хаузър издаде рядко изявление по повод старта, с което разполага IGN: студиото иска да надмине очакванията, да покаже на какво са способни игрите и гледа към „още много години“ споделени преживявания. Какво точно означава това, например онлайн режим, Rockstar не казва. В някои часови зони, например в Нова Зеландия, играчите вече могат да стартират играта; в Европа обикновено през нощта към 19 ноември. Съобщенията за над 1,5 млрд. долара от предварителни поръчки идват от пазарни наблюдатели, не от официално съобщение на Rockstar. PC версията остава без дата; облачният стрийминг на Xbox се споменава като временна възможност. Който цитира оценки и данни за продажби, трябва да има предвид снимката към 18 ноември 2026; и двете могат бързо да се променят. PlayStation официално датира старта в четвъртък, 19 ноември. Поддръжката посочва, че преди игра е нужна системна актуализация на PS5.", "weitere_links": ["IGN (Sam Houser)", "PC Games Hardware", "PC Games (Test)", "PlayStation", "PlayStation Support"], "_src": "8303d6cb"}, "2026-11-20-wow-forever-15-jahre-rekord": {"titel": "Blizzard: World of Warcraft Forever има повече активни играчи седмично, отколкото WoW е имал през последните 15 години, а след две седмици са създадени над 15 милиона героя", "schlagzeile": "WoW Forever: толкова играчи седмично не е имало от 15 години", "kurz": "Две седмици след старта Blizzard обявява рекорд за World of Warcraft Forever: толкова хора седмично не са играли WoW от 15 години. Към това се добавят над 15,16 милиона създадени героя. Конкретен брой играчи Blizzard обаче не посочва.", "zusammenfassung": "Рекордът беше обявен на 18 ноември в X от Холи Лонгдейл, вицепрезидент и изпълнителен продуцент на World of Warcraft. Според PC Games и GamesRadar+ WoW за последно е бил на това ниво в началото на 2010-те, по времето на Cataclysm; тогава Blizzard съобщаваше за около 12 милиона абонати. Инфографика показва данни към 18 ноември: 15 160 147 създадени героя, около 1,48 милиарда завършени мисии и почти 9,8 милиарда победени противници. Към това се добавят над 140 000 гилдии, над 71 милиона групи и почти 29 милиона използвани предмета за лагеруване от новата система за лагери. Героите на играчите са загинали близо 197 милиона пъти, от които около 29 милиона в битки срещу други играчи. Най-смъртоносният бос в подземие е архимагът Аругал от Shadowfang Keep. Важно: героите не са играчи, мнозина създават по няколко. WoW Forever стартира на 4 ноември и се връща към ранния свят на Азерот, разширен с нови зони и подземия. Според Blizzard първите нови рейдове трябва да последват на 9 декември.", "weitere_links": ["GamesRadar+"], "_src": "08fa3246"}, "2026-11-18-windows-server-2028-vorschau": {"titel": "Microsoft публикува публичен предварителен преглед на Windows Server 2028 с по-твърда стандартна защита, локален ИИ и нова техника за съхранение, но без дата за готовата версия", "schlagzeile": "Windows Server 2028 излиза като публичен преглед — без крайна дата", "kurz": "Microsoft публикува публичен предварителен преглед на Windows Server 2028. Целта е по-твърда стандартна защита, локален ИИ и по-бързо съхранение, например с нативен NVMe. Компанията още не посочва дата за готовата версия.", "zusammenfassung": "Така пише Microsoft в блога на Windows Server Tech Community, съобщава heise. Заинтересованите могат също да кандидатстват за Technology Adoption Program. Ясно е и че Microsoft продължава да предлага сървърна операционна система за ползване в собствен център за данни, а не само облачни услуги. При сигурността е предвидена по подразбиране укрепена конфигурация Server Core, нова базова линия за сигурност, Trusted Launch за виртуални машини от поколение 2 и начало на поддръжка на поверителни виртуални машини на подходящ хардуер на място. Планирани са и автоматични сертификати и подготовка за постквантова криптография. Повече скорост обещават нативен NVMe стек, включен по подразбиране, NVMe през TCP и RDMA и възможност за старт от томове ReFS. Управлението на сървъри трябва да влезе като преглед в Microsoft Intune, а режимът за виртуализация на Windows Admin Center е общодостъпен. При ИИ Microsoft говори за „хибриден интелект“: изводът трябва да може да се изпълнява по-близо до данните или под собствен контрол, сред другите с Foundry Local, Windows ML, vLLM и llama.cpp. Като хардуерен преглед Microsoft посочва картата Instinct MI350P на AMD за първата половина на 2027. Microsoft eXecution Containers трябва допълнително да изолират локалния извод. Ако се запази обичайният ритъм, готовата версия може да се появи след около година; това не е ангажимент. Прегледът минава през програмата Windows Insider за сървъри.", "_src": "5da9242a"}, "2026-11-18-amd-ces-2027-zen6-teaser": {"titel": "AMD насрочи участие на CES 2027 на 5 януари в Лас Вегас; тийзър показва много тънък лаптоп, а официални подробности за чиповете още няма", "schlagzeile": "AMD потвърждава участие на CES 2027 — очакват се лаптопи със Zen 6", "kurz": "AMD твърдо обеща участие на CES 2027 в Лас Вегас. Датата е 5 януари 2027 в 10 ч. местно време, 19 ч. централноевропейско. Тийзър показва много тънък, леко отворен лаптоп; кои точно чипове ще представи AMD още не е потвърдено.", "zusammenfassung": "Датата съобщи мениджърът на AMD Джак Хуин на X на 17 ноември, пише ComputerBase; темата отразява и PCGH. Хуин говори за „следваща ера на компютрите“ и иска да даде поглед на CES в Mandalay Bay. Изображението сочи към особено тънки лаптопи. През последните години AMD обикновено представяше на CES нови мобилни процесори, а наличността в магазините често идваше чак месеци по-късно. ComputerBase свързва тийзъра с вече известните кодови имена Medusa Point за предстоящите чипове за лаптопи и с неофициални списъци на мостри от последните седмици, например варианти с 10, 8 и 6 ядра. Тези конфигурации и честоти не са потвърдени от AMD. Не е потвърдено и дали на CES ще бъдат показани настолни производни със Zen 6; PCGH поставя въпроса и официален отговор няма. Съобщенията за допълнителни много икономични ядра под Zen 6 и Zen 6c засега остават предположения. До 5 януари сигурни са главно датата и тийзърът на лаптопа; техническите данни ще дойдат, когато ги обяви самата AMD.", "weitere_links": ["PC Games Hardware"], "_src": "c30de252"}, "2026-11-18-nvidia-q3-huang-bleibt-draussen": {"titel": "В първия си тримесечен отчет след оставката на Дженсън Хуанг Nvidia обявява 115,8 млрд. долара приходи; съветът не възнамерява да го върне като изпълнителен директор", "schlagzeile": "Рекордно тримесечие на Nvidia: съветът изключва връщането на Хуанг като CEO", "kurz": "Nvidia отчете 115,8 млрд. долара приходи и 65,3 млрд. печалба за третото си фискално тримесечие, над очакванията. Председателят на съвета Харви Джоунс заяви, че органът не възнамерява да върне като изпълнителен директор подалия оставка Дженсън Хуанг. По-рано Хуанг беше казал, че ще се почувства удостоен да се върне, ако съветът прецени това за правилно.", "zusammenfassung": "Това е първият тримесечен отчет след оставката на Хуанг миналата седмица. Nvidia официално обявява 115,8 млрд. долара приходи, със 103 процента повече от година по-рано и с 20 процента повече от предходното тримесечие; печалбата нарасна до 65,3 млрд. Само сегментът на центровете за данни донесе 107,6 млрд., със 110 процента повече. Някога самостоятелният бизнес с игри вече е част от Edge Computing, който общо реализира 8,2 млрд., с 42 процента повече. Временната изпълнителна директорка и финансов директор Колет Крес говори за силен старт на сървърната платформа Vera Rubin и за непроменен продуктов план. За четвъртото тримесечие, което е с една седмица по-дълго, Nvidia очаква 130 млрд. приходи, плюс-минус 3 процента, без чипове за центрове за данни за Китай. Брутният марж се очаква да спадне до 71–72 процента. Ангажиментите за бъдещи компоненти нараснаха до 390 млрд. от 279 млрд. през предходното тримесечие, според ComputerBase главно заради скъпи договори за памет. В началото на разговора с анализатори Джоунс уточни, че съветът единодушно е приел оставката на Хуанг и не възнамерява да го върне като изпълнителен директор; няма да отговаря на въпроси за текущото вътрешно разследване. Часове по-рано Хуанг беше написал, че ще се почувства удостоен да се върне, ако съветът прецени, че това е в интерес на акционерите, служителите, компанията и САЩ. Търсенето на постоянен ръководител продължава вътрешно и външно, а Крес остава временно на поста. Преизчислени, резултатите съответстват според ComputerBase на около 105,3 млрд. евро приходи и 59,4 млрд. евро печалба.", "weitere_links": ["Nvidia IR (Quartalsbericht)", "heise online", "TechPowerUp"], "_src": "2b860864"}, "2026-11-18-windows11-baseline-protection": {"titel": "Windows 11 тества Baseline Protection: приложенията получават отговор да или не за осем функции за сигурност и могат да предупредят, да ограничат функции или да откажат старта; общата наличност е планирана за 2027", "schlagzeile": "Windows 11 тества проверка, с която приложения могат да блокират старта", "kurz": "Microsoft тества в Insider предварителен преглед функцията Windows Baseline Protection. Тя събира осем вече съществуващи защити в доклад, който програмите могат да поискат. Разработчиците могат тогава да предупредят, да ограничат функции или да спрат старта; общата наличност е планирана за 2027.", "zusammenfassung": "Windows Latest описва предварителния преглед подробно. Сред осемте точки са, наред с другото, Secure Boot и целостта на паметта. Който е изключил тези функции, например за да стартира Linux успоредно, не преминава проверката. Приложенията получават ясно да или не, списък на липсващото или по-трудно за фалшифициране хардуерно потвърждение, което доставчик може да провери на свои сървъри. Microsoft подчертава, че системата само докладва състоянието; политиката остава за всеки разработчик. Adobe, Battle.net, 1Password и Schoolyear вече тестват интерфейса. Нито една от тези компании не е обявила, че ще блокира общо компютрите, които не минат проверката; Battle.net според репортажа говори за по-висока сигурност при ниско триене за играчите. В Настройки нова страница „Сигурност > Baseline protection“ трябва да показва състоянието и да може да включи много от липсващите функции с един превключвател и рестарт. Microsoft планира обща наличност за 2027; дотогава това остава Insider тест, който още може да се промени. За играчи и майстори е важно, че защита, която може да се изключи, вече може да не предизвиква само местно предупреждение, а да попречи на старта на отделни програми, ако доставчикът реши така.", "weitere_links": ["PC Games Hardware"], "_src": "578e7024"}, "2026-11-17-java4shell-rce": {"titel": "Критичната уязвимост Java4Shell в OpenJDK може да позволи отдалечено изпълнение на код чрез дефектно Base64 декодиране на някои x86-64 системи с AVX-512; Oracle публикува корекции", "schlagzeile": "Java4Shell: сериозна уязвимост в Java, корекциите на Oracle вече са тук", "kurz": "В OpenJDK има уязвимост, наречена Java4Shell, която може да позволи на нападател отдалечено да изпълни код на засегнати системи. Тя е в хардуерно ускорена Base64 функция на някои x86-64 процесори с AVX-512. Oracle публикува корекции на 17 ноември; като временно решение ускорението може да се изключи.", "zusammenfassung": "Уязвимостта е с номер CVE-2026-114938. Изследователската фирма Calif я оценява с 9,2 по CVSS 4.0, критично ниво, а Oracle дава 8,1 (високо) по CVSS 3.1, съобщава BleepingComputer; темата отразяват и heise и PCGH. Засегнати са OpenJDK от версия 17.0.6 и базирани на него пакети, включително Oracle Java SE, Amazon Corretto, Eclipse Temurin, компилацията OpenJDK на Microsoft, Azul Zulu и OpenJDK на Red Hat. Грешката е в ускорен Base64 декодер, използван само на x86-64 процесори с определени AVX-512 инструкции; по-нови Ryzen и Intel системи може следователно да са по-изложени от по-стари машини без тези инструкции. Calif твърди, че е демонстрирала неаутентифицирано изпълнение на код сред други на Jenkins, Jira, Confluence, Keycloak и JFrog Artifactory, и само с вход в още услуги. Няма единна атака за всички програми; подготвените данни трябва във всеки случай да достигнат уязвимата функция. Oracle публикува поправки в ноемврийската актуализация за сигурност. Който не може да обнови веднага, може временно да изключи ускорението със стартови опции, които спират Base64 intrinsici или AVX-512, според изследователите. Има обща демонстрация на повредата в паметта; Calif не е публикувала готови атаки срещу посочените приложения.", "weitere_links": ["heise online", "PC Games Hardware", "Phoronix"], "_src": "91436d41"}, "2026-11-17-game-awards-2026-nominierte": {"titel": "The Game Awards 2026: GTA 6 е номинирана в осем категории; за GOTY се борят 007 First Light, Control Resonant, GTA 6, Phantom Blade Zero, Resident Evil Requiem и Zelda: Ocarina of Time; церемония на 10 декември", "schlagzeile": "Game Awards 2026: GTA 6 обира осем номинации", "kurz": "Номинациите за The Game Awards 2026 са ясни. GTA 6 присъства в осем категории, включително Игра на годината. Победителите ще бъдат обявени на 10 декември в Лос Анджелис.", "zusammenfassung": "На 17 ноември Geoff Keighley публикува номинациите за The Game Awards 2026 във всички категории. Grand Theft Auto 6 води с осем номинации, сред които Игра на годината, Режисура, Сюжет, Художествено направление, Музика и Звук. За Игра на годината се борят 007 First Light, Control Resonant, GTA 6, Phantom Blade Zero, Resident Evil Requiem и The Legend of Zelda: Ocarina of Time. Control Resonant и 007 First Light също имат по няколко номинации. В категорията Most Anticipated Game са например Fable, God of War Laufey и The Witcher 4. В Best Ongoing Game са например Arc Raiders, Fortnite и The Witcher 3. Победителите се определят 90% от международно жури и 10% от феновете чрез гласуване, което вече е отворено. Категорията Player's Voice се решава изцяло от феновете. Церемонията ще се излъчи на 10 декември от Peacock Theater в Лос Анджелис и както обикновено се очакват анонси на нови игри. Интересно е, че GTA 6 излиза едва на 19 ноември и така на косъм попада в периода за тази година. Пълният списък с категории е в посочените източници.", "weitere_links": ["IGN Deutschland"], "_src": "a391820a"}, "2026-11-17-doom-dark-ages-fsr41-vulkan": {"titel": "Обновление 5 на Doom: The Dark Ages е първата Vulkan игра с официални AMD FSR 4.1 и Frame Generation 4; AMD обновява и приставката за Unreal Engine", "schlagzeile": "Doom: The Dark Ages е първата Vulkan игра с нативен FSR 4.1", "kurz": "С обновление 5 Doom: The Dark Ages е първата Vulkan игра, която официално поддържа FSR 4.1 и Frame Generation 4 на AMD. Така отпада досега често нужният обход през инструменти на трети страни. Същевременно AMD обнови приставката за Unreal Engine до версия 4.1.2, която обаче остава ограничена до DirectX 12.", "zusammenfassung": "Това потвърди мениджърът на AMD Джак Хуин в X, съобщава ComputerBase. В края на октомври AMD вече беше включила Vulkan интерфейс в FSR SDK 2.4.0, но игрите трябваше още да го вградят. Машинното увеличаване в FSR 4.1 работи на Radeon RX 9000, RX 7000 и RX 6000, както и на избрани APU Ryzen. За Frame Generation 4 на базата на ИИ са нужни поне видеокарти Radeon от серията RX 9000. id Software посочва също, че Frame Generation може да се включи на графика на Intel, ако хардуерът и драйверите го позволяват; конкретни модели студиото не назовава. Приставката Unreal 4.1.2 пренася новостите от SDK към Unreal Engine 5.3 до 5.8, разширява увеличаването към RX 6000 и някои Ryzen с вградена графика и подобрява frame pacing на RX 9000. Vulkan пътят от SDK още не е в тази приставка. Обновление 5 добавя и режима Slaughter за сюжетното разширение Revelations, излязло през юли 2026, с безкрайни вълни от врагове с нарастваща трудност. За тикера е важен преди всичко първият нативен ползване на FSR 4.1 под Vulkan, не просто още една кръпка за игра.", "_src": "0f86c167"}, "2026-11-18-firaxis-entlassungen": {"titel": "Firaxis съкращава според Bloomberg около една трета от персонала, около 60 души; ръководителката на студиото Хийдър Хейзън напуска, а 2K потвърждава преустройството", "schlagzeile": "Студиото за Civilization, Firaxis, съкращава около една трета от хората", "kurz": "Студиото за Civilization и XCOM, Firaxis, е съкратило около 60 души, около една трета от персонала, според Bloomberg. Ръководителката на студиото Хийдър Хейзън напуска компанията, потвърждава говорител на 2K. Bloomberg, позовавайки се на запознати лица, съобщава и за трудности в разработката на нова игра XCOM.", "zusammenfassung": "Съкращенията са от 17 ноември, малко преди старта на GTA 6 в компанията майка Take-Two. 2K потвърждава преустройството, но не и броя на засегнатите. В изявление 2K казва, че Firaxis се съсредоточава отново върху силата си да създава първокласни стратегически игри, намалява студиото и трябва да се сбогува с талантливи колеги. Тези решения никога не са леки, но са необходими. За напускането на Хейзън 2K казва, че тя предава ръководството сега, за да може нов екип да поеме следващата глава от самото начало. Bloomberg, позовавайки се на запознати, съобщава още, че нова игра XCOM е имала трудности в разработката и през лятото е пропуснала важен етап; работата продължава, но проектът може отново да се промени заради съкращенията. Тези точки не са официално потвърдени. Последната игра на студиото, Civilization VII, излезе през февруари 2025 и раздели играчите. Firaxis вече намаляваше персонала през минали години. Следващото ръководство на студиото още не е обявено.", "weitere_links": ["PC Gamer", "Eurogamer"], "_src": "71672269"}, "2026-11-23-valve-amdgpu-weniger-ruckler": {"titel": "Разработчичка на Valve представя преработени пачове за ядрото AMDGPU, които трябва да намалят накъсването в някои Windows игри под Proton чрез групиране на обновленията на картите на паметта", "schlagzeile": "По-малко накъсване под Linux: пачове на Valve ще изгладят игрите на Radeon", "kurz": "Разработчичката на Valve Natalie Vock публикува нови пачове за Linux графичния драйвер AMDGPU. Те трябва да намалят осезаемото накъсване в някои Windows игри под Proton. Пачовете още се преглеждат, измервания няма.", "zusammenfassung": "Много нови игри използват т.нар. sparse bindings и при нужда закачат или откачат части от текстури или други графични ресурси. Според Vock драйверът досега синхронизира тези обновления с друга графична работа, така че при високо натоварване графичните и изчислителните опашки дълго стоят. Освен това всяка промяна изисква собствено системно извикване, което струва много процесорно време. Десетте пача въвеждат нов интерфейс AMDGPU_GEM_VA2, който обединява много промени в едно извикване и синхронизира по-избирателно. Според Vock това води до значително намаляване на накъсването, но тя не дава числа или засегнати игри. Първа версия се появи още през май, а групирането беше добавено с ревизията от 17 ноември, съобщават Phoronix и VideoCardz. За да има полза за играчите, нов интерфейс трябва да използва и драйвер като Mesa RADV. Дали пачовете ще влязат още в Linux 7.5, не е ясно. Новината е на няколко дни, а я включваме заради значението ѝ за игрите под Linux с карти Radeon.", "weitere_links": ["VideoCardz"], "_src": "be341a3f"}, "2026-11-21-fsr-4-1-2-unreal-rx6000": {"titel": "AMD пуска FSR Upscaling 4.1.2 като плъгин за Unreal Engine 5 и така носи ML мащабиране на Radeon RX 6000 и преносими устройства с Ryzen", "schlagzeile": "FSR 4.1 за Unreal Engine 5: ML мащабиране вече и за Radeon RX 6000", "kurz": "AMD обнови своя FSR плъгин за Unreal Engine 5 до версия 4.1.2. Така базираното на ML мащабиране FSR за първи път работи на Radeon RX 6000 и на избрани процесори Ryzen с интегрирана графика. Плъгинът поддържа Unreal Engine от 5.3 до 5.8, засега само с DirectX 12.", "zusammenfassung": "AMD публикува обновлението в GPUOpen на 16 ноември, а VideoCardz съобщи на 17 ноември. Плъгинът се базира на FSR SDK 2.4 с кодово име Redstone. За Radeon RX 6000 и Ryzen AI Max AMD използва пълния INT8 модел, а за по-слабата интегрирана графика в лаптопи и преносими устройства – оптимизиран модел с по-малко от половината размер. Изборът става автоматично според хардуера, а на неподдържани видеокарти се използва FSR 3. Пакетът включва още FSR Frame Generation 4.0.2 и нов swapchain, който при Radeon RX 9000 оставя показването на кадрите на драйвера. Тази функция изисква драйвер Adrenalin 26.10.1 или по-нов, а FSR Frame Generation 4.0.2 изисква Windows 11. Плъгинът Anti-Lag 2 също е обновен до версия 2.0.6. SDK вече поддържа Vulkan, но плъгинът за Unreal все още не, а AMD не дава срок. Тъй като плъгинът интегрира FSR чрез интерфейса FSR, игрите могат по-късно да получават по-нови версии на FSR и чрез обновления на драйвера. Дали и кога отделните игри ще въведат обновлението, решават разработчиците.", "weitere_links": ["AMD GPUOpen"], "_src": "97119f61"}, "2026-11-16-gta6-hacker-schuldig": {"titel": "Хакерът зад изтичането на GTA 6 от 2022 г. се призна за виновен пред британски съд; атаките срещу Rockstar, Uber и EE/BT са нанесли щети за около 10 млн. паунда", "schlagzeile": "Изтичането на GTA 6 от 2022 г.: хакерът се призна за виновен", "kurz": "Днес 21-годишният младеж, който през 2022 г. хакна Rockstar Games и публикува ранни видеа от GTA 6, се призна за виновен пред съд в Лондон. Присъдата все още предстои.", "zusammenfassung": "На 16 ноември мъжът се призна за виновен пред Woolwich Crown Court в югоизточен Лондон, че е хакнал Rockstar Games и други компании, сред които Uber и EE/BT. Според публикацията прогнозните щети от кибератаките са около 10 милиона паунда. По времето на атаката срещу Rockstar той е бил на 16–17 години. Според Eurogamer, който се позовава на BBC, тогава е бил настанен в хотел под полицейска закрила и за атаката е използвал само Amazon Fire Stick, телевизора в хотела и Bluetooth клавиатура и мишка. Според информацията той е проникнал и в Slack каналите на Rockstar и е заплашил да публикува изходния код на GTA 6. Изтичанията от 2022 г. показаха около час незавършен геймплей и за първи път разкриха главната героиня Лусия. Заради диагноза тежък аутизъм първоначално е бил настанен в болница, но междувременно е обявен за годен да бъде съден и в началото на годината е преместен в обикновен затвор. Присъдата все още предстои. Случаят не бива да се бърка с изтичанията от 2026 г., които се приписват на друго лице. Rockstar потвърди пробива през 2022 г. и заяви, че разработката няма да бъде засегната в дългосрочен план.", "_src": "bd2dd5e0"}, "2026-11-16-speicherpreise-ssd-dreifach": {"titel": "Проверка на цените на ComputerBase за ноември: RAM средно с 446 процента, SSD с 162 процента и твърдите дискове със 151 процента по-скъпи спрямо средата на септември 2025 г.", "schlagzeile": "Криза с паметта: RAM поскъпна с 446 процента, някои SSD струват тройно", "kurz": "ComputerBase отново провери цените на RAM, SSD и твърдите дискове. Средно паметта е с 446 процента над нивото от средата на септември 2025 г., а SSD с 162 процента. Някои комплекти памет струват над шест пъти повече, а някои SSD – три пъти повече.", "zusammenfassung": "От средата на септември 2025 г. ComputerBase следи онлайн цените на по дванадесет комплекта RAM, SSD и твърди диска, които тогава са били особено търсени. Според новия анализ цените достигат нови върхове през ноември. Средно RAM струва с 446 процента повече, отколкото в началото на наблюдението, а някои комплекти са над 500 процента, тоест над шест пъти по-скъпи. SSD поскъпнаха от плюс 146 процента в средата на октомври до плюс 162 процента, а отделни модели струват тройно. Твърдите дискове са средно със 151 процента над началната стойност и напоследък са поскъпнали само леко. Някои комплекти памет поевтиняха малко, но други поскъпнаха още повече. Офертите на малки търговци в eBay и Amazon Marketplace не се включват, защото биха изкривили тенденцията и са рисковани за купувачите. Редакцията подозира, че зад много от тях стоят търговци, които са се запасили по време на кризата. Край не се вижда: според ComputerBase през ноември AMD ще вдигне отново и цените на видеокартите Radeon.", "_src": "0a0a2c9f"}, "2026-11-16-subnautica-2-ea2-gruselbiome": {"titel": "Subnautica 2: видео на разработчиците показва новите, особено зловещи подводни зони от Early Access 2.0, актуализацията се очаква през декември 2026 г.", "schlagzeile": "Subnautica 2: най-голямата актуализация носи най-страшните дълбини досега", "kurz": "Unknown Worlds показва в ново видео на разработчиците зоните от Early Access 2.0 за Subnautica 2. Мъгла, линии на видимост и осветление трябва да ги направят особено заплашителни. Актуализацията се очаква през декември 2026 г., но точна дата още няма.", "zusammenfassung": "Early Access 2.0 е най-голямата досега актуализация за подводната игра за оцеляване, съобщава PC Games. В новото видео разработчиците обясняват как се създават биомите: първо в т.нар. greybox се определя къде живеят съществата и кои зони са защитени. След това подводна мъгла, премислени линии на видимост и светлинни ефекти създават потискаща атмосфера. Цветовете издават къде е безопасно: топлите тонове означават безопасни зони, а студените – опасни. В скрити пещери и ниши чакат награди като нови ресурси, а забележителни скали, източници на светлина и растения показват пътя. Освен това има мистериозна чума, която отнема почти целия цвят на засегнатите части от света, докато не бъдат излекувани. Така светът трябва сам да разказва историята си, без дневници и кинематографични сцени. Видеото показва и новото шаси FROG за превозното средство Tadpole. Early Access 2.0 е планиран за декември 2026 г.", "_src": "88c1897c"}, "2026-11-16-huang-comeback-ft": {"titel": "Financial Times: дни след оставката си Дженсън Хуанг обмисля завръщане като CEO на Nvidia; инвеститорите натискат, Вашингтон е против", "schlagzeile": "Завръщане след оставката? Дженсън Хуанг обмисля да се върне в Nvidia", "kurz": "Само дни след оставката си Дженсън Хуанг обмисля завръщане начело на Nvidia, твърди Financial Times. Инвеститори и известни имена от Силициевата долина притискат борда, а финансовият министър на САЩ Скот Бесент иска нов шеф отвън. Нищо не е решено.", "zusammenfassung": "Дженсън Хуанг се оттегли миналата седмица като CEO на Nvidia след съобщения за няколко връзки, включително с мениджърка в сингапурския клиент на Nvidia Megaspeed. Според Financial Times, на който се позовават ComputerBase и heise, Хуанг вече е обсъждал с доверени хора възможно завръщане и подкрепя тези усилия. Онлайн инициатива под мотото „Върнете Дженсън“ вече отчита над 170 000 поддръжници, сред които по нейни данни над 8200 служители на Nvidia; тези числа не могат да бъдат проверени независимо. Сред инициаторите е основателят на Uber Травис Каланик, кампанията подкрепя и Илон Мъск. Големите инвеститори Брад Герстнър (Altimeter Capital) и Гавин Бейкър (Atreides Management) призовават борда в отворено писмо да не изключва повторно назначаване на Хуанг. Съпротивата идва от Вашингтон: в неделя финансовият министър Скот Бесент се обяви следващият CEO да бъде търсен извън компанията. Според публикацията той иска и в рамките на десет дни информация дали Nvidia е спазвала американските правила за износ. Банковата комисия на Сената на САЩ също призова Хуанг и министъра на търговията Хауърд Лутник на изслушване. Независимото разследване, възложено от борда, все още продължава. Хуанг не притежава мажоритарен дял и не може сам да отмени решенията на борда. Докато ситуацията се изясни, финансовият директор Колет Крес ръководи компанията временно, а във вторник Nvidia обявява тримесечните си резултати.", "weitere_links": ["heise online", "IGN", "TechPowerUp"], "_src": "50d29cce"}, "2026-11-16-phantasialand-chlor-microsoft-ausfall": {"titel": "Последици от срива на облака на Microsoft: алармени имейли на басейнова система в хотел на Phantasialand не са пристигнали, след предозиране на хлор има 15 пострадали", "schlagzeile": "Алармен имейл така и не пристигна: сривът на Microsoft доведе до 15 пострадали", "kurz": "Заради срива на облака на Microsoft в четвъртък и петък алармен имейл в хотел Ling Bao на увеселителния парк Phantasialand в Брюл, Германия, не е стигнал до никого. Повредена дозираща система е изсипала прекалено много хлор в басейн. 15 гости се оплакаха от проблеми с дишането, четирима са откарани в болница.", "zusammenfassung": "Според германската телевизия WDR, на която се позовава heise, системата за поддръжка и безопасност на сауна зоната е подала аларма по имейл. Заради продължителния срив на облачните услуги на Microsoft обаче тези имейли така и не са пристигнали. Автоматичната дозираща система на басейна е била повредена и е добавила твърде много хлор във водата. В петък следобед това е довело до изтичане на хлорен газ в басейновата зона на хотела, който е част от Phantasialand. Първоначално 13 гости се оплакаха от проблеми с дишането, по-късно броят им нарасна до 15. Четирима души бяха откарани в болница, а един трябваше да остане под наблюдение със средно тежки наранявания. Пожарната на Брюл е била на място с 40 души около два часа; басейнът беше затворен, водата сменена, а вече отново работи. Сривът на Microsoft продължи от четвъртък следобед поне до петък по обяд. Според heise той е имал реални и опасни последици, а престъпници го използват от петък и за фишинг имейли.", "_src": "9e40db29"}, "2026-11-16-playstation-controller-bezahlen-patent": {"titel": "Патентна заявка на Sony: контролер на PlayStation да чете данни за плащане от смартфони и карти чрез NFC, Bluetooth или QR код", "schlagzeile": "Плащане с контролера? Патент на Sony го превръща в четец на карти", "kurz": "Sony е подала патентна заявка за контролер на PlayStation, който чете данни за плащане от смартфон или карта чрез NFC, Bluetooth или QR код. Така покупките на конзолата биха ставали без досадно въвеждане. Подобен продукт не е обявен.", "zusammenfassung": "Заявката „Video Game Controller-Driven Information Transfer“ (US 2026/0273403 A1) е от 17 март 2025 г., а патентното ведомство на САЩ я публикува на 17 септември 2026 г., съобщават Golem и Engadget. Когато конзолата поиска плащане, потребителят доближава смартфон или карта до контролера. Той разпознава устройството чрез NFC, Bluetooth или допир, а един вариант чете със сензор за изображение QR код от екрана на телефона. Светлина, звук или вибрация потвърждават връзката, след което конзолата проверява данните на сървър. Посочени са кредитни и банкови сметки, карти за подарък, както и цифрови и крипто портфейли; оставащият баланс на карта за подарък би се показвал директно на екрана. Освен покупки на игри Sony споменава покупки в приложения, мърчандайз, поръчки на храна и кредит за турнири, изложения и игрални зали. Споделянето на профили на играчи, присъединяването към мултиплейър сесии или изпращането на екранни снимки към телефона също биха ставали с докосване. Sony обосновава идеята с това, че днешните процеси често изискват няколко устройства и писане на клавиатура. Патентната заявка обаче защитава само идея, а дали Sony някога ще я приложи, остава открито.", "weitere_links": ["Engadget"], "_src": "464cad26"}, "2026-11-16-intel-sammelklage": {"titel": "Акционери подават в Сан Хосе колективен иск срещу Intel, CEO Лип-Бу Тан и други мениджъри, че са разкрили твърде късно срива в продажбите на компютри", "schlagzeile": "Срив с 29 процента: акционери съдят Intel и CEO Лип-Бу Тан", "kurz": "Акционери на Intel подадоха колективен иск във федерален съд на САЩ в Сан Хосе срещу компанията, CEO Лип-Бу Тан и други мениджъри. Те обвиняват Intel, че е разкрила твърде късно срива в продажбите на компютри. След тримесечните резултати на 29 октомври акциите поевтиняха с почти 29 процента.", "zusammenfassung": "Искът е подаден от адвокатската кантора Robbins Geller Rudman & Dowd, съобщава heise, позовавайки се на BBC; за случая пише и Reuters. Той обхваща всички акционери, купили акции на Intel между 23 юли и 29 октомври 2026 г. Твърди се, че е имало „съществено неверни и/или подвеждащи“ изявления за спада в продажбите на компютри и за последиците от проектите за центрове за данни. Според Wccftech искът засяга освен CEO Лип-Бу Тан и финансовия директор Дейвид Зинснър и посочва продажба на акции за 23 млрд. долара през август. На 29 октомври Intel призна, че заради кризата с паметта са продадени още по-малко компютри от очакваното, и съобщи за проблеми с доставките на чипове за центрове за данни. За текущото тримесечие компанията очаква приходи от едва 15 до 16 млрд. долара, докато анализаторите очакваха около 17 млрд. След това акциите загубиха почти 29 процента за един ден. Intel все още не е коментирала иска. Ищците търсят обезщетение в неуточнен размер, а по обвиненията сега ще се произнесе съдът.", "weitere_links": ["Wccftech"], "_src": "0fdca8b2"}, "2026-11-16-razor-lake-12p-bllc": {"titel": "Изтичане: Intel Razor Lake ще получи геймърски чип с 12 P-ядра, 4 LP-E ядра и голям кеш bLLC без обикновени E-ядра, произведен по Intel 18A-P", "schlagzeile": "Изтичане: Intel подготвя геймърски процесор с 12 P-ядра и огромен кеш?", "kurz": "Информаторът Jaykihn съобщава за настолен чип Razor Lake с дванадесет P-ядра, четири енергоспестяващи ядра и голям кеш (bLLC), но без обикновени E-ядра. Това би бил отговорът на Intel на процесорите X3D на AMD. Razor Lake се очаква едва през 2028 г., а нищо от това не е официално.", "zusammenfassung": "Според TechPowerUp и VideoCardz известният информатор за Intel Jaykihn е посочил в X конфигурация „12+0+4“ за Razor Lake. Това означава дванадесет P-ядра, никакви обикновени E-ядра и четири икономични LP-E ядра, съчетани с големия кеш от последно ниво на Intel (bLLC). Концепцията bLLC се смята за отговора на Intel на чиповете X3D на AMD с допълнителен кеш, които са особено силни в игрите. Отключеният чип трябва да замени по-рано споменаван заключен модел 8+0+4 с bLLC. Всички дванадесет P-ядра ще бъдат на отделен изчислителен чип, който според Jaykihn се произвежда по процеса 18A-P на Intel, докато повечето плочки на Razor Lake уж се правят от TSMC. Освен това модел със 125 вата, ядра 6+12+4 и bLLC е бил преместен от Nova Lake към Razor Lake. Така Nova Lake-S би имал с един bLLC вариант по-малко от очакваното. Razor Lake-S се очаква през 2028 г. и ще използва същия сокет LGA 1954 като Nova Lake-S. Intel е включила номера на модели Razor Lake в справочник за ISA, но спецификациите не са потвърдени. Планове толкова напред във времето още могат да се променят.", "ursprungsquelle": "Jaykihn в X", "weitere_links": ["VideoCardz в X"], "_src": "b4662c61"}, "2026-11-16-pokepark-fishing-rally-gefunden": {"titel": "Изгубена игра с Pokémon е открита: колекционер откри тестов картридж с PokéPark Fishing Rally DS от 2005 г., PSA Video Games потвърждава автентичността", "schlagzeile": "Изгубена игра с Pokémon изплува след 20 години – и може да се играе", "kurz": "Колекционер е открил тестов картридж с PokéPark Fishing Rally DS – риболовна игра, която през 2005 г. е била достъпна само в японски увеселителен парк. PSA Video Games потвърди автентичността му. Така е запазено парче от историята на Pokémon, смятано за изгубено.", "zusammenfassung": "PokéPark Fishing Rally DS е бил достъпен само няколко месеца през 2005 г. в PokéPark в Нагоя. Посетителите изтегляли риболовната мини игра на своя Nintendo DS чрез Download Play от станции в парка. След дванадесет часа или при изключване на конзолата тя се изтривала сама. Играчите ловели Pokémon и се състезавали за награди в класации. След затварянето на парка играта се смятала за изгубена, защото била само на специални тестови картриджи за персонала. Картридж, предложен в eBay за 9000 долара през юли, съдържал само софтуера за класацията. Сега според Polygon колекционерът Даниел Куадри притежава картридж със самата игра, а PSA Video Games потвърди, че е истински. С него той може, както някога, да изпраща играта на други DS конзоли чрез Download Play. Засега картриджът остава в запечатана кутия за защита.", "_src": "0c147818"}, "2026-11-16-wireview-pro-ii-garantie": {"titel": "Thermal Grizzly публикува условията на удължената гаранция за видеокарти на WireView Pro II: 24 месеца защита при повреда на конектора, но само с включено наблюдение", "schlagzeile": "Стопен конектор? Thermal Grizzly обяснява кога важи гаранцията за GPU", "kurz": "Thermal Grizzly публикува условията на удължената гаранция за видеокарти на WireView Pro II. Тя покрива за 24 месеца повреди по конектора 12VHPWR или 12V-2x6 и произтичащите от тях повреди на GPU. Наблюдението трябва да остане включено, а shunt модовете и копаенето са изключени.", "zusammenfassung": "WireView Pro II се поставя между кабела на захранването и видеокартата и измерва тока по всяка отделна 12-волтова линия. Thermal Grizzly обещава на купувачите удължена гаранция при повреди по захранващия конектор, а според TechPowerUp производителят вече е обяснил условията в често задавани въпроси. Нито USB кабелът, нито Y-разклонителят към дънната платка трябва да са свързани; разклонителят позволява на устройството да изключи компютъра при авария, но е само препоръчителен. Наблюдението трябва да остане включено: праговете за ток, температура или мощност могат да се намалят, но не и да се вдигат над стойностите по подразбиране. Удължители между WireView и видеокартата са разрешени, стига всяка 12-волтова линия да остане отделна; адаптери, които обединяват линиите вътрешно, не се покриват. Конектор под 90 градуса сам по себе си не е проблем, а откъм захранването важат кабелите, одобрени за съответния модел. Гаранцията е 24 месеца от покупката на WireView, дори след изтичане на гаранцията на картата, но само за първия купувач с документ за покупка. Изключени са shunt модове, XOC BIOS с вдигнат лимит на мощността и търговско копаене, както и повреди без връзка с конектора. При рекламация Thermal Grizzly първо опитва ремонт, а ако не стане, изпраща карта със сравнима производителност, не непременно от същата марка. Който забележи следи от стопяване, трябва да изключи компютъра, да извади захранването от контакта, да остави конектора поставен, да направи снимки и да се свърже с поддръжката.", "_src": "c3d9a0f0"}, "2026-11-16-windows11-remote-lock-intune": {"titel": "Insider компилация 29708.1001 на Windows 11 тества Remote Lock: ИТ отделът може да заключи изгубен служебен компютър през Intune без изтриване на данни; само ИТ може да махне заключването", "schlagzeile": "Изгубен лаптоп? Windows 11 тества дистанционно заключване, което маха само ИТ", "kurz": "Microsoft тества в Insider версия функцията Remote Lock. С нея ИТ отделите могат да заключват през Intune изгубени или откраднати служебни компютри, без да трият данни. Парола, ПИН или локален администраторски акаунт вече не помагат.", "zusammenfassung": "Windows Latest откри функцията в компилация 29708.1001 в експерименталния канал „Future Platforms“ от 13 ноември. При заключване Windows излиза от всички сесии, скрива опциите за вход и показва заключен екран със съобщение, че организацията е заключила устройството. Според Microsoft нищо не се изтрива, BitLocker остава включен, а устройството продължава да се управлява в Intune. Рестартът или изключването от интернет не махат заключването; отключва се само от ИТ през Intune. Потребителският акаунт остава активен, така че при откраднати данни за вход ИТ трябва да го деактивира отделно в Entra ID. Изискват се Windows Pro, Enterprise или Education и устройство, управлявано чрез Entra ID или MDM; засега настройката става тромаво чрез персонализиран профил в Intune. Уловката: устройство без връзка получава заключването едва при следващото свързване. Освен това Remote Lock не блокира нито средата за възстановяване, нито безопасния режим, нито стартирането от USB памет, затова Microsoft продължава да смята BitLocker за необходим. Още през март 2025 г. служител на Microsoft беше казал, че дистанционно заключване за Windows не се планира. Като Insider тест функцията все още може да се промени до излизането си.", "_src": "9f3701ee"}, "2026-11-16-linux-7-4-rc3-zen5": {"titel": "Излезе Linux 7.4-rc3: TSA защита за AMD Zen 5, енергоспестяващи функции за графиката на AMD, заобиколни решения за ARM ядра и по-добра поддръжка на сензори", "schlagzeile": "Linux 7.4-rc3: защита за Zen 5 процесорите и пестене на енергия за AMD графика", "kurz": "Линус Торвалдс пусна третата пробна версия на Linux 7.4. Според Neowin тя носи защита за процесорите Zen 5 на AMD и енергоспестяващи функции за някои графични чипове на AMD. Финалната версия се очаква след седем пробни версии.", "zusammenfassung": "Торвалдс описва изминалата седмица като доста нормална: повечето промени засягат мрежови и графични драйвери и са малки. В областта на файловите системи се откроява голяма, но по същество тривиална промяна в конвенцията за извикване на iomap. Според Neowin rc3 съдържа описана като критична защита срещу микроархитектурната уязвимост TSA в процесорите Zen 5 на AMD. За графиката на AMD с IP версия 11.0.2 се активират енергоспестяващи функции като Multi-Coarse Gate Clock и Fine-Grain Clock Gating. При ARM ядрата Cortex-A715 и Cortex-A720 ядрото на системата заобикаля дефектни броячи на производителността, които могат да дават грешни стойности и предупреждения. За предстоящите графични платформи на Intel има корекции при разпознаването на монитори през USB-C портове. Освен това ядрото отчита по-надеждно напрежения, обороти на вентилатори и температури при дънни платки със сензорни чипове NCT6775. С това е достигната приблизително половината от цикъла на разработка. Дистрибуции като Arch и Fedora обикновено приемат новите ядра едва след първото поправъчно издание.", "weitere_links": ["Phoronix"], "_src": "55a0b07f"}, "2026-11-16-project-helix-konsole-pc-spiele": {"titel": "Вицепрезидентът на Xbox Джейсън Роналд: Project Helix е конзола, която пуска и PC игри, а не компютър за конзолни игри; невронното рендиране трябва да помогне срещу високите цени на компонентите", "schlagzeile": "Project Helix: следващият Xbox е конзола, която пуска и PC игри", "kurz": "Microsoft разкри нови подробности за Project Helix в списанието за 25-годишнината на Xbox. Според вицепрезидента на Xbox Джейсън Роналд Helix е конзола, която може да пуска и игри от твоя компютър, а не компютър за конзолни игри. Срещу високите цени на компонентите Microsoft залага, наред с друго, на невронно рендиране.", "zusammenfassung": "За 25-ия рожден ден на Xbox Microsoft неочаквано издаде юбилейно списание, а IGN и Insider Gaming обобщиха изявленията в него за Project Helix. „Helix е замислена като конзола, която може да пуска и игри от твоя компютър. Тя не е компютър, който може да пуска и конзолни игри“, казва Джейсън Роналд, вицепрезидент по следващото поколение. Играчите ще могат да вземат със себе си библиотеката си от четири поколения Xbox заедно с прогреса, а границите между конзолните и компютърните игри трябва да паднат. Напредналите потребители все пак ще получат по-дълбоки настройки за графика и производителност. Роналд посочва ROG Xbox Ally като предшественик, чиито концепции и обратна връзка се влагат в Helix. Запазването на старите игри е ключово, казва той: съвместимостта още сега определя как се проектира платформата. За кризата с компонентите Роналд казва, че трябва да се изобретяват нови технологии, за да останат конзолите достъпни. Невронното рендиране може да създава кадри, без да изисква повече изчислителна мощ или памет. Microsoft не дава дата или цена; според IGN се говори за старт най-рано в края на 2027 г. Как ще изглеждат устройствата от семейството Helix, все още не е ясно.", "weitere_links": ["Insider Gaming (първо конзола)", "Insider Gaming (невронно рендиране)", "Insider Gaming (запазване на игри)"], "_src": "e894d330"}, "2026-11-16-gta6-jason-lucia-kleinkriminelle": {"titel": "GTA 6: според интервю на Rockstar за The Guardian Джейсън и Лусия започват като дребни престъпници и трябва да стигнат до големите удари", "schlagzeile": "GTA 6: Джейсън и Лусия започват като дребни мошеници, големите удари са после", "kurz": "В GTA 6 Джейсън и Лусия не започват като професионални обирджии, а като дребни престъпници. Това съобщава The Guardian след разговори с Rockstar. Доходни задачи като обири на бижутерии ще са възможни едва по-късно.", "zusammenfassung": "Британският вестник The Guardian е разговарял с Роб Нелсън, съръководител на студиото Rockstar North, и с ръководителката по издателската дейност Дженифър Колб, а IGN обобщава материала. Според него в началото двамата главни герои могат само да палят на кабел обикновени коли и да отключват прости ключалки. Обирите на бижутерии във Вайс Сити или карането на спортни коли из Леонида ще са възможни едва след като се издигнат. Нелсън описва Джейсън и Лусия като млада двойка, „притисната до стената“. Обирите – от бензиностанции до луксозни бутици – ще са по-лесни или по-доходни, ако се подготвят, например чрез изключване на камери, кражба на записи от наблюдение или проучване на незабележими входове. Който пропусне подготовката, рискува обирът бързо да прерасне в хаос. Според The Guardian за първи път в поредицата ще има и механики, които насърчават съпричастността. Rockstar все още не е казал какво означава това конкретно, нито колко дълго трае издигането. GTA 6 излиза на 19 ноември за PS5 и Xbox Series X|S.", "_src": "b6c3d707"}, "2026-11-16-xbox-boot-animationen-25": {"titel": "За 25-годишнината: Xbox Series X|S и Xbox One получават стартовата анимация на оригиналния Xbox и две стартови анимации на Xbox 360", "schlagzeile": "За 25-ия си рожден ден Xbox връща оригиналната стартова анимация", "kurz": "За 25-годишнината на Xbox собствениците на Xbox Series X|S и Xbox One отново могат да използват стартовата анимация на първия Xbox. Добавят се и две анимации на Xbox 360 от 2005 и 2010 г. Според Xbox актуализацията се разпространява през деня.", "zusammenfassung": "Microsoft отбеляза на 15 ноември 25 години Xbox и обяви в официалния профил на Xbox в X три класически стартови анимации. Освен научнофантастичното интро на оригиналния Xbox има два варианта за Xbox 360 – от старта през 2005 г. и от 2010 г. Според IGN това са до голяма степен непроменени копия на тогавашните видеа. Анимациите идват на всички конзоли Xbox Series X|S и Xbox One и се разпространяват постепенно. Който още не ги вижда, трябва да прояви малко търпение. За юбилея Microsoft издаде и списание с поглед назад и напред, включително нови подробности за следващото поколение Project Helix. Първа нова стартова последователност Microsoft беше добавила още по-рано тази година.", "weitere_links": ["Xbox в X"], "_src": "d0945bc7"}, "2026-11-16-librem-5-v2-risc-v": {"titel": "Purism стартира кампания за финансиране на Linux смартфона Librem 5 v2 с осемядрен RISC-V чип SpacemiT K1, 8 GB RAM и 128 GB памет от 1599 долара", "schlagzeile": "Linux телефонът Librem 5 v2 залага на RISC-V – за солените 1599 долара", "kurz": "Purism събира пари за второто поколение на своя Linux смартфон Librem 5. Вместо Arm чип в него има осемядрен RISC-V процесор на SpacemiT, плюс 8 GB RAM и 128 GB памет. Подкрепящите плащат поне 1599 долара и няма да получат устройството преди 2028 г.", "zusammenfassung": "Librem 5 v2 използва SpacemiT K1 с осем RISC-V ядра и така заменя четириядрения Arm чип на NXP от първия модел. Purism обещава повече производителност, по-дълъг живот на батерията и по-малко топлина. RAM паметта се увеличава от 3 на 8 GB, а вградената памет – от 32 на 128 GB. Корпусът, 5,7-инчовият IPS дисплей с 720 × 1440 пиксела и сменяемата батерия от 4500 mAh остават същите, за да се улеснят ремонтите и надгражданията между поколенията. Остават и хардуерните ключове за камера, модем и GPS, USB-C портът и жакът за слушалки. Новото е подобрен 4G модем, две SIM карти и хардуерно кодиране, което за първи път трябва да позволи снимки с 13 мегапиксела и HD видео; планиран е и сменяем 5G модул. Операционната система е базираната на Debian PureOS с интерфейса Phosh. OMG! Ubuntu припомня, че първото поколение страдаше от закъснения, поскъпвания и неравномерно качество на изработката. Преходът към RISC-V изисква и много работа по графичните драйвери, управлението на енергията и производителността на браузъра. Кампанията продължава до февруари 2027 г.", "_src": "79ec4d2b"}, "2026-11-16-fbi-artex-ki-angriffe": {"titel": "ФБР предупреждава за ARTEX: AI рамка за тестове за проникване се злоупотребява от август 2026 г. за автоматизирани атаки по света, включително при атаката по веригата за доставки на ConnectWise", "schlagzeile": "ФБР предупреждава: AI инструментът ARTEX автоматизира хакерски атаки по света", "kurz": "ФБР предупреждава за ARTEX – рамка за тестове за проникване с изкуствен интелект, с която нападатели злоупотребяват поне от август 2026 г. Някои пробиви са стигали до привилегирован достъп за под три часа. С нея е била извършена и октомврийската атака по веригата за доставки на ConnectWise.", "zusammenfassung": "В предупреждение FLASH от петък ФБР пише, че няколко групи използват рамката с отворен код срещу организации от финансите, администрацията, технологиите, отбраната, здравеопазването и други сектори, съобщава BleepingComputer. ARTEX е написан на Go и оставя AI агенти до голяма степен сами да извършват разузнаване, търсене на уязвимости, атаки, повишаване на правата и кражба на данни. Той няма собствен AI модел, а се свързва с външни езикови модели като Claude, GPT, DeepSeek, GLM, Grok и Kimi. Според ФБР така дори нападатели с малко опит могат да атакуват няколко цели едновременно. Инструментът е особено добър в откриването на слабости в пренебрегвани системи като партньорски портали, приложения за служители, стари услуги и интеграции с трети страни. Разработчикът „Autumn-27“ публикува ARTEX в GitHub през юли и го премахна на 8 октомври, но форкове, архивни копия и търговска версия ARTEX PRO продължават да се разпространяват. В началото на ноември изследователи преброиха над 1600 публично достъпни конзоли на ARTEX. Сред посочените атаки е октомврийската атака по веригата за доставки на ConnectWise Cloud Backup, чрез която нападатели са проникнали в Microsoft 365 среди на клиенти. ФБР препоръчва да се защитят приложенията, достъпни от интернет, и административните достъпи до облака, да се проверят правата и журналите за удостоверяване и да се ограничи честотата на заявките към чувствителни API. Изследователят по сигурността MalwareMustDie публикува и безплатен пакет с правила за откриване за популярни инструменти за сигурност.", "_src": "05be065b"}, "2026-11-15-cyberpunk-torrent-regen-mod": {"titel": "Модът „Torrent“ за Cyberpunk 2077 заменя дъжда в Night City с отделни 3D капки и добавя гръмотевични бури със светкавици", "schlagzeile": "Cyberpunk 2077: нов мод най-сетне кара Night City да вали истински", "kurz": "Модът Torrent заменя плоските ефекти на дъжд в Cyberpunk 2077 с отделни 3D капки, пръски и бури. Капките реагират на вятъра, светлината и скоростта. Модът е безплатен в Nexus Mods.", "zusammenfassung": "Модърът CyanideX пусна мода Torrent за Cyberpunk 2077, съобщава Eurogamer, позовавайки се на DSOGaming. Той заменя досегашните доста плоски ефекти на дъжд с отделни 3D капки със собствен размер и скорост на падане. Капките реагират на движението на играча: при бързо каране шибат към предното стъкло, а силният вятър ги отнася настрани. Уличните лампи, неоновите реклами и фаровете на колите се отразяват в капките, а дъждът вече не вали през покриви и в сгради. Капките пръскат по земята, при силен дъжд в далечината има мъгла, а колите вдигат пръски по мократа улица. Добавена е и нова система за бури с разклонени светкавици, чиято честота се настройва в десет степени. С мода AudioXL след всяка светкавица следва гръм, съобразен с разстоянието. За играчи, чувствителни към светлина, опцията Reduce Flashes заменя трептенето с бавно просветване и намалява светкавиците наполовина. Torrent работи с Nova City 2 и други модове за времето. Публикациите не дават данни за производителността на по-слаби компютри. Модът вече е безплатно достъпен в Nexus Mods.", "_src": "84dc6ca1"}, "2026-11-15-dawn-of-war-4-systemanforderungen": {"titel": "Warhammer 40.000: Dawn of War 4 – публикувани са системните изисквания, препоръчват се 32 GB RAM и 125 GB на NVMe SSD", "schlagzeile": "Dawn of War 4 иска 32 GB RAM и 125 GB SSD – в разгара на RAM кризата", "kurz": "King Art и Deep Silver публикуваха изискванията за PC на Dawn of War 4. Стратегията е скромна към процесора и видеокартата, но не и към паметта: препоръчват се 32 GB RAM и 125 GB на NVMe SSD. Играта излиза на 3 декември.", "zusammenfassung": "Малко преди старта на Warhammer 40.000: Dawn of War 4 разработчикът King Art и издателят Deep Silver обявиха системните изисквания за PC, съобщава PC Games Hardware. Като минимум са достатъчни Core i5-10600K или Ryzen 5 2600X, GeForce GTX 1660 или Radeon RX 5700 и 16 GB RAM. Препоръчват се Core i7-12700 или Ryzen 5 7600X, GeForce RTX 3060 Ti или Radeon RX 9060 с 8 GB и 32 GB оперативна памет. И в двата случая играта изисква 125 GB на NVMe SSD; според King Art около 25 GB от тях са резерв за DLC и ъпдейти. Не е известно за каква резолюция и кадрова честота важат данните. Официално Windows 11 е посочена дори в минималните изисквания, но в публикация в Steam разработчиците поясниха, че играта работи и на 64-битов Windows 10. Тъй като Microsoft прекрати поддръжката на Windows 10, King Art обаче не може да гарантира съвместимост с бъдещи ъпдейти там. Високите изисквания към паметта идват във време, когато RAM паметта значително поскъпна. Който не иска да инсталира, може да играе Dawn of War 4 и чрез стрийминг в GeForce Now. Играта струва 59,99 евро в Steam, Commander Edition с разширението Year 1 – 89,99 евро, а при предварителна поръчка има десет процента отстъпка. Nvidia вече пусна Game Ready драйвер за играта – GeForce драйвер 621.24.", "_src": "c938792d"}, "2026-11-16-madden-gta6-nicht-loeschen": {"titel": "EA показва в Madden NFL 27 изскачащ прозорец „Don't Delete!“ в стил Вайс Сити и обявява актуализация за 17 ноември, два дни преди GTA 6", "schlagzeile": "„Не трий!“: Madden 27 се бори за място на диска точно преди GTA 6", "kurz": "EA показва в Madden NFL 27 нов изскачащ прозорец със съобщението „Don't Delete!“ и обявява актуализация за 17 ноември. EA не споменава GTA 6, но палмите и розово-лилавите цветове силно напомнят за Вайс Сити. GTA 6 изисква над 200 GB и излиза два дни по-късно.", "zusammenfassung": "Играчи забелязаха съобщението през уикенда, CharlieIntel го разгласи, а IGN пише за него. По същество в него се казва, че екип подготвя голям удар и трябва да се изчака сигналът на вътрешен човек на 17 ноември. В този вторник трябва да излезе нова актуализация на Madden NFL 27. EA не споменава изрично GTA 6, но дизайнът и текстът ясно намекват за играта на Rockstar. Още на 10 ноември официалният профил на Madden в X рекламира актуализация за 18 ноември с думите, че 210 GB не бива да застават между играчите и тяхната лига. Контекст: в зависимост от конзолата GTA 6 изисква над 200 GB и много играчи трябва да изтрият други игри, за да я инсталират. В първите екранни снимки в прозореца имаше и печатна грешка „awating signal“, която явно бързо е поправена. В социалните мрежи много играчи реагират с усмивка. GTA 6 излиза на 19 ноември за PS5 и Xbox Series X|S.", "_src": "9feb44ca"}, "2026-11-15-kongress-ki-chip-exporte": {"titel": "След случая Megaspeed Конгресът на САЩ с подкрепа и от двете партии прокарва по-строг контрол върху износа на AI чипове; части може да влязат в закона за отбраната NDAA", "schlagzeile": "След аферата Megaspeed: Конгресът на САЩ иска по-строг износ на AI чипове", "kurz": "Демократи и републиканци искат по-строг контрол върху износа на мощни AI чипове, съобщава ComputerBase, позовавайки се на Financial Times. Някои предложения може да бъдат включени в годишния закон за отбраната на САЩ. Дали това ще стане до края на годината, е неясно.", "zusammenfassung": "Случаят около клиента на Nvidia Megaspeed от Сингапур раздвижва експортната политика на САЩ. Според ComputerBase, който се позовава на Financial Times, няколко законопроекта за контрол на AI чиповете получават подкрепа и от двете партии в Конгреса. Те трябва да ограничат продажбите в чужбина и да дадат на Конгреса повече дума при вече одобрени сделки. Американските власти от над година проверяват дали Megaspeed е пренасочвала чипове на Nvidia към Китай. Едно от предложенията, Remote Access Security Act, ще затрудни отдалечения достъп на китайски компании до AI ускорители в чуждестранни центрове за данни, ако самите те нямат право да купуват тези чипове. Някои предложения може да бъдат включени в годишния закон за отбраната NDAA, който се смята за почти невъзможен за блокиране. Законодатели искат и от министъра на търговията Хауърд Лътник обяснение защо Nvidia е имала право да доставя на Megaspeed. Според Financial Times предложенията и преди са напредвали, но случаят Megaspeed значително е увеличил шансовете им. Не е ясно дали Конгресът ще има достатъчно време до края на годината. Засега не са известни преки последици за геймърските видеокарти. Дебатът обаче засяга Nvidia в деликатен момент: компанията представя тримесечните си резултати на 17 ноември.", "_src": "33b7866c"}, "2026-11-15-playstation-black-friday-zubehoer": {"titel": "Black Friday на PlayStation от 16 ноември: отстъпки за DualSense, слушалки Pulse, PS VR2 и игри, но без намаление на цената на PS5 и PS5 Pro", "schlagzeile": "Black Friday на PlayStation: отстъпки за контролери и PS VR2, не и за PS5", "kurz": "Black Friday кампанията на Sony започва в полунощ местно време в нощта срещу понеделник и продължава до края на ноември. Има отстъпки за контролери DualSense, слушалки, PS VR2 и игри, но самата PS5 не поевтинява. Цените в евро Sony още не е обявила.", "zusammenfassung": "Sony обяви подробностите за своята Black Friday кампания, която започва на 16 ноември в полунощ местно време и продължава до 30 ноември. В PlayStation Blog Sony посочва отстъпки в САЩ: 20 долара за DualSense, 30 долара за DualSense Edge, 40 долара за слушалките Pulse Elite, 30 долара за слушалките Pulse Explore, 30 долара за контролера Access и 100 долара за PS VR2. Според Polygon така DualSense струва 54 долара, а PS VR2 – 299 долара в САЩ. PS5 и PS5 Pro не получават официална отстъпка, за разлика от миналата година с намален пакет, отбелязва Push Square. Намалени са и игри като Marvel's Wolverine, Saros, Ghost of Yōtei Complete Edition и Marvel Tōkon: Fighting Souls, а в PlayStation Store има до 75 процента отстъпка за игри за PS5 и PS4. Според Push Square членовете на PS Plus в Германия и Австрия, наред с други страни, получават още пет процента отстъпка от промоционалната цена при покупка през PlayStation Direct. Има оферти и за нови членове на PS Plus и за преминаване към Premium или Deluxe. Цените в евро и точната продължителност на отделните оферти Sony ще публикува едва при старта на регионалната Black Friday страница, като те може да се различават според държавата и търговеца. 27-инчовият монитор с кука за зареждане се предлага само в САЩ и Япония.", "weitere_links": ["PlayStation.Blog", "Push Square", "PlayStation в X"], "_src": "8e3329d9"}, "2026-11-15-rtx4090ti-es-china": {"titel": "Предполагаема инженерна мостра на никога неизлязлата GeForce RTX 4090 Ti с 18 176 CUDA ядра е обявена в китайска платформа за обяви", "schlagzeile": "Изтичане: Никога неизлязла RTX 4090 Ti се продавала в Китай", "kurz": "Според VideoCardz в китайска платформа за употребявани стоки се предлага предсерийна RTX 4090 Ti. Продавачът посочва 18 176 CUDA ядра – около единадесет процента повече от RTX 4090. Тези данни не са проверени независимо.", "zusammenfassung": "Nvidia така и не пусна GeForce RTX 4090 Ti на пазара, но прототипи продължават да се появяват. Според VideoCardz поредна предполагаема инженерна мостра е обявена в китайска платформа за употребявани стоки. Обявата е забелязана от потребителя в X @meiei_nowa, а UNIKO's Hardware публикува още снимки. Според продавача картата има 18 176 CUDA ядра, 192 ROP и 568 TMU. Това съвпада със слуховете за RTX 4090 Ti отпреди години и означава около единадесет процента повече шейдъри от обикновената RTX 4090 с 16 384 ядра. Професионалната карта RTX 6000 Ada Generation има същия брой ядра. Пълната конфигурация на чипа AD102 с 18 432 ядра пък имаше само никога неизлезлият прототип TITAN Ada, тестван от оувърклокъра der8auer. Продавачът твърди, че картата изисква вътрешен драйвер на Nvidia, но при тестовете е работила без видими проблеми. По-ранни мостри на RTX 4090 Ti се отличаваха с четирислотов дизайн със завъртяна платка; екземпляр, тестван от Gamers Nexus, обаче работеше само с нормалните параметри на RTX 4090. Nvidia никога не е обяснила официално защо е отказала картата. Само от обявата не може да се докаже, че наистина става дума за RTX 4090 Ti.", "ursprungsquelle": "Обява в китайска платформа за употребявани стоки, забелязана от @meiei_nowa в X, снимки от UNIKO's Hardware", "_src": "a774e6e2"}, "2026-11-15-game-awards-nominierungen-gta6": {"titel": "The Game Awards обявяват номинациите на 17 ноември; GTA 6 може да участва въпреки излизането си на 19 ноември", "schlagzeile": "Game Awards: номинациите идват във вторник – GTA 6 още може да участва", "kurz": "Номинираните за The Game Awards 2026 ще бъдат обявени във вторник в 18:00 ч. централноевропейско време на живо. GTA 6 излиза чак два дни по-късно, но според официалните правила може да участва. Самата церемония е на 10 декември в Лос Анджелис.", "zusammenfassung": "Джеф Кийли ще представи номинираните за The Game Awards 2026 във вторник в отделно излъчване на живо в YouTube и Twitch. Началото е в 18:00 ч. централноевропейско време; в предишни години предаването траеше само около десет минути. Наградите се връчват в над 30 категории, а кандидатите за игра на годината традиционно идват накрая. Интересът е заради GTA 6, която излиза чак два дни по-късно за PS5 и Xbox Series X|S. Според официалния правилник, цитиран от Polygon, за основните категории е достатъчно играта да е в продажба до петък в 21:00 ч. тихоокеанско време. GTA 6 се вмества в срока, макар номинацията да не е гарантирана. За наградата на публиката Players' Voice срокът е дори краят на месеца. Номинациите се определят от жури от над 100 медии и организации на създатели на съдържание, а според PC Games победителите се избират 90 процента от журито и 10 процента от гласуване на феновете. Не е известно дали Rockstar е изпратила кодове за играта на журито предварително. Подобен случай имаше през 2014 г., когато Smash Bros за Wii U беше номинирана малко преди старта си в САЩ. Церемонията е на 10 декември в Peacock Theater в Лос Анджелис, което по нашето време е през нощта срещу 11 декември.", "weitere_links": ["Polygon"], "_src": "18002e56"}, "2026-11-15-phishing-microsoft-365-ausfall": {"titel": "Microsoft предупреждава за фишинг кампания, която изпраща фалшиви съобщения за срива на Microsoft 365", "schlagzeile": "Фишинг вълна използва срива на Microsoft 365 – Microsoft предупреждава", "kurz": "Престъпници използват срива на Microsoft 365 от тази седмица за фишинг, предупреждава екипът на Microsoft Threat Intelligence. Фалшиви съобщения за прекъсване твърдят, че задържани имейли ще бъдат изтрити, ако не кликнете върху линк. Истинска информация за сривове има само в центъра за администриране на Microsoft 365.", "zusammenfassung": "Малко след големия срив на облачните услуги на Microsoft се появяват фишинг имейли за него, съобщава heise online. Екипът на Microsoft Threat Intelligence предупреждава в Bluesky за кампания, която имитира съобщения за състоянието на Microsoft 365. Имейлите се позовават на реалния инцидент в Exchange Online с идентификатор EX1550543. Някои от съобщенията, открити от Microsoft в петък, твърдят, че по време на срива имейли са били задържани и ще бъдат изтрити до 24 часа, ако не бъдат възстановени чрез линк. Темите често следват схемата „Outage“ плюс шестсимволен код, а като подател се използват имена като „Outage Notification“ или „Service Health“. Според Microsoft имейлите идват от три домейна, а линковете пренасочват през SendGrid към друг сайт. Досега кампанията е насочена към организации от различни сектори в САЩ. Схемата съответства на типичен фишинг за данни за вход, но Microsoft все още не е потвърдила, че реално са откраднати пароли или е разпространен зловреден софтуер. Microsoft Defender блокира използваните домейни, а Defender for Office 365 поставя такива имейли под карантина. Администраторите трябва да проверят политиките си за Safe Links и да четат съобщенията за сривове само в центъра за администриране на Microsoft 365. За всички: не кликайте върху линкове в имейли, които заплашват с изтриване и притискат със срокове.", "_src": "a428b950"}, "2026-11-15-dawnwalker-1-2-new-game-plus": {"titel": "The Blood of Dawnwalker: ъпдейт 1.2 носи New Game Plus, максимално ниво 100 и промени в баланса през седмицата от 16 ноември", "schlagzeile": "Blood of Dawnwalker: New Game Plus и ниво 100 идват тази седмица", "kurz": "С ъпдейт 1.2 за The Blood of Dawnwalker Rebel Wolves добавя най-желаната функция: New Game Plus. Освен това максималното ниво се вдига до 100. Ъпдейтът трябва да излезе през тази седмица, точен ден още няма.", "zusammenfassung": "Полското студио Rebel Wolves, основано от бивши разработчици на The Witcher, обяви ъпдейт 1.2 за вампирската си ролева игра The Blood of Dawnwalker. Той трябва да излезе през седмицата от 16 ноември; студиото не е посочило точна дата. Най-важната новост е режим New Game Plus, който се отключва след епилога. Нивото, уменията и инвентарът се пренасят в новото преминаване. Максималното ниво се вдига до 100, враговете се мащабират еднакво във всички региони, а предметите получават собствени New Game Plus версии с променени стойности. Ъпдейтът променя доста неща и без New Game Plus: Rebel Wolves коригира здравето на враговете и колко често използват специалните си умения. Освен това геометрията на терена се преработва, за да е по-плавно движението в битка и при изследване. Собствениците на Eclipse Edition получават допълнителни песни в саундтрака в играта, който по-късно ще излезе и в Spotify и други стрийминг услуги. Пълни бележки към пача още няма, затова липсват точни цифри за промените в баланса. Неясно е и дали New Game Plus може да се играе няколко пъти подред. Според GamesRadar+ тази седмица играта завърши втора в две категории на Golden Joystick Awards.", "weitere_links": ["Polygon", "GamesRadar+"], "_src": "3dd042af"}, "2026-11-15-gta6-album-tracklist-leak": {"titel": "Списъкът с песни на официалния албум на GTA 6 изтече във видео преди премиерата; Rolling Stone и Billboard го смятат за истински според свои източници", "schlagzeile": "Изтичане: Lana Del Rey, Dua Lipa, Jennie – това ли са песните на GTA 6?", "kurz": "Видео от магазин явно показва винилното издание на „Grand Theft Auto VI: The Album“ с пълния списък с песни. Според PC Gamer източници на Rolling Stone и Billboard потвърждават списъка. Rockstar не е коментирал.", "zusammenfassung": "Няколко дни преди премиерата на GTA 6 списъкът с песни на официалния албум явно е изтекъл. Според IGN видео от магазин, споделено в социалните мрежи, показва предната и задната страна на двойната плоча „Grand Theft Auto VI: The Album“, която трябва да излезе едва на 19 ноември за около 50 долара. Според Insider Gaming албумът съдържа 34 песни. Сред споменатите са Lana Del Rey с неиздаваната досега песен „Crazy For You“, Dua Lipa и Jennie от Blackpink; PC Gamer посочва още Playboi Carti и Keith Richards. Сред първите песни са две на френското дуо Justice – едната с Michael McDonald, а другата с Tame Impala, SZA и King Gizzard & the Lizard Wizard. Според PC Gamer източници на Rolling Stone и Billboard са определили списъка като верен. Rockstar Games и Take-Two не са потвърдили списъка; според нашите правила той затова остава изтичане. Важно: албумът не е пълният саундтрак на играта. Радиостанциите в играта съдържат и лицензирани песни, а музиката на Justice ще излезе отделно на 11 декември според IGN. GTA 6 излиза на 19 ноември за PS5 и Xbox Series X|S; дата за PC все още няма.", "weitere_links": ["IGN", "Insider Gaming (Tom Henderson)"], "_src": "2d952e53"}, "2026-11-15-ubuntu-pro-ki-sicherheitspatches": {"titel": "Canonical пуска архива Edge: потребителите на Ubuntu Pro могат да тестват създадени от ИИ корекции за сигурност преди редовната проверка", "schlagzeile": "Ubuntu тества ИИ корекции за сигурност – който иска, ги получава по-рано", "kurz": "Canonical предлага на потребителите на Ubuntu Pro нов доброволен архив с пакети, наречен Edge. В него попадат корекции за сигурност, създадени от ИИ система на име Surge, преди да са напълно проверени. Според Canonical обикновените актуализации продължават да се проверяват от хора.", "zusammenfassung": "Canonical вече оставя ИИ агенти да закърпват част от пропуските в сигурността на Ubuntu. Според OMG! Ubuntu компанията е изградила система от няколко ИИ агента, наречена Surge, която пренася корекции за известни уязвимости в пакети от потребителското пространство към по-стари версии. Тези машинно генерирани корекции попадат в нов архив, наречен Edge. Архивът е доброволен и по подразбиране е изключен; който иска да го ползва, трябва сам да го активира в системата си. Surge не закърпва ядрото на Linux. Според Canonical редовните актуализации на Ubuntu ще продължат да се проверяват и тестват от хора, а корекциите на Surge няма да попадат автоматично в стабилните версии. Като причина Canonical посочва силно нарасналия брой сигнали за уязвимости, открити с помощта на езикови модели, както и атаките с ИИ агенти; екипът по сигурността вече е пуснал два пъти повече корекции, отколкото миналата година. Потребителите на архива Edge трябва да помагат за проверката на ИИ корекциите в ежедневна употреба, преди те да бъдат пуснати за всички. Ubuntu Pro е безплатен за лична употреба на до пет устройства, а Edge е наличен за Ubuntu от 18.04 до 26.04 LTS. Актуализациите от него по подразбиране не се инсталират автоматично. Остава риск: непроверените корекции могат да съдържат грешки, затова Edge е по-скоро за тестери, отколкото за продуктивни системи.", "_src": "6705813e"}, "2026-11-15-lol-new-dawn-blg-weltmeister": {"titel": "Riot обяви на финала на Worlds „League of Legends: New Dawn“ – най-голямото преработване на играта от 2009 г.; BLG стана световен шампион", "schlagzeile": "League of Legends ще бъде изцяло обновена през 2027 г. – BLG взе титлата", "kurz": "Riot Games представи „New Dawn“ на финала на Световното първенство по LoL – голяма актуализация за 2027 г. Клиентът, Summoner's Rift, графиката и геймплеят ще се променят значително. Самия финал спечели Bilibili Gaming с 3:1 срещу Gen.G.", "zusammenfassung": "На финала на Световното първенство по League of Legends 2026 в Бруклин Riot Games обяви „League of Legends: New Dawn“. Според IGN става дума за цялостна актуализация, която ще излезе през 2027 г. и ще промени клиента, Summoner's Rift, визията и геймплея. Изпълнителният продуцент Paul Bellezza говори в първия трейлър за началото на нова ера за League. Трейлърът показва между другото преработен избор на шампиони, напомнящ мобилната игра Wild Rift, както и обновени миниони, дракони и Барон Нашор. Кадрите загатват и за нова или силно преработена система от руни и по-големи промени в терена на картата. Riot все още не разкрива какво точно ще се промени в геймплея; пълната презентация е планирана за януари 2027 г. От старта през 2009 г. е имало няколко големи преработки, например новата карта през 2014 г., но нищо от такъв мащаб. Затова GameStar вече говори за „League of Legends 2“, а самата Riot го нарича актуализация. Дали играчите ще приемат промените, предстои да се види. В спортно отношение титлата спечели китайският отбор Bilibili Gaming: според Insider Gaming BLG победи Gen.G с 3:1 на финала. Мид лейнърът Knight беше избран за най-полезен играч на турнира.", "weitere_links": ["Insider Gaming (Tom Henderson)", "IGN Deutschland"], "_src": "cb4615e1"}, "2026-11-15-zephyr-4070tis-ein-luefter": {"titel": "Zephyr все пак пуска в Китай RTX 4070 Ti Super Sakura Snow X с един вентилатор за 285 вата въпреки по-ранното отказване", "schlagzeile": "Един вентилатор за 285 вата: мини RTX 4070 Ti Super все пак излиза", "kurz": "Китайският производител Zephyr все пак продава своята RTX 4070 Ti Super Sakura Snow X, след като през март моделът беше замразен заради скъпата памет GDDR6X. Според Zephyr това е единствената серийна карта от този тип, която охлажда 285 вата само с един аксиален вентилатор. За тиха работа производителят препоръчва ограничение на мощността от 220 вата при загуба на производителност под пет процента.", "zusammenfassung": "След няколко отлагания и временно отказване Zephyr все пак пусна на пазара GeForce RTX 4070 Ti Super Sakura Snow X, съобщава PC Games Hardware. Според производителя това е единствената серийна RTX 4070 Ti Super, която отвежда 285 вата мощност на платката с един-единствен аксиален вентилатор. За целта обаче вентилаторът трябва да се върти бързо. Затова Zephyr препоръчва за по-тиха работа ограничението на мощността да се намали до 220 вата; така производителността в игри би паднала с по-малко от пет процента. Производителят не казва кои игри е тествал. През март 2026 г. Zephyr временно спря модела заради силно поскъпналата GDDR6X и вместо него обяви RTX 4070 Super с 12 GB. Картата е в корпус, фрезован от метален блок, и е предназначена за компактни компютри, в които не се побира карта с три вентилатора. Малката първа партида се продаваше от търговец в Douyin и според Techtesters вече е изчерпана. Официална цена няма; през юли се говореше за 6199 до 6499 юана, около 795 до 835 евро без данъци и мита. Zephyr не е обявил пускане в Германия. Впрочем ограничението от 220 вата може да се зададе самостоятелно на всяка RTX 4070 Ti Super, например с около 77 процента ограничение на мощността в MSI Afterburner при референтен TGP.", "_src": "bc4ac344"}, "2026-11-15-inxile-buero-schuesse": {"titel": "Изстрели по офис сградата на Xbox студиото inXile в Калифорния: няма пострадали, полицията задържа заподозрян", "schlagzeile": "Изстрели по сградата на Xbox студиото inXile – полицията задържа заподозрян", "kurz": "В сряда беше стреляно по офис сградата в Тъстин, Калифорния, в която се намира Xbox студиото inXile. Никой не е пострадал. Два дни по-късно полицията задържа заподозрян; мотивът все още не е ясен.", "zusammenfassung": "Офис сградата на студиото на Microsoft inXile Entertainment в Тъстин, Калифорния, е била улучена от изстрели. Според Insider Gaming местни медии съобщиха за инцидента следобед на 11 ноември, като няколко куршума са попаднали в сградата. Полицията заяви пред списание Aftermath, че става дума за стрелба от движещ се автомобил, и откри няколко гилзи. Никой не е пострадал. Сутринта на 13 ноември полицията задържа заподозрян; името и мотивът не са известни, разследването продължава. Не е изяснено дали студиото е било целта. Говорител заяви, че всички са облекчени, че никой не е пострадал, че се грижат за екипа и работят в тясно сътрудничество с властите. inXile е известно с поредицата Wasteland и работи по Clockwork Revolution – ексклузивна игра за Xbox, планирана за 2027 г. Xbox не е обявил последици за играта.", "_src": "349ed63a"}, "2026-11-15-inoffizielle-pc-ports-astro-bot-totk": {"titel": "Неофициални нативни портове за PC: Astro Bot върви под Windows като първа ексклузивна игра за PS5, а Zelda: Tears of the Kingdom дори на GeForce MX550", "schlagzeile": "Astro Bot и Zelda на PC: фенски портове без емулатор набират скорост", "kurz": "С Astro Bot за първи път ексклузивна игра за PS5 работи като неофициален нативен порт за PC, включително с DLSS и Frame Generation. Същевременно потребител показва Zelda: Tears of the Kingdom чрез рекомпилация на лаптопен GPU с едва 2 GB памет. Нито един от двата проекта не е одобрен от Sony или Nintendo.", "zusammenfassung": "Вместо да емулират конзолни игри, фенски проекти все по-често ги превеждат директно в нативен PC код. Според ComputerBase вече има такъв порт за Windows на Astro Bot, игра на годината за 2024 г. Разработчикът твърди, че е използвал PS5 копие на играта; графиката се превежда към Vulkan чрез компонент от проекта KytyPS5. Добавка интегрира Nvidia DLSS, Frame Generation и Reflex. С Ryzen 5 5500 и RTX 5060 портът достига според разработчика едва 32 до 34 fps при 1440p в тежкото ниво Sky Garden, а другаде най-често 40 до 50 fps, тоест по-малко от 60-те fps на PS5. С Frame Generation са малко над 60 fps, а с Multi Frame Generation – до 128 fps. Успоредно с това, според PC Games Hardware, потребител в Reddit показва Zelda: Tears of the Kingdom чрез проекта TotK Recomp на лаптоп с GeForce MX550 и 2 GB видеопамет. Той говори за около 30 fps със спадове; резолюцията не посочва. Според бележките към изданието версия 0.4.0 на порта се нуждае само от 3,4 вместо 4,8 GB VRAM на Radeon RX 9070. И двата проекта са неофициални и не са одобрени от Sony или Nintendo; колко дълго ще останат достъпни, не е ясно. Според ComputerBase мнозина вече се надяват на подобни портове на GTA 6, която излиза на 19 ноември първо само за конзоли.", "weitere_links": ["PC Games Hardware (PCGH)"], "_src": "af19c7e6"}, "2026-11-14-huang-petition-musk": {"titel": "Петиция за завръщането на Хуанг начело на Nvidia: над 100 000 подписа, подкрепа от Илон Мъск, над 1600 вътрешни коментара", "schlagzeile": "„Bring back the boss“: 100 000 искат Дженсън Хуанг обратно в Nvidia", "kurz": "Според Golem публична петиция за завръщането на Дженсън Хуанг в Nvidia има над 100 000 подписа, включително над 2000 от настоящи и бивши служители. Илон Мъск обяви в X, че ще я подпише. И във вътрешния форум много служители настояват за завръщането на основателя.", "zusammenfassung": "Само дни след оставката на Дженсън Хуанг се надига съпротива срещу решението на борда на директорите. Според Golem петиция с мотото „33 години заслужават отговор“ е имала над 100 187 подписа вечерта на 14 ноември. Сред тях се твърди, че има над 2000 настоящи и бивши служители на Nvidia, което не може да се провери отвън. Илон Мъск посочи петицията в X на 13 ноември и обяви, че ще я подпише. Според Wired във вътрешния форум за предложения на Nvidia има и публикация за завръщането на Хуанг с над 1600 коментара, повечето в подкрепа. Heise съобщава, че временният главен изпълнителен директор Колет Крес е обявила общо събрание на служителите за 18 ноември. Бордът обяви оставката на Хуанг след публикации за втора афера с мениджърка, пряко подчинена на него; по-късно Reuters съобщи за трета връзка. Самият Хуанг не се е изказвал след имейла си до служителите от неделя. Nvidia и председателят на борда Харви Джоунс все още не са реагирали на петицията. Петицията няма правна сила; решението е изцяло на борда.", "weitere_links": ["heise online", "PC Games Hardware (PCGH)"], "_src": "cb2772ff"}, "2026-11-14-gta6-codes-fehlen-box": {"titel": "Някои физически издания на GTA 6 нямат четлив код за изтегляне, а търговците реагират различно", "schlagzeile": "Купи GTA 6, но в кутията няма код? Първи купувачи съобщават за дефекти", "kurz": "Няколко купувачи съобщават, че във физическото им издание на GTA 6 няма четлив код за изтегляне. Вместо кода има само сива лента, която не може да се изстърже. Според Polygon засегнати са версии за PlayStation и Xbox, но проблемът не изглежда широко разпространен.", "zusammenfassung": "GTA 6 излиза изцяло дигитално; дори кутията в магазина не съдържа диск, а само код за изтегляне. Кодът е отпечатан на гърба на обложката и трябва да се вижда през прозрачната кутия. От 12 ноември търговците доставят предварителните поръчки, за да могат купувачите да изтеглят играта предварително. Според Polygon няколко купувачи вече съобщават, че кодът им липсва: вместо символи има само сива лента, която прилича на поле за изстъргване, но не може да се изстърже. Това засяга както копия за PlayStation, така и за Xbox. Търговците реагират различно: някои магазини на Best Buy са отказали връщане, Amazon е възстановил сумата, а GameStop препраща към Rockstar. Двама потребители в Reddit разказват, че поддръжката на Rockstar е затворила сигналите им без решение. Rockstar все още не се е изказал публично. Polygon смята, че засегнати са само малко копия. Който е купил кутия, трябва да провери кода преди старта на 19 ноември.", "_src": "fc2b8517"}, "2026-11-14-xbox-25-spiele-pc-kauf": {"titel": "За юбилея на Xbox: 25 безплатни игри при покупка на нов компютър с Windows, но само в САЩ", "schlagzeile": "25 безплатни Xbox игри – но само с нов PC и само в САЩ", "kurz": "Microsoft отбелязва 25 години Xbox с пакет от 25 игри за PC, сред които Skyrim, Halo: Combat Evolved Anniversary и Gears of War: Reloaded. Те се дават само при покупка на отговарящ на условията нов компютър с Windows до края на 2026 г., считано от началото на ноември. Промоцията важи единствено в САЩ.", "zusammenfassung": "Шефката на Xbox Аша Шарма представи в X пакета „25 Years of Xbox Bundle“. Според условията на Microsoft всеки, който купи и активира отговарящ на условията нов компютър с Windows, получава 25 дигитални игри за PC. Сред тях са Skyrim Special Edition, Oblivion, Halo: Combat Evolved Anniversary, Gears of War: Reloaded, Age of Empires 2, Doom, Quake, Fallout 76 и Call of Duty: WWII. Отговарят на условията избрани устройства с Windows Home от участващи търговци и производители, включително някои преносими конзоли; устройства с Windows Pro са изключени с едно изключение. Рециклирани, разопаковани, върнати и демонстрационни устройства не се броят. Покупката трябва да е направена между 2 ноември и 31 декември 2026 г. Пакетът ще се появи в Microsoft Store в раздела „Включено с устройството“ най-късно на 30 ноември и трябва да бъде заявен до 12 февруари 2027 г. Лицензите са обвързани с акаунта в Microsoft и не могат да се прехвърлят. Според PC Games промоцията важи само в САЩ, т.е. не и в Германия или Австрия. Не е известно дали ще бъде разширена. Общността приема акцията по-скоро критично, включително защото новият PC хардуер в момента е особено скъп.", "weitere_links": ["Microsoft (условия на офертата)", "Аша Шарма в X"], "_src": "5e070100"}, "2026-11-14-12v2x6-pinprotect-november": {"titel": "Над десет нови случая на разтопени захранващи конектори при GeForce през ноември; специален кабел на Corsair показва кога PinProtect изключва", "schlagzeile": "Пак разтопени: над десет случая с конектори само през ноември", "kurz": "VideoCardz е преброил само за ноември над десет съобщени случая на повредени 16-пинови захранващи конектори при карти GeForce, чак до RTX 5070. Същевременно тест със специален кабел на Corsair показва, че защитата PinProtect наистина изключва при претоварване.", "zusammenfassung": "Проблемите с конектора 12V-2×6 не спират. VideoCardz е събрал сигнали, които каналът UNIKO's Hardware е обобщил от Reddit, китайски форуми и други общности, и стига до над десет случая само през ноември. Засегнати са сред други RTX 5090 D, няколко RTX 4090, RTX 5080, RTX 5070 Ti и две RTX 5070. Прави впечатление RTX 5070, за която Nvidia посочва само 250 вата срещу 575 вата при RTX 5090. Част от повредите са по видеокартата, други по адаптери или от страната на захранването. От отделните сигнали не може да се изведе колко чести са подобни повреди като цяло, а причините не са проверени поотделно. В тази връзка Professional Review показа неизвестен досега тестов кабел на Corsair, при който всяка от шестте 12-волтови линии може да се прекъсне с превключвател. При RTX 5080 с натоварване около 250 вата линиите бяха изключвани една след друга. Едва когато ток течеше само през няколко пина и един пин премина прага от около 9,5 ампера, PinProtect в захранването Corsair RM1200e изключи картата. Според Wccftech кабелът не се продава и очевидно служи за вътрешни тестове.", "weitere_links": ["Wccftech"], "_src": "bc31497b"}, "2026-11-14-geforce-freeman-nope": {"titel": "Евангелистът на GeForce в Nvidia Джейкъб Фрийман отхвърля спекулациите за края на GeForce след оставката на Хуанг", "schlagzeile": "Край на GeForce след оттеглянето на Хуанг? Човек на Nvidia: „Nope“", "kurz": "След оставката на Дженсън Хуанг много геймъри се питат дали Nvidia ще се откаже от GeForce. Евангелистът на GeForce Джейкъб Фрийман отговори точно на този въпрос в X с кратко „Nope“. Официална пътна карта по темата обаче няма.", "zusammenfassung": "Откакто Дженсън Хуанг напусна поста главен изпълнителен директор на Nvidia, се спекулира, че компанията ще се съсредоточи още повече върху хардуера за ИИ и ще свие гейминг бизнеса. Джейкъб Фрийман, евангелист на GeForce в Nvidia и бивш продуктов мениджър в EVGA, коментира темата в X. Той беше на LAN партито PDXLAN в САЩ и написа, че тази седмица са се случили много неща, но работата с колеги, които обичат PC гейминга, продължава. Когато потребител го попита директно дали това е краят на GeForce, той отговори с „Nope“ и усмихнато емоджи. Това е личен отговор в X, а не официално съобщение на Nvidia. Nvidia не е представила нова пътна карта за гейминг. Според VideoCardz Nvidia преди това е отменила няколко продукта, вече обсъдени с партньорите, сред тях серия SUPER с 3 GB чипове памет; това не е потвърдено. Изказването на Фрийман няма да направи и видеокартите по-евтини: в САЩ RTX 5090 в момента струва над три пъти препоръчителната си цена.", "weitere_links": ["Wccftech"], "_src": "52c2591a"}, "2026-11-14-tarkov-konsole-mobile": {"titel": "Escape from Tarkov: конзолната версия ще бъде обявена през 2027 г., но излиза най-рано през 2028 г.; мобилната игра ще е extraction шутър с изглед отгоре", "schlagzeile": "Tarkov: конзоли не по-рано от 2028, мобилната игра с изглед отгоре", "kurz": "Шефът на Battlestate Никита Буянов иска да представи конзолната версия на Escape from Tarkov догодина, но тя няма да излезе преди 2028 г. Според Insider Gaming планираната мобилна игра няма да е порт, а extraction шутър с изглед отгоре. И тази игра трябва да бъде обявена през 2027 г.", "zusammenfassung": "В интервю за Insider Gaming Battlestate Games разкри нови подробности за плановете си за Tarkov. Според PC Games шефът на студиото Никита Буянов е близо до намирането на партньор за конзолната версия. Той твърдо очаква да представи официално конзолната версия през 2027 г., може би още в началото на годината. Той изключи издаване през 2027 г., така че реалистично е най-рано 2028 г. Battlestate все още не е казало категорично за кои конзоли ще излезе версията. Буянов и преди беше заявил, че конзолната версия няма да бъде опростена и дори ще мине без помощ при прицелване; дали това ще остане така, не е ясно. Студиото работи и върху игра от света на Tarkov за смартфони. Според Буянов това е extraction игра с визията на Tarkov, но от трето лице с изглед отгоре, подобно на Escape from Duckov или Zero Sievert. Вече има играеми прототипи, а обявяването е планирано за догодина. Освен това през декември стартира вторият PvP сезон на Escape from Tarkov.", "weitere_links": ["PC Games"], "_src": "957c3f7e"}, "2026-11-14-rtx5090-usa-dreifach-uvp": {"titel": "RTX 5090 отново е налична в Newegg, но на над три пъти препоръчителната цена; в Япония цените на RTX 5090 и RTX 5080 падат", "schlagzeile": "RTX 5090 отново е налична – на тройна препоръчителна цена", "kurz": "GeForce RTX 5090 отново е директно налична в Newegg в САЩ. Най-евтиният модел обаче струва 6249,99 долара – над три пъти повече от препоръчителната цена от 1999 долара. В Япония пък цените на RTX 5090 и RTX 5080 спаднаха осезаемо през последните дни.", "zusammenfassung": "След седмици почти без наличности американският търговец Newegg отново предлага няколко модела RTX 5090 за директна покупка, съобщава VideoCardz. Най-евтин е ASUS ROG Astral RTX 5090 OC за 6249,99 долара. Моделите на GIGABYTE и MSI струват между около 6600 и 7000 долара, а MSI SUPRIM SOC – 7349,99 долара. Официалната препоръчителна цена на Nvidia остава 1999 долара, така че дори най-евтината оферта е около 3,1 пъти по-скъпа. През септември самият Newegg почти нямаше наличности и купувачите разчитаха основно на търговци от маркетплейса. В Япония цените вървят надолу: според Wccftech, позовавайки се на ITmedia и Gazlog, Palit RTX 5090 GameRock в Dospara поевтиня от 1 288 000 на 1 048 000 йени, а в магазина в Акихабара дори до 999 800 йени. RTX 5080 спадна от до 359 800 на 299 800 йени. Това съвпада по време с оставката на Дженсън Хуанг, но публикациите не виждат пряка връзка. Според тях цените са достигнали върха си още в края на октомври, след което наличностите са нараснали. Дали от това ще последва широк спад на цените, остава неясно.", "weitere_links": ["Wccftech"], "_src": "2a354308"}, "2026-11-14-steamos-3-10-hdmi21-amd": {"titel": "SteamOS 3.10.0 Preview: HDMI 2.1 с VRR, FRL и ALLM за графика AMD, mesh шейдъри за Nvidia от Turing нататък", "schlagzeile": "SteamOS 3.10 Preview: графиката AMD най-сетне получава HDMI 2.1 с VRR", "kurz": "Valve пусна SteamOS 3.10.0 като публична предварителна версия. С графика AMD системата вече поддържа HDMI 2.1 с VRR, FRL и ALLM. Картите на Nvidia от Turing нататък получават mesh шейдъри, а към това се добавя ядро на базата на Linux 7.3.", "zusammenfassung": "Според GamingOnLinux Valve пусна предварителната версия на SteamOS 3.10.0. За потребителите с графика AMD най-важната новост е поддръжката на HDMI 2.1 с променлива честота на опресняване (VRR), Fixed Rate Link (FRL) за висока пропускателна способност и автоматичния режим с ниска латентност ALLM. Като известен проблем Valve посочва, че мониторът Dell G3223Q може да остане черен. За графика Nvidia има подобрения в стабилността и производителността, mesh шейдъри от поколението Turing нататък и поправки на графични грешки в Shadow of the Tomb Raider и The Surge 2. В режим „Игра“ се добавя разширението на Vulkan VK_EXT_present_timing. Освен това Valve подобрява frame timing с ограничителя на кадри при VRR и намалява трептенето в интерфейса на Steam. ASUS ROG Xbox Ally X20 получава настройки за HDR и яркост. Десктоп режимът преминава към KDE Plasma 6.8.2, а ядрото – към Linux 7.3. Това е ранна тестова версия; Valve съветва да се преминава към нея само ако можете да живеете с възможни грешки.", "_src": "9372f312"}, "2026-11-14-gta6-fake-pc-download-malware": {"titel": "Фалшиво изтегляне на GTA 6 за PC разпространява инфостийлър, който краде данни за вход в Steam и криптопортфейли", "schlagzeile": "Внимание: „GTA 6 за PC“ е зловреден софтуер и краде акаунти в Steam", "kurz": "Изследователи по сигурността от Cynet предупреждават за уж изтегляне на GTA 6 за PC, което всъщност е зловреден софтуер. Той краде, наред с другото, пароли, акаунти в Steam и Roblox и данни от криптопортфейли. Версия на GTA 6 за PC няма; играта излиза на 19 ноември само за PS5 и Xbox Series X|S.", "zusammenfassung": "Малко преди старта на GTA 6 измамници се опитват да се възползват от вълнението. Според Neowin компанията за сигурност Cynet е анализирала уж „GTA 6 EXE FILE DOWNLOAD“, разпространяван чрез бележник в Google Colab. Връзката води към страница, която се представя за софтуерен портал и с номер на версия, брояч на изтегляния и значки като „Virus-free“ и „Verified“ трябва да изглежда надеждна. Предлагат се само 72 MB, а в архива има миниатюрен EXE файл и текстов файл. Текстовият файл подканва EXE да се стартира като администратор, предупрежденията за сигурност да се игнорират и да се добави изключение в антивирусната програма. Който го направи, инсталира инфостийлър, който разпознава виртуални машини и пясъчници и се вмъква в процесите на браузъра. Той краде пароли, бисквитки, данни от сърфирането, тайни от разширения на браузъра, данни за вход в Steam и Roblox и данни от криптопортфейли. Освен това може да подменя копирани криптоадреси и да изтегля допълнителен зловреден софтуер. Важно: версия на GTA 6 за PC не е обявена. При старта на 19 ноември играта излиза само за PlayStation 5 и Xbox Series X|S, така че всяко изтегляне за Windows или Mac почти сигурно е измама.", "_src": "0ac2cf10"}, "2026-11-14-wine-11-22-avx-arm": {"titel": "Wine 11.22 емулира AVX на ARM64 и поправя 34 грешки, включително в Guild Wars 2 и Star Citizen", "schlagzeile": "Wine 11.22: Windows програми с AVX вече работят и на ARM", "kurz": "Версията за разработка Wine 11.22 може да емулира AVX инструкции в x86 емулацията на ARM64. Така повече съвременни Windows програми работят на ARM компютри с Linux. Добавени са и 34 корекции на грешки, включително за игри.", "zusammenfassung": "Проектът Wine пусна версията за разработка 11.22. Най-важната новост според Phoronix е поддръжката на AVX инструкции в x86 емулацията на ARM64. Много съвременни Windows програми изискват AVX и досега не работеха или работеха ограничено на ARM системи с Wine. С ARM64EC компилации тези инструкции вече могат да се емулират. Това е особено интересно за Linux на ARM компютри. Wine 11.22 също обновява локалните данни до Unicode CLDR 49, въвежда рандомизация на адресното пространство и подобрява изобразяването на шрифта Tahoma. Общо версията поправя 34 известни грешки, включително в Guild Wars 2, Star Citizen и Logos Bible Software. Wine е основата на Proton на Valve, с който Windows игрите работят на Linux и Steam Deck. Новостите от Wine обаче стигат до Proton едва с времето. Това е версия за разработка; стабилната Wine 12.0 се подготвя за началото на 2027 г.", "_src": "c3cec6af"}, "2026-11-14-windows11-neuer-ausfuehren": {"titel": "Windows 11 получава през декември новия прозорец „Изпълни“, бутонът „Преглед“ отпада", "schlagzeile": "Win+R в нов вид: новият прозорец „Изпълни“ идва за всички през декември", "kurz": "Преработеният прозорец „Изпълни“ на Windows 11 пристигна в канала Release Preview. Той трябва да достигне до всички компютри с 25H2 и 26H2 с Patch Tuesday на 8 декември. Старият прозорец остава достъпен чрез превключвател.", "zusammenfassung": "Microsoft въвежда модернизирания прозорец „Изпълни“ (Win+R) за всички потребители на Windows 11. Според Windows Latest той вече е в Release Preview компилациите 26200.10066 (25H2) и 26300.10066 (26H2). Обикновено след това в края на месеца идва незадължителна актуализация, а на 8 декември – разпространение до всички чрез Patch Tuesday. Внедряването е постепенно, така че не всеки компютър ще го получи веднага. Новият прозорец е базиран на WinUI 3, поддържа тъмен режим и според Microsoft се отваря средно за 94 милисекунди вместо 103 милисекунди при стария. Бутонът „Преглед“ отпада: според Microsoft в извадка от 35 милиона потребители само 0,0038 процента някога са го натискали. Пътищата все още могат да се въвеждат, а новият пряк път ~\\ води до потребителската папка. Предишните команди се показват над полето за въвеждане и се превъртат със стрелките. Който предпочита стария прозорец, може да превключи обратно в Настройки > Система > Разширени. Microsoft иска постепенно да прехвърли още стари диалогови прозорци към WinUI 3, например свойствата във File Explorer.", "weitere_links": ["Windows Insider Blog"], "_src": "3c051621"}, "2026-11-14-blade-runner-aaa-spiel": {"titel": "Собственикът на Blade Runner Alcon води разговори за AAA видеоигра по поредицата", "schlagzeile": "Blade Runner като AAA игра? Собственикът на марката потвърждава разговори", "kurz": "Alcon Entertainment, собственик на марката Blade Runner, води разговори за голяма AAA игра. Двамата шефове на Alcon потвърдиха това в интервю за IGN. Подробности като студио, платформи или срок още няма.", "zusammenfassung": "Филмовата поредица Blade Runner може да получи голяма видеоигра. Андрю Косов и Бродерик Джонсън, шефовете на собственика на марката Alcon Entertainment, потвърдиха пред IGN, че се водят разговори за AAA игра. Изявлението дойде в интервю за новия сериал Blade Runner 2099, който стартира в Prime Video на 25 ноември. На въпроса защо след успеха на Cyberpunk 2077 няма голяма Blade Runner игра, Косов отговори „Да“ и изрично подчерта „AAA“. Играчите трябвало да могат да взаимодействат със света на Blade Runner. Повече не искаше да разкрие. Затова студио, платформи и срок не са известни, а разговорите още не означават обявена игра. Марката досега няма голям късмет с игрите: за класика се смята само приключенската игра на Westwood от 1997 г., която получи ремастър през 2022 г. Обявената през 2023 г. Blade Runner 2033: Labyrinth на Annapurna се смята за отменена.", "_src": "df74a8ea"}, "2026-11-14-pearl-abyss-ki-pipeline": {"titel": "Студиото на Crimson Desert Pearl Abyss иска да разшири AI в цялата си разработка, DokeV е планиран за 2028 г.", "schlagzeile": "Въпреки скандала с Crimson Desert: Pearl Abyss залага още повече на AI", "kurz": "Pearl Abyss, студиото зад Crimson Desert, иска занапред да използва AI в цялата разработка на игри. Това пише в писмото към тримесечните резултати. Студиото дава и цел за DokeV: втората половина на 2028 г.", "zusammenfassung": "Pearl Abyss разширява използването на AI в разработката на игри. Според PC Gamer и Eurogamer това става ясно от писмото на студиото към резултатите за третото тримесечие на 2026 г. Екипът вече тества нови игрови системи с AI, преди да ги реализира трудоемко ръчно. AI трябва също да автоматизира повтарящи се задачи, да помага при създаването на съдържание и да оптимизира тестовете – в целия процес на разработка. Pearl Abyss подчертава, че AI е само инструмент, а не заместител на разработчиците; геймплеят и съдържанието ще продължат да се създават от екипа. Темата е деликатна: в началото на годината студиото трябваше да се извини, след като в Crimson Desert бяха открити 2D графики, генерирани от AI. Тогава то обясни, че те е трябвало да бъдат заменени преди излизането, и че не е оповестило достатъчно ясно използването на AI. Писмото не казва кои точно игри са засегнати и колко AI съдържание ще влезе в готовите игри. Освен това Pearl Abyss дава цел за DokeV: шарената екшън игра трябва да излезе през втората половина на 2028 г.", "weitere_links": ["Insider Gaming"], "_src": "2e134a95"}, "2026-11-14-nvidia-ceo-suche-haas": {"titel": "Търсене на шеф в Nvidia: бордът се е обърнал към шефа на Arm Рене Хаас, Nvidia нарича спекулациите преждевременни", "schlagzeile": "Шефът на Arm начело на Nvidia? Бордът натиска спирачката", "kurz": "Според Financial Times бордът на Nvidia се е обърнал към главния изпълнителен директор на Arm Рене Хаас като възможен наследник на Дженсън Хуанг. Самата Nvidia казва, че едва избира агенция за подбор на ръководители и още не е контактувала официално с кандидати. Същевременно циркулира уж писмо от служители с искане Хуанг да се върне, което мениджър от Nvidia нарича фалшификат.", "zusammenfassung": "След оставката на Дженсън Хуанг Nvidia търси нов главен изпълнителен директор. Според статия на Financial Times, обобщена от Tom's Hardware, бордът се е обърнал към шефа на Arm Рене Хаас като възможен наследник. Хаас е един от няколко кандидати; не е ясно дали ще получи оферта и дали би я приел. До 2013 г. той работи около седем години в Nvidia, включително по GPU за лаптопи и чиповете Tegra, а от 2022 г. ръководи Arm. Nvidia реагира на статията: бордът заяви пред CNBC, че едва избира агенция за подбор и не е контактувал официално с никакви кандидати. Спекулациите за конкретни имена били преждевременни. Засега финансовият директор Колет Крес ръководи компанията временно. Според WIRED, цитиран от PCGH, настроенията вътре в компанията са разделени: публикация във вътрешната кутия за идеи на Nvidia е събрала над 1600 коментара, предимно в полза на завръщането на Хуанг. Разпространявано в мрежата писмо, уж подписано от ръководители на Nvidia, обаче е фалшификат според вицепрезидента по изследванията на Nvidia Брайън Катандзаро; той казва, че не го е подписвал и подкрепя борда. Според Wccftech Илон Мъск е обявил, че ще подпише петиция за завръщането на Хуанг. Nvidia не е обявявала възстановяване на Хуанг. Според PCGH засега няма известни последици за продуктите или цените на GeForce. На 17 ноември Nvidia за първи път ще представи тримесечни резултати без Хуанг.", "weitere_links": ["PC Games Hardware", "Wccftech", "CNBC"], "_src": "5f97b49c"}, "2026-11-14-pioner-eingestellt": {"titel": "Шутърът за оцеляване Pioner спира, студиото няма пари за разработка и сървъри", "schlagzeile": "Край след единадесет месеца: шутърът за оцеляване Pioner затваря", "kurz": "Шутърът за оцеляване Pioner спира по-малко от година след старта си в ранен достъп. Разработчикът GFAGames не е намерил финансиране за по-нататъшна разработка и сървъри. Кога ще бъдат изключени сървърите, още не е ясно.", "zusammenfassung": "Шутърът за оцеляване Pioner стига до края си. Според PC Gamer разработчикът GFAGames е обявил в Steam, че прекратява разработката и затваря играта. Разговорите със съществуващи и нови партньори за финансиране са се провалили. Студиото вече няма достатъчно собствени средства, за да продължи разработката и да поддържа сървърите. От представянето си през 2021 г. Pioner се смяташе за смесица от Stalker, Metro и Escape from Tarkov, с кампания за един играч и кооперативен и PvP режим в късносъветски свят. Играта беше в ранен достъп от декември 2025 г. и достигна връх от 1686 едновременни играчи в Steam. След технически проблеми и бавни ъпдейти броят им рязко спадна през лятото, а в средата на септември играеха само няколко десетки души. Много купувачи искат възстановяване на парите под обявлението. GFAGames още не е коментирало. Дата за изключването на сървърите също още липсва.", "_src": "4a2ae3c6"}, "2026-11-14-euro-office-desktop": {"titel": "Европейската офис алтернатива Euro-Office вече е налична като настолно приложение за Windows, macOS и Linux", "schlagzeile": "Европейската алтернатива на Office вече работи и офлайн на десктопа", "kurz": "Euro-Office, европейската алтернатива на Microsoft 365, вече е налична като безплатно настолно приложение с името Nextcloud Office Desktop. То работи офлайн на Windows, macOS и Linux. Технически е разклонение на ONLYOFFICE.", "zusammenfassung": "Euro-Office вече е налично и като класическо настолно приложение. Според OMG! Ubuntu приложението се казва Nextcloud Office Desktop и е безплатно и с отворен код. Euro-Office беше обявено през март 2026 г. като европейска алтернатива на Microsoft 365 и досега работеше само чрез сървър в браузъра или като мобилно приложение. Настолната версия обаче работи без собствен сървър и офлайн. Тя предлага текстообработка, електронни таблици, презентации и PDF инструменти. Поддържат се формати на Microsoft като DOCX, XLSX и PPTX, както и отворени формати като ODT. Освен това приложението може да се свърже с Nextcloud или други сървъри за съвместна редакция. Има инсталатори за Windows и macOS на x86 и ARM64, както и за Linux на x86 като DEB и RPM пакети. Технически Euro-Office се базира на ONLYOFFICE, чийто производител гледа критично на разклонението. Критики идват и от лагера на LibreOffice. OMG! Ubuntu отбелязва, че засега приложението изглежда предимно като преименуван ONLYOFFICE.", "weitere_links": ["Dr. Windows"], "_src": "cc9ac9bc"}, "2026-11-14-m365-stoerung-ursache": {"titel": "Microsoft се извинява за големия срив на Microsoft 365 и посочва мрежов ъпгрейд като причина", "schlagzeile": "Срив на Microsoft 365: нито хакери, нито AI – виновен е мрежов ъпгрейд", "kurz": "Microsoft се извини за световния срив на Outlook, Teams и други услуги. Според Microsoft причината е грешка от по-ранен мрежов ъпгрейд, а не атака или AI. Предстои подробен доклад.", "zusammenfassung": "Microsoft назова причината за големия срив на Microsoft 365 на 12 ноември. Според PC Gamer компанията изрично се извини на клиенти и партньори в изявление. Грешката е възникнала при по-ранно разширяване на мрежовия капацитет и е станала проблем едва след по-късна промяна в мрежата. Не е имало кибератака или участие на AI агенти. В мрежата преди това се спекулираше дали срива не е причинен от код, генериран от AI. Microsoft твърди, че е отстранила основната причина, и съобщава за широко възстановяване на услугите. Възстановяването умишлено е било постепенно, за да се проверява стабилността, и затова е отнело повече време. В събота Microsoft съобщи, че услугите са напълно възстановени за последните засегнати клиенти и региони. Засегнати бяха Outlook, Teams, SharePoint и Copilot. Microsoft ще публикува подробен доклад след приключване на вътрешния преглед. Бизнес клиентите могат според договора си да проверят за SLA компенсация.", "weitere_links": ["Windows Latest", "Associated Press"], "_src": "8b4d83fb"}, "2026-11-14-windows-oob-aktivierung": {"titel": "Microsoft пуска спешна актуализация срещу грешки при активиране след ноемврийския Patch Tuesday", "schlagzeile": "Спешна актуализация: Microsoft поправя активирането на Windows", "kurz": "Microsoft пусна извънредни актуализации, които отстраняват грешката при активиране 0x80041008 след ноемврийския Patch Tuesday. Засегнати бяха основно фирми, които активират Windows чрез slmgr.vbs. Актуализациите са налични за Windows 11 23H2, Windows 10 и Windows Server.", "zusammenfassung": "Microsoft поправи със спешна актуализация грешката при активиране след ноемврийския Patch Tuesday. Това съобщава Neowin. След актуализациите за сигурност командите за активиране и лицензиране чрез инструмента slmgr.vbs се проваляха с грешка 0x80041008. Засегнати бяха основно фирми, които управляват активирането и продуктовите ключове чрез скриптове. Извънредните актуализации са налични за Windows Server 2025 (KB5136489), Windows Server 2022 (KB5136487), Windows Server 2019 и Windows 10 Enterprise LTSC 2019 (KB5136490), Windows 11 23H2 (KB5136483), както и за Windows 10 22H2 с ESU и Windows 10 Enterprise LTSC 2021 (KB5136493). Това са кумулативни актуализации, които съдържат и всички предишни корекции. Windows Server и Windows 10 ги получават през каталога на Microsoft Update, а Windows 11 23H2 – и през незадължителните актуализации в Windows Update. Статията не споменава отделна актуализация за по-новите версии 24H2, 25H2 и 26H2. Според статията тази актуализация не решава също потвърдения проблем с печата след Patch Tuesday. Microsoft така или иначе препоръчва за автоматизация да се използва PowerShell вместо slmgr.vbs.", "_src": "2b8d555d"}, "2026-11-14-nvidia-wsj-knappheit": {"titel": "Доклад на WSJ: Хуанг е финансирал AI стартъпи, за да изкупуват излишните GPU на Nvidia", "schlagzeile": "Доклад: Плащала ли е Nvidia на AI стартъпи да купуват нейните GPU?", "kurz": "Според Wall Street Journal Дженсън Хуанг е финансирал с пари на Nvidia AI стартъпи и центрове за данни, които после са купували GPU на Nvidia. Причината била излишък от поръчани чипове от TSMC. Финансовият директор Колет Крес се е противопоставила.", "zusammenfassung": "Нов доклад на Wall Street Journal хвърля светлина върху финансовите практики на Nvidia при Дженсън Хуанг. TechPowerUp и Wccftech го обобщават. Според доклада Nvidia е подкрепяла финансово AI стартъпи и по-малки облачни доставчици, които с тези пари са купували GPU на Nvidia и са строили центрове за данни. Причината била, че големите облачни компании все повече използват собствени чипове, а Nvidia е поръчала от TSMC повече чипове, отколкото е имала непосредствени купувачи. Хуанг вътрешно е говорил за „лавина“, която идва към него. Според доклада през август е имало спор с финансовия директор и сегашен временен изпълнителен директор Колет Крес, която искала да ограничи подобно кръгово финансиране, включително многомилиардната сделка с OpenAI. Според Wccftech Крес е постигнала гаранциите за изчислителен капацитет за OpenAI да бъдат намалени от до 250 на до 125 милиарда долара. След това Хуанг я е критикувал пренебрежително. Крес също е предупредила, че много от малките облачни доставчици всъщност не могат да си позволят тези GPU. Докладът не доказва дали тази практика пряко е вдигнала цените на GPU и паметта за геймърите; това е тълкуване на Wccftech. Според наличните публикации Nvidia не е коментирала. Обвиненията идват от анонимни източници и не са официално потвърдени.", "weitere_links": ["Wccftech"], "_src": "638a0a69"}, "2026-11-14-core-ultra-7-260k": {"titel": "Intel Core Ultra 7 260K се появява без анонс, засега само в два готови компютъра на Newegg", "schlagzeile": "Тих старт: Intel Core Ultra 7 260K идва само в готови компютри", "kurz": "Intel тихо пусна нов настолен процесор – Core Ultra 7 260K. Засега той е само в два геймърски компютъра на Newegg и не се продава самостоятелно. Технически това е леко орязан Core Ultra 7 265K.", "zusammenfassung": "Intel пусна нов настолен процесор, без да го обяви. Според TechPowerUp Core Ultra 7 260K се предлага само в два геймърски компютъра на ABS, собствената марка на Newegg. Kaze II Aqua го съчетава с RTX 5060 за 1699,99 долара, а Flux II Aqua – с RTX 5070 за 1999,99 долара. Newegg потвърждава, че процесорът остава ексклузивен и няма да се продава отделно. Според Tom's Hardware Intel го определя като модел с ограничена наличност, без версия в кутия. Технически чипът до голяма степен съответства на Core Ultra 7 265K: 8 производителни и 12 ефективни ядра, 30 MB L3 кеш и 125 вата базова мощност. Максималната честота на P-ядрата обаче е със 100 MHz по-ниска – 5,4 GHz. Тъй като поддържа само DDR5-6400, той принадлежи към оригиналната фамилия Arrow Lake, а не към обновлението с DDR5-7200. Първите обяви на Newegg бяха противоречиви – понякога пишеше 260KF или boost от 5,2 GHz. Все още няма тестове. За хората, които сглобяват сами, процесорът е безинтересен, а цени и наличност в Европа не са известни.", "weitere_links": ["VideoCardz", "Wccftech"], "_src": "98b50ecf"}, "2026-11-13-rainbow-six-vegas-leak": {"titel": "Доклад: Ubisoft Montreal работи по нов Rainbow Six: Vegas с кодово име Spades", "schlagzeile": "Изтичане: Завръща ли се Rainbow Six: Vegas след 18 години?", "kurz": "Според Insider Gaming Ubisoft е одобрила нов Rainbow Six: Vegas с кодово име Spades. Играта уж е в ранна фаза на разработка в Ubisoft Montreal. Ubisoft не е потвърдила това, а обявяването вероятно е след години.", "zusammenfassung": "Поредицата Rainbow Six: Vegas може да се завърне след почти две десетилетия. Позовавайки се на анонимни източници, Insider Gaming съобщава, че Ubisoft е одобрила нова игра Vegas с кодово име Spades. Тя уж е в ранна фаза на разработка в Ubisoft Montreal. Общо там били стартирани три нови проекта, като още един от тях също щял да се развива във вселената на Rainbow Six. Според източниците по-скоро става дума за Vegas 3, отколкото за римейк, но това не е сигурно. Последната част, Rainbow Six: Vegas 2, излезе през 2008 г. Оттогава фокусът беше основно върху Rainbow Six Siege. Марката вече принадлежи на Vantage Studios, дъщерна компания на Ubisoft, в която Tencent притежава 26,32 процента. Ubisoft не е коментирала, така че проектът не е потвърден. Самият Insider Gaming очаква официалното обявяване да отнеме още няколко години.", "ursprungsquelle": "Insider Gaming (Tom Henderson), анонимни източници", "weitere_links": ["TechPowerUp"], "_src": "84094430"}, "2026-11-13-word-kompatibilitaet-layout": {"titel": "Microsoft премахва стари опции за съвместимост от Word, по-стари документи може да загубят оформлението си от декември", "schlagzeile": "Word ще разбърка оформлението на стари документи – как да ги запазите", "kurz": "Microsoft премахва някои стари настройки за съвместимост от Word. Документи, запазени с Word 2010 или по-стар, може да пренасят текста по различен начин. В Windows промяната започва през декември 2026 г., на Mac – в началото на 2027 г.", "zusammenfassung": "Microsoft разчиства Word и премахва някои по-стари опции за съвместимост. Това съобщава heise, позовавайки се на съобщението в Центъра за съобщения MC1551147. Засегнати са документи, създадени или последно запазени в Word 2010 или по-стар, които използват тези настройки. В такива файлове текстът може в бъдеще да се пренася различно. Разстоянията и номерата на страниците може да се променят, а изображения и фигури да се преместят на друга страница. Microsoft не казва кои точно опции отпадат. Самият режим на съвместимост остава. В Windows промяната ще се случи през декември 2026 г., на Mac – в началото на 2027 г. Microsoft не споменава възможност за отлагане. Който разчита на точното оформление, трябва предварително да провери важните стари документи и да ги експортира в PDF. Според heise конвертирането в новия формат на Word не помага, защото при него старите настройки за съвместимост също се губят.", "weitere_links": ["Neowin"], "_src": "9f271045"}, "2026-11-13-ps5-qssr-sechs-spiele": {"titel": "AI скалирането QSSR на Sony идва в още шест игри на стандартния PS5, сред тях Spider-Man 2 и Arc Raiders", "schlagzeile": "AI скалиране за обикновения PS5: шест игри стават по-резки", "kurz": "AI скалирането QSSR на Sony идва в още шест игри за PS5, сред които Marvel's Spider-Man 2, Control Resonant и Arc Raiders. QSSR се базира на PSSR от PS5 Pro, но работи на стандартния PS5. Spider-Man 2 вече получи обновлението.", "zusammenfassung": "Sony разширява своето AI скалиране Quick Spectral Super Resolution, накратко QSSR, към още игри на стандартния PS5. Потвърдени са Marvel's Spider-Man 2, Control Resonant, The Finals, ARC Raiders, No Man's Sky и Hell Let Loose: Vietnam. Според PlayStation в X Spider-Man 2 стартира днес; VGC съобщава, че останалите вече са обновени или ще бъдат скоро. QSSR е изграден върху същата основа като PSSR на PS5 Pro. Първите игри с QSSR бяха Marvel's Wolverine и Ghost of Yōtei. Insomniac обещава по-стабилна и по-рязка картина в режимите за качество и производителност на Spider-Man 2. Remedy говори за осезаемо по-добра стабилност на образа и по-фини детайли в Control Resonant. Студиата на Arc Raiders, No Man's Sky и Hell Let Loose: Vietnam също посочват по-рязка и по-чиста картина. Digital Foundry нарече потенциала на технологията забележителен, именно защото много игри от това поколение страдат от ниска резолюция и слабо скалиране. Студиата не дават измервания на кадрите в секунда или резолюцията. Затова все още не е ясно дали QSSR коства производителност.", "weitere_links": ["PlayStation в X", "Insider Gaming"], "_src": "010812aa"}, "2026-11-13-gta6-day-one-patch-macca": {"titel": "GTA 6 седмица преди премиерата: разпространява се първото обновление 1.002, първи тийзър на анимационния сериал Macca & Friends в играта", "schlagzeile": "GTA 6: първо обновление преди премиерата – и собствен анимационен сериал", "kurz": "Седмица преди старта Rockstar разпространява първо обновление за GTA 6 от около 1 GB, без бележки за промените. Има и първи поглед към Macca & Friends, анимационен сериал, който върви в играта. Според Guardian върху GTA 6 са работили близо 5000 души.", "zusammenfassung": "Малко преди премиерата на 19 ноември GTA 6 вече получава първото си обновление. Според Polygon някои играчи са получили в петък известие за версия 1.002 с размер около един гигабайт. Rockstar не е публикувала бележки за промените, вероятно и за да не издава сюжета. Обновлението изглежда се разпространява на етапи, така че не всички го виждат веднага. Според Polygon са възможни още обновления преди старта. Освен това акаунтът DiscussingFilm в X публикува първи тийзър на Macca & Friends – сериал, който Rockstar е продуцирала за играта, съобщава IGN. Анимацията за алигатора Мака и приятелите му върви в играта по канала Weazel. Според New York Times Роб Нелсън, един от ръководителите на Rockstar North, е имал нужда от около 80 часа за едно превъртане. Според репортаж на Guardian, обобщен от Golem, в разработката са участвали близо 5000 души. Не е известно колко от тях са външни изпълнители. Според Bloomberg Rockstar днес има 4711 служители в дванадесет офиса. GTA 6 излиза за PS5 и Xbox Series X/S; версия за PC не е обявена.", "weitere_links": ["IGN", "Golem.de"], "_src": "eed94cb0"}, "2026-11-13-gow-sons-of-sparta-ps4": {"titel": "God of War: Sons of Sparta излиза за PS4 на 16 ноември и получава два нови режима", "schlagzeile": "God of War: Sons of Sparta идва на PS4 – с два нови режима", "kurz": "2D спин-офът God of War: Sons of Sparta излиза и за PS4 на 16 ноември. Едновременно PS4 и PS5 получават с безплатно обновление два нови режима: спийдрън режим и режим, в който всеки удар е смъртоносен.", "zusammenfassung": "Sony пренася God of War: Sons of Sparta на още една платформа. 2D екшън платформърът излиза за PlayStation 4 на 16 ноември в полунощ местно време, потвърди PlayStation в X. Едновременно идва безплатно обновление с два нови режима за версиите за PS4 и PS5. Режимът Хермес е спийдрън режим с таймер по отсечки и постоянна класация. Отключва се след завършване на играта или с код в началното меню, съобщава VGC. В режима Ереб един удар стига както за Кратос, така и за враговете. Този режим се избира при започване на нова игра. Sons of Sparta е разработена от Mega Cat Studios съвместно със Santa Monica Studio и излезе за PS5 през февруари. Играта разказва канонична история от младостта на Кратос по време на обучението му в Спарта с брат му Деймос. Материалът не споменава цена за версията за PS4.", "weitere_links": ["PlayStation в X", "Polygon"], "_src": "2fba3bd2"}, "2026-11-13-tsmc-mitarbeiterdaten-leak": {"titel": "TSMC потвърждава изтичане на данни: информация за служители се появява онлайн, уж предлагана за три биткойна", "schlagzeile": "Изтичане при TSMC: данни на служители уж се продават за три биткойна", "kurz": "В задължително уведомление до американската комисия по ценните книжа TSMC потвърди, че данни на настоящи и бивши служители са се появили без разрешение на външен сайт. Според TSMC данните идват от услуги на облачен доставчик, а собствените ѝ системи не са компрометирани. TSMC твърди, че данни на клиенти не са засегнати.", "zusammenfassung": "Най-големият договорен производител на чипове в света потвърди изтичане на данни. Във формуляр 6-K до американската SEC TSMC пише, че данни на настоящи и бивши служители са станали достъпни без разрешение на външен сайт. Според Seeking Alpha, цитиран от PC Gamer, става дума за над 46 000 записа. TSMC посочва, че данните съвпадат с информация, съхранявана при неназован доставчик на облачни услуги. Няма признаци за проникване в собствените ѝ системи. Засегнатите са уведомени, а компанията работи с облачния доставчик, разследващите органи и външна фирма за сигурност. Тайванският вестник United Daily News съобщава, че хакери са предлагали 6,9 GB данни в нелегален форум за три биткойна. Публикувана извадка уж съдържа номера на лични карти, адреси и банкови данни; TSMC не е потвърдила това. Според TSMC данните нямат връзка с дейността ѝ или с информация за клиенти. По това, което се знае досега, дизайни на чипове или данни на клиенти като Nvidia, AMD или Apple не са засегнати. TSMC попадна в заглавията още през 2023 г. заради хакнат доставчик.", "_src": "581609d8"}, "2026-11-13-intel-desktop-marktanteil": {"titel": "Mercury Research: Intel си връща около пет процентни пункта пазарен дял при настолните процесори от AMD през третото тримесечие на 2026 г.", "schlagzeile": "Изненада: Intel отнема пазарен дял от AMD при настолните процесори", "kurz": "Според Mercury Research делът на AMD при настолните процесори е спаднал от около 35 на 29,9 процента през третото тримесечие на 2026 г. Анализаторите предполагат, че Intel е пренасочила повече чипове към настолния пазар. AMD може да страда и от слабия пазар на геймърски компютри.", "zusammenfassung": "Intel си върна значителна позиция при настолните процесори през третото тримесечие на 2026 г. Според новите данни на Mercury Research, за които пише PC Gamer, делът на AMD при настолните компютри е спаднал от около 35 процента през второто тримесечие до 29,9 процента. Това е спад с около пет процентни пункта за три месеца. Самата Mercury Research не е напълно сигурна на какво се дължи. Анализаторите предполагат, че заради слабото търсене на лаптопи Intel е успяла да насочи повече чипове към настолния пазар, който през третото тримесечие е сезонно по-силен. AMD пък не е показала сезонен ръст. Като втора причина Mercury посочва по-голямата зависимост на AMD от гейминг пазара, който страда от оскъдни и скъпи видеокарти. Към това се добавят високите цени на RAM и SSD, които отказват мнозина от покупка на нов компютър. Intel има силно присъствие при производителите на компютри, които сглобяват и евтини системи на по-стари DDR4 платформи. PC Gamer подчертава, че това не е знак за здрав пазар: двата производителя уж са доставили с над десет процента по-малко чипове за лаптопи през третото тримесечие. В производителността в игри AMD остава напред с моделите X3D.", "_src": "abc6b821"}, "2026-11-13-huang-kongress-anhoerung": {"titel": "Конгресът на САЩ привиква бившия шеф на Nvidia Дженсън Хуанг под заплаха от призовка, Тръмп предлага Тим Кук за наследник", "schlagzeile": "Конгресът заплашва Хуанг с призовка – Тръмп иска Тим Кук начело на Nvidia", "kurz": "Три комисии на Камарата на представителите на САЩ искат да разпитат Дженсън Хуанг в началото на декември и заплашват с призовка, ако не се яви. Той трябва да свидетелства и публично пред банковата комисия на Сената. Междувременно президентът Тръмп препоръчва Тим Кук от Apple за нов шеф на Nvidia.", "zusammenfassung": "Натискът върху напусналия основател на Nvidia Дженсън Хуанг продължава да расте. Според PC Gamer председателите на три комисии на Камарата на представителите са поканили Хуанг и главния юрисконсулт на Nvidia Тим Тетър на закрити разпити със стенограма на 1 и 2 декември. Ако не се явят, ги заплашва призовка. Темите са предполагаема контрабанда на AI чипове, използване на продукти на Nvidia от враждебни армии и съобщения за намеса в американския експортен контрол, включително около сингапурската фирма MegaSpeed. Предишно писмо, изпратено преди оставката на Хуанг, беше формулирано много по-любезно. Освен това сенатор Тим Скот е поканил Хуанг на публично изслушване в банковата комисия на Сената на 3 декември, както и министъра на търговията Хауърд Лутник. Според BBC, цитирана от PC Gamer, Хуанг е готов да се яви пред Конгреса. Същевременно президентът Доналд Тръмп посочи в Truth Social желания от него наследник: Тим Кук, който беше шеф на Apple до септември, а сега е изпълнителен председател на борда, съобщава Golem. Решението обаче е на борда на Nvidia, който иска да разгледа вътрешни и външни кандидати. Дотогава финансовият директор Колет Крес ръководи компанията временно. Не е известно дали Кук изобщо проявява интерес.", "weitere_links": ["Golem.de"], "_src": "210eda80"}, "2026-11-13-november-patch-druck-aktivierung": {"titel": "Microsoft потвърждава: ноемврийските обновления на Windows причиняват грешки при печат и проблеми с активацията", "schlagzeile": "Ноемврийският пач на Windows: печатът и активацията създават проблеми", "kurz": "Microsoft потвърди два нови проблема с ноемврийските обновления за сигурност. Документи с невидими изображения понякога не могат да се отпечатат, а някои команди за активация завършват с грешка 0x80041008. Поправка за активацията се очаква в следващите дни.", "zusammenfassung": "Ноемврийският Patch Tuesday създава още проблеми. Според BleepingComputer Microsoft е потвърдила, че след обновленията печатът може да се провали. Засегнати са документи с изображения, които при избраната резолюция на печат имат височина или ширина нула. Такива невидими изображения има например във водни знаци или котви на оформлението в документи на Word. Проблемът засяга най-вече печата през графичния интерфейс на Windows GDI, от Windows 10 и Windows Server 2016 нагоре. Освен това команди за активация през инструмента slmgr.vbs завършват с грешка 0x80041008. Това засяга основно фирми, които автоматизират активацията и KMS сървъри. Според Microsoft вече активираните устройства остават активирани. Поправка се очаква в следващите дни, а дотогава може да помогне само бизнес поддръжката. За проблема с печата материалът все още не дава срок. Тази седмица Microsoft потвърди също, че ноемврийските обновления не се инсталират на системи с октомврийското предварително обновление. Домашните потребители са засегнати основно от грешката при печат.", "weitere_links": ["BleepingComputer (активация)"], "_src": "5b5d312a"}, "2026-11-13-xbox-25-konsole-ausverkauft": {"titel": "Xbox Series X за 25-годишнината се разпродаде за секунди, прекупвачи искат до 2500 долара", "schlagzeile": "Юбилейният Xbox изчезна за секунди – прекупвачи искат до 2500 долара", "kurz": "Полупрозрачният зелен Xbox Series X за 25-годишнината беше разпродаден за секунди в Microsoft Store. Феновете са ядосани от малкото бройки и липсата на защита срещу ботове. Според IGN конзоли вече са продадени в eBay за 1500 до 2500 долара.", "zusammenfassung": "Пускането на лимитирания Xbox Series X за 25-ия рожден ден на марката се провали за много фенове. Според IGN конзолата изчезна за секунди от Microsoft Store. Microsoft предварително беше обявила само ограничено количество, различно според пазара и търговеца. Конзолата струва нормално 999 долара. Според IGN GameStop временно предлагаше своята квота за 4950 долара; и тя вече е изчерпана. В eBay IGN откри десетки вече продадени бройки за 1500 до 2500 долара. Феновете критикуват най-вече, че Microsoft не въведе нито опашка, нито ограничение до истински Xbox акаунти. Някои разказват, че количката просто изчезнала по време на покупката. Шефката на Xbox Аша Шарма каза през октомври, че търсенето на конзоли е по-голямо от предлагането. Не е известно дали Microsoft ще зареди още. Материалът не споменава цени или наличност в Европа.", "_src": "b36d434d"}, "2026-11-13-gdc-ps6-helix-ki": {"titel": "Анкета на GDC: 10% от разработчиците вече работят по игри за PS6, 8% по Project Helix, 40% ползват генеративен AI", "schlagzeile": "Вече в разработка: всеки десети разработчик прави игра за PS6", "kurz": "В анкетата на GDC 10% от разработчиците с текущ проект казват, че играта им е планирана за следващото PlayStation. 8% посочват Project Helix на Microsoft. Освен това 40% използват генеративен AI, но 55% го смятат за вреден.", "zusammenfassung": "Новият доклад State of the Game Industry на Game Developers Conference показва, че следващото поколение конзоли вече е в разработка. Според Golem 10% от анкетираните с текущ проект казват, че играта им е предвидена за бъдещото PlayStation на Sony. 8% посочват следващия Xbox на Microsoft с кодово име Project Helix. Възможни бяха няколко отговора, затова не е ясно за колко различни игри става дума. Най-важната платформа остава PC с 81%, следван от PS5 с 45% и Xbox Series X/S с 37%. Steam Deck достига 32%, Switch 2 – 29%, а Steam Machine на Valve – 21%. Втората голяма тема е AI: според Eurogamer 40% от анкетираните използват генеративен AI в работата си, с четири процентни пункта повече от миналата година. Същевременно 55% казват, че AI вреди на игралната индустрия. В AAA студията 27% се чувстват притиснати или насърчавани да ползват AI, докато при инди разработчиците са само 9%. За броя на анкетираните Golem посочва над 2600, а Eurogamer – над 2300. Данните за съкращенията от същата анкета бяха в тикера още вчера.", "weitere_links": ["Eurogamer"], "_src": "bdc4eaf1"}, "2026-11-13-microsoft-365-grossstoerung": {"titel": "Голям срив на Microsoft 365: Outlook, Exchange, Teams и Copilot не работиха с часове, възстановяването е постепенно", "schlagzeile": "Outlook и Teams не работят: Microsoft 365 се бори с голям срив", "kurz": "От четвъртък вечерта Microsoft 365 е с масови смущения по целия свят, засегнати са Outlook, Exchange Online, Teams и Copilot, наред с други. Според Microsoft много сървъри неочаквано са отпаднали и не става дума за кибератака. В петък сутринта страницата за състояние на Microsoft все още показва влошаване на услугата; устойчиво възстановяване още няма.", "zusammenfassung": "В четвъртък, 12 ноември, се стигна до един от най-големите сривове на Microsoft 365 напоследък. Според BleepingComputer инцидентът с номер MO1550821 е започнал в 13:26 ч. по времето на източното крайбрежие на САЩ, тоест вечерта в Централна Европа. Засегнати бяха Exchange Online и Outlook, Teams, SharePoint Online, Microsoft 365 Copilot и Defender XDR, наред с други, във всички региони. Като причина Microsoft посочва редица сървъри, които неочаквано са станали недостъпни и са претоварили останалата инфраструктура. Компанията спря всички внедрявания, преразпредели трафика и рестартира сървъри. Според Neowin първите мерки не проработиха както се очакваше, тъй като ключов процес на засегнатите сървъри е бил претоварен. Мениджърът на Microsoft Чарлз Ламана се извини и заяви, че няма признаци за атака. През нощта Microsoft съобщи за бавно възстановяване, но в петък сутринта официалната страница за състояние все още показва влошаване на услугата; Microsoft говори само за частичен успех и устойчиво възстановяване още няма. Според Windows Latest бизнес клиентите могат да поискат SLA кредит през административния център на Microsoft 365. Дали и колко пари ще бъдат върнати, зависи от реалния брой засегнати потребители и продължителността. Частните потребители на Outlook.com по правило нямат право на това.", "weitere_links": ["Neowin", "heise online", "Golem.de", "Windows Latest (SLA кредит)"], "_src": "e59ef834"}, "2026-11-13-nvidia-doj-ermittlungen": {"titel": "Съобщения: Министерството на правосъдието на САЩ разследва Nvidia, Supermicro и Megaspeed след оставката на Хуанг", "schlagzeile": "След оставката на Хуанг: правосъдието на САЩ разследвало Nvidia", "kurz": "Според Semafor няколко отдела на Министерството на правосъдието на САЩ са започнали разследвания, засягащи Nvidia, Supermicro и Megaspeed. В центъра са AI ускорители, предполагаемо доставени в Китай. Засега няма признаци за обвинение срещу Nvidia или бившия CEO Дженсън Хуанг.", "zusammenfassung": "Ден след оставката на Дженсън Хуанг за Nvidia не става по-спокойно. Според heise Semafor съобщава, позовавайки се на двама държавни служители, че различни отдели на Министерството на правосъдието на САЩ са започнали разследвания. Те засягали Nvidia, производителя на сървъри Supermicro и базираната в Сингапур компания Megaspeed. Megaspeed е обвинена, че е доставяла AI ускорители на Nvidia в Китай въпреки американските експортни ограничения. В центъра била ролята на бивша ръководителка в Megaspeed, с която Хуанг е имал връзка. Според heise засега няма признаци, че министерството ще повдигне обвинения срещу Nvidia или Хуанг. Nvidia и министерството отказаха коментар. Supermicro заяви, че Megaspeed никога не е бил неин клиент, и обеща сътрудничество с властите. Освен това Reuters съобщава за още една връзка на Хуанг със служителка на Nvidia. За купувачите на GeForce карти засега няма известни последици. Nvidia представя тримесечните си резултати на 17 ноември, където темата вероятно ще бъде засегната.", "weitere_links": ["PC Games Hardware (тримесечни резултати на 17.11)"], "_src": "3049650e"}, "2026-11-13-codex-radeon-r600-fix": {"titel": "С помощта на OpenAI Codex: в Linux е поправена почти 20-годишна грешка във видеодекодера на Radeon HD 2000/3000", "schlagzeile": "AI откри стар бъг в Radeon: поправка за HD 2000/3000 идва в Linux 7.5", "kurz": "Програмист любител откри и поправи с помощта на OpenAI Codex видео грешка в почти 20-годишни Radeon GPU от ерата R600. Пачът държи видеоданните във VRAM и влиза в Linux 7.5. AMD не поддържа тези карти от години.", "zusammenfassung": "Сред пачовете за графичния драйвер на AMD за Linux 7.5 според Phoronix има необичайна поправка. Тя засяга видеодекодера UVD на картите Radeon от поколението R600, тоест Radeon HD 2000 и 3000 отпреди почти 20 години. Разработчикът Тед Булок забелязал повредени видеокадри на стар iMac с чип RV610. Грешките се появявали, когато декодерът чете компресирани видеоданни от системната памет, докато GPU едновременно рисува. Когато данните бяха в графичната памет, видеата вървяха чисто. Затова пачът му държи UVD буферите във VRAM за чиповете RV610, RV620, RV630, RV635 и RV670. Тествал е само на собствения си хардуер, за останалите чипове още липсва потвърждение. Булок открито пише, че е използвал OpenAI Codex за анализа, тестовете и пача. Пачът е приет и влиза в Linux 7.5. Прозорецът за сливане за тази версия се отваря около края на годината.", "_src": "f0dd1006"}, "2026-11-13-windhawk-patchday-fix": {"titel": "Ноемврийският Patch Tuesday счупи модове на Windhawk, разработчикът дава заобиколно решение", "schlagzeile": "Patch Tuesday счупи модовете на Windhawk – ето как да ги върнете", "kurz": "След ноемврийската актуализация KB5132061 много модове на инструмента Windhawk спряха да работят, особено за лентата на задачите и Explorer. Причината са липсващи символи за дебъгване от Microsoft. Разработчикът пусна заобиколно решение, просто изключете и включете модовете отново.", "zusammenfassung": "Windhawk е популярен инструмент за персонализиране на Windows чрез модове, например лентата на задачите или File Explorer. След ноемврийския Patch Tuesday потребители съобщават според Neowin, че модовете им вече не се зареждат. Проблемът се появи на 10 ноември в issue в GitHub, малко след актуализацията KB5132061, и засяга Windows 11 и Windows 10. Разработчикът на Windhawk Майкъл Малцев потвърди грешката. Причината е, че Microsoft не е публикувала част от символите за дебъгване за новите версии на Windows. Windhawk има нужда от тези символи, за да намери местата в системата, които модът променя. Според Малцев това не е първият път, когато Microsoft предоставя символите със закъснение или изобщо не ги предоставя. Като решение има ръчно съпоставяне чрез кеша със символи на Windhawk, което връща към работа повечето засегнати модове. То вече е включено в онлайн кеша. Ако все още имате проблеми, изключете и включете отново засегнатите модове в Windhawk.", "_src": "ea0f7eeb"}, "2026-11-13-wolfenstein-3-offiziell": {"titel": "Xbox потвърждава: Wolfenstein 3 официално е в продукция в MachineGames", "schlagzeile": "Най-сетне официално: MachineGames работи по Wolfenstein 3", "kurz": "Xbox потвърди на FanFest за 25-годишнината си, че Wolfenstein 3 е в продукция в MachineGames. Актьорите на B.J. Blazkowicz и Grace Walker се завръщат. Още няма дата и платформи.", "zusammenfassung": "Дълго се спекулираше, сега е официално: Wolfenstein 3 е в продукция. Шефката на Xbox Аша Шарма потвърди проекта в X по време на Xbox FanFest в Сиатъл. Играта отново се разработва от шведското студио MachineGames, което наскоро направи Indiana Jones and the Great Circle. MachineGames показа страница от сценария с изречението \"His reputation precedes him\". На снимка от студиото за motion capture се виждат Браян Блум и Дебра Уилсън, които отново играят B.J. Blazkowicz и Grace Walker. Предшественикът Wolfenstein II: The New Colossus излезе през 2017 г. Ръководителят на студиото Йерк Густафсон беше казвал и преди, че историята на B.J. винаги е планирана като трилогия. Xbox още не е обявил трейлър, дата или платформи. Успоредно в Amazon се подготвя сериал Wolfenstein.", "weitere_links": ["IGN Deutschland", "Аша Шарма в X"], "_src": "28db60dc"}, "2026-11-13-pocketpair-gta6-urlaub": {"titel": "Студиото на Palworld, Pocketpair, праща служителите си на „командировка до Vice City“ за старта на GTA 6", "schlagzeile": "GTA 6 треска: студиото на Palworld дава почивка на всички за старта", "kurz": "Студиото на Palworld, Pocketpair, освобождава в седмицата на старта всички служители, които искат да играят GTA 6. Официално това се нарича „спешна командировка до Vice City“. Logitech и други фирми също дават почивни дни за старта.", "zusammenfassung": "GTA 6 излиза на 19 ноември за конзоли и някои фирми вече се пренастройват. Японското студио Pocketpair, известно с Palworld, публикува в X шеговито съобщение. Всички служители, които искат да играят GTA 6, са освободени от задълженията си от 19 до 23 ноември и са насърчени да отидат на „командировка до Vice City“. Тъй като в периода има уикенд, на практика това са три почивни дни. Pocketpair подчертава, че актуализациите за Palworld и Craftopia въпреки това ще излязат по план. Според PC Gamer студиото не е само: Logitech дава на около 7000 свои служители почивен ден на 19 ноември с „Logi Game Day“, като всяка игра е позволена. Американският производител на тунинг части Burger Motorsports и канадският производител на камиони Edison Motors също обявиха почивни дни за старта. Rockstar все още не е обявил дата за PC версия на GTA 6.", "_src": "ba5c4541"}, "2026-11-13-og-xbox-pc-21-spiele": {"titel": "Xbox пуска още 21 игри от първия Xbox на PC, четири класики получават постижения за първи път", "schlagzeile": "KOTOR, Morrowind и още: 21 класики от първия Xbox вече вървят на PC", "kurz": "Чрез обратната съвместимост на PC вече вървят още 21 игри от първия Xbox, общо 25. Сред тях са Morrowind, двете KOTOR и TimeSplitters 2. Четири игри получават постижения за първи път.", "zusammenfassung": "Четири месеца след старта на обратната съвместимост за игри от първия Xbox на PC Microsoft добавя още. Добавени са 21 заглавия, с което каталогът за PC стига 25 игри. Според VGC и Thurrott сред тях са The Elder Scrolls III: Morrowind, Star Wars: Knights of the Old Republic I и II, Jedi Academy, Jedi Outcast, TimeSplitters 2 и Crimson Skies. Morrowind и Grabbed by the Ghoulies са включени и в Game Pass. За първи път има постижения за четири класики: двете KOTOR, Blinx: The Time Sweeper и Conker: Live and Reloaded. Според Xbox те могат да се отключват на PC и на конзола. Вицепрезидентът на Xbox Джейсън Роналд пише също, че първите четири игри вече вървят по-стабилно и по-бързо, а всички заглавия поддържат мишка и клавиатура. Предстоят още игри. Обявата е част от Xbox FanFest около 25-годишнината на 15 ноември.", "weitere_links": ["Thurrott.com", "Xbox в X"], "_src": "92b056c0"}, "2026-11-13-geforce-621-24": {"titel": "Nvidia GeForce 621.24 WHQL: Game Ready за Dawn of War 4 и Assetto Corsa Rally, подготовка за DLSS 5 в Where Winds Meet", "schlagzeile": "GeForce 621.24: нов драйвер за Dawn of War 4 и DLSS 5", "kurz": "Nvidia пусна драйвера GeForce 621.24 WHQL само осем дни след 621.14. Той е Game Ready за Dawn of War 4 и Assetto Corsa Rally и подготвя DLSS 5 в Where Winds Meet. Поправени са само две грешки, засягащи главно професионални и видео приложения.", "zusammenfassung": "С GeForce 621.24 WHQL Nvidia пуска четвъртия си драйвер за 22 дни. Според PCGH в центъра е Warhammer 40,000: Dawn of War 4, която излиза на 3 декември, а купувачите на Commander Edition могат да играят още от 30 ноември. Оптимизирана е и Assetto Corsa Rally, а рали симулаторът трябва да получи на 19 ноември актуализация с DLSS 4.5 и Dynamic Multi Frame Generation. Това генериране на кадри изисква GeForce RTX 5000. На 23 ноември Where Winds Meet трябва да получи DLSS 5 с ново невронно рендериране, според PCGH само за карти Blackwell и системи RTX Spark. Поправени са две грешки: OptiX denoiser в Chaos Vantage можеше да се проваля при високи резолюции, а H.265 видеа от DJI в профил D-Log се показваха с грешни цветове в приложения на Windows. Бележките към изданието не посочват отворени проблеми при старта. Ново е и CUDA 13.5. Поддържат се настолни карти от GTX 1630 до RTX 5090, Pascal и Maxwell вече не са включени. Ако не играете нито една от споменатите игри, не е нужно да обновявате веднага.", "weitere_links": ["TechPowerUp"], "_src": "ba5b256f"}, "2026-11-13-amd-china-gpu-kuerzung": {"titel": "Доклад: AMD е намалила доставките на геймърски GPU в Китай с 20 до 50 процента от октомври", "schlagzeile": "Изтичане: Намалява ли AMD доставките на Radeon в Китай с до 50%?", "kurz": "AMD е намалила от октомври доставките на геймърски GPU за производителите на карти в Китай с 20 до 50 процента, твърди се. Това съобщава китайският форум Board Channels, който очаква недостигът да продължи до януари. AMD не е коментирала.", "zusammenfassung": "Според публикация от 12 ноември в китайския браншов форум Board Channels AMD е намалила значително от началото на четвъртото тримесечие количеството геймърски графични чипове за партньорите си в Китай. Става дума за поне 20 до 50 процента по-малко, а месечните квоти продължавали да намаляват. Ситуацията вече била също толкова напрегната, колкото при Nvidia. Източникът очаква предлагането да остане силно ограничено до януари. Цените на Radeon в Китай растели всяко тримесечие, което се обяснява с по-високите разходи за памет и GPU. AMD отново щяла да вдигне този месец цената на комплектите GPU и GDDR6, след поскъпване през октомври. TechPowerUp посочва, че докладът не дава конкретни бройки, засегнати модели или причини. Освен това се отнася само за Китай и не е ясно дали Европа или САЩ ще видят подобни съкращения. AMD не е коментирала доклада. Данните не са потвърдени и трябва да се разглеждат като индикация за пазарната ситуация, а не като факт.", "_src": "96b17733"}, "2026-11-13-fable-gameplay-4-minuten": {"titel": "Xbox показва четири минути нов геймплей от Fable, премиера на 23 февруари 2027 г.", "schlagzeile": "Четири минути нов Fable: битки, магия и мрачна гора", "kurz": "Xbox публикува четири минути нов геймплей от рестарта на Fable от Playground Games. Виждат се ръкопашен бой, бой от разстояние и магия, записани на PC с ултра настройки. Fable излиза на 23 февруари 2027 г. за Xbox Series X|S, PS5 и PC.", "zusammenfassung": "За 25-годишнината на Xbox шефката Аша Шарма сподели ново геймплей видео от Fable. Според IGN четирите минути показват основно битки с меч, оръжия от разстояние и магия. Записът е направен на PC с ултра графични настройки. В историята Героят от Briar Hill разследва заедно с местна героиня странни магически случки в гората Deepwood. Играта се разработва от Playground Games, известни със серията Forza Horizon. Fable първоначално беше планирана за тази есен и беше отложена за 23 февруари 2027 г. Излиза за Xbox Series X|S, PS5 и PC и вече може да се поръча предварително в Steam. Реакциите са смесени: според PC Gamer видеото е мрачно и доста обикновено и малко напомня за пъстрата, чудата поредица Fable. В коментарите в YouTube обаче реакцията беше предимно положителна. Кратък клип естествено показва само малка част от играта.", "weitere_links": ["PC Gamer", "Аша Шарма в X"], "_src": "083ecad5"}, "2026-11-13-id-software-neues-spiel": {"titel": "id Software потвърждава нова игра с режисьор Хюго Мартин, Doom: The Dark Ages получава Slaughter Mode", "schlagzeile": "Създателите на Doom от id Software вече работят по следващата си игра", "kurz": "id Software работи по нова игра, отново с Хюго Мартин като game director. Коя поредица ще е, не е ясно. Преди това Doom: The Dark Ages получава на 16 ноември безплатен Slaughter Mode за притежателите на разширението Revelations.", "zusammenfassung": "Шефката на Xbox Аша Шарма потвърди по време на Xbox FanFest, че id Software вече работи по следващата си игра. Самото студио написа в X, че проектът се прави от екипите му в Тексас и Франкфурт, а game director отново е Хюго Мартин. Мартин беше творчески директор на Doom (2016) и Doom Eternal и game director на Doom: The Dark Ages. Дали ще е нов Doom, Quake или нещо съвсем различно, id не казва. Според id ще мине време, докато има какво повече да се покаже, така че проектът вероятно е в ранна фаза. VGC припомня, че id Software беше силно засегнато от съкращенията в Xbox, като общо 136 души загубиха работата си. Преди това на 16 ноември идва Slaughter Mode за Doom: The Dark Ages. Безкрайният режим за един играч е безплатна актуализация за всички, които имат разширението Revelations.", "weitere_links": ["VGC", "PC Gamer", "Аша Шарма в X"], "_src": "1b3eaa23"}, "2026-11-13-cmp170hx-80gb-hack": {"titel": "Хардуерен хак: майнинг картата Nvidia CMP 170HX може да се отключи до 80 GB HBM2e и до 126 SM", "schlagzeile": "От 8 на 80 GB: хак превръща майнинг картата на Nvidia в AI карта", "kurz": "Разработчичка е отключила с трик с напрежението пълните 80 GB HBM2e вместо 8 GB на старата майнинг карта Nvidia CMP 170HX. Успяла е да активира и до 126 вместо 70 изчислителни блока. Модификацията изисква запояване, необратима е и може да унищожи картата.", "zusammenfassung": "Nvidia продаваше CMP 170HX през 2021 г. като ускорител само за Ethereum, но вътре в нея е същият чип GA100 като в картата за центрове за данни A100. Фабрично са достъпни само 8 GB от реално монтираните 80 GB HBM2e, както и 70 от 128 стрийминг мултипроцесора. Със софтуерния инструмент cmpunlocker още от лятото можеха да се отключат до 64 GB. Разработчичка на име Кейт отива по-далеч с хардуерен хак, публикуван на 10 ноември: малка допълнителна платка с микроконтролер STM32 създава целенасочени спадове на напрежението и кара eFuse контролера отново да приема заключени настройки. Според ComputerBase девет от десет тествани карти след това предлагат пълните 80 GB, една стига до 64 GB. В зависимост от екземпляра стават активни и 120 до 126 SM. В тест OpenCL FP16 модифицираната карта достига 85,9 TFLOPS и изпреварва стандартна A100 с 72,5 TFLOPS. Според ComputerBase тази стойност не може директно да се пренесе към реални AI приложения. С допълнителни настройки би трябвало да се отключат и PCIe 4.0 x16 и NVLink. Уловката: намесата изисква запояване и според разработчичката между един и 48 часа опити. Промените в eFuse са необратими и грешка може да направи картата неизползваема. Няма гаранция, че и други екземпляри имат толкова работещ хардуер.", "weitere_links": ["PC Games Hardware"], "_src": "d1af15c7"}, "2026-11-13-game-awards-disney-plus": {"titel": "The Game Awards 2026 за първи път и в Disney+", "schlagzeile": "The Game Awards 2026 за първи път ще се излъчват и в Disney+", "kurz": "The Game Awards 2026 за първи път ще се излъчват и в Disney+. Twitch, YouTube и други платформи остават, а шоуто е на 10 декември в Лос Анджелис.", "zusammenfassung": "The Game Awards имат нов партньор тази година: според IGN шоуто за първи път ще се излъчва и в Disney+. Освен това то ще върви както обикновено в Twitch и YouTube, както и в Steam, TikTok, X, Facebook и Kick, наред с други. Церемонията е в четвъртък, 10 декември, в Peacock Theater в Лос Анджелис. Започва в 19:30 ч. по времето на източното крайбрежие на САЩ, което в Централна Европа е 1:30 ч. през нощта на 11 декември. Водещ отново е Джеф Кийли. Според Variety Disney иска да използва партньорството, за да рекламира собствени игрови и анимационни проекти. IGN нарежда сред фаворитите Resident Evil Requiem, 007 First Light и римейка на Ocarina of Time. GTA 6 излиза на 19 ноември и така на косъм влиза в тазгодишните награди.", "_src": "862b9826"}, "2026-11-13-halo-ce-firefight": {"titel": "Halo: Campaign Evolved получава тази зима Firefight като безплатна актуализация", "schlagzeile": "Halo: Campaign Evolved получава безплатен режим Firefight", "kurz": "Римейкът Halo Campaign Evolved получава тази зима режима Firefight като безплатна актуализация. До четирима играчи се бият заедно срещу вълни от врагове. Повече подробности ще има на Halo Fest в средата на декември.", "zusammenfassung": "Xbox обяви на FanFest, че Halo: Campaign Evolved ще получи режим Firefight. Firefight е кооперативен PvE режим за до четирима играчи, който вече присъства в няколко игри от Halo. Актуализацията ще излезе безплатно някъде тази зима, точна дата още няма. Според VGC посетителите на FanFest е трябвало да могат да изпробват режима на място. Повече подробности Xbox ще даде на Halo Fest на 12 и 13 декември. Halo: Campaign Evolved е римейк на кампанията от първия Halo и излезе през юли. VGC отбелязва, че намаленото Halo Studios след съкращенията в Xbox поддържа вече само съществуващите игри Halo. Според VGC ново Halo се разработва в Activision.", "weitere_links": ["Thurrott.com", "Аша Шарма в X"], "_src": "3a3814c4"}, "2026-11-12-amd-26-11-1-ssd-fix": {"titel": "AMD Adrenalin 26.11.1 отстранява постоянния запис върху SSD", "schlagzeile": "Драйвер Radeon 26.11.1: AMD най-сетне спира постоянния запис по SSD", "kurz": "AMD пусна незадължителния драйвер Adrenalin 26.11.1. Той официално отстранява грешката, заради която драйверът постоянно записваше данни на SSD във фонов режим. Списъкът с известни проблеми обаче се удължи.", "zusammenfassung": "Потребители на Radeon откриха, че драйверът Adrenalin постоянно записва данни на диска във фонов режим, дори в покой. heise предупреди, че това може да застраши живота на SSD, а досега помагаше само безплатен инструмент от общността. Сега според Wccftech и Neowin AMD пусна незадължителния драйвер 26.11.1, който трябва официално да реши проблема. Според бележките към версията засегнати са собствениците на Radeon RX 7000 и RX 9000, а грешката се появяваше и при местене или преоразмеряване на прозорци. Списъкът с известни проблеми включва девет нови точки, главно сривове и таймаути на драйвера в отделни игри като Cyberpunk 2077 и War Thunder. При картите RX 9000 AMD посочва и графични дефекти в Phantom Blade Zero. Засегнатите от проблема със SSD трябва да инсталират обновлението, след което могат да премахнат инструмента от общността.", "weitere_links": ["Neowin", "heise online"], "_src": "336a15b3"}, "2026-11-12-gdc-umfrage-entlassungen": {"titel": "Анкета на GDC: всеки трети анкетиран в игровата индустрия е бил съкратен за две години", "schlagzeile": "Анкета на GDC: всеки трети анкетиран от игровата индустрия е съкратен", "kurz": "В новата анкета на GDC сред над 2600 професионалисти 34 процента казват, че са били съкратени през последните две години. Над половината от тях все още нямат работа. Според анкетата настроението в индустрията е лошо.", "zusammenfassung": "15-ото издание на анкетата „State of the Game Industry“ на GDC обхваща над 2600 професионалисти от индустрията по света, съобщава VGC. 34 процента казват, че са били съкратени през последните две години, а в САЩ дори 39 процента. В анкетата от януари стойността е била 28 процента. От съкратените 54 процента все още са без работа, а 27 процента са подали поне 100 кандидатури. 17 процента са били съкратени дори два пъти за две години. Само 45 процента от работещите смятат работата си поне донякъде сигурна за следващите дванадесет месеца. 81 процента се притесняват за бъдещето си в индустрията.", "_src": "f0c14b73"}, "2026-11-12-steam-pruefstau-ki": {"titel": "Задръстване в проверките на Steam заради поток от AI игри: още инди игри се отлагат", "schlagzeile": "Поток от AI игри в Steam: инди игри засядат в опашката на Valve", "kurz": "Проверката на нови игри в Steam в момента отнема до дванадесет дни, според разработчиците заради поток от нискокачествени AI игри. Няколко инди заглавия трябваше да отложат премиерата си. Valve затегна правилата за подаване, но критиците смятат, че това не стига.", "zusammenfassung": "От началото на ноември разработчици се оплакват от дълго чакане за одобрение от Valve на нови игри и билдове в Steam. Според Eurogamer Valve обяснява, че проверките могат да отнемат до дванадесет дни заради броя подадени игри, които трябва да бъдат проверени отново. Като причина се сочи поток от евтини игри, създадени с генеративен AI. Tower defense играта Australia Did It на Рами Исмаил и Aesthetician Labs трябваше да излезе на 10 ноември и все още чака одобрение. Amazing Slot Survivor също трябваше да оттегли датата си 13 ноември, засегнати са и други инди игри. Valve въведе по-строги правила за подаване, за да отсява по-рано игри, изцяло генерирани с AI. Исмаил смята, че Valve не може да остане неутрална към AI, без да навреди на истинските разработчици.", "_src": "5412161f"}, "2026-11-12-windows-signdrop-zero-day": {"titel": "SignDrop: нова zero-day уязвимост в Windows дава SYSTEM права, корекция още няма", "schlagzeile": "Zero-day SignDrop в Windows: SYSTEM права и все още без корекция", "kurz": "Изследовател по сигурността публикува SignDrop, нова непоправена уязвимост в Windows заедно с експлойт. Тя дава на нападателите SYSTEM права и заобикаля самозащитата на антивирусния софтуер. Според изследователя са засегнати около 80 процента от инсталациите на Windows.", "zusammenfassung": "Според BleepingComputer изследователят Абделхамид Насери, известен като Nightmare Eclipse, е публикувал нов zero-day експлойт за Windows. SignDrop използва точно защитна мярка, която Microsoft въведе през октомври 2025 г. за драйвера Common Log File System (CLFS). По заобиколен път привилегировани процеси като Windows Defender могат да бъдат накарани да създават файлове със SYSTEM права. Според Насери така може да се заобиколи и защитата срещу намеса на антивирусен и EDR софтуер. Той е тествал Windows 11 26H2 и Windows Server 2025 и смята, че около 80 процента от инсталациите са уязвими. Уязвими са системите, при които стойността в регистъра за режима на удостоверяване на CLFS е 0 или 1. Според Насери няма заобиколно решение и потребителите трябва да чакат корекция от Microsoft. Статията не споменава позиция на Microsoft.", "_src": "d8efd221"}, "2026-11-12-gta6-karte-leak": {"titel": "GTA 6: отпечатаната карта от Collector's Edition е изтекла чрез мърч събитие", "schlagzeile": "Изтичане: Картата на GTA 6 вече в мрежата седмица преди премиерата?", "kurz": "В мрежата се разпространяват снимки на отпечатана стилизирана карта на Леонида, която уж е от Collector's Edition на GTA 6. Снимките уж идват от мърч акция в Selfridges във Великобритания. Rockstar не е коментирала, а картата вероятно не е точно копие на игровия свят.", "zusammenfassung": "Седмица преди излизането на GTA 6 на 19 ноември се появяват снимки на карта, съобщават VGC и Insider Gaming. Те уж показват отпечатаната карта от Collector's Edition и идват от GTA 6 акция на веригата универсални магазини Selfridges. Според VGC най-ясната снимка е от вече изтрит Instagram профил, а друга снимка показва сгънатата карта във витрина в Манчестър. Според Insider Gaming източникът е служител на Selfridges, но това не е доказано. Картата показва Леонида стилизирано с окръзи и мотиви в стил клипарт, като монстър тракове, НЛО и самолети. Insider Gaming смята, че тя не отразява точно игровия свят. Rockstar не е потвърдила снимките. Който иска да избегне спойлери, трябва да внимава в социалните мрежи.", "weitere_links": ["Insider Gaming", "Polygon"], "_src": "a2e2106c"}, "2026-11-12-xbox-25-sharma-memo": {"titel": "25 години Xbox: Аша Шарма загатва за разработка с AI в меморандум, плюс Halo Firefight и Xbox Playback", "schlagzeile": "25 години Xbox: шефката иска малки екипи да строят огромни светове", "kurz": "За 25-ия рожден ден на Xbox шефката Аша Шарма публикува меморандум, който силно напомня за генеративен AI. Малки екипи ще могат да строят светове, за които днес са нужни стотици разработчици. Xbox обяви и режим Firefight за Halo: Campaign Evolved и годишния преглед Xbox Playback.", "zusammenfassung": "Шефката на Xbox Аша Шарма публикува за 25-годишнината меморандум със заглавие „25 Years of Xbox“. В края пише, че твърде много идеи никога не стават игри и че това трябва да се промени. Скоро един човек ще има възможности, за които някога са били нужни цели нации, а малки екипи ще могат да строят светове, които днес изискват стотици разработчици. Според Eurogamer терминът генеративен AI не се използва, но формулировките силно го подсказват. Шарма идва от AI отдела на Microsoft, но при встъпването си като шеф на Xbox каза, че има „нулева толерантност към лош AI“. За годишнината тя обяви в X и режим Firefight за Halo: Campaign Evolved, който идва като безплатно обновление тази зима; според Insider Gaming това е PvE режим за четирима играчи. Освен това се разпространява Xbox Playback, преглед на собствените игри и постижения в Xbox. Xbox не посочи конкретни AI проекти в меморандума.", "weitere_links": ["IGN", "Insider Gaming", "Asha Sharma auf X (Halo Firefight)"], "_src": "0b7ff29f"}, "2026-11-12-gta6-suedkorea-freigabe": {"titel": "GTA 6 едва не остана без възрастова категория в Южна Корея заради сцени с голота", "schlagzeile": "GTA 6 почти забранена? Южна Корея спори седмици за голотата", "kurz": "Южнокорейският орган за класификация GCRB дълго не можа да се разбере за GTA 6. Спорният момент беше голотата без сексуален контекст. Накрая играта получи категория „само за възрастни“ с осем гласа срещу един.", "zusammenfassung": "Според IGN Германия Rockstar е подала заявка за възрастова категория в Южна Корея на 1 септември. Първото гласуване на GCRB на 10 септември завършило наравно: трима членове искали да откажат категория, трима били за „само за възрастни“. Според протоколите от заседанията, получени от InvenGlobal, някои членове възразили срещу сцени с голота без сексуален контекст. Решението било отложено, докато не бъде налична играема версия, а няколко дати били изместени. На 18 октомври комисията решила с осем гласа срещу един категория „само за възрастни“. Отказ би спрял напълно продажбите в Южна Корея. GTA 6 излиза на 19 ноември за PS5 и Xbox Series X и S.", "weitere_links": ["Polygon"], "_src": "c47f9d24"}, "2026-11-12-nvidia-linux-nvroot-forgeptr": {"titel": "NvRoot и ForgePtr: публикувани са две уязвимости в Linux драйвера на Nvidia, обявени са още 25", "schlagzeile": "Linux драйверът на Nvidia: уязвимост дава root на процеси в контейнер", "kurz": "Фирмата за сигурност Stealthium публикува две уязвимости в отворените модули за ядрото на Nvidia за Linux. Чрез ForgePtr процес в GPU контейнер може да получи root на хоста. Корекции вече има, а предстоят още 25 разкрития.", "zusammenfassung": "Според Phoronix първите две от общо 27 обявени уязвимости в драйверния стек на Nvidia вече са публични. ForgePtr (CVE-2026-47501) позволява на непривилегирован процес в GPU контейнер да получи root права на хоста. С NvRoot (CVE-2026-47591) GPU може да презаписва файлове, които операционната система е маркирала само за четене. И двете уязвимости съществуват от около четири години в отворените модули на Nvidia и са оценени като високи (CVSS 7,8). Особено засегнати са облачните доставчици, които отдават GPU на множество клиенти. NvRoot е поправена в драйверите 610.57.04, 595.91.07 и 580.178.04, а ForgePtr в 615.71.09. Според Phoronix Stealthium е обявила още 25 разкрития, свързани с AI софтуерния стек на Nvidia. Който използва GPU на Nvidia под Linux, особено в контейнери, трябва да обнови драйвера.", "_src": "fa81fb4c"}, "2026-11-12-huang-ruecktritt-kress": {"titel": "Дженсън Хуанг се оттегля като CEO на Nvidia след 33 години, финансовият директор Колет Крес поема временно", "schlagzeile": "Край на една ера: Дженсън Хуанг подава оставка в Nvidia", "kurz": "Nvidia обяви оставката на съоснователя и CEO Дженсън Хуанг, който напуска всички постове с незабавен ефект. Финансовият директор Колет Крес ще ръководи компанията засега като временен CEO. Председател на борда става Харви К. Джоунс.", "zusammenfassung": "След дни на криза вече е официално: Дженсън Хуанг напуска ръководството на Nvidia след 33 години. Според ComputerBase той се отказва от постовете президент, CEO и член на борда, а според PC Gamer с незабавен ефект. Хуанг не е уволнен; според TechPowerUp той е подписал писмо за оставка. Поводът са публикации за две извънбрачни връзки, включително с мениджърка, която му е била пряко подчинена. Преди това бордът е заседавал извънредно, а според Bloomberg вече е наета външна фирма за търсене на наследник. Финансовият директор Колет Крес ръководи бизнеса като временен CEO и едновременно остава CFO. Председател на борда става Харви К. Джоунс. Крес заяви, че ще надгражда основата, която Хуанг е изградил за 33 години. От съобщението не става ясно дали Хуанг ще има роля в компанията в бъдеще. Кой ще бъде постоянен CEO е открит въпрос; засега има само спекулации. Последици за продуктите GeForce, цените или драйверите засега не са известни.", "weitere_links": ["PC Games Hardware", "TechPowerUp", "PC Gamer", "heise online"], "_src": "330d1f5e"}, "2026-11-12-paradox-wester-ruecktritt": {"titel": "Шефът на Paradox Фредрик Вестер се оттегля, Матиас Лиля поема през януари", "schlagzeile": "След провала на Bloodlines 2: Paradox получава нов шеф", "kurz": "CEO на Paradox Interactive Фредрик Вестер напуска поста си и преминава в борда на директорите. Заместникът му Матиас Лиля поема на 4 януари 2027 г. Издателят има зад гърба си няколко трудни години.", "zusammenfassung": "Според Eurogamer Фредрик Вестер се оттегля като CEO на Paradox Interactive и като член на борда ще се занимава с дългосрочното развитие. Наследник ще бъде досегашният заместник-CEO Матиас Лиля от 4 януари 2027 г., като дотогава Вестер остава на поста. Вестер ръководи Paradox от 2009 до 2018 г. и отново от 2021 г. Вторият му мандат включва трудната разработка на Vampire: The Masquerade Bloodlines 2, чийто търговски провал рязко срина оперативната печалба. Към това се добавят спирането на Life by You, отлагането на Prison Architect 2 и тежкият старт на Cities: Skylines 2, чиято конзолна версия все още липсва. Лиля иска да инвестира повече в основния бизнес и да работи по-тясно с играчите и модърите. Следващите игри са Lego Skylines и стратегията Afterworld.", "_src": "b6ea62b9"}, "2026-11-12-siren-halo-gddr7": {"titel": "Слух: Siren Halo на AMD ще използва графична памет GDDR7 вместо само LPDDR5X", "schlagzeile": "Изтичане: Ще получи ли мега-APU-то Siren Halo на AMD истинска GDDR7?", "kurz": "Според информатор бъдещото Halo APU на AMD, Siren Halo, ще работи с памет GDDR7. Сегашните Halo чипове използват обща памет LPDDR5X за CPU и GPU. Нищо не е потвърдено.", "zusammenfassung": "Хардуерният информатор Gotou_kai3 твърди, че Siren Halo на AMD ще получи памет GDDR7, съобщават Wccftech и PCGH. Подобно на Medusa Halo, Siren Halo ще използва Zen 6 и RDNA 5, но ще бъде истински наследник, а не просто обновление. Сегашните Halo чипове като Strix Halo използват LPDDR5X като обща памет за CPU и GPU. GDDR7 би дала много по-голяма пропускателна способност, което може да помогне особено на графиката в игрите. Според Wccftech не е ясно дали CPU и GPU ще могат да ползват и двата пула памет, или GDDR7 ще бъде само за графиката. За AI задачи графично решение само с GDDR7 може да е по-малко гъвкаво от голямата обща памет на сегашните чипове Ryzen AI Max. AMD не е анонсирала Siren Halo, а срокове и спецификации не са известни.", "weitere_links": ["Wccftech"], "_src": "6fee7dbc"}, "2026-11-12-apache-http2-luecke": {"titel": "Критична уязвимост в HTTP/2 модула на Apache: препоръчва се обновяване до 2.4.71", "schlagzeile": "Критична уязвимост в Apache: обновете уеб сървърите с HTTP/2 веднага", "kurz": "Уеб сървърът Apache има критична уязвимост в модула mod_http2, която може да позволи отдалечено изпълнение на код. Засегнати са само сървъри с включен HTTP/2. Версия 2.4.71 отстранява грешката.", "zusammenfassung": "Според heise уязвимостта CVE-2026-119618 се намира във функцията assign_headers() на модула mod_http2. Манипулация на паметта там може да доведе до отдалечено изпълнение на зловреден код. Според Golem Red Hat оценява уязвимостта с 9,8 от 10 точки. Открили са я OSS скенер на Anthropic и двама изследователи от Google Cloud Vulnerability Research. Тъй като mod_http2 не е включен по подразбиране, засегнати са само сървъри, които използват HTTP/2. Експерти като Кевин Бомонт смятат експлойта за труден заради защити като ASLR. Въпреки това администраторите трябва да обновят до Apache 2.4.71, която затваря още две уязвимости. Който не може да обнови веднага, трябва засега да изключи HTTP/2.", "weitere_links": ["Golem.de"], "_src": "8ac52b3f"}, "2026-11-12-rtx5090-96gb-mod": {"titel": "Модифицирана RTX 5090 с 96 GB памет се появи на китайски пазар за употребявани стоки", "schlagzeile": "RTX 5090 с 96 GB: китайски мод за около 900 000 долара", "kurz": "На китайската платформа Xianyu се предлага модифицирана GeForce RTX 5090 с 96 GB видеопамет. Ориентировъчната цена е около 900 000 долара, а реалната се договаря лично. Не е доказано, че картата наистина работи.", "zusammenfassung": "Китайски модъри пренасят настолни GPU на собствени платки и многократно увеличават паметта за AI задачи. Сега според Wccftech и PCGH се е появила обява за RTX 5090 с 96 GB, колкото има RTX Pro 6000. Забелязал я е специалистът по ремонти VIK-on в Xianyu, пазара за употребявани стоки на Alibaba, а първи е съобщил VideoCardz. Чипът GB202 е на собствена платка с чипове памет Samsung от двете страни. Освен картата продавачът предлага схеми на платката и модифициран BIOS, но се насочва само към бизнес клиенти с договор за поверителност. Посочената цена от 6 488 888 юана, около 900 000 долара, е ориентировъчна; реалната цена се договаря лично. Няма бенчмаркове, така че работоспособността на картата не е потвърдена.", "weitere_links": ["Wccftech"], "_src": "4c5d0781"}, "2026-11-12-swtor-directx12-test": {"titel": "Star Wars: The Old Republic започва публичен тест на DirectX 12, графиката първоначално е умишлено опростена", "schlagzeile": "SWTOR получава DirectX 12 – и засега изглежда по-зле", "kurz": "Почти 15 години след излизането си Star Wars: The Old Republic тества клиент с DirectX 12. Публичният тест започва тази седмица директно в обичайния лаунчер. Много графични ефекти в началото липсват умишлено.", "zusammenfassung": "Според PC Games студиото Broadsword модернизира технологията на MMORPG Star Wars: The Old Republic. Тази седмица започва публичен тест на новия DirectX 12 клиент, без регистрация и код за достъп. В обичайния лаунчер малка стрелка позволява избор между старата и новата версия; и двете използват същите сървъри и герои. Много детайли от средата и ефекти все още липсват или са опростени в новия клиент, ограничени са и графичните настройки. Това е умишлено: първо се цели стабилност, производителност и съвместимост с възможно най-много компютри. Играчите трябва да докладват накъсване, графични грешки и сривове заедно с хардуера си. За играчи на Mac тестът засега не е достъпен. Според Broadsword проектът ще продължи до късно през 2027 г., след което графиката постепенно трябва да достигне поне старото ниво.", "_src": "b512307b"}, "2026-11-12-apex-neural-rendering": {"titel": "Apex Neural Rendering: стартъп обещава независима от производителя алтернатива на DLSS, FSR и XeSS", "schlagzeile": "По-добро от DLSS? Apex носи генериране на кадри и за трите GPU лагера", "kurz": "Компанията Apex Compute представи Apex Neural Rendering (ANR) със супер резолюция, реконструкция на лъчи и генериране на кадри за GeForce, Radeon и Arc. Генерирането на кадри вече е достъпно като безплатна бета в GitHub. Обещанията са големи, но според ComputerBase трудно могат да се проверят.", "zusammenfassung": "Apex Compute, досега специализирана в AI ускорители за edge, иска да се конкурира с DLSS, FSR и XeSS чрез Apex Neural Rendering (ANR). ANR трябва да предлага супер резолюция, реконструкция на лъчи и генериране на кадри независимо от производителя на Nvidia, AMD и Intel. Според компанията то е до 2,4 пъти по-бързо и дава по-добро качество на картината от DLSS. Засега е налично само генерирането на кадри като безплатна бета в GitHub; то се вгражда чрез OptiScaler и има режими 2×, 3× и 4×. Според Apex супер резолюцията и реконструкцията на лъчи са още в разработка. Според ComputerBase генерирането на кадри работи от GeForce GTX 16 и RTX 2000 нагоре, от Radeon RX 5000 нагоре включително Steam Deck и на Intel Arc A, под Windows 10, Windows 11 и Linux с Proton. ComputerBase критикува несъответствия в данните на производителя, например уж измервания на FSR с повече от един AI кадър, и неясни фактори в сравнителните видеа. Все още няма независими тестове, така че обещанията за производителност и качество не са потвърдени.", "weitere_links": ["TechPowerUp", "Wccftech", "GamingOnLinux"], "_src": "6efb8d9d"}, "2026-11-12-samsung-hbm-onyang": {"titel": "Недостиг на памет: Samsung строи нова линия за пакетиране на HBM и иска да я завърши година по-рано", "schlagzeile": "RAM кризата: Samsung изтегля новата HBM фабрика с година напред", "kurz": "Samsung започна в Онянг строежа на нова линия за пакетиране на HBM. Тя трябва да заработи през юни 2028 г., година по-рано от планираното. Причината е продължаващият недостиг на памет.", "zusammenfassung": "Според ComputerBase Samsung направи първа копка в кампуса си в Онянг, Асан, на нова производствена линия за пакетиране на HBM памет. Работата трябва да започне през юни 2028 г., година по-рано от първоначалния план. Samsung инвестира в Онянг 46 трилиона вона, около 31 милиарда евро, като по-голямата част е за оборудване. Предвидени са около 31 000 квадратни метра чисти помещения на три етажа и около 700 нови работни места. През октомври Samsung заяви, че вече е договорила доставките на HBM за 2027 г. и далеч не може да покрие търсенето. HBM се използва главно в AI ускорители, но недостигът натоварва целия пазар на памет и така и цените на RAM за потребителите на PC. В краткосрочен план новата линия няма да промени цените.", "_src": "7ecef997"}, "2026-11-12-outlook-mails-blockiert": {"titel": "Outlook.com: дефектно правило за спам отхвърляше истински имейли дни наред – съобщенията са изгубени", "schlagzeile": "Outlook отхвърляше имейли дни наред – и те няма да се върнат", "kurz": "Дефектно правило за спам на Microsoft дни наред отхвърляше легитимни имейли до адреси в Outlook.com, Hotmail и Live. Microsoft отмени ъпдейта и подателите и получателите не трябва да променят нищо. Отхвърлените имейли обаче не могат да бъдат възстановени, затова трябва да помолите подателите да ги изпратят отново.", "zusammenfassung": "Ако пощата ви в Outlook.com напоследък беше подозрително тиха, може да сте засегнати. Според Windows Latest поне от 5 ноември легитимни имейли до адреси в Outlook.com, Hotmail, Live и MSN са били отхвърляни. Подателите получаваха съобщения за грешка, че в имейлите им липсват SPF, DKIM или DMARC записи, макар че това отчасти не беше вярно. Microsoft потвърди пред Windows Latest, че причината е ъпдейт на правилата за спам. Компанията го отмени и според Windows Latest пощата отново работи от 9 ноември. Нито подателите, нито получателите трябва да променят настройки. Проблемът: отхвърлените имейли не са попаднали в папката за спам, а изобщо не са пристигнали. Затова Microsoft не може да ги възстанови. Който е очаквал важни имейли, трябва да помоли подателите да ги изпратят отново. Администраторите намират инцидента в административния център на Microsoft 365 под номер EX1545193. Microsoft не казва колко потребители са засегнати.", "_src": "74d3487f"}, "2026-11-12-powershell-signatur-kb5132061": {"titel": "Ноемврийският ъпдейт KB5132061: по-строга проверка проваля някои подписани PowerShell скриптове", "schlagzeile": "Ъпдейт на Windows спира подписани PowerShell скриптове – ето решението", "kurz": "С ноемврийския ъпдейт за сигурност Windows проверява по-строго кодирането на текста в подписани PowerShell скриптове. Скриптове с дефектен UTF-8 тогава може да се смятат за неподписани и да спрат да работят както досега в управлявани среди. Microsoft препоръчва да се запазят като UTF-8 с BOM и да се подпишат отново.", "zusammenfassung": "С ъпдейта KB5132061 от 10 ноември Microsoft затегна проверката на подписите в PowerShell. Досега Windows все още можеше да обработва скриптове с невалиден UTF-8, като заменяше дефектните знаци. Това вече не става и засегнатите файлове се отхвърлят. Според Microsoft тогава Get-AuthenticodeSignature показва „NotSigned“ за скрипт, който всъщност е подписан. Set-AuthenticodeSignature може да прекъсне с грешка. На устройства с App Control for Business засегнатите скриптове може да работят само в ограничен езиков режим. Засегнати са най-вече скриптове с дефектен UTF-8, UTF-8 без BOM в системи с друга кодова страница и файлове в кодировки като Shift-JIS. Microsoft препоръчва скриптовете да се проверят, да се запазят като валиден UTF-8 с BOM и да се подпишат отново. Примерен скрипт с име Repair-SignedPowerShellUtf8.ps1 открива засегнатите файлове и не презаписва оригинали. Според Neowin промяната важи не само за Windows 11, а и за Windows 10 Enterprise LTSC 2021 и Windows Server 2025. Домашните потребители без подписани скриптове обикновено няма да забележат нищо.", "weitere_links": ["Microsoft Support (KB5132061)", "Microsoft Support (ръководство за кодиране)"], "_src": "22fabd49"}, "2026-11-12-tomb-raider-catalyst-switch2": {"titel": "Amazon посочва Tomb Raider: Catalyst и за Nintendo Switch 2", "schlagzeile": "Tomb Raider: Catalyst вероятно идва и за Switch 2", "kurz": "Публикация на официалния новинарски сайт на Amazon посочва Switch 2 като платформа и за двете предстоящи игри Tomb Raider. За Legacy of Atlantis това беше известно, за Catalyst досега не. Amazon е издател на Catalyst, но потвърждение от Crystal Dynamics или Nintendo все още липсва.", "zusammenfassung": "Според Insider Gaming в публикация на Amazon News, обновена на 9 ноември, пише, че двете нови игри Tomb Raider ще излязат за PS5, Xbox Series X/S, Nintendo Switch 2 и Steam. За Tomb Raider: Legacy of Atlantis (2027) версията за Switch 2 вече беше официална, а играта може да се поръча предварително в eShop. Новото е посочването на Tomb Raider: Catalyst. Играта беше отложена тази година за 2028 г. Catalyst се издава от Amazon Game Studios, което придава тежест на информацията. Insider Gaming все пак допуска грешка в статията, макар че тя е онлайн без промени от два дни. Crystal Dynamics и Nintendo все още не са потвърдили версията за Switch 2. Няма технически подробности, нито дата за версията за Switch 2.", "_src": "de9ab1dc"}, "2026-11-12-steam-erfolge-linux-64bit": {"titel": "Ъпдейт на клиента Steam: Achievement Sets за всички, а Linux клиентът най-сетне работи като 64-битова програма", "schlagzeile": "Ъпдейт на Steam: нови комплекти постижения и 64 бита за Linux", "kurz": "Valve пусна нов ъпдейт на Steam за всички потребители. Игрите вече могат да групират постиженията в комплекти за основната игра и DLC, без да се губи 100-процентовото завършване. В Linux клиентът Steam вече е 64-битова програма и работи в контейнер Steam Runtime.", "zusammenfassung": "На 11 ноември Valve пусна ъпдейт на клиента Steam в стабилния канал. Най-важната новост за всички са Steam Achievement Sets. С тях разработчиците могат да групират постиженията по основна игра и DLC. Така нови постижения или постижения от DLC вече не правят непълна една вече завършена колекция. Сезонни или вече непостижими постижения могат да се архивират. Добавена е и преработена страница с постижения. В Linux клиентът Steam вече е 64-битово приложение и работи в контейнер Steam Runtime. Според Valve това трябва да осигури еднакво поведение в различните дистрибуции; това е същата технология, която използват и игрите. Според TechPowerUp досега Steam в Linux все още беше 32-битова програма. Ъпдейтът поправя и, наред с други неща, срив при събуждане от режим на заспиване. Дали разработчиците ще използват новите комплекти постижения, зависи от тях.", "weitere_links": ["Steam (обявление за Achievement Sets)", "9to5Linux"], "_src": "95507831"}, "2026-11-12-witcher3-ki-stimme-geralt": {"titel": "The Witcher 3: CD Projekt коригира с ИИ полския глас на Гералт в новото разширение – със съгласието на актьора", "schlagzeile": "След инсулт: ИИ връща младежкото звучене на полския глас на Гералт", "kurz": "В предстоящото разширение на The Witcher 3, Songs of the Past, полският глас на Гералт се обработва с ИИ. Актьорът Яцек Розенек записва всички реплики сам, но гласът му се промени забележимо след инсулт през 2019 г. С негово съгласие ИИ компанията Respeecher го доближава до някогашното му звучене.", "zusammenfassung": "CD Projekt Red потвърди, че използва ИИ в полската версия на новото разширение на The Witcher 3, Songs of the Past. Първо за това съобщи Game File, а PC Gamer, VGC и IGN подеха темата. Яцек Розенек винаги е озвучавал Гералт на полски, но през 2019 г. претърпя инсулт и временно не можеше да говори. След дълги тренировки той се върна, но днес гласът му звучи по-ниско и по-грубо. Тъй като разширението се развива в средата на историята на The Witcher 3, разликата можеше да се усети. Затова Розенек продължава сам да записва всички реплики, а Respeecher след това ги доближава до звученето му отпреди около дванайсет години. Моделът е обучен с по-ранните му записи за играта. Розенек изрично подкрепя това и казва, че гласът трябва да е възможно най-близо до някогашния. Продуцентът по локализация Миколай Швед говори за специален случай заради заболяването и вижда в това етична употреба със съгласие. Според CD Projekt нищо подобно не се планира за английския глас на Дъг Кокъл. CD Projekt вече работи с Respeecher по Cyberpunk 2077: Phantom Liberty, тогава със съгласието на семейството на починал актьор. В публикациите няма дата за Songs of the Past.", "weitere_links": ["VGC", "IGN"], "_src": "b5c1fa87"}, "2026-11-12-helldivers2-kosmetik-mods": {"titel": "Helldivers 2: след смяната на анти-чийт системата и вълната от ревюта козметичните модове трябва да се върнат със следващия хотфикс", "schlagzeile": "Helldivers 2: Arrowhead иска отново да разреши безобидните модове", "kurz": "След преминаването към Easy Anti-Cheat много модове в Helldivers 2 вече не работят, а в Steam последваха над 10 000 негативни ревюта. Arrowhead обявява, че някои чисто козметични модове трябва отново да работят със следващия хотфикс. Модовете, които променят геймплея, остават забранени.", "zusammenfassung": "Arrowhead смени в Helldivers 2 анти-чийт системата от GameGuard на Easy Anti-Cheat. Според студиото целта е била да се спрат модове, които дават нечестно предимство или вредят на други. При това обаче спряха да работят и безобидни козметични модове. Реакцията беше остра: според PC Gamer в Steam се появиха над 10 000 нови негативни ревюта, а последните оценки са „предимно негативни“. В новия си блог за разработката Arrowhead признава, че PC играчите са загубили фенски модове. След корекции някои козметични модове трябва отново да работят със следващия хотфикс. Модовете, които променят геймплея, остават забранени, защото технически не могат да се различат от чийтове. Модовете все така нямат официална поддръжка. Arrowhead се извинява и за неточна пътна карта и пропуснати дати за пачове. За началото на декември са планирани, наред с други неща, реактивни раници, които могат да се ползват при носене на двуръчни предмети. Студиото не посочва дата за хотфикса.", "_src": "0f2f4919"}, "2026-11-12-marvel-1943-fast-fertig": {"titel": "Доклад: Marvel 1943: Rise of Hydra е почти готова, но значително по-малка от планираното", "schlagzeile": "Изтичане: Почти готова ли е Marvel 1943 – но силно орязана?", "kurz": "След слухове за спиране Kotaku съобщава, че Marvel 1943: Rise of Hydra е почти завършена. Играта обаче ще предлага значително по-малко съдържание и геймплей дълбочина от планираното. Skydance не е коментирала официално.", "zusammenfassung": "Около Marvel 1943: Rise of Hydra, играта на Ейми Хениг с Капитан Америка и Черната пантера, напоследък имаше слухове за предстоящо спиране. Според Kotaku и репортера на Bloomberg Джейсън Шрайър ръководството на Skydance е съобщило на служителите в Slack, че това не е вярно. Kotaku съобщава също, че играта е „close to done“, тоест почти готова. Разработката обаче е била трудна и значително е надхвърлила бюджета. Затова обхватът и продължителността са били силно съкратени. Според източниците на Kotaku играта е „light on gameplay“, като голяма част се управлява с един бутон. Marvel 1943 е започнала като игра за Netflix. Обявена е през 2024 г. и оттогава е отлагана няколко пъти. Няма дата за излизане. Всички сведения идват от анонимни източници и Skydance не ги е потвърдила.", "ursprungsquelle": "Kotaku (чрез IGN)", "_src": "3cff0819"}, "2026-11-12-nvidia-board-huang-abloesung": {"titel": "Според медии бордът на Nvidia обмисля отстраняването на CEO Дженсън Хуанг и вече търси наследник", "schlagzeile": "Смяна на върха на Nvidia? Бордът обсъжда отстраняване на Хуанг", "kurz": "Според Wall Street Journal бордът на директорите на Nvidia подготвя отстраняването на основателя и CEO Дженсън Хуанг. Поводът е статия на New York Times за втора извънбрачна връзка, този път с мениджърка, пряко подчинена на него. Според Bloomberg външна фирма вече търси наследници. До обяд Nvidia все още не е обявила решение; съобщенията се базират на анонимни източници.", "zusammenfassung": "Кризата около шефа на Nvidia Дженсън Хуанг се задълбочава. Според Wall Street Journal бордът е искал да заседава в сряда вечерта (американско време) за бъдещето на Хуанг, като отстраняване е било на масата. Поводът е нова статия на New York Times: освен вече признатата афера Хуанг е имал връзка и с вицепрезидентка, която докладва пряко на него. Вестникът се позовава на петима бивши служители и заявява, че сам не е виждал предполагаемо видео от инцидент през март. Нито Nvidia, нито засегнатите са потвърдили информацията. Според Bloomberg бордът вече работи с външна фирма за търсене на наследник, обмисля се и временен CEO. На заден план е разследването, започнало в неделя, за аферата на Хуанг с мениджърка на клиента на Nvidia Megaspeed, която американските власти са определили като предполагаем китайски агент; Китай отрича. Хуанг ръководи Nvidia от основаването ѝ през 1993 г., а според PCGH няма посочен наследник. Според PCGH за отстраняването му е достатъчно обикновено мнозинство на директорите. След публикациите акциите поевтиняха с около осем процента в извънборсовата търговия и паднаха до 52-седмично дъно. Nvidia представя тримесечните си резултати на 17 ноември, а на 18 ноември е планиран поверителен брифинг в Конгреса на САЩ. Засега не са известни конкретни последици за картите GeForce, цените или драйверите. Важно: всичко се основава на медийни публикации с анонимни източници от Wall Street Journal, New York Times и Bloomberg; до обяд Nvidia не е обявила решение и ситуацията може да се променя.", "weitere_links": ["PC Games Hardware", "heise online", "Golem.de", "IGN", "PC Gamer"], "_src": "f0402e6d"}, "2026-11-12-golden-joystick-2026": {"titel": "Golden Joystick Awards 2026: Resident Evil Requiem е игра на годината, Crimson Desert печели на PC", "schlagzeile": "Golden Joysticks: Resident Evil Requiem взе „Игра на годината“", "kurz": "На 44-тите Golden Joystick Awards Resident Evil Requiem спечели голямата награда Ultimate Game of the Year. Най-добра игра за PC стана Crimson Desert. Мултиплейър хитът Meccha Chameleon грабна четири награди, а The Witcher 4 е най-очакваната игра.", "zusammenfassung": "Golden Joystick Awards се смятат за най-старото зрителско гласуване в гейминг индустрията и през 2026 г. се проведоха за 44-ти път. Голямата награда Ultimate Game of the Year спечели Resident Evil Requiem на Capcom. Хорър играта спечели и като най-добра конзолна игра, за най-добър трейлър и за най-добра главна роля – Анджела Сант'Албано като Грейс Ашкрофт. Според TheGameVerse Capcom беше избрано и за студио на годината. Най-добра игра за PC стана Crimson Desert, макар че излиза и на конзоли. Играта на криеница Meccha Chameleon спечели четири награди: най-добра мултиплейър игра, най-добра самоиздадена инди игра, Streamer's Choice и Developers' Choice. The Witcher 3: Wild Hunt Remastered стана най-добър ремастър, а The Witcher 4 – най-очаквана игра. Феновете избраха Steam Controller за най-добър гейминг хардуер. Други награди получиха Onimusha: Way of the Sword (звук), Control: Resonant (визуален дизайн), Doom: The Dark Ages – Revelations (разширение) и Subnautica 2 (ранен достъп). Наградите се организират от издателя на PC Gamer.", "weitere_links": ["TheGameVerse в X (списък с победители)"], "_src": "d4e2e75f"}, "2026-11-12-gta6-clip-realistisch": {"titel": "GTA 6: Rockstar споделя клип от играта, който мнозина смятат за истинско видео от телефон в Маями", "schlagzeile": "Реалност или GTA 6? Нов клип на Rockstar заблуди интернет", "kurz": "Около 15-секунден клип от GTA 6 от първо лице предизвиква спорове, защото мнозина го смятат за истинско видео. Той пресъздава реално видео от телефон с колите от GTA по време на маркетинговата акция в Маями. Rockstar сподели клипа в своята история в Instagram, което според IGN говори за истински кадри от играта.", "zusammenfassung": "Седмица преди премиерата на GTA 6 кратък клип предизвиква удивление. Той се появи първо в профила в Instagram „Only in Dade“, който събира странни сцени от Маями-Дейд. В него се вижда шофиране по Ocean Drive покрай редица впечатляващи коли, както и втора гледна точка от тротоара. Според IGN, Polygon и Insider Gaming клипът пресъздава истинско видео, заснето през октомври по време на маркетинговата акция на Rockstar с пресъздадени коли от GTA в Маями. Много зрители първоначално го взеха за реални кадри или за ИИ. Rockstar сподели клипа в историята си в Instagram и го хареса, което IGN смята за силен знак за истински кадри от играта. Според Polygon обаче Rockstar не го е потвърдила изрично. Феновете предполагат, че така може да изглеждат записите с камерата на телефона в играта. Insider Gaming подчертава, че клипът не казва нищо за евентуален режим от първо лице. GTA 6 излиза на 19 ноември за PS5 и Xbox Series X/S и според Rockstar работи с 30 fps на конзолите. Предварителното изтегляне вече тече.", "weitere_links": ["Insider Gaming", "Polygon", "GamePro (преглед на новините)"], "_src": "34198252"}, "2026-11-12-black-forest-games-unabhaengig": {"titel": "Black Forest Games се откупува от Embracer и основава групата студиа Third Signal", "schlagzeile": "Германското студио на Destroy All Humans се откупи от Embracer", "kurz": "Германското студио Black Forest Games се отдели от THQ Nordic и Embracer чрез обратно изкупуване от ръководството. Едновременно с това основава Third Signal – група от независими студиа. Екипът ще продължи да работи с THQ Nordic.", "zusammenfassung": "След девет години под шапката на THQ Nordic и Embracer Black Forest Games отново е независимо. Според Eurogamer и PC Gamer това стана чрез обратно изкупуване от ръководството. Студиото е разработило, наред с други, Giana Sisters: Twisted Dreams и римейковете на първите две игри Destroy All Humans. То е основано от бивши служители на Spellbound Entertainment, известна с Desperados и Arcania: Gothic 4. Заедно с независимостта стартира Third Signal – група от независими студиа, която в бъдеще трябва да помага и на други инди екипи. Шефът на Third Signal Андреас Тоблер казва по същество, че много от най-добрите игри на последното десетилетие са създадени от екипи от 50, а не от 500 души. Според прессъобщението THQ Nordic и Black Forest Games ще продължат да си сътрудничат в разработката. Студиото явно не е поело правата върху Destroy All Humans. Управителят Адриан Гьорш обявява нов проект, без подробности. През 2024 г. студиото беше засегнато от съкращенията в Embracer и загуби тогава около 50 работни места.", "weitere_links": ["PC Gamer"], "_src": "7dfb6efd"}, "2026-11-12-nintendo-dmca-github": {"titel": "Nintendo премахва чрез DMCA 144 хранилища в GitHub с фърмуер за модчипове за Switch и два емулатора", "schlagzeile": "Nintendo чисти GitHub: емулатори за Switch и фърмуер за модчипове изчезват", "kurz": "Nintendo изпрати четири DMCA искания до GitHub срещу емулаторите за Switch Yuzu и Citron Neo, както и срещу фърмуер за модчипове. GitHub премахна 144 хранилища с този фърмуер. Според TorrentFreak обаче той все още може да се намери на други места в платформата.", "zusammenfassung": "Nintendo отново действа срещу инструменти за заобикаляне на защитата срещу копиране на Switch. Според IGN GitHub е получил четири DMCA искания, които е публикувал. На прицел са емулаторите Yuzu и Citron Neo, но най-вече фърмуерът за модчипове като Picofly. Такива чипове се запояват към дънната платка на Switch и заобикалят защитата срещу копиране. GitHub премахна 144 хранилища с фърмуера и ги замени с известие за DMCA. В искането си от 6 ноември Nintendo твърди, че техническите мерки за защита трябва да предотвратяват играенето на пиратски копия и на неоторизирани устройства. Според TorrentFreak обаче фърмуерът все още е наличен на други места в GitHub. Още през 2024 г. Nintendo премахна около 8500 копия на Yuzu. IGN свързва новата вълна с информации, че емулатори малко преди това са пуснали на PC новия римейк на Ocarina of Time; пряка връзка не е доказана. Дали Nintendo планира още стъпки, е неясно.", "_src": "788c053c"}, "2026-11-12-id-veteranen-hidden-horses": {"titel": "Около 20 бивши разработчици от id Software основават студиото Hidden Horses и планират арена шутър", "schlagzeile": "След съкращенията в Xbox: бивши от id основават собствено шутър студио", "kurz": "Около 20 бивши разработчици от id Software основаха Hidden Horses – студио, собственост на самите служители. Първият им проект е самостоятелният арена шутър Danger Pay. Той ще бъде финансиран, наред с другото, чрез Kickstarter.", "zusammenfassung": "При съкращенията в Xbox през юли 2026 г. id Software е загубила според информациите 136 разработчици. Около 20 от тях сега основаха Hidden Horses – студио, собственост на служителите. Според PC Gamer основателите имат общо над 250 години опит. Студиото ще се управлява демократично и ще поставя дългосрочната стабилност пред бързия растеж и съмнителната монетизация. Съоснователят Дъстин Ланд казва, че искат да запазят екипа заедно и да правят класически шутъри. Първата игра се казва Danger Pay – самостоятелен арена шутър за брутално телевизионно шоу. Като вдъхновение студиото посочва филма The Running Man от 1987 г. и аркадната игра Smash TV. За финансирането е планирана кампания в Kickstarter. Платформи, дата и старт на Kickstarter все още не са известни.", "_src": "2eb4f3a4"}, "2026-11-12-tes6-sentinel-pause": {"titel": "Bethesda: няма новини за The Elder Scrolls 6: Sentinel за годишнината на Skyrim – и няма да има „известно време“", "schlagzeile": "15 години Skyrim, но без Elder Scrolls 6: Bethesda охлажда феновете", "kurz": "За 15-ия рожден ден на Skyrim феновете се надяваха на новини за The Elder Scrolls 6: Sentinel. Bethesda Game Studios уточни в Reddit, че няма да има голямо обявяване. Нищо ново за Sentinel няма да има „известно време“.", "zusammenfassung": "The Elder Scrolls V: Skyrim навърши 15 години на 11 ноември. В subreddit-а на The Elder Scrolls 6 феновете гадаеха за изненада за годишнината, подхранена от тийзър на подкаст за „голямо обявяване“. Водещият по-късно уточни, че то няма нищо общо с Bethesda. След това се обади и официалният профил на Bethesda Game Studios в Reddit. Няма да има голямо обявяване и нищо ново за Sentinel няма да бъде показано „известно време“, написа студиото. Bethesda официално обяви заглавието Sentinel едва в началото на ноември. The Elder Scrolls 6 беше анонсирана още през 2018 г. За годишнината Skyrim е с намаление на всички платформи. The Elder Scrolls Online прави главата Greymoor безплатна част от основната игра, а там тече събитие за Skyrim до 2 декември. Кога ще има нова информация за Sentinel, не е ясно.", "weitere_links": ["PC Gamer"], "_src": "85003521"}, "2026-11-11-xbox-cloud-ohne-game-pass": {"titel": "Xbox Cloud Gaming без Game Pass: купете игрово време или играйте безплатно с реклами", "schlagzeile": "Xbox Cloud Gaming се отваря: купете часове или играйте безплатно с реклами", "kurz": "От 11 ноември играчите в поддържаните държави могат да купуват игрово време в облака на Xbox и без абонамент за Game Pass. Xbox рекламира и безплатен стрийминг с реклами, с ограничение на времето за сесия. Могат да се стриймват само собствени игри или избрани free-to-play заглавия.", "zusammenfassung": "Microsoft преустройва Xbox Cloud Gaming. Според Xbox Wire от 11 ноември играчите на поддържаните пазари могат да купуват игрово време в облака в Xbox Store, без да се абонират за Game Pass. По време на теста за Insider пакетите без реклами струваха 3,99 долара за 10, 7,99 долара за 25 и 11,99 долара за 50 часа; това бяха изрично встъпителни цени, а цени в евро източниците не посочват. Купените часове не изтичат и според Xbox предлагат по-кратко чакане и по-добро качество на стрийма. На официалната страница за облачни игри и в X Xbox рекламира и безплатен стрийминг с реклами, където е наличен, с ограничения на времето за сесия. В теста за Insider ограничението беше един час според The Verge. Могат да се стриймват собствени игри, избрани free-to-play заглавия и игри от Game Pass. От ноември абонатите на Game Pass имат месечни лимити: 15 часа при Ultimate, 10 при Premium и 5 при Essential. След като ги изразходват, могат да докупят часове или да преминат към варианта с реклами. Точно навреме GTA 6 излиза на 19 ноември чрез облака и за Xbox One. Кои държави ще бъдат включени от старта, не е ясно.", "weitere_links": ["Xbox Wire (GTA VI в облака, игрово време от 11.11)", "Xbox Cloud Gaming (официална страница)", "Xbox Wire (цени в теста Insider)", "Xbox Wire (месечни лимити)", "The Verge"], "_src": "cfedef5c"}, "2026-11-11-dark-souls-server-zurueck": {"titel": "Dark Souls 2 и 3: онлайн функциите отново работят след почти две седмици прекъсване", "schlagzeile": "Dark Souls 2 и 3 отново са онлайн – причината остава тайна", "kurz": "След почти две седмици пауза онлайн функциите на Dark Souls 2 и 3 отново работят на всички платформи. Според PC Gamer нахлуванията и съобщенията отново функционират. FromSoftware не разкри какъв точно е бил проблемът със сървърите.", "zusammenfassung": "Сървърите на Dark Souls 2 и Dark Souls 3 отново работят. Почти две седмици по-рано мултиплейър функциите на двете игри бяха изключени на всички платформи заради необяснен проблем със сървъра. На официалния сайт на Dark Souls сега кратко пише, че проверката е приключила, корекция е приложена и онлайн функциите са възстановени. Според PC Gamer нахлуванията и съобщенията отново работят както обикновено. FromSoftware все още не посочва причината. За сравнение: през 2022 г. PC сървърите на всички игри Dark Souls бяха офлайн почти година, тогава заради уязвимост, позволяваща изпълнение на зловреден код. Дали и този път зад това стои проблем със сигурността, не е известно. По време на паузата помагаха фенски модове като Seamless Co-op, които работят независимо от официалните сървъри. Който иска да играе класическите нахлувания, вече може отново.", "_src": "76889d66"}, "2026-11-11-kb5132061-installationsfehler": {"titel": "Windows 11: Microsoft потвърди грешки при инсталиране на KB5132061 и разпространява автоматичен ремонт", "schlagzeile": "Microsoft потвърди грешката KB5132061 – поправката идва сама", "kurz": "Microsoft вече официално потвърди проблемите с инсталацията на ноемврийската актуализация за сигурност KB5132061. На засегнатите компютри с Windows 11 инсталацията се прекъсва или се опитва многократно; типичните кодове за грешка са 0x800f0993, 0x800f0989 и 0x80070306. Според Microsoft ремонтът се изпълнява автоматично чрез Windows Update и трябва да достигне засегнатите устройства в рамките на 24 до 48 часа след старта в сряда в 19:00 виенско време; след това актуализацията за сигурност се инсталира сама. Потребителите не трябва да правят нищо, освен да останат онлайн и да получават актуализациите през Настройки.", "zusammenfassung": "Ноемврийската актуализация за сигурност KB5132061 не може да се инсталира на част от компютрите с Windows 11, инсталацията понякога спира едва при 99 процента, а повторните опити често не помагат. Съобщават се кодовете за грешка 0x800f0993, 0x800f0989 и 0x80070306, понякога и 0x800f0922. Microsoft документира проблема в сряда като известен проблем в английските бележки към изданието на KB5132061. Според компанията ремонтът се изпълнява автоматично на засегнатите устройства, които са свързани с интернет и използват Windows Update в Настройки; не са нужни ръчни стъпки, за да го получите. Всички засегнати устройства трябва да получат поправката в рамките на 24 до 48 часа след старта в сряда в 19:00 виенско време (10:00 тихоокеанско време) и след това сами да изтеглят и инсталират актуализацията за сигурност. Служебно съобщение на Microsoft, цитирано от BleepingComputer, уточнява, че е засегната само част от устройствата с незадължителната октомврийска предварителна актуализация KB5127936; устройствата без нея не са засегнати. Microsoft не посочва точната причина. По-рано Windows Latest и порталът DrWindows съобщиха за грешките, но много системи никога не бяха засегнати. По-ранните съвети да се изключи Windows Sandbox или да се пуснат DISM и sfc остават на заден план, защото компанията вече съветва да се изчака автоматичният ремонт. Който след изтичането на 48-те часа все още не може да инсталира актуализацията, според Microsoft трябва да използва помощта на Windows или да се свърже с поддръжката. Това си остава актуализация за сигурност, затова не бива да се спира трайно.", "weitere_links": ["Dr. Windows", "BleepingComputer", "Neowin", "Windows Latest"], "_src": "7755549c"}, "2026-11-11-harada-xbox-series-s": {"titel": "Бившият шеф на Tekken Кацухиро Харада: конзоли като Xbox Series S не би трябвало да излизат", "schlagzeile": "Легендата на Tekken Харада за Series S: „допълнителна работа за по-слабо дете“", "kurz": "Кацухиро Харада разкритикува Xbox Series S на конференция за разработчици в Южна Корея, докато в залата имаше представител на Xbox. Основният проблем според него е, че конзолата много прилича на Series X, но е осезаемо по-слаба. Разработчик от CD Projekt възрази, че оптимизацията помага на всички платформи.", "zusammenfassung": "Кацухиро Харада, дълги години ръководител на поредицата Tekken, а днес шеф на новото VS Studio, говори открито за Xbox Series S на Console Game Developers Conference 2026 в Южна Корея. Според Inven Global, цитиран от Eurogamer, той заяви пред присъстващ висш представител на Xbox, че би искал хардуер като Series S да не излиза. Най-големият проблем не е само ограничената памет, а това, че конзолата много прилича на Series X и въпреки това е неудобно по-слаба. След най-добрата версия усещането е като да вършиш допълнителна работа за малко по-слабо дете. При Switch 2 пък може да се мисли за отделно устройство за феновете на Nintendo. Тъй като например в САЩ има повече потребители на Series S, отколкото на Series X, не може да се пести, а оплакванията за по-лоши текстури после стигат до разработчиците. Павел Саско от CD Projekt Red възрази, че оптимизацията за по-слаб хардуер кара игрите да вървят значително по-добре на всички платформи, а ниската цена разширява пазара. Техническият директор на Shift Up ДонгКи Ли каза, че очаква с нетърпение следващия Xbox с кодово име Helix. Става дума за мнение, изразено на панел, а не за официална позиция на Microsoft или на някое студио.", "weitere_links": ["Video Games Chronicle", "PC Gamer"], "_src": "8dad0743"}, "2026-11-11-rtx5080-24gb-gestrichen": {"titel": "Съобщения: Nvidia е отменила RTX 5080 с 24 GB – моделът с 16 GB остава", "schlagzeile": "Изтичане: Nvidia е отменила RTX 5080 с 24 GB", "kurz": "Според китайския браншов канал Board Channels Nvidia е уведомила партньорите си, че планираната за януари 2027 г. RTX 5080 с 24 GB се отменя. Причината били скъпите чипове GDDR7 по 3 GB. RTX 5080 с 16 GB продължавала да се произвежда. Nvidia не е потвърдила нищо от това.", "zusammenfassung": "Според нови съобщения засега няма да има RTX 5080 с 24 GB видеопамет. TechPowerUp цитира китайския браншов канал Board Channels, според който Nvidia официално е уведомила производителите на карти, че планираното за януари 2027 г. пускане отпада. Като причина се посочват разходите: според публикацията, цитирана от PC Gamer, чиповете GDDR7 по 3 GB струват около три пъти повече от използваните досега чипове по 2 GB. С по-скъпата памет картата би трябвало да излезе на цена, която трудно би се продавала. Затова познатата RTX 5080 с 16 GB продължавала да се произвежда. Според по-ранни слухове моделът с 24 GB щял да има същия брой изчислителни блокове, но повече памет, по-голяма пропускателна способност и малко по-високи честоти. PC Gamer припомня, че преди дори се говореше, че версията с 24 GB може да замени RTX 5090 и варианта с 16 GB; мениджърът на Nvidia Джеф Фишър обаче подчерта, че производството на RTX 5090 не е спряно. Според TechPowerUp не се очертава Super обновление, а следващата голяма стъпка би била серията RTX 60. Важно: самият модел с 24 GB никога не е обявяван официално, така че става дума за слух за края на един слух. Nvidia не е коментирала.", "ursprungsquelle": "Board Channels (via VideoCardz, Gazlog, harukaze5719)", "weitere_links": ["PC Gamer", "PC Games Hardware", "Wccftech"], "_src": "2c9fc45e"}, "2026-11-11-gta6-de-cix-rekord": {"titel": "Предварително изтегляне на GTA 6: интернет възелът DE-CIX отчита нов рекорд", "schlagzeile": "Изтеглянето на GTA 6 счупи рекорд: 22,3 терабита в секунда във Франкфурт", "kurz": "През първата вечер на предварителното изтегляне на GTA 6 интернет възелът DE-CIX във Франкфурт измери нов пик от 22,30 терабита в секунда. Операторът отчита и световен рекорд. GTA 6 ще може да се играе от полунощ на 19 ноември.", "zusammenfassung": "Стартът на предварителното изтегляне на Grand Theft Auto VI остави измерими следи в мрежата. Както операторът на DE-CIX съобщи на Golem, възелът във Франкфурт достигна на 10 ноември в 20:20 ч. нов пик от 22,30 терабита в секунда. Това е с 19,06 процента повече от предишния рекорд от януари 2026 г. Общо за всички локации на DE-CIX по света бяха измерени 33,01 терабита в секунда, също рекорд. Техническият директор на DE-CIX Томас Кинг обясни, че големите премиери на игри са сред събитията, които могат много бързо силно да вдигнат трафика. По обем на данните DE-CIX Франкфурт се смята за най-големия интернет възел в Европа. Предварителното изтегляне за PS5 и Xbox Series X|S започна в нощта срещу 10 ноември, а файлът е около 210 до 212 GB. Според PC Games и германски интернет доставчик е отчел многократно по-голям от обичайния игрови трафик. GTA 6 ще може да се играе от полунощ на 19 ноември. Дали самият ден на премиерата ще донесе нови рекорди, предстои да видим.", "weitere_links": ["PC Games"], "_src": "b0fe5f64"}, "2026-11-11-mh-wilds-ascendance-beta": {"titel": "Промени в Steam подсказват бета за разширението Ascendance на Monster Hunter Wilds", "schlagzeile": "Изтичане: Ще получи ли Monster Hunter Wilds: Ascendance скоро бета?", "kurz": "Capcom тихо преименува в Steam старото бета приложение на Monster Hunter Wilds на „Ascendance Beta test“, както показва SteamDB. Това подсказва предстоящ тест на разширението. Capcom все още не е обявила нищо, дата не е известна.", "zusammenfassung": "Първото голямо разширение за Monster Hunter Wilds се казва Ascendance и трябва да излезе през 2027 г. Според Eurogamer и PC Gamer Capcom вече е преименувала в Steam старото бета приложение на основната игра. Според дневника на промените в SteamDB то вече се казва Monster Hunter Wilds: Ascendance Beta test и е получило ново основно изображение. Това подсказва предстоящ бета тест. Тъй като приложението има същото ID като по-ранната бета на Wilds, то може да се появи отново в библиотеките на бившите тестери; тогава отделна регистрация може да не е нужна. Кога би могла да започне бета, е напълно неясно; Eurogamer предпазливо залага на началото на 2027 г. Capcom последно показа Ascendance на септемврийския State of Play и на Tokyo Game Show, включително завръщащия се Древен дракон Teostra. Разширението трябва да е по-трудно, след като много играчи намериха основната игра за твърде лесна при излизането ѝ. Става дума за индикации от данни в Steam, а не за официално обявяване.", "ursprungsquelle": "SteamDB-Änderungsprotokoll (via PC Gamer)", "weitere_links": ["PC Gamer"], "_src": "2faf2355"}, "2026-11-11-radeon-ssd-fix-tool": {"titel": "Неофициален инструмент с отворен код спира постоянния запис на atieclxx.exe върху SSD", "schlagzeile": "Драйверът на Radeon износва SSD: безплатен инструмент спира записа", "kurz": "Разработчик от общността публикува в GitHub безплатен инструмент срещу бъга на Radeon, при който atieclxx.exe се копира върху SSD всяка секунда. Той проверява дали компютърът е засегнат, оценява износването и блокира записа, без да изключва услугата. Това е неофициално решение, не от AMD.", "zusammenfassung": "На някои компютри с драйвер Radeon или драйвер за чипсет на AMD файлът atieclxx.exe, който принадлежи към услугата AMD External Events Utility, се копира сам всяка секунда. Това създава постоянно натоварване със запис на системния диск и дори без използване бързо се натрупват стотици гигабайти, което ненужно състарява SSD. Член на общността с името Necandi публикува в GitHub инструмента Radeon-atieclxx-SSD-Fix, съобщават ComputerBase и Wccftech. Първо той проверява дали системата е засегната и оценява досегашното износване на SSD. Оценката е груба: приема, че бъгът съществува от поставянето на картата на AMD, а ако SSD не отчита време на работа, смята с осем часа работа на ден. Вместо да изключва услугата, инструментът само забранява на системния акаунт да презаписва копието. Така опитът за копиране се проваля, а FreeSync, frame pacing и бързите клавиши би трябвало да продължат да работят. Предишни решения като спиране на услугата или изключване на Resizable BAR можеха да създават проблеми точно там. Който не иска инструмент, според ComputerBase може сам да отнеме правата с команда icacls и по-късно да ги възстанови. Разработчикът подчертава, че няма връзка с AMD и че използването е на собствена отговорност. AMD обяви официална корекция с драйвер 26.11.1, която още не е излязла.", "weitere_links": ["Wccftech"], "_src": "3c8c1851"}, "2026-11-11-zen6-epyc-tests": {"titel": "AMD Epyc 9006 Venice в продажба: първите тестове показват голям скок за Zen 6", "schlagzeile": "Първи тестове на Zen 6: 256-ядреният чип на AMD е с 58% по-бърз", "kurz": "AMD вече официално продава сървърните процесори Epyc 9006 Venice със Zen 6. В първите независими тестове на Phoronix топ моделът Epyc 9996 е средно 1,58 пъти по-бърз от досегашния флагман Zen 5c. За геймърите това е първи поглед към архитектурата на бъдещите чипове Ryzen.", "zusammenfassung": "AMD обяви старта на продажбите на шестото поколение Epyc с кодово име Venice, представено още през юли. Началото е с девет модела за сокет SP7, а според Golem в началото на 2027 г. следват още 22 за SP8. Phoronix успя да тества двата топ модела. Epyc 9996 има 256 ядра Zen 6c, до 4,1 GHz и TDP 600 вата и според ценовата листа на AMD струва 14 904 долара. В двусокетна система той средно по всички тестове постига 1,58 пъти производителността на предшественика Epyc 9965 със 192 ядра. При HPC приложения е около два пъти по-бърз от Intel Xeon 6980P и въпреки по-високата консумация дава най-добрата производителност на ват. Според Golem компактните ядра печелят от по-големи чиплети с 32 вместо 12 ядра. Вторият тестван чип, Epyc 9686F, има 96 ядра Zen 6 с до 5,3 GHz. За геймърите това са сървърни чипове, но те за първи път независимо показват какво може архитектурата Zen 6, която по-късно се очаква и в процесорите Ryzen. Колко от това ще стигне до игрите, не може да се изведе от сървърни тестове. Phoronix посочва и че пълната производителност изисква бърза памет MRDIMM, която при сегашната криза с RAM вероятно ще е много скъпа.", "weitere_links": ["Phoronix (тест на Epyc 9996)", "PC Games Hardware", "AMD в X"], "_src": "f935df7f"}, "2026-11-11-zelda-oot-5-2-mio": {"titel": "Римейкът на Zelda: Ocarina of Time продаде над 5,2 милиона копия за четири дни", "schlagzeile": "Римейкът на Zelda счупи рекорд на Switch 2: 5,2 милиона за четири дни", "kurz": "Nintendo съобщава за над 5,2 милиона продадени копия на римейка на Ocarina of Time през първите четири дни. Това е най-бързият старт на продажбите на игра на Nintendo за Switch 2. Според Nintendo става дума за реални продажби, а не само за доставки към търговците.", "zusammenfassung": "Римейкът на The Legend of Zelda: Ocarina of Time е голям успех за Nintendo. Според прессъобщение на компанията през първите четири дни след излизането на 5 ноември по света са продадени над 5,2 милиона копия. Така това е най-успешният старт на продажбите на издадена от Nintendo игра за Switch 2, според Golem както в света, така и в Европа. Според Golem Nintendo говори за реално продадени бройки, а не само за доставки към търговците. Няма разбивка по региони или между дигитални и физически копия. Рекордът се отнася изрично до собствените игри на Nintendo, подчертава Eurogamer. Римейкът е приет много добре и от критиката: Golem посочва среден резултат 96 точки в Metacritic. Нови са например графиката, саундтракът, озвучаването и преработените битки. Успехът е забележителен и защото играта излезе само две седмици преди GTA 6. Римейкът е част от честванията за 40-годишнината на поредицата Zelda.", "weitere_links": ["Golem.de", "IGN Deutschland"], "_src": "6dbb5df2"}, "2026-11-11-ps5-100-millionen": {"titel": "Sony потвърди: PlayStation 5 е продадена в над 100 милиона бройки", "schlagzeile": "PS5 надхвърли 100 милиона – точно зад първия PlayStation", "kurz": "Sony потвърди, че към 10 ноември към търговците са доставени над 100 милиона PS5. Така конзолата изпреварва PS3 и PSP и е точно зад първия PlayStation със 102,4 милиона. Напоследък обаче продажбите са осезаемо по-бавни от година по-рано.", "zusammenfassung": "PlayStation 5 достигна кръгла граница: според официалния преглед на продажбите на Sony до 10 ноември 2026 г. са доставени над 100 милиона конзоли. Броят включва доставки към търговците (sell-in), а не продажби на крайни клиенти. Така PS5 изпревари PS3 (87,4 милиона) и PSP (76,4 милиона). Първият PlayStation е все още малко напред със 102,4 милиона, а PS4 със 117 милиона и PS2 с над 160 милиона са далеч напред. Темпото се забави: според Insider Gaming през първото тримесечие на фискалната година са доставени 1,6 милиона броя вместо 2,5 милиона, а през второто 2,6 вместо 4 милиона. Най-силната година беше фискалната 2023 г. с 20,8 милиона конзоли. Sony посочва и 127 милиона активни месечни потребители на PlayStation към 30 септември. При софтуера PS4 и PS5 имат 154,3 милиона продадени бройки след две тримесечия на текущата фискална година. Доколко GTA 6 ще повиши продажбите на конзоли от 19 ноември, ще покажат едва данните за третото тримесечие.", "weitere_links": ["Insider Gaming"], "_src": "0a83a0a1"}, "2026-11-11-nvidia-aktie-china-chips": {"titel": "Акциите на Nvidia на най-ниското си ниво от март: доклад говори за над 240 000 AI системи, стигнали до Китай чрез мрежа от фирми", "schlagzeile": "Акциите на Nvidia падат още: чипове за 7,5 млрд. $ са отишли в Китай?", "kurz": "След два дни на загуби акциите на Nvidia затвориха във вторник на 168,89 долара, най-ниското ниво от края на март. Microsoft за кратко я изпревари по пазарна стойност. Според доклад на The Information жената, с която Дженсън Хуанг призна за връзка, е доставила в Китай системи на Nvidia за поне 7,5 милиарда долара.", "zusammenfassung": "Скандалът около главния изпълнителен директор на Nvidia Дженсън Хуанг продължава да тежи на борсата. След спад от над 4% в понеделник акциите паднаха с още 5,5% във вторник и затвориха на 168,89 долара, най-ниското ниво от 30 март. Пазарната стойност остава малко над 4 трилиона долара; в началото на октомври беше над 5,5 трилиона. Microsoft беше за кратко пред Nvidia във вторник, а Apple я беше изпреварила още преди обвиненията да станат известни. Поводът е нов доклад на The Information, който цитира двама души, познаващи Алис Хуанг, с която шефът на Nvidia призна за връзка. Тя е позволила чрез мрежа от фирми доставки за Китай на над 240 000 системи A100, H100 и H200 на стойност поне 7,5 милиарда долара. За A100 и H100 от октомври 2022 г. важат американски ограничения за износ. Според доклада роля играят китайската компания за центрове за данни Century Litong и сингапурската фирма Megaspeed, която от октомври 2023 г. е сред предпочитаните облачни партньори на Nvidia. Американски власти настоявали Megaspeed да бъде включена в черен списък. Китай отхвърля обвинението в шпионаж. Nvidia започна вътрешно разследване, което според анализатор, цитиран от CNBC, може да продължи четири до шест седмици. Същият анализатор оценява вероятността Хуанг да загуби поста си на около 15%. Данните за доставките идват от анонимни източници и не са официално потвърдени.", "weitere_links": ["heise online (доклад за доставките в Китай)"], "_src": "3a8f3e41"}, "2026-11-11-fortis-games-schliessung": {"titel": "Мобилното студио Fortis Games затваря, засегнати са около 440 работни места, Las Vegas Sands спира финансирането", "schlagzeile": "Fortis Games затваря – около 440 работни места, казино гигантът спира парите", "kurz": "Основаното през 2022 г. мобилно студио Fortis Games затвори, засегнати са около 440 позиции. Според бивш служител инвеститорът Las Vegas Sands е прекратил финансирането и всички договори по света. Двете игри на студиото бяха все още в ранна тестова фаза.", "zusammenfassung": "Поредно голямо затваряне в игралната индустрия: Fortis Games вече не съществува, засегнати са около 440 работни места. Главният изпълнителен директор Стивън Чианг потвърди затварянето пред GamesBeat на 10 ноември. Той каза, че екипът е разочарован, че след над пет години не е постигнал целите си, и сега ще се съсредоточи върху това да помогне на служителите да намерят нова работа. Бивш продуцент написа в LinkedIn, че компанията майка Las Vegas Sands е решила да спре финансирането и да прекрати всички договори по света. Студиото от Сан Франциско е основано през 2022 г. от Чианг, който преди това е работил в Electronic Arts и Zynga. Fortis работеше по мобилните игри Twilight Towers и Bloom & Breakfast, които бяха в ранен soft launch; според продуцента със солидни показатели. Бивш директор по комуникациите пък написа, че подходът, ориентиран към общността, не е намерил достатъчен отклик сред играчите. Какво ще стане с двете игри, не е известно.", "_src": "2298d3f0"}, "2026-11-11-windows11-speicherintegritaet": {"titel": "Windows 11 вече включва автоматично целостта на паметта (HVCI) на повече компютри – защита, която може да забави игрите", "schlagzeile": "Windows 11 включва целостта на паметта – какво означава това за геймърите", "kurz": "С ноемврийската актуализация Windows 11 автоматично включва целостта на паметта (HVCI) на повече съществуващи компютри. Защитата блокира подправени драйвери, но според самия Microsoft може да струва производителност в игрите. Ако сте я изключили съзнателно, тя остава изключена, а изключването ѝ все още е възможно.", "zusammenfassung": "Microsoft затяга настройка за сигурност, която засяга геймърите. От незадължителната октомврийска актуализация, а сега и с актуализацията от Patch Tuesday KB5132061, Windows 11 може при актуализации автоматично да включва целостта на паметта, наричана още HVCI. Досега тя обикновено беше активна само на нови компютри и при чисти инсталации. Според Windows Latest промяната важи за Windows 11 25H2 и 26H2. Целостта на паметта работи в изолирана от хипервайзора на Windows зона и там проверява дали драйверите и кодът на ядрото са надеждни, така че дори превзето ядро не може да изпълни непроверен код. На някои компютри за целта ще бъде включена и базираната на виртуализация сигурност (VBS). Преди включване Windows проверява хардуера, съвместимостта на драйверите и производителността, а внедряването е постепенно. Ако сте изключили функцията сами, Windows няма да я включи отново; фирмените политики имат предимство. Уловката за геймърите: самият Microsoft преди няколко години препоръча в помощна статия да се изключи целостта на паметта за по-добра производителност в игрите. Тя може да се изключи от Защита на Windows, Защита на устройството, Подробности за изолацията на ядрото. Дали да го направите, е въпрос на баланс, защото защитата е насочена срещу зловреден софтуер, който се промъква в ядрото на Windows чрез драйвери.", "_src": "0b7240ab"}, "2026-11-10-fairgames-eingestellt": {"titel": "Sony спира live-service шутъра Fairgames след разочароващ тест, без съкращения в Haven Studios", "schlagzeile": "Sony спира Fairgames – поредният live-service шутър е история", "kurz": "PlayStation прекрати разработката на шутъра за обири Fairgames от Haven Studios. Според вътрешен имейл, за който съобщава Bloomberg, отзивите и задържането на играчите в тест не са достигнали целите. Съкращения няма да има, студиото ще подпомага други екипи на Sony.", "zusammenfassung": "Fairgames е история. Sony прекрати разработката на live-service шутъра три години след обявяването му през 2023 г., както първо съобщи Bloomberg. Във вътрешен имейл ръководителите в PlayStation Шон Декър и Джон Дойл пишат, че скорошен тест е убедил технически и организационно, но отзивите и задържането на играчите са били смесени и под целите. Заедно с трудния пазар за PvP шутъри е взето решение да не се продължава. Според съобщенията разработчикът Haven Studios няма да бъде закрит и не се планират съкращения; екипът ще подпомага други студия на Sony. Haven е основано през 2021 г. от Джейд Реймънд, която вече напусна студиото, и е купено от Sony през 2022 г. Fairgames е било преработвано няколко пъти от представянето си, а вътрешни тестове е трябвало да са приети зле още през 2025 г. Истински геймплей никога не беше показан официално, само рендерирани сцени от обявяващия трейлър. Стратегията на Sony за live-service игри от 2022 г. предвиждаше поне десет такива заглавия до 2026 г. Наред с успехи като Helldivers 2 вече има много спрени проекти и провала на Concord.", "weitere_links": ["Polygon", "IGN"], "_src": "ff8dd113"}, "2026-11-10-nvidia-tsmc-bestellungen": {"titel": "Доклад от Тайван: Nvidia може да намали поръчките на чипове в TSMC, AMD и проектантите на ASIC биха спечелили", "schlagzeile": "Изтичане: Намалява ли Nvidia поръчките си за чипове в TSMC?", "kurz": "Тайванският вестник Commercial Times съобщава, позовавайки се на неназовани източници от веригата на доставки, че Nvidia може да поръчва по-малко чипове от TSMC. Посочва се натискът от скандала около Дженсън Хуанг и по-строгите проверки за износ. Докладът не назовава продукт, производствен процес, обем или срок. Nvidia и TSMC не коментираха.", "zusammenfassung": "Nvidia може да намали поръчките си към договорния производител TSMC. Това съобщава тайванският вестник Commercial Times, позовавайки се на неназовани източници от веригата на доставки; TechPowerUp подхвана доклада. Не се казва за какви продукти, производствен процес, количества и период става дума. Като причини докладът посочва натиск отвътре и отвън: вътрешно скандалът около Дженсън Хуанг и разследването на борда на Nvidia, външно по-строгите проверки за износ. Освен това в Хонконг е трябвало да има складирани чипове H200. Споменава се и подозрението, че някои фирми, одобрени за H200, може да са фиктивни, но изрично като подозрение, а не като установен факт. Ако Nvidia освободи капацитет, вестникът очаква AMD и разработчици на собствени AI чипове като MediaTek, Alchip и GUC да го поемат. Съкращенията биха засегнали най-вече доставчици като TSMC и ASE. За геймърите това не би означавало автоматично по-евтини видеокарти, защото паметта, която в момента е в недостиг, не идва от TSMC. Докладът се основава на един източник; Nvidia и TSMC не са го коментирали. До потвърждение трябва да се приема като слух.", "ursprungsquelle": "Commercial Times (Тайван), чрез TechPowerUp", "_src": "a929a8ec"}, "2026-11-10-gta6-xbox-fsr4-dateien": {"titel": "Датамайнъри откриха FSR библиотеки на AMD в Xbox пакета на GTA 6, дали се ползва FSR 4.1.2, остава неясно", "schlagzeile": "Изтичане: Ползва ли GTA 6 на Xbox вече AI ъпскейлинга FSR 4 на AMD?", "kurz": "Предварителното изтегляне на GTA 6 за Xbox съдържа два файла на AMD, чиито имена съвпадат с интеграцията на FSR 4.1.2 за Xbox Series X|S. Това е знак, а не доказателство: файловете на играта са криптирани, а същият интерфейс може да премине и към по-стария FSR 3.1. Rockstar не е коментирал.", "zusammenfassung": "Скоро след старта на предварителното изтегляне на GTA 6 за Xbox датамайнъри откриха в инсталационния пакет две библиотеки на AMD: amd_fidelityfx_loader_xbox.dll и amd_fidelityfx_upscaler_xbox.dll. Откри ги датамайнърът Tex2, а други потребители сравниха имената с документацията на FSR 4.1.2 за Xbox Series X|S. Първи съобщи VideoCardz, а PC Games Hardware постави находката в контекст. AMD и Microsoft пуснаха FSR 4.1.2 за Xbox на 4 ноември; това е първият базиран на AI ъпскейлър за конзолите, с два INT8 модела, Full и Lite. Имената на файловете обаче не доказват, че GTA 6 наистина използва FSR 4.1.2. Същият SDK на AMD съдържа и класическия FSR 3.1.6, към който интерфейсът може да премине. Тъй като файловете на играта са криптирани, съдържанието на библиотеките още не може да се провери. За конзолите Rockstar досега потвърди само 30 fps на всички модели и PSSR на PS5 Pro; официална информация за ъпскейлинга на Xbox няма. Най-късно при старта на 19 ноември анализите би трябвало да покажат кой метод се използва.", "ursprungsquelle": "Датамайнър Tex2 (X), първо съобщено от VideoCardz", "_src": "548f3594"}, "2026-11-10-patchday-november-1235": {"titel": "Patch Tuesday на Microsoft за ноември 2026: поправени 1235 уязвимости, сред тях активно експлоатирана zero-day в Outlook", "schlagzeile": "Рекорден Patch Tuesday: 1235 уязвимости – дупка в Outlook вече се атакува", "kurz": "Microsoft поправи 1235 уязвимости в сигурността в ноемврийския Patch Tuesday, 66 от тях критични. Уязвимост за подправяне в Outlook вече се използва за кражба на данни за NTLM акаунти. Windows 11 получава KB5132061 и KB5131087, а Windows 10 в програмата ESU – KB5131096.", "zusammenfassung": "Ноемврийският Patch Tuesday на Microsoft отново е огромен: според BleepingComputer актуализациите поправят 1235 уязвимости; още 108 бяха поправени по-рано през месеца и не се броят. През октомври бяха дори 1411; Microsoft все по-често използва AI за откриване на уязвимости. 66 уязвимости са критични, 48 от тях позволяват отдалечено изпълнение на код. Около 639 засягат Windows и негови компоненти. Най-спешна е уязвимост за подправяне в Microsoft Outlook, която вече се атакува. Според Microsoft е достатъчно жертвата да отвори специално подготвен файл със съобщение: тогава Outlook се свързва със сървър на нападателите без обичайното предупреждение и може да разкрие данни за вход под формата на NTLM хешове. Windows 11 получава кумулативните актуализации KB5132061 и KB5131087, а Windows 10 22H2 в програмата за разширени актуализации на защитата – KB5131096. Според Neowin при някои потребители инсталирането на KB5132061 се проваля с грешка 0x800f0993. Въпреки това всеки, който ползва Windows или Office, трябва да инсталира актуализациите скоро, особено заради уязвимостта в Outlook.", "weitere_links": ["Dr. Windows", "Neowin (грешка при инсталиране)"], "_src": "e3b7656c"}, "2026-11-10-fritzbox-5690-pro-speicher": {"titel": "Fritz!Box 5690 Pro: според сервизните данни по-новите устройства имат само половината RAM и флаш памет при същия артикулен номер", "schlagzeile": "Fritz!Box 5690 Pro: по-новите устройства с половин памет – същият номер", "kurz": "По-новите бройки на Fritz!Box 5690 Pro очевидно имат само 1 GB RAM и 2 GB флаш вместо 2 и 4 GB. Артикулният номер и хардуерната версия са същите, разликата личи само в хардуерната подревизия. Fritz говори за обичайни за бранша промени без влияние върху производителността.", "zusammenfassung": "Който купи днес Fritz!Box 5690 Pro, не получава непременно същия хардуер като купувачите при старта. Забелязал го е потребител с две устройства: по-новото показваше значително по-голямо натоварване на RAM при същата версия на Fritz!OS. Според сервизните данни устройство от юли 2024 г. има 2 GB RAM и 4 GB флаш, а едно от юни 2026 г. само 1 GB RAM и 2 GB флаш. Използваемата за системата RAM пада така от 1754 на 742 MB, а вътрешната памет, използвана например за Fritz!NAS, се свива от около 1,7 GB на 680 MB. Вариантите се различават само по хардуерната подревизия, която се е повишила от 3 на 5; артикулният номер и хардуерната версия са същите, а отвън рутерите изглеждат еднакво. Кога точно е направена промяната, не е ясно; известно време двата варианта изглежда са доставяни паралелно. Fritz заяви пред Router-FAQ.de, че вътрешни компоненти като чиповете памет понякога се променят по време на жизнения цикъл на продукта; това било обичайно за бранша и не променяло спецификацията и производителността. Компанията не потвърди изрично намаляването наполовина. Сравнителни тестове на двата варианта още няма, неясно е и дали това ще се отрази на бъдещи актуализации. Все пак е неловко, защото при пускането през юни 2024 г. Fritz изрично рекламираше големия капацитет на паметта.", "_src": "aa5e40e9"}, "2026-11-10-auto-sr-xbox-ally-ryzen": {"titel": "Microsoft Auto SR излиза от предварителната версия на ROG Xbox Ally X и X20 и идва на Copilot+ компютри с AMD Ryzen, нов режим до 120 fps", "schlagzeile": "Мащабирането Auto SR в Windows: вече преносимо, с HDR и до 120 fps", "kurz": "AI мащабирането Auto SR на Microsoft официално стартира на преносимите конзоли ROG Xbox Ally X и X20. Новото е режим за производителност до 120 fps, работа в преносим режим без докинг станция и комбинация с Auto HDR. Auto SR вече работи и на избрани Copilot+ компютри с AMD Ryzen.", "zusammenfassung": "В блога на DirectX Microsoft обяви официалния старт на Automatic Super Resolution (Auto SR) на преносимите конзоли ROG Xbox Ally X и ROG Xbox Ally X20. Auto SR кара игрите да работят вътрешно с по-ниска резолюция и ги мащабира с изкуствен интелект на NPU, без играта да трябва да поддържа това. Досега функцията беше достъпна само като предварителна версия и само в докинг станция. Сега тя работи и на вградения екран и на батерия. Поддържат се и игри в 1080p, а на монитор Auto SR може да ги мащабира до 1440p. Нов режим за производителност вдига границата от досегашните около 60 до 75 fps до 120 fps; в примера на Microsoft с Rocket League средната стойност се е повишила от 70 на 115 fps. Освен това за първи път Auto SR и Auto HDR могат да се използват едновременно. Преносимият режим, 1080p и новите Copilot+ компютри с AMD Ryzen са достъпни веднага. Режимът за производителност и поддръжката на Auto HDR ще идват постепенно с обновления на Windows. Нужни са актуалните обновления на Windows 11, обновен Game Bar и пакетът Auto Super Resolution от Microsoft Store.", "_src": "539f5a74"}, "2026-11-10-gpu-taskman-vram": {"titel": "GPU Taskman: инструмент с отворен код показва точно кои програми колко графична памет заемат", "schlagzeile": "Кой изяжда VRAM-а ти? Безплатен инструмент го показва за всяка програма", "kurz": "Разработчикът от Microsoft и GitHub Скот Хансълман пусна инструмента с отворен код GPU Taskman. Той показва за всяка програма колко графична памет е заета, както и натоварването, температурата и честотата на GPU. Инструментът все още е експериментален.", "zusammenfassung": "Скот Хансълман, вицепрезидент в Microsoft и GitHub, разработи GPU Taskman – безплатен инструмент за командния ред. Той трябва да показва по-точно от диспечера на задачите на Windows къде отива графичната памет. Показват се заетостта на VRAM, системната памет, използвана от GPU, и отделните процеси, както и натоварване, температура, консумация, честота и стойности за PCIe. Инструментът разграничава например работния плот, браузърите, игрите и AI приложенията. При локални AI модели в llama.cpp, Ollama или LM Studio той може да изчисли отделно паметта за теглата на модела и за KV кеша. На геймърите може да помогне да открият тесни места във VRAM, които причиняват накъсване. Хансълман обаче предупреждава, че използваната системна RAM не означава автоматично препълване на VRAM, а инструментът не разпознава отделни текстури. GPU Taskman поддържа карти на NVIDIA и AMD под Windows 10 и 11, както и Linux, WSL и Mac компютри с Apple Silicon; версия 0.3.5 добавя GPU на Intel под Linux. Той е достъпен под лиценз MIT в GitHub, с преносима версия за Windows. Софтуерът все още е експериментален, а някои стойности са приблизителни.", "_src": "43537581"}, "2026-11-10-ps-plus-pc-app-ende": {"titel": "Sony спира приложението PlayStation Plus за PC на 10 декември, Death Stranding 2 влиза в каталога Extra", "schlagzeile": "Край на стрийминга на PS Plus на PC – ползвали са го само 0,4%", "kurz": "Sony спира приложението PlayStation Plus за Windows на 10.12.2026 г. и така прекратява стрийминга на игри от PS Plus на PC. Според Sony приложението са ползвали под 0,4% от членовете с Premium. В същата публикация Sony обявява новите игри в Extra и Premium начело с Death Stranding 2.", "zusammenfassung": "В самия край на публикацията си за новите игри в PS Plus за ноември Sony обяви края на приложението за PC. От 10 декември приложението PlayStation Plus за PC вече няма да е достъпно, а с него и облачният стрийминг на игри от PS Plus Premium на компютри с Windows. Като причина Sony посочва слабото използване: под 0,4% от имащите право членове с Premium са ползвали приложението. Абонаментите и предимствата на PS5 и PS4 не са засегнати, а Sony ще уведоми директно засегнатите потребители. Така изчезва един от начините да се играят игри за PlayStation на PC без конзола. Сред новостите в каталога Extra и Premium през ноември са Death Stranding 2: On the Beach, Atomfall и Dragon Quest III HD-2D Remake. Hell Let Loose идва на 11 ноември, а Like a Dragon: Pirate Yakuza in Hawaii, Trepang2, MotoGP 26 и Cricket 26 – на 24 ноември. Само за Premium се добавят Soul Reaver 2 и Freedom Wars Remastered.", "weitere_links": ["Eurogamer", "PlayStation в X"], "_src": "235d58ff"}, "2026-11-10-amd-zen6-ipc-epyc": {"titel": "AMD разкрива архитектурата Zen 6: 27% по-висок IPC, стартират Epyc 9006 „Venice“ с до 256 ядра", "schlagzeile": "Zen 6 е тук: AMD обещава 27% повече IPC – първо при сървърните Epyc", "kurz": "AMD разкри технологията зад Zen 6 и посочва 27% по-висок IPC спрямо Zen 5. Първите чипове със Zen 6 са сървърните процесори Epyc 9006 „Venice“ с до 256 ядра и до 5,3 GHz. Стойността на IPC идва от необичайно сравнение на AMD. За настолни процесори Ryzen със Zen 6 AMD все още не е казала нищо.", "zusammenfassung": "С края на ембаргото AMD публикува тази вечер много подробности за архитектурата Zen 6. Според AMD IPC, тоест производителността на такт, нараства средно с 27% спрямо Zen 5, с около 20% при обикновени приложения и около 31% при задачи с изкуствен интелект. ComputerBase и heise обаче посочват, че AMD е сравнила 16 ядра Zen 6c в един чиплет с 16 ядра Zen 5, разпределени в два чиплета, което не е класическо сравнение на IPC. Технически ядрото става по-широко: op кешът нараства до 6750 записа и подава 18 вместо 12 микрооперации на такт, а регистровият файл и буферът за пренареждане растат до 352 и 640 записа. AVX-512 остава, както и SMT. Обикновените ядра Zen 6 са по дванадесет в чиплет с 48 MB L3 кеш, а компактните Zen 6c – по 32 в чиплет със 128 MB L3, произведени по 2-нанометровия процес на TSMC. Първите продукти са сървърните процесори Epyc 9006 „Venice“ с до 256 ядра, 16 канала за DDR5 памет, PCIe 6.0 и до 600 вата. Високочестотните модели достигат до 5,3 GHz. AMD казва, че вече доставя, а първите системи трябва да излязат още тази година. При първите дистанционни измервания на heise едно ядро Zen 5 е имало нужда от около 22% повече време в Blender от едно ядро Zen 6, което обаче работи и на по-висока честота. През 2027 г. следват по-малка платформа, както и Venice-X с 3D V-Cache и Verano с памет LPDDR5X. След това в пътната карта са Zen 7 „Florence“ за 2028 г. и Zen 8 „Ravenna“. На събитието AMD не каза нищо за процесори Ryzen за настолни компютри и лаптопи със Zen 6, нито за срока им.", "weitere_links": ["heise online", "AMD в X"], "_src": "d9fcfe1b"}, "2026-11-10-amd-mext-flash-statt-ram": {"titel": "AMD MEXT: софтуер прехвърля рядко използваната памет на флаш, за да спести скъпа DRAM", "schlagzeile": "Криза с RAM: AMD иска да спести до 75% DRAM чрез флаш памет", "kurz": "AMD представи MEXT – софтуер, който прехвърля рядко използвани страници от паметта от DRAM на флаш SSD. Така сървърите трябва да работят почти толкова бързо с много по-малко скъпа памет. Засега предложението е само за сървъри Epyc. Всички данни за производителността са от AMD.", "zusammenfassung": "С MEXT AMD отговаря на продължаващия недостиг на памет. Според AMD DRAM представлява от 75 до 90% от цената на сървъра в зависимост от конфигурацията, докато голяма част от паметта остава неизползвана или е с излишен капацитет. MEXT разпознава „студени“ страници от паметта и ги премества на флаш памет, тоест на NVMe SSD. Модели с изкуствен интелект трябва да предвиждат кои данни скоро ще са нужни отново и да ги връщат навреме в DRAM. Според Wccftech софтуерът се състои от драйвер за Linux, AI машина, която работи на едно ядро Epyc, и инструмент за наблюдение. Според AMD така нуждата от DRAM може да се намали с 20 до 75% при сходна производителност. В пример от проектирането на чипове сървър с наполовина по-малко DRAM все още постига 95% от производителността. Тези стойности са данни на производителя, независими тестове все още липсват. Според Phoronix драйверът за Linux не е с отворен код. Засега MEXT е предназначен само за сървъри Epyc с NVMe устройства, а по-късно ще има лиценз. AMD намекна, че подобно решение може да стане интересно и за обикновени компютри, но конкретни планове няма.", "weitere_links": ["ComputerBase", "Phoronix"], "_src": "f9b8ff0f"}, "2026-11-10-gta6-vorbestell-rekord-xbox-cloud": {"titel": "Според Sony и Microsoft GTA 6 е най-поръчваната предварително игра в техните магазини, Xbox One я получава през облака, Xbox сключва 10-годишно партньорство с Take-Two", "schlagzeile": "GTA 6 чупи рекорди по предварителни поръчки – и идва дори на Xbox One", "kurz": "Sony и Microsoft съобщават, че GTA 6 е най-поръчваната предварително игра в историята на PlayStation Store и Microsoft Store. Чрез Xbox Cloud Gaming при старта тя ще върви и на стария Xbox One. Шефката на Xbox Аша Шарма говори за ново 10-годишно партньорство с Take-Two. Никой не дава конкретни данни за продажбите.", "zusammenfassung": "В PlayStation Blog Sony пише, че GTA 6 е най-поръчваната предварително игра в историята на PlayStation Store. Microsoft съобщава същото за Microsoft Store в Xbox Wire. Нито една от двете компании не дава числа; Take-Two наскоро каза само, че предварителните поръчки далеч надхвърлят очакванията. Заради очаквания наплив Sony и Microsoft съветват играта да се изтегли предварително възможно най-рано. На PlayStation GTA 6 излиза на 19 ноември в полунощ местно време, като се започва от Нова Зеландия. Xbox Cloud Gaming предлага играта от 19 ноември в 1:00 ч. по източноамериканско време, тоест в 7:00 ч. в Австрия, на Xbox One и Xbox Series X|S, с графичните настройки на Series S. Стрийминг на PC или смартфон не е предвиден. В X шефката на Xbox Аша Шарма нарече това „първата стъпка“ от ново 10-годишно стратегическо партньорство с Take-Two, без да дава подробности. Според Xbox Wire през следващите месеци в Xbox Cloud Gaming ще се появят още игри на Rockstar като GTA V и Red Dead Redemption 2. От 11 ноември играчите в поддържаните държави могат да купуват и време за игра в облака без абонамент за Game Pass.", "weitere_links": ["PlayStation.Blog", "Аша Шарма в X", "IGN"], "_src": "1f6dc907"}, "2026-11-10-eu-dfa-lootboxen-entwurf": {"titel": "Изтекъл проект на европейския Digital Fairness Act: лутбоксовете по подразбиране изключени за непълнолетни, pay-to-win забранен за деца", "schlagzeile": "Изтичане: иска ли ЕС да изключи по подразбиране лутбоксовете за деца?", "kurz": "Предполагаем проект на европейския закон Digital Fairness Act излезе предсрочно. Той предвижда лутбоксовете да са изключени по подразбиране за непълнолетни, а всички играчи да могат да ги изключват. Официалното представяне е планирано за 11 ноември, а до закон има още много.", "zusammenfassung": "Френското специализирано издание Contexte публикува предполагаем проект на Digital Fairness Act, а Eurogamer съобщава за него. Според Eurogamer Европейската комисия смята да представи официално предложението на 11 ноември. Проектът е насочен срещу нелоялни практики в дигиталния свят, включително монетизацията в игрите. Всички играчи трябва да могат да изключват лутбоксовете, тоест награди със случайно съдържание; за непълнолетните те трябва да са изключени по подразбиране. Механики pay-to-progress и pay-to-win не трябва да се предлагат на деца, ако продуктът е насочен към тях или доставчикът знае, че го ползват непълнолетни. При виртуалните валути реалната цена на покупките трябва да е прозрачна, както и шансовете за печалба при лутбоксовете. Текстът предвижда и задължителна възрастова класификация за игрите. Освен игрите засяга рекламата от инфлуенсъри, скритите цени и трудно прекратимите абонаменти. Важно: става дума за изтекъл проект, който може още да се промени до представянето. След това следват преговори; според Eurogamer законът може да бъде приет в края на 2027 г. и да се прилага широко до 2030 г.", "ursprungsquelle": "Contexte (via Video Games Industry Memo)", "_src": "792e7165"}, "2026-11-10-asrock-vbios-tool-1-0-6": {"titel": "ASRock пуска инструмента за флашване на VBIOS 1.0.6 за RX 7900 XT/XTX, след като версия 1.0.5 направи карти неизползваеми", "schlagzeile": "След „тухлясали“ RX 7900 XTX: ASRock пуска нов BIOS инструмент – без обяснение", "kurz": "ASRock пусна инструмента за флашване ASRVBFlash 1.0.6 за Radeon RX 7900 XT и XTX. Според потребители предишната версия 1.0.5 е извадила карти от строя след обновяването. ASRock не казва какво е променено и каква е била причината.", "zusammenfassung": "В началото на ноември се натрупаха съобщения, че Radeon RX 7900 XT и XTX на ASRock не стартират след официално обновяване на VBIOS. Виновен беше инструментът ASRVBFlash 1.0.5: след рестарта системата вече не зареждаше. След това ASRock очевидно свали версията от страниците си за изтегляне. Сега тихомълком се появи версия 1.0.6, която според TechPowerUp трябва да предотвратява повредата и правилно да инсталира обновлението на фърмуера за по-голяма сигурност. Няма списък с промени, нито обяснение на причината, което критикува и PCGH. Остава неясно как ASRock постъпва с вече повредените карти. Според TechPowerUp клиент в Япония е получил отговор, че карта, повредена от официалното обновление, се покрива от гаранцията. На клиент в Европа обаче е казано, че свалянето на охладителя за повторно флашване на BIOS чипа води до загуба на гаранцията. Затова засегнатите трябва да минат през RMA, вместо да експериментират сами. Който още не е обновил, може и да изчака опита на други потребители с 1.0.6.", "weitere_links": ["PC Games Hardware", "Wccftech"], "_src": "a328de5f"}, "2026-11-10-gta6-30fps-ps5-pro": {"titel": "Rockstar потвърждава: GTA 6 цели 30 fps на всички конзоли, PS5 Pro получава PSSR и ексклузивни сенки с ray tracing", "schlagzeile": "GTA 6 върви на 30 fps – и на PS5 Pro, но със сенки с ray tracing", "kurz": "Rockstar потвърди, че GTA 6 цели 30 кадъра в секунда на всички конзоли, включително на PS5 Pro. В замяна Pro версията получава по-рязка картина чрез PSSR и ексклузивни сенки с ray tracing. Предварителното изтегляне е достъпно от днес, а премиерата е на 19 ноември.", "zusammenfassung": "Със старта на предварителното изтегляне Rockstar Games за първи път официално обясни техниката на GTA 6 на конзолите. Играта е разработена от нулата за сегашното поколение конзоли и цели 30 кадъра в секунда, като изстисква двете платформи „до абсолютните им граници“. Според Rockstar това важи за PS5, PS5 Pro, Xbox Series X и Series S. Rockstar не споменава режим с 60 fps. PS5 Pro получава по-рязка картина чрез AI мащабирането на Sony PSSR и сенки с ray tracing, които има само там. На PS5 GTA 6 използва хаптиката, адаптивните тригери и високоговорителя на DualSense, както и Tempest 3D Audio; Rockstar и Sony казват, че играта се играе най-добре на PS5. Remote Play се поддържа на PlayStation и Xbox. Чрез Xbox Cloud Gaming играта може да се стриймва на конзоли Xbox с графичните настройки на Series S, но не и на PC. Rockstar все още не е обявила версия за PC. В зависимост от конзолата изтеглянето изисква до 212 GB. Има и нов трейлър за предварителното изтегляне с почти 30 секунди нови сцени.", "weitere_links": ["PlayStation.Blog", "Eurogamer", "Rockstar Games в X"], "_src": "1689ad08"}, "2026-11-10-steam-deck-framerate-daten": {"titel": "Steam вече показва в страниците на магазина средната кадрова честота на играчите на Steam Deck", "schlagzeile": "Steam вече показва реални fps – как върви една игра на Deck?", "kurz": "Valve вече показва в Steam за много игри средната кадрова честота на Steam Deck. Данните идват от играчи, които са се съгласили да ги споделят. По-късно ще бъдат добавени и други устройства.", "zusammenfassung": "Valve добави нов показател за производителност в Steam. В раздела за съвместимост със Steam Deck на страницата на игра след клик върху „Научете повече“ вече се вижда средната кадрова честота на Steam Deck. Хистограма показва и колко често е измервана всяка стойност, така че се виждат и колебанията. Данните идват от играчи, които са се съгласили да изпращат данни за кадровата честота. Стойността се показва при игри, които Valve е проверила за съвместимост с Deck, тоест с оценки „Потвърдена“, „Може да се играе“ или „Не се поддържа“. Valve обяснява, че досегашната оценка се базира на фиксирани тестови критерии и не отговаря на представата на всеки играч за плавна игра. Игра с оценка „Не се поддържа“ може за някои все пак да е добре играема, докато потвърдена игра може да има нисък fps. Според Valve функцията в бъдеще ще обхване и други устройства. Дали сред тях ще са и обикновени настолни компютри с многото им хардуерни комбинации, не е ясно.", "weitere_links": ["PC Gamer", "GamingOnLinux"], "_src": "6dbc5420"}, "2026-11-10-msi-rtx50-preise-china": {"titel": "Доклад от Китай: MSI щяла силно да вдигне през ноември дистрибуторските цени на картите RTX 50, на RTX 5080 с до 8000 юана", "schlagzeile": "Изтичане: MSI щяла да поскъпне RTX 5080 в Китай с до 8000 юана", "kurz": "Според китайския браншов канал ChannelGate MSI вдига през ноември дистрибуторските цени на всички карти RTX 50. При RTX 5080 увеличението щяло да е от 1300 до 8000 юана, или около 190 до 1200 долара. Става дума за цени за дистрибутори в Китай, не за официални цени за крайни клиенти. MSI не е потвърдила това.", "zusammenfassung": "Китайският браншов канал ChannelGate (Board Channels) съобщава за нови ценови листи на MSI за ноември. Според него дистрибуторските цени на всички модели RTX 50 в Китай се повишават спрямо октомври. За серията RTX 5080 се посочват от 1300 до 8000 юана повече, за RTX 5070 Ti от 800 до 4000 юана, а за RTX 5070 от 500 до 1000 юана. RTX 5060 Ti щяла да поскъпне с 200 до 400 юана в зависимост от паметта, RTX 5060 с 200 до 500 юана, а дори RTX 3050 със 100 юана. Wccftech преизчислява максималната стойност за RTX 5080 на около 1200 долара. Важно: максимумът важи само за отделни модели и става дума за цени за търговци в Китай, а не за нова световна препоръчителна цена. Дали и колко силно това ще засегне Европа, не е ясно. Съобщението се вписва в по-ранни доклади на ChannelGate за поскъпвания при други производители на карти. Основната причина щели да са силно повишените цени на паметта. Самата MSI не е коментирала, затова остава непотвърден доклад.", "ursprungsquelle": "ChannelGate / Board Channels (WeChat), via harukaze5719", "weitere_links": ["IT之家 (ChannelGate)", "TechRadar"], "_src": "59a47e79"}, "2026-11-10-arc-raiders-17-mio": {"titel": "Nexon: Arc Raiders е продадена в над 17 милиона копия за една година, приходите се очаква да спаднат през четвъртото тримесечие", "schlagzeile": "Arc Raiders надхвърли 17 милиона – но продажбите се забавят", "kurz": "Според издателя Nexon екстракшън шутърът Arc Raiders е продаден в над 17 милиона копия за първия си рожден ден. През третото тримесечие обаче са добавени само един милион. Nexon очаква през четвъртото тримесечие по-малко приходи, отколкото при старта преди година.", "zusammenfassung": "В тримесечния си отчет Nexon даде нови данни за Arc Raiders на Embark Studios. Екстракшън шутърът излезе в края на октомври 2025 г. и оттогава е продаден в над 17 милиона копия. Според Nexon обаче през третото тримесечие на 2026 г. са добавени само около един милион, така че продажбите значително са се забавили. За четвъртото тримесечие Nexon очаква по-малко приходи от играта, отколкото в същото тримесечие на миналата година, когато беше успешният старт. Спрямо предходното тримесечие приходите се очаква да останат приблизително същите. Според Nexon приходите са в рамките на прогнозата, а обновлението Frozen Trail е върнало бивши играчи и е спечелило нови. Arc Raiders остава едно от най-важните заглавия на Nexon и беше основната причина за ръста на приходите през първите девет месеца на годината. Все още не е ясно дали ще има постоянен самостоятелен PvE режим; в Китай такъв вече има.", "_src": "95842a04"}, "2026-11-10-nvidia-fbi-sammelklagen": {"titel": "Подозрения за шпионаж около шефа на NVIDIA Хуанг: според Тръмп ФБР проверява случая, адвокатски кантори търсят инвеститори за искове", "schlagzeile": "Шпионската афера около NVIDIA: ФБР проверява случая, задават се искове", "kurz": "По случая с предполагаемата китайска шпионка от обкръжението на шефа на NVIDIA Дженсън Хуанг вече проверява ФБР, според президента на САЩ Тръмп. Не е ясно дали евентуално разследване засяга и Хуанг. Няколко американски адвокатски кантори търсят инвеститори за възможни колективни искове срещу NVIDIA.", "zusammenfassung": "Аферата около шефа на NVIDIA Дженсън Хуанг и предполагаемата китайска шпионка Алис Хуанг набира скорост. Според Spiegel и Reuters президентът на САЩ Доналд Тръмп е казал, че ФБР разглежда случая. Не е ясно дали проверката засяга и самия Дженсън Хуанг; въпреки еднаквата фамилия двамата не са роднини. Тръмп защити Хуанг и каза по същество, че му вярва, че не е знаел нищо за шпионска дейност. Хуанг по-рано призна връзката и се извини публично, а бордът на NVIDIA започна разследване с външни експерти. Според PC Gamer няколко американски адвокатски кантори, сред които Rosen Law Firm, търсят инвеститори за възможни искове заради подвеждащи изявления. Според Guardian в Сан Хосе вече е заведен иск, в който NVIDIA и Хуанг са обвинени, че са премълчали възможен риск за сигурността. Работодателят на Алис Хуанг, Megaspeed, е заподозрян, че е изнасял чипове на NVIDIA за Китай без разрешение; NVIDIA и Megaspeed по-рано отрекоха това. Според PC Gamer Хуанг трябва да даде показания при закрити врата пред комисии на Конгреса на 18 ноември. Нито едно от обвиненията досега не е решено от съд.", "weitere_links": ["PC Gamer"], "_src": "79f7d817"}, "2026-11-10-chrome-zero-day": {"titel": "Chrome 157 затваря девет уязвимости, сред които активно използваната CVE-2026-125350", "schlagzeile": "Уязвимост в Chrome вече се атакува – обнови сега до версия 157", "kurz": "Google пусна актуализация на Chrome с девет корекции за сигурност. Уязвимост в XML компонента на браузъра вече се използва активно. Сигурните версии са 157.0.8103.50/.51 за Windows и Mac и 157.0.8103.50 за Linux.", "zusammenfassung": "Google пусна актуализация за сигурност на Chrome, която затваря девет уязвимости, съобщава Golem. Според Google поне една от тях вече се използва активно: CVE-2026-125350. Става дума за грешка от типа use-after-free в компонента, който обработва XML данни; тежестта е оценена като висока, но Google все още не дава CVSS оценка. Google не казва как и срещу кого се използва уязвимостта. Не е ясно и дали потребителят трябва да кликне нещо, за да успее атаката. От останалите осем уязвимости шест са с висока, а две със средна тежест; засегнати са, наред с други, JavaScript енджинът V8, WebGL и интерфейси към GPU и файловата система. Както обикновено, Google задържа техническите подробности, докато повечето потребители не обновят. Сигурните версии са 157.0.8103.50/.51 за Windows и macOS и 157.0.8103.50 за Linux. Други браузъри на базата на Chromium като Edge, Vivaldi или Brave вероятно също са засегнати и ще получат актуализации в следващите дни. Съвет: Помощ › Всичко за Google Chrome стартира проверката за актуализация; след това рестартирай браузъра.", "_src": "3c9a011f"}, "2026-11-10-switch-eshop-geschenke": {"titel": "Системната актуализация 23.5.0 за Switch подготвя функция за подаръци в Nintendo eShop за семейни групи", "schlagzeile": "Switch и Switch 2: скоро ще подаряваш игри – но само в семейството", "kurz": "С системна актуализация 23.5.0 Nintendo подготвя възможността за подаряване на игри от eShop. Функцията ще се активира с актуализация на eShop в средата на ноември. Подаръци могат да се пращат само на членове на собствената семейна група.", "zusammenfassung": "Nintendo пусна системна актуализация 23.5.0 за Switch 2 и първия Switch. Тя подготвя нова функция: дигитални игри, DLC и пакети за ъпгрейд от eShop скоро ще могат да се подаряват. Ограничението: получателите трябва да са членове на собствената семейна група в Nintendo Account, която има до осем членове. Според Nintendo наблюдаваните детски акаунти не могат да изпращат подаръци, някои продукти са изключени, а броят на покупките за подарък за даден период е ограничен; точни лимити Nintendo не дава. При покупка се отбелязва „Купи като подарък“ на страницата на продукта, избира се получателят и неговата конзола и се плаща както обикновено. Подаръкът пристига веднага в менюто HOME на получателя. Функцията ще бъде активирана едва с актуализация на eShop: в бележките към актуализацията се посочва 17 ноември, а Nintendo of America пише за 16 ноември, вероятно заради часовата зона. На Switch 2 версия 23.5.0 позволява и настройване на функциите за достъпност още при първоначалната настройка. Който иска да подари игри на приятели извън семейната група, ще трябва и занапред да използва карти за подарък за eShop.", "weitere_links": ["VGChartz (бележки към актуализацията)", "Nintendo of America в X (подсказка)"], "_src": "51b1c15b"}, "2026-11-10-mesa-26-3": {"titel": "Излезе Mesa 26.3: AMD Anti-Lag за RADV, графиката Nova Lake е включена по подразбиране, Vulkan Video за NVK", "schlagzeile": "Linux графичният драйвер Mesa 26.3: Anti-Lag за Radeon и още Vulkan", "kurz": "Свободната колекция графични драйвери Mesa 26.3 е тук. Потребителите на Radeon получават чрез RADV разширението на Vulkan за AMD Anti-Lag, а графиката Intel Nova Lake вече не е експериментална. Добавят се и Vulkan Video за драйвера на NVIDIA NVK и много подобрения за Vulkan.", "zusammenfassung": "Излезе Mesa 26.3 – четвъртото голямо издание за годината на свободните OpenGL и Vulkan драйвери за Linux, съобщават Phoronix и 9to5Linux. За геймърите с Radeon карта най-важната новост е VK_AMD_anti_lag във Vulkan драйвера RADV – Vulkan интерфейсът за AMD Anti-Lag, който намалява входното забавяне. RADV носи и подобрения за ранните GCN GPU и поддръжка за GFX1171. При Intel графиката на Nova Lake вече е включена по подразбиране и не е експериментална, а новият компилатор за шейдъри Jay е активиран. Intel включва и компресия на буферите, която според Phoronix трябва да подобри производителността в игри с DXVK, тоест при Windows игри чрез Proton. Свободният драйвер на NVIDIA NVK получава Vulkan Video за видео ускорение. Добавят се и много нови Vulkan разширения за Arm Mali, PowerVR и други драйвери. Mesa 26.3 е достъпна във FreeDesktop.org; повечето дистрибуции ще я доставят със следващите актуализации на пакетите. Колко помага Anti-Lag в отделните игри зависи от това дали играта или слоят за транслация го използва; измервания все още няма.", "weitere_links": ["9to5Linux"], "_src": "24e0a075"}, "2026-11-10-take-two-ki-decompiling": {"titel": "Take-Two засилва техническата и правната защита срещу обратния инженеринг на GTA 6 с помощта на ИИ", "schlagzeile": "Неофициален PC порт на GTA 6 чрез ИИ? Take-Two засилва защитата", "kurz": "Шефът на Take-Two Строс Зелник приема сериозно декомпилирането с помощта на ИИ и иска да засили техническата защита и правните действия. Причината е опасението, че GTA 6 може да се появи неофициално на PC. За официална PC версия или диск Take-Two не казва нищо; това ще дойде от Rockstar.", "zusammenfassung": "Преди старта на GTA 6 на 19 ноември расте опасението, че инструменти с ИИ могат по-бързо да декомпилират конзолни игри и да ги разпространяват като неофициални PC портове. IGN попита главния изпълнителен директор на Take-Two Строс Зелник за това в интервю и по време на въпросите на инвеститорите. Зелник казва, че индустрията дълго е била до голяма степен пощадена от пиратството заради размера на файловете, сложността и връзката със сървъри, но това става все по-трудно. Затова Take-Two се съсредоточава върху засилване на техническата защита и правните си действия. Той очаква пиратството да засегне бизнеса „в по-голяма или по-малка степен“, но го смята за управляемо и не го вижда като финансова заплаха. Според IGN част от тревогата е свързана със сигурността на PS5: homebrew сцената работи по jailbreak-ове за по-нов фърмуер, а GTA 6 се очаква да изисква актуален фърмуер. Зелник не каза кога GTA 6 официално ще излезе на PC. Според Insider Gaming (позовавайки се на Variety) той посочи, че такава информация винаги идва от лейбъла, тоест от Rockstar; същото важи и за евентуална версия на диск. При старта GTA 6 излиза само за PS5 и Xbox Series X|S. Бивш технически директор на Rockstar North наскоро предположи, че Rockstar може да ускори PC порт по тази причина, но това не е потвърдено.", "weitere_links": ["Insider Gaming"], "_src": "a25dcecd"}, "2026-11-10-sega-newsletter-leak": {"titel": "SEGA: атака срещу доставчика на бюлетини ARARA разкрива около 2,2 милиона имейл адреса", "schlagzeile": "Изтичане на данни при SEGA: 2,2 млн. имейл адреса откраднати от доставчик", "kurz": "При атака срещу японския доставчик на бюлетини ARARA са изтекли около 2,2 милиона имейл адреса на клиенти на SEGA. Според SEGA имена, пароли и платежни данни не са засегнати, нито акаунтите в SEGA. Клиентите трябва да внимават за фалшиви имейли от името на SEGA.", "zusammenfassung": "SEGA потвърди на 9 ноември изтичане на данни при своя доставчик на бюлетини ARARA. Засегнати са 2 196 044 имейл адреса; при 92 273 от тях са изтекли и данни, свързани с изпращането, като какво точно – още се проучва. Според SEGA става дума за единадесет бюлетина на SEGA и SEGA Fave, изпратени между юли и октомври 2026 г., например за аркадни игри като CHUNITHM и maimai, за Tokyo Game Show и за лотарийни акции. Според SEGA имена, дати на раждане, адреси, телефонни номера, данни за кредитни карти и пароли не са засегнати. Имейл адресите от SEGA Account също минават през друга система и не са част от изтичането. Злоупотреба с данните засега не е потвърдена. Самата ARARA съобщи за пробива в началото на ноември; според BleepingComputer и Infosecurity Magazine там общо са засегнати около 77 милиона имейл адреса на около 380 корпоративни клиенти, очевидно чрез уязвимост в уеб сървъри. SEGA спря изпращането чрез ARARA и ще информира засегнатите поотделно. Който е получавал бюлетини на SEGA, трябва да внимава особено за фишинг в имейли, свързани със SEGA.", "weitere_links": ["SEGA (съобщение, на японски)", "Infosecurity Magazine"], "_src": "ba66609c"}, "2026-11-10-take-two-gta6-vorbestellungen": {"titel": "Take-Two: предварителните поръчки за GTA 6 далеч надхвърлят очакванията, до 3,5 млрд. долара в тримесечието на старта", "schlagzeile": "GTA 6: предварителни поръчки „далеч над очакванията“ – Take-Two чака рекорд", "kurz": "Десет дни преди старта на GTA 6 Take-Two съобщава за предварителни поръчки на „безпрецедентно“ ниво. За текущото тримесечие компанията очаква net bookings от 3,35 до 3,5 млрд. долара. Конкретни числа за предварителните поръчки Take-Two все още не дава.", "zusammenfassung": "Take-Two представи на 9 ноември резултатите си за второто тримесечие на финансовата 2027 година, а GTA 6 беше в центъра на вниманието. Според главния изпълнителен директор Строс Зелник предварителните поръчки са „далеч над очакванията“ и продължават да достигат „безпрецедентни“ нива, съобщават Insider Gaming, Eurogamer и PC Gamer. За текущото трето тримесечие, в което попада стартът на 19 ноември, Take-Two очаква net bookings от 3,35 до 3,5 млрд. долара. Според PC Gamer това дори е малко под оценката на анализаторите от 3,51 млрд. долара (LSEG, чрез Reuters). За цялата финансова 2027 година компанията очаква 8 до 8,2 млрд. долара. Take-Two все още не дава конкретни числа за предварителните поръчки, защото суровите данни без сравнение биха могли да заблудят. Изминалото тримесечие беше по-слабо: net bookings от 1,6 млрд. долара бяха под очакванията и с 18 процента под миналогодишните. Една от причините е NBA 2K27, която стартира добре, но остана под прогнозата; Зелник вижда очакването за GTA 6 като една от причините. Take-Two даде и нови данни за продажби: GTA 5 е на около 235 милиона копия, а Red Dead Redemption 2 наближава 90 милиона. Поредицата GTA като цяло има почти 480 милиона продадени бройки.", "weitere_links": ["PC Gamer", "Eurogamer", "Insider Gaming (GTA 5)", "Insider Gaming (RDR2)"], "_src": "38d7088e"}, "2026-11-10-skydance-games-entlassungen": {"titel": "Skydance Games съкращава служители и орязва проекти – месец след сливането на Paramount и Warner Bros.", "schlagzeile": "След мегасливането: Skydance Games съкращава разработчици и орязва проекти", "kurz": "Skydance Games съкрати работни места и „намали някои проекти“. Това става месец след сливането на Paramount и Warner Bros. Discovery. Компанията не казва колко души са засегнати.", "zusammenfassung": "Skydance Games потвърди съкращения, съобщават IGN и PC Gamer, позовавайки се на изявление пред Variety. Компанията е решила да намали някои проекти и затова има засегнати позиции; това не е оценка на таланта или отдадеността на засегнатите. Първи за напускането си съобщиха служители на Paramount Games Studio, основано едва през юни. Към Paramount Games спадат, наред с други, Skydance Interactive и Skydance New Media. Там наскоро бяха обявени игри като Teenage Mutant Ninja Turtles: The Last Ronin, както и адаптации на Yellowstone, Tulsa King и Lioness. Не е известно кои проекти се орязват. Skydance не казва колко работни места отпадат; според Insider Gaming засегнати са поне 30 разработчици, вероятно повече. Съкращенията идват около месец след одобрението на сливането на Paramount и Warner Bros. Discovery под шапката на Skydance. Какво означава това за подразделението Warner Bros. Games, остава открито.", "weitere_links": ["PC Gamer"], "_src": "a7836025"}, "2026-11-10-rdna5-gfx13-linux": {"titel": "AMD публикува пачове за Linux драйвера за GFX13 – графичното IP от следващо поколение (вероятно RDNA 5)", "schlagzeile": "RDNA 5 наближава: AMD изпраща първите Linux драйвери за GFX13", "kurz": "AMD публикува над 12 600 реда код за драйвера на Linux ядрото за GFX13, следващото поколение графика Radeon. Най-вероятно става дума за RDNA 5. Засега пачовете не разкриват нови подробности за производителност или функции.", "zusammenfassung": "Разработчикът на AMD Алекс Дойхер публикува серия пачове, които подготвят драйвера на Linux ядрото AMDGPU за GFX13, съобщават Phoronix и VideoCardz. GFX13 е следващото графично IP на AMD и много вероятно означава RDNA 5; AMD не е потвърдила официално името. Осемте пача съдържат над 12 600 реда код, без обичайните големи заглавни файлове. Те включват и поддръжка за конкретните варианти GFX 13.0.1 и GFX 13.0.4. Според Phoronix засега пачовете разкриват малко за възможностите или новите функции на RDNA 5. За компилатора LLVM пачове за GFX13 имаше още от началото на годината, сега следва драйверът за ядрото. Phoronix очаква поддръжката в Linux ядро 7.5. Други блокове, които вероятно ще са част от RDNA 5 GPU, като Display Core Next 6, вече са в ядрото. AMD често публикува ранни Linux драйвери месеци преди пускането на пазара; AMD не дава дата за видеокарти с RDNA 5.", "weitere_links": ["VideoCardz"], "_src": "c780eb89"}, "2026-11-10-nvidia-megaspeed-nyt": {"titel": "Доклад на NYT: NVIDIA се е намесила в разследване в САЩ срещу заподозрения контрабандист на ИИ чипове Megaspeed", "schlagzeile": "Доклад: NVIDIA е забавила разследване за контрабанда на чипове", "kurz": "Според New York Times главният юрисконсулт на NVIDIA се е обърнал директно през 2025 г. към Министерството на търговията на САЩ, което разследваше фирмата Megaspeed за предполагаема контрабанда на чипове към Китай. Разследването засяда и е предадено на Министерството на правосъдието. Става дума за медиен доклад; нямаме позиция на NVIDIA.", "zusammenfassung": "След новината за разследването на борда на NVIDIA около главния изпълнителен директор Дженсън Хуанг идва нов натиск: според Wccftech New York Times пише за ролята на NVIDIA в разследванията срещу фирмата Megaspeed. Компанията за центрове за данни със седалище в Сингапур беше подозирана, че служи като параван, за да вкарва контрабандно ИИ ускорители на NVIDIA в Китай, заобикаляйки американския експортен контрол. Megaspeed се ръководи от Алис Хуанг, която според американските разузнавателни служби е работила за Пекин; това е същата жена, с която Дженсън Хуанг призна за връзка. Според доклада главният юрисконсулт на NVIDIA Тим Тетър се е обърнал директно през 2025 г. към Bureau of Industry and Security към Министерството на търговията. Той се е позовал на това, че номинираният от Тръмп Джеф Кеслър му е разрешил този пряк контакт. Няколко служители са възприели това като сериозно нарушение на обичайните процедури. След това разследването засяда и е предадено на Министерството на правосъдието. Разговорите на фирмени адвокати с ведомства сами по себе си са нормални; спорно според доклада е естеството на контакта. Според Wccftech на 18 ноември Хуанг предстои закрито изслушване в Конгреса на САЩ. Обвиненията идват от медийни публикации; нямахме позиция на NVIDIA по тях.", "_src": "12d2733c"}, "2026-11-09-dark-heresy-release": {"titel": "Warhammer 40,000: Dark Heresy на Owlcat излиза на 28 януари 2027 г. за PC, PS5 и Xbox Series", "schlagzeile": "Warhammer 40k: Dark Heresy има дата – излиза на 28 януари 2027 г.", "kurz": "Owlcat Games обяви датата на излизане на Warhammer 40,000: Dark Heresy. Тактическата ролева игра излиза на 28.01.2027 за PC, PS5 и Xbox Series X/S, а версия за Switch 2 ще последва по-късно. Играете като инквизитор, който преследва еретици.", "zusammenfassung": "Owlcat Games обяви с прессъобщение и трейлър датата на излизане на тактическата си ролева игра Warhammer 40,000: Dark Heresy, съобщават Eurogamer и GameStar. Играта излиза на 28 януари 2027 г. за PC, PlayStation 5 и Xbox Series X/S. Дата за Switch 2 ще бъде обявена „на по-късен етап“. Dark Heresy надгражда Warhammer 40,000: Rogue Trader, който Owlcat издаде преди няколко години. Този път играете като инквизитор, който издирва еретици и тъмни влияния в 41-вото хилядолетие. Според Eurogamer Owlcat е преработила много от основните системи. От известно време тече бета с целия първи акт, достъпна за купувачите на Founders Edition. Бетата ще бъде изключена на 7 януари, докато Owlcat подготвя играта за старта. Eurogamer припомня, че Rogue Trader беше хвален за света и битките, но при излизането си имаше проблеми с бъгове и слаба производителност. Затова тепърва ще се види как ще работи Dark Heresy при старта. Паралелно Owlcat работи по ролева игра по научнофантастичната поредица The Expanse.", "weitere_links": ["GameStar"], "_src": "e9845177"}, "2026-11-09-ps-portal-speicher-japan": {"titel": "Sony пуска в Япония нов модел PlayStation Portal с вградена памет за бъдещи функции", "schlagzeile": "Нов PS Portal със собствена памет – Sony намеква за още функции", "kurz": "Sony пуска в Япония на 10.12.2026 нов модел PlayStation Portal с вградена памет. Според Sony Japan паметта е предвидена за бъдещи функции, а подробностите ще бъдат обявени по-късно. Цената остава 39 980 йени, предварителните поръчки започват на 13.11.2026, а дали моделът ще дойде и в Европа, не е ясно.", "zusammenfassung": "Sony пуска в Япония обновен модел на PlayStation Portal, съобщава IGN, позовавайки се на официалния блог на Sony Japan. Най-важната разлика спрямо досегашното устройство е вградената памет. Sony пише, че я е добавила с оглед на бъдещи функции и ще съобщи подробности, когато бъдат уточнени. Какви ще са тези функции, Sony все още не казва. Едновременно с това Sony променя официалното японско име от „PlayStation Portal Remote Player“ на „PlayStation Portal Player“. В блога Sony подчертава също, че дори играчи без PS5 могат да играят PS5 игри на Portal; това се отнася до облачния стрийминг за абонатите на PS Plus Premium, който Sony въведе миналата година. IGN тълкува паметта и смяната на името като възможна стъпка от обикновен аксесоар за Remote Play към по-самостоятелна преносима конзола; това е оценка, а не обявление на Sony. Новият модел излиза в Япония на 10 декември, предварителните поръчки започват на 13 ноември, а цената остава 39 980 йени. Той е само на японски и изисква японски PSN акаунт. Дали и кога ще излезе в други региони, не е известно.", "_src": "e6a33542"}, "2026-11-09-sshole-angriffe": {"titel": "Уязвимостта в OpenSSH „SSHole“ (CVE-2026-123158) се използва активно, нападатели получават root на системи с Alpine", "schlagzeile": "Уязвимостта „SSHole“ в OpenSSH вече се атакува – обновете Alpine сървърите", "kurz": "Уязвимостта в OpenSSH на системи с musl като Alpine Linux, за която писахме на 05.11.2026, вече се използва активно. Няколко фирми за сигурност съобщават за атаки, а в един honeypot нападателите са получили root достъп. Уязвимостта вече се нарича „SSHole“ (CVE-2026-123158); решението е OpenSSH 10.6p2 и рестарт на sshd след това.", "zusammenfassung": "Уязвимостта в OpenSSH, за която писахме на 5 ноември, вече се атакува активно, съобщават BleepingComputer, SecurityWeek и The Hacker News. Тя вече носи прякора „SSHole“ и идентификатора CVE-2026-123158 (CVSS 8.1). Засегнат е OpenSSH преди версия 10.6p2 на Linux системи с C библиотеката musl без PAM, например стандартната конфигурация на Alpine Linux; откривателят посочва за проверка и OpenWrt, Buildroot, Yocto и много Docker образи. С много дълга парола от 257 до 1024 байта нападателите могат да влязат в акаунти, които изобщо не би трябвало да приемат парола. Според BleepingComputer опитите за атаки са започнали на 5 ноември, когато няколко часа след поправката се появи proof of concept. Фирмата Previdian потвърждава успешен root достъп на собствен honeypot с истински Alpine Linux и до 8 ноември е отчела 20 опита от 13 IP адреса от девет държави. GreyNoise регистрира първото успешно използване в реална среда на 7 ноември и наблюдава 16 успешни вериги на атака: нападателите проучваха системата и контейнерите, запитваха облачни метаданни, опитваха да прочетат хешове на пароли и root SSH ключове и да добавят свои ключове за постоянен достъп. Решението е OpenSSH 10.6p2 или поправеният пакет на дистрибуцията; Alpine публикува пакети за всички клонове от 3.16 нататък. Важно: след обновяването sshd трябва да се рестартира, иначе продължава да работи старата версия; според watchTowr засега уязвимостта използват основно ботнети и криптомайнъри. Като незабавна мярка помага PasswordAuthentication no. Администраторите трябва също да проверят логовете за неочаквани записи „Accepted password for“ при акаунти без парола и за непознати SSH ключове.", "weitere_links": ["SecurityWeek", "The Hacker News", "Help Net Security"], "_src": "36ee778e"}, "2026-11-09-gta6-festival-miami": {"titel": "Rockstar обявява „Grand Theft Auto VI: The Festival“ на 21 ноември в Маями с Travis Scott, Cardi B и Justice", "schlagzeile": "GTA 6 получава собствен музикален фестивал – с Travis Scott и Cardi B", "kurz": "Rockstar отбелязва старта на GTA 6 с музикален фестивал в Маями. „Grand Theft Auto VI: The Festival“ ще се проведе на 21.11.2026 в Mana Wynwood, сред изпълнителите са Travis Scott, Cardi B, Kodak Black и Justice. Билетите се разпределят чрез лотария, а самата игра излиза на 19.11.2026.", "zusammenfassung": "Rockstar Games обяви в X музикален фестивал за старта на GTA 6, съобщават VGC и Eurogamer. „Grand Theft Auto VI: The Festival“ ще се проведе на 21 ноември в Mana Wynwood в Маями, два дни след излизането на играта на 19 ноември. Според Rockstar ще излязат артисти от играта и от официалния саундтрак. Потвърдени според VGC са сред други Travis Scott, Don Toliver, Kodak Black, Sofaygo, Cardi B, Ca7riel и Paco Amoroso, Justice, Metro Boomin, Rauw & Friends, Suero и Tainy, както и няколко DJ сета в дуо. Билетите се продават чрез платформата DICE и се разпределят чрез лотария. Според Rockstar трябва да се регистрирате за лотарията за предварителна продажба до вторник, 10 ноември, 16:00 ч. източно време в САЩ (22:00 ч. в Австрия); шансът за билети идва в сряда в 12:00 ч. източно време (18:00 ч. при нас). За играта излизат два саундтрака на CD, винил и в стрийминг услугите: „GTA 6: The Album“ с 34 нови песни на 19 ноември, сред които с Travis Scott и Keith Richards, и на 11 декември „Grand Theft Auto VI: Original Score“ с 30 композиции на френското електронно дуо Justice.", "weitere_links": ["Rockstar Games в X", "Rockstar Games в X (лотария за билети)", "Eurogamer"], "_src": "31cad77d"}, "2026-11-09-amd-ssd-fix-26-11-1": {"titel": "AMD потвърждава постоянен запис върху SSD заради драйвера Radeon, поправката се очаква с Adrenalin 26.11.1", "schlagzeile": "Драйверът Radeon изяжда живота на SSD: поправка се очаква с 26.11.1", "kurz": "Допълнение към новината ни от 08.11.2026: според TechPowerUp и PC Gamer грешката, при която услуга на драйвера Radeon постоянно пише върху SSD, ще бъде поправена с Adrenalin 26.11.1. Според TechPowerUp засегнати са версиите 26.10.1 и 26.10.2, а дата за новия драйвер все още няма. Потребители съобщават за спад на здравето на SSD с около 1 процент на месец.", "zusammenfassung": "За грешката в драйвера Radeon с постоянен запис върху SSD, за която писахме на 8 ноември, се очертава решение. Според TechPowerUp AMD е потвърдила, че са засегнати драйверите Adrenalin 26.10.1 и 26.10.2 и че поправката ще дойде с версия 26.11.1. PC Gamer цитира представителя на AMD AMD_Vik в Reddit, според когото проблемът „би трябвало да е поправен“ в 26.11.1; точна дата няма, но според PC Gamer драйверът се очаква в рамките на месеца. Виновникът е услугата atieclxx.exe от AMD External Events Utility, която отговаря например за разпознаването на монитори и клавишните комбинации на софтуера Radeon и явно записва данни в безкраен цикъл. Съобщава се за 0,3 до 1,5 MB/s, а един потребител в Reddit посочва постоянни 5 MB/s. Потребител в X е измерил 19,5 GB запис за 12 часа и смята, че грешката съществува от Adrenalin 26.7.1 от юни. В Reddit потребители съобщават, че здравето на SSD-то им пада с около 1 процент на месец заради това; това са потребителски наблюдения, а не измервания на AMD. Не всяка система е засегната, а PC Gamer не успя да възпроизведе грешката. Като временно решение TechPowerUp посочва изключване на AMD External Events Utility, което може да причини проблеми с картината, или изключване на Resizable BAR, което може да струва производителност. TechPowerUp по-скоро съветва да се изчака официалният драйвер.", "weitere_links": ["PC Gamer", "ComputerBase"], "_src": "fc743806"}, "2026-11-09-amdlss5-2-radeon": {"titel": "Модът AMDLSS5 2.0 носи невронно рендериране в стил DLSS 5 на картите Radeon със собствен енджин", "schlagzeile": "Мод носи невронното рендериране на DLSS 5 на Radeon – вече много по-бързо", "kurz": "Неофициалният мод AMDLSS5 излезе във версия 2.0 и има за цел да донесе невронно рендериране в стил DLSS 5 на картите Radeon. Според разработчика вече работи на собствен енджин и е значително по-бърз от други модове. Измерванията са само от разработчика. Модът няма нищо общо с AMD или NVIDIA.", "zusammenfassung": "Wccftech съобщава за версия 2.0 на общностния мод AMDLSS5 от разработчика Wehaveall. Той цели да донесе на картите AMD Radeon невронно рендериране в стил DLSS 5, тоест подобрения с изкуствен интелект на осветлението и материалите, като се включва в съществуващите DirectX 12 вериги за мащабиране. Новото е собствен енджин, който заменя досегашната зависимост от друг мод и би трябвало да има по-малко натоварване. В публикация в Reddit разработчикът показва резултати от PresentMon в Resident Evil Requiem в 4K с FSR на RX 9070 XT: средно 101,2 fps и 78,5 fps при 1% low, срещу 91,3 и 66,0 с версия 1.6.1 и 61,6 и 55,5 с други модове. Оттам идват рекламираните 64 процента повече fps, но само в сравнение с други модове, а не с играта без мод или с истинския DLSS 5 на NVIDIA. Това са данни на разработчика от една сцена с една карта; независими тестове още няма. Нова поддръжка получават PRAGMATA, Nioh 3 и GTA V Enhanced, последната само в офлайн режим на историята с изключен BattlEye. Основни цели са RX 9070 и RX 9070 XT; серията RX 9060 би трябвало теоретично да работи, а картите RX 7000 имат експериментална алфа поддръжка, но според Wccftech разработчикът не е проверил нито едното на реален хардуер. Добавени са и 39 цветови профила, локално тонално картографиране, подобрени ambient occlusion и непряко осветление, както и преработено 2x генериране на кадри в избрани игри. Модът е безплатен в GitHub, но изходният код на новия енджин още не е публикуван.", "_src": "23e75a0d"}, "2026-11-09-amazon-us-amd-vor-nvidia": {"titel": "Amazon САЩ през октомври: AMD продава повече видеокарти от NVIDIA, RX 9070 XT е най-продавана", "schlagzeile": "Amazon САЩ: AMD продаде повече видеокарти от NVIDIA през октомври", "kurz": "Според данните за продажбите в Amazon САЩ за октомври 2026 г. AMD е продала малко повече видеокарти от NVIDIA: около 9200 срещу 8900 броя. Най-продаваната карта е Radeon RX 9070 XT с около 3300 броя. NVIDIA все пак има повече приходи заради по-високите средни цени. Данните са от събирач на данни, а не от производителите.", "zusammenfassung": "Wccftech съобщава за данни за продажбите в Amazon САЩ за октомври 2026 г., събрани от TechEpiphany. Според тях AMD е продала там през октомври с малко най-много видеокарти: около 9200 броя срещу около 8900 за NVIDIA. Според Wccftech това е забележително, защото Amazon САЩ обикновено е доминиран от NVIDIA, докато AMD по-често води например в Германия. По приходи NVIDIA остава напред, тъй като средната ѝ продажна цена е 1313 долара срещу 915 долара за AMD. Най-продавана е Radeon RX 9070 XT с около 3300 броя; RTX 5070 Ti достига едва около една трета от това. Второ място заема RTX 5060 Ti (8 и 16 GB заедно) с около 2250 броя, следвана от RX 9060 XT с около 2150. RTX 5070 остава под 2000 броя, а RTX 5090 стига само до около 150 заради слабата наличност. Дори старата Arc A380 се е продала повече – около 500 броя. Според данните Intel достига около 6,22 процента дял благодарение на Arc B570, B580 и картите Arc Pro. Wccftech смята, че силно повишените цени са основната причина купувачите да избират по-евтини карти. Важно: данните обхващат само един магазин в САЩ и не идват от AMD, NVIDIA или Amazon; затова са само моментна картина, а не пазарни дялове за целия пазар.", "_src": "1307b37c"}, "2026-11-09-bit-reactor-entlassungen": {"titel": "Star Wars Zero Company: студиото Bit Reactor съкращава служители въпреки добрите отзиви и милион продажби", "schlagzeile": "Star Wars Zero Company: студиото съкращава хора – въпреки хита и 84 точки", "kurz": "Bit Reactor, студиото зад Star Wars Zero Company, е съкратило служители. VGC съобщава това въз основа на публикации в LinkedIn на засегнати разработчици. А играта получи добри отзиви и според EA е продадена в един милион копия. Колко работни места са засегнати, не е ясно.", "zusammenfassung": "Bit Reactor, разработчикът на Star Wars Zero Company, е съкратил служители, съобщава VGC, позовавайки се на сайта Bespin Bulletin. Няколко разработчици, сред които старши environment artist, UI инженер, продуцент и старши QA анализатор, са написали през последните дни в LinkedIn, че са засегнати. Колко позиции общо отпадат, не е известно. Според съобщения преди излизането през август студиото е пуснало в неплатен отпуск около 80 процента от служителите си, защото парите са свършвали. През октомври шефът на студиото Greg Foertsch каза, че част от тях се връщат; според съобщения така студиото отново е достигнало над половината от предишния си размер. Не е ясно дали сега са засегнати и завърнали се служители или само хора, които не са били върнати след отпуска. Поне един засегнат пише, че е съкратен след три месеца отпуск. Горчиво е, защото Star Wars Zero Company излезе в края на август с много добри отзиви и има 84 точки в Metacritic. На 9 октомври официалният акаунт EA Star Wars съобщи за един милион продадени копия. VGC не цитира официално становище на Bit Reactor за съкращенията.", "weitere_links": ["GameStar"], "_src": "52d9b77e"}, "2026-11-09-notepadpp-7zip-luecken": {"titel": "Notepad++ 8.9.9 затваря шест уязвимости, 7-Zip 26.06 поправя неуточнени уязвимости", "schlagzeile": "Notepad++ и 7-Zip: обновления запушват дупки в сигурността – обновете сами", "kurz": "Notepad++ 8.9.9 затваря шест уязвимости, като най-сериозната е с висок риск. Според разработчика 7-Zip 26.06 също поправя уязвимости, но без подробности. 7-Zip няма функция за обновяване, затова трябва да го обновите сами. В Windows това става лесно с winget.", "zusammenfassung": "Два широко използвани инструмента за Windows получиха обновления за сигурност, съобщава heise online. Notepad++ 8.9.9 на разработчика Don Ho затваря шест уязвимости. Най-сериозна е препълване на буфер в heap паметта в SAML декодера на плъгина mimeTools: подправени SAML съобщения биха могли при декодиране да презапишат паметта и евентуално да изпълнят зловреден код. Бюлетинът оценява риска като висок, но не посочва CVSS оценка. Останалите пет уязвимости се считат за средни, като според heise някои от тях вероятно позволяват повишаване на правата в системата, например чрез UAC записването на защитени файлове или съобщения между прозорци. CVE номера още няма. Освен това версията ускорява търсенето във файлове и обновява компонента на редактора Scintilla до 5.6.9. Notepad++ има собствена проверка за обновления; алтернативно помага winget update Notepad++.Notepad++. Архиваторът 7-Zip излезе през уикенда във версия 26.06. Разработчикът Igor Pavlov пише само, че са поправени някои грешки и уязвимости, без да казва кои и колко сериозни. Той е подобрил и поддръжката на файлове, разделени с Linux инструмента split. Тъй като 7-Zip не проверява за обновления, потребителите трябва сами да изтеглят новата версия или в Windows да използват winget upgrade 7zip.7zip. heise препоръчва с winget upgrade --all да се инсталират наведнъж всички налични обновления.", "weitere_links": ["heise online (7-Zip)"], "_src": "2abed807"}, "2026-11-09-sonicwall-sslvpn-angriffe": {"titel": "SonicWall: атакува се уязвимост в SSLVPN, обновленията на фърмуера поправят седем пробива", "schlagzeile": "Защитни стени SonicWall: VPN уязвимост се атакува – обновете веднага", "kurz": "Нападатели очевидно използват уязвимост в SSLVPN на защитните стени SonicWall, с която може да се заобиколи SAML вписването, а с него и многофакторното удостоверяване. SonicWall и американската агенция CISA съветват бързо обновяване. SSLVPN е уязвим само ако SAML е включен за VPN вписване. Новият фърмуер поправя общо седем уязвимости.", "zusammenfassung": "SonicWall публикува в петък бюлетин за сигурност за седем уязвимости в SonicOS, съобщава heise online. За една от тях производителят допуска, че вече може да е използвана при атаки; американската агенция за сигурност CISA също предупреждава. Става дума за CVE-2026-19868 (CVSS 7.1, висок риск): който има валидни данни за вход за друг метод на вписване, може с нея да заобиколи SAML удостоверяването, което се използва например за единно вписване. Така очевидно може да се заобиколи и многофакторното удостоверяване, наложено чрез SAML. Според SonicWall SSLVPN е уязвим само ако SAML е включен за SSLVPN вписвания. Поправката е SonicOS 7.3.4-7013 за защитни стени Gen7 и 8.2.3-8015 за устройства Gen8, както и по-новите версии. Обновленията затварят още шест уязвимости, сред тях две с CVSS 8.8, свързани с междудомейн политики и проверка на сесии, и препълване на буфер в heap в SSL-VPN, което може да се задейства без удостоверяване (CVSS 7.5). Към тях се добавят две препълвания на буфер в TACACS+ и слабо хеширане на пароли при виртуални устройства, всички със среден риск. heise напомня, че SonicWall още в началото на октомври съобщи за критична уязвимост с максимална оценка в устройствата SMA1000. Засегнати са предимно фирми и администратори; който поддържа защитна стена SonicWall у дома или в офиса, трябва да обнови фърмуера сега.", "_src": "6679ffee"}, "2026-11-08-windows11-app-updates": {"titel": "Windows 11 тества централна страница за обновления на приложения от трети страни", "schlagzeile": "Край на изскачащите прозорци? Windows 11 тества общи обновления", "kurz": "В предварителна версия на Windows 11 26H2 в Настройките се появи нова страница „Обновления на приложения“. Тя трябва да събира на едно място обновленията на програми от трети страни, като браузъри или медийни плейъри, вместо всяко приложение да показва свои известия. Това ще работи само ако разработчиците регистрират приложенията си. При теста на Windows Latest още нямаше нито един регистриран доставчик.", "zusammenfassung": "Windows Latest откри в предварителна версия на Windows 11 26H2 страница „Обновления на приложения“ в Настройки > Приложения. Страницата вече се беше появявала за кратко през декември 2025 г. и сега се появи отново, което според Windows Latest подсказва скорошно пускане. Целта е обновленията на програми извън Microsoft Store да се събират на едно място, вместо всяко приложение да показва свои изскачащи прозорци, както навремето прочутият обновител на Java. Основата е „Windows Update Orchestration Platform“, която Microsoft представи през 2025 г. Разработчиците могат да регистрират там приложенията си като доставчици и да запазят собствените си сървъри и инсталатори за обновления; Windows поема само координацията. Ще се поддържат MSIX и APPX пакети, както и класически Win32 програми. За регистрация разработчиците трябва да предоставят скрипт или програма, която търси обновления; по подразбиране Windows изпълнява тази проверка на всеки 22 часа. Windows ще планира инсталирането подобно на системните обновления, като отчита използването, батерията и мрежата, за да не прекъсва работата. На тестовия компютър на Windows Latest обаче страницата съобщаваше, че няма регистриран доставчик на приложения, дори самата Microsoft за Teams или Outlook, а бутонът за проверка на обновления беше неактивен. Следователно това е функция в тестов етап, която още не може да се използва. Дали наистина ще помогне, зависи от това колко разработчици ще се включат; Microsoft не иска да принуждава никого. Microsoft не е обявила дата на пускане.", "_src": "06466579"}, "2026-11-08-nvidia-board-untersuchung-huang": {"titel": "Бордът на NVIDIA започва независимо разследване относно главния изпълнителен директор Дженсън Хуанг", "schlagzeile": "Бордът на NVIDIA започва разследване – CEO признава афера", "kurz": "Бордът на директорите на NVIDIA започна независимо разследване, след като медии съобщиха, че главният изпълнителен директор Дженсън Хуанг е бил мишена на чуждо разузнаване. В съобщение до служителите, публикувано от NVIDIA, Хуанг призна, че е изневерил на съпругата си. Според борда засега няма причина да се смята, че националната сигурност или фирмени тайни са компрометирани. Хуанг остава CEO.", "zusammenfassung": "Вечерта на 8 ноември 2026 г. NVIDIA публикува две изявления. В първото бордът обявява независимо разследване: комисия от независими директори с помощта на външни адвокати ще провери дали основателят и CEO Дженсън Хуанг е бил мишена на дейност на чуждо разузнаване. Бордът пише, че няма причина да смята, че националната сигурност или тайни на NVIDIA са компрометирани, но ще разгледа цялата налична информация. Хуанг подкрепя проверката и ще сътрудничи; бордът изразява доверие в него и в ръководния му екип. Във второто изявление, съобщение до служителите, публикувано първо от Axios, Хуанг се извинява на семейството си и на служителите и признава, че е изневерил на съпругата си. Предисторията са материали на Financial Times и New York Times от предходните дни. Според тях меморандум, основан на информация от американското разузнаване, приписва на Хуанг връзка с жена на име Алис Хуанг, бивш ръководител в Megaspeed, клиент на NVIDIA; според тези материали американските служби я смятали за информатор на Министерството на държавната сигурност на Китай. Въпреки еднаквата фамилия двамата не са роднини, според материалите. Нито меморандумът, нито основанията му са публични, а нито Хуанг, нито бордът коментират по същество обвиненията в шпионаж; според Axios съобщението на Хуанг не споменава Алис Хуанг. Следователно изявлението на борда не потвърждава обвиненията. Според NYT целта е била да се научи повече за американските AI чипове. Говорителят на NVIDIA Джон Рицо е заявил, според ComputerBase, че събитията няма да забавят работата на компанията. Не е ясно кога ще има резултати от разследването; бордът ще информира при необходимост.", "weitere_links": ["heise online", "IGN"], "_src": "ae83deda"}, "2026-11-08-layden-ps5-300": {"titel": "Бившият шеф на PlayStation Шон Лейдън: Sony има нужда от PS5 за 300 долара, а не от PS6 за 1200", "schlagzeile": "Бивш шеф на PlayStation: не PS6 за 1200 $, а PS5 за 300 $", "kurz": "Бившият шеф на PlayStation Шон Лейдън съветва Sony вместо скъпо PS6 да направи значително по-евтино PS5. „Иновацията не трябва да идва от PS6 за 1200 долара, а от още едно PS5 за 300 долара“, каза той в подкаста The Trophy Room. Според него PS5 е първата платформа, която с времето е поскъпнала. Това не казва нищо за официалните планове за PS6.", "zusammenfassung": "Шон Лейдън, бивш президент и CEO на Sony Interactive Entertainment America, коментира следващото PlayStation в подкаста The Trophy Room, съобщава IGN. Според него PS6, която залага основно на повече рейтрейсинг и повече терафлопа, не носи достатъчно истинска иновация. „Мисля, че имаме достатъчно мощ в машината“, каза Лейдън. За него истинската иновация не би била PS6 за 1200 долара, а още едно PS5 за 300 долара. Той припомни, че PS2 се е продавало за 99 долара в края на живота си, докато PS5 е първата платформа, която според него с времето поскъпва. Sony трябвало да направи конзолата по-малка и по-евтина; чипът и операционната система са достатъчно добри за игрите, които хората искат да играят. IGN дава контекст: при старта преди шест години PS5 струваше 499 долара в САЩ, а Digital Edition – 399 долара. Директно от PlayStation стандартната версия днес струва 649, Digital Edition – 599, а PS5 Pro – 899 долара. Sony обяснява поскъпванията с трудната икономическа среда. Официална информация за PS6 има малко: през май Sony каза, че още решава кога да я пусне, а доклад от февруари говореше за възможно отлагане до 2028 или 2029 г. Лейдън отдавна не е в Sony; думите му са лично мнение, а не информация за плановете на Sony. Конкретна цена на PS6 не е известна; 1200-те долара са изострен пример на Лейдън.", "_src": "5da916e2"}, "2026-11-08-amd-radeon-ssd-writes": {"titel": "AMD потвърждава грешка в драйвера Radeon, която постоянно пише на SSD", "schlagzeile": "Драйверът Radeon пише непрекъснато на SSD-то в покой", "kurz": "Някои потребители на карти AMD Radeon съобщават, че графичният драйвер постоянно пише върху системния SSD дори когато компютърът е в покой. За виновен се сочи процесът atieclxx, тоест AMD External Events Client Module. Според Wccftech и Neowin AMD е признала проблема и работи по поправка; тя не фигурира в бележките към Adrenalin 26.10.2 от 30.10.2026 г. Не всяка система изглежда засегната и не е доказано колко реално скъсява това живота на SSD.", "zusammenfassung": "На 8.11.2026 г. Wccftech и Neowin съобщиха за грешка в графичните драйвери Radeon на AMD, която може да предизвика постоянни записи върху системния диск, дори когато компютърът не прави нищо друго. За спусък се сочи процесът atieclxx, AMD External Events Client Module, който принадлежи към AMD External Events Utility и сред другото управлява смяна на монитори, бързи клавиши и FreeSync. Данните на потребителите често са между около 0,3 и 1,5 мегабайта в секунда, отделни доклади споменават около 5 мегабайта в секунда. При непрекъснати 5 MB/s това теоретично прави около 432 гигабайта хост записи на ден; Wccftech подчертава, че това е горна граница при постоянна натовареност и не съответства автоматично на обема, реално записан в NAND. Според репортажите не е доказано дали и колко грешката скъсява живота на SSD. Проблемът не бил съвсем нов и се появявал под Windows 10 и Windows 11 на различни карти Radeon и версии на Adrenalin; някои компютри с актуалния драйвер 26.10.2 според потребители изобщо не показват необичайно натоварване. Служител на AMD с име AMD_Matt през октомври потвърдил поведението като истински проблем, който се разследва. Друг представител, AMD_Vik, по-късно дал сигнал, че поправка вероятно вече е внесена, но може да е изпуснала срока за следващата версия на драйвера. Adrenalin Edition 26.10.2, излязла на 30.10.2026 г., не споменава грешката в официалните бележки към версията. Neowin добавя, че AMD е посочила връзка с PCIe филтъра на Microsoft и Resizable BAR. Като заобиколни решения и двете издания посочват временно спиране на услугата AMD External Events Utility през управлението на услугите на Windows или изключване на Resizable BAR; и двете могат да засегнат FreeSync, бързите клавиши на Adrenalin или производителността в игрите. Някои потребители обаче съобщават, че FreeSync и ReBAR са продължили да работят след спирането на услугата. Който иска да провери дали собственият му компютър е засегнат, трябва в Монитора на ресурсите, раздел Диск, да търси постоянна записваща активност от atieclxx. Според репортажите още няма обновление на драйвера с поправката.", "weitere_links": ["Neowin"], "_src": "f2340f0a"}, "2026-11-08-gpu-preise-plus40": {"titel": "Цени на видеокарти: средно почти 40 процента нагоре от август", "schlagzeile": "Видеокартите са почти 40% по-скъпи от август", "kurz": "GameStar сравни актуалните цени на видеокарти: от август 2026 г. следените модели са поскъпнали средно с почти 40 процента. Между януари и август промяната без RTX 5090 все още беше около три процента. Според анализа самата RTX 5090 е скочила от около 3000 евро през януари през 4350 евро през август до сегашни около 7500 евро.", "zusammenfassung": "На 8.11.2026 г. GameStar публикува нов поглед към уличните цени на актуалните видеокарти. През август същият преглед на 16 модела на AMD, NVIDIA и Intel без RTX 5090 все още показваше средна промяна около три процента спрямо януари 2026 г. Оттогава тенденцията при практически всички разгледани карти сочи само нагоре. Докладът съзнателно изключва RTX 5090 от средната стойност, защото като топ модел с 32 гигабайта памет тя заема особено място. Цената ѝ е нараснала от около 3000 евро през януари през 4350 евро през август до сегашни около 7500 евро. И под нея, чак до RTX 5050, картината също е мрачна: ако посоката се запази, RTX 5080 скоро ще е над 2000 евро, а за входната RTX 5050 ще се дължат почти 400 евро. За следените модели GameStar стига до средно поскъпване от почти 40 процента от август. Текстът сочи като причина продължаващия бум на изкуствения интелект. Хардуерни компании като AMD също ясно казвали, че се виждат преди всичко като фирми за центрове за данни, а не за игри. Всички известни на автора прогнози за кризата с паметта и хардуера приемат, че положението ще продължи години и по-скоро ще се влоши, отколкото да се подобри. Точните ценови прогнози са трудни; авторът все пак очаква още по-високи цени и по-лоша наличност. Процентите идват от собствения ценови анализ на GameStar; освен 5090, 5080 и 5050 текстът не изрежда цените на отделните модели в таблица.", "_src": "cf2fd89d"}, "2026-11-08-12v2x6-kabel-rtx-pro-6000": {"titel": "Повредени 12V-2×6 кабели при две RTX PRO 6000 въпреки първокласно захранване", "schlagzeile": "PC за 32 000 $: 12V-2×6 кабели се ронят при две RTX PRO 6000", "kurz": "Потребител в Reddit с две NVIDIA RTX PRO 6000 Blackwell откри повредена оплетка и на двата захранващи кабела 12V-2×6, въпреки че картите бяха ограничени до 500 вата. Повредите се появиха откъм GPU и откъм захранването, но нищо не се е стопило. Захранването е Seasonic PRIME TX-1600 Noctua Edition. Причината не е измерена; става дума за единичен случай.", "zusammenfassung": "VideoCardz съобщава за публикация в Reddit на потребителя Doomslayer606, който използва в работната си станция две NVIDIA RTX PRO 6000 Blackwell в 600-ватовата Workstation Edition с по 96 GB GDDR7. Според VideoCardz картите струват общо над 32 000 долара. Захранват се от Seasonic PRIME TX-1600 Noctua Edition с два собствени 16-пинови кабела. Въпреки че собственикът е ограничил двете карти до 500 вата, той забелязал и на двата кабела, че оплетката на два отделни проводника е твърда, напукана и лесно се отлепва. Повредите се появили както при конекторите на видеокартите, така и откъм захранването, където били дори по-големи, макар тези конектори почти да не са пипани. Самата изолация на проводниците останала непокътната, а нито по картите, нито по захранването имало видими следи от стопяване или обезцветяване. Преди това потребителят забелязал, че от време на време GPU или NVMe SSD изчезва от PCIe шината, затова няколко пъти е преоткачвал кабелите. Той подозира локално прегряване заради неравномерно разпределен ток, но температура и ток не са измервани. В резултат е купил резервни кабели с термична защита и обмисля да ограничи картите до 450 вата; при 300 вата е загубил 40 до 50 процента производителност в своите задачи. Според материала Seasonic и NVIDIA не са коментирали. Това е единичен случай без потвърждение от производителя, но се вписва в дългата поредица проблеми около 16-пиновия конектор. VideoCardz съветва захранващите конектори да се проверяват редовно, без постоянно да се откачват и закачват.", "_src": "a3d9d41a"}, "2026-11-08-rtings-woled-edge-rot": {"titel": "Дълготраен тест на RTINGS: 14 от 16 по-стари WOLED телевизора имат повредени пиксели по краищата", "schlagzeile": "„Edge rot“: 14 от 16 WOLED телевизора с мъртви пиксели по краищата", "kurz": "В 18 000-часовия тест на RTINGS 14 от 16 телевизора с WOLED панели на LG Display развиха мъртви пиксели по краищата на екрана. RTINGS нарича това „edge rot“; няма нищо общо с прегарянето. Трите тествани QD-OLED телевизора не бяха засегнати. Засегнати са основно модели от 2020 до 2022 г.; по-новите панели от 2024 г. насам не са тествани.", "zusammenfassung": "Тестовият сайт RTINGS публикува резултати от ускорения си тест за дълготрайност, в който телевизорите са работили около 18 000 часа. От 16 устройства с WOLED панели на LG Display 14 са развили мъртви пиксели, малки групи пиксели или видими повреди по краищата на екрана, т.е. 87,5 процента. RTINGS нарича явлението „edge rot“. За разлика от прегарянето, според RTINGS то не зависи от показването на статично съдържание и не може да се избегне с разнообразно съдържание. При по-старите WBC панели засегнати са 9 от 10 устройства, пет от тях тежко; при по-новите WBE панели – 5 от 6, сред тях модели на LG и Sony. LG G3 от 2023 г. не показа повреди по краищата. Трите QD-OLED телевизора с панели на Samsung Display нямаха edge rot; RTINGS обаче подчертава, че три бройки са твърде малко, за да се обяви QD-OLED за имунен. Три проверени OLED монитора, включително един WOLED модел, също не показаха повреди по краищата. Двама служители на RTINGS са открили проблема и на личните си устройства от 2020 и 2021 г. Точната причина не е изяснена; обсъждат се замърсяване при производството и слабости в защитния слой, който трябва да пази панела от влага. LG Electronics и LG Display потвърдиха пред RTINGS, че явлението може да се появи при малък брой продукти, изложени дълго на топлина, влага или други тежки условия, но не се очаква при нормални условия. 87,5 процента са резултат от малка тестова група при непрекъснато натоварване, а не процент на дефекти при всички продадени устройства. RTINGS все още не е установил дали са засегнати панели от 2024 г. насам.", "weitere_links": ["Hardware Busters"], "_src": "d6fa466e"}, "2026-11-07-warzone-switch2": {"titel": "Call of Duty: Warzone вече е безплатна на Nintendo Switch 2", "schlagzeile": "Warzone вече е безплатна на Nintendo Switch 2", "kurz": "Call of Duty: Warzone излезе на Nintendo Switch 2 и е безплатна в Nintendo eShop. Не е нужно да се купува Modern Warfare 4, но е нужен акаунт в Activision. Стартът съвпадна със Season 1; едновременно приключи поддръжката за PlayStation 4 и Xbox One.", "zusammenfassung": "Според Insider Gaming Call of Duty: Warzone е достъпна на Nintendo Switch 2 и може да се изтегли от eShop като самостоятелна безплатна игра. Който няма Modern Warfare 4, пак може да играе battle royale. Нужен е акаунт в Activision. Стартът дойде заедно със Season 1; Activision пише, че може да се влезе в Hajin, Zodiac и останалите карти и плейлисти, докато безплатната игра пристига за пръв път на преносимото устройство на Nintendo. Nintendo Life отрази офертата на 7.11.2026 и измери на собственото си устройство 122 GB; нямаме официален размер на изтеглянето от Activision. Insider Gaming представя хода като завръщане на поредицата към хардуера на Nintendo: Modern Warfare 4 според този разказ е първата Call of Duty на конзола Nintendo след Ghosts на Wii U. Със Season 1 Activision прекрати поддръжката за PlayStation 4 и Xbox One; напредъкът се твърди, че може да се пренесе на поддържани платформи чрез същия свързан акаунт в Activision. Разделителна способност, кадрова честота и подробности за crossplay на версията за Switch 2 не са посочени в наличното ни отразяване. Самият старт беше на 6.11.2026; използваната от нас статия на Insider Gaming излезе на 7.11.2026.", "weitere_links": ["Nintendo Life (измерване 122 GB)"], "_src": "88111250"}, "2026-11-07-pulse-elevate-verschoben": {"titel": "Sony отлага безсрочно тонколоните Pulse Elevate заради производствен проблем", "schlagzeile": "Sony отлага Pulse Elevate безсрочно – точно преди старта", "kurz": "Sony отложи безсрочно началото на продажбите на безжичните тонколони Pulse Elevate. Датата 12 ноември отпада, защото тестовете за качество са открили производствен проблем. Sony не посочва нова дата; какво става с вече направените предварителни поръчки, не е ясно.", "zusammenfassung": "На 6.11.2026 Sony отложи безсрочно старта на тонколоните Pulse Elevate в PlayStation Blog. Eurogamer и IGN отразиха съобщението на 7.11.2026. В блога Sony пише, че текущите тестове за качество са установили производствен проблем и затова е взето решение стартът да се отложи; допълнителното време трябва да гарантира, че продуктът ще даде предвиденото изживяване. Sony не посочва нова дата и не описва проблема подробно. Тонколоните трябваше да излязат в продажба по света на 12 ноември, само дни след съобщението. Препоръчителната цена на обновената страница в блога е 219,99 щатски долара, 219,99 евро и 199,99 паунда. Pulse Elevate е първата безжична двойка тонколони на Sony за настолни игри и стои до слушалките Pulse Elite и слушалките Pulse Explore. Свързват се чрез PlayStation Link с PS5, компютри, Mac и PlayStation Portal и могат едновременно да се сдвояват с телефон по Bluetooth. В дясната тонколона има микрофон с това, което Sony нарича подпомагано от ИИ потискане на шума. Вариантът Midnight Black трябваше да е наличен навсякъде, белият – само в избрани държави, сред които Германия, Австрия и Великобритания. Предварителните поръчки течаха от септември. Eurogamer пише, че не е ясно какво се случва сега с тези поръчки.", "weitere_links": ["PlayStation Blog (официално съобщение)", "IGN"], "_src": "67242cb4"}, "2026-11-07-anno117-fsr3-rtx30": {"titel": "Anno 117 Update 3.0: FSR 3 Frame Generation вече е включен по подразбиране на GeForce RTX 30", "schlagzeile": "Anno 117 вече включва Frame Generation на AMD при картите RTX 30", "kurz": "С Update 3.0 Anno 117: Pax Romana включва по подразбиране FSR 3 Frame Generation на AMD при картите GeForce RTX 30 в автоматичните графични настройки. Причина: собственият DLSS Frame Generation на NVIDIA работи едва от RTX 40 нагоре. Повече показвани fps обаче не означават по-малко забавяне на входа.", "zusammenfassung": "Ubisoft Mainz пусна на 5 ноември 2026 г. Update 3.0 за Anno 117: Pax Romana заедно с разширението „Dawn of the Delta“. Според официалните бележки към пача автоматичното разпознаване на графиката вече включва по подразбиране FSR 3 Frame Generation на AMD при картите GeForce от серията RTX 30. PCGH отрази това на 7 ноември и обяснява контекста: DLSS Frame Generation на NVIDIA официално е запазен за сериите RTX 40 и RTX 50, докато FSR 3 работи независимо от производителя и не изисква AI блокове. При системи, на които играта задава профил „Нисък“, Frame Generation обаче вече не се включва автоматично, за да се избегнат колебания при компютри близо до минималните изисквания. Ubisoft не дава конкретни данни за прираста на fps. Frame Generation вмъква междинни кадри: показваната честота на кадрите расте, но забавянето на входа не намалява от това. Други промени засягат накъсването при движение на камерата над големи градове, спадовете в производителността при маркиране на пътища и архива на книгата със задачи. Според бележките към пача обновлението оправя и множество сривове и грешки. Който не използва автоматичната настройка или не иска Frame Generation, може да го управлява в графичните опции.", "weitere_links": ["Anno Union: бележки към Update 3.0"], "_src": "e94737ea"}, "2026-11-07-assassins-creed-mars-rom": {"titel": "Доклад: Ubisoft работи по Assassin's Creed „Mars“ в Древен Рим и по мобилното отклонение „Pocket“", "schlagzeile": "Изтичане: Връща ли се Assassin's Creed в Рим?", "kurz": "Според създателя на съдържание J0nathan Ubisoft разработва Assassin's Creed с кодово име „Mars“, чието действие трябва да е в Древен Рим, както и мобилно заглавие „Pocket“ в Йерусалим. Insider Gaming знае кодовите имена, но не успя да провери достатъчно данните. Според доклада излизане би било възможно едва около 2029/2030 г.", "zusammenfassung": "Insider Gaming съобщи на 7 ноември 2026 г. за твърдения на youtuber-а J0nathan, който в миналото често е имал вярна информация за Assassin's Creed. Според него Ubisoft работи по Assassin's Creed с кодово име „Mars“, чието действие трябва да е в Древен Рим. Два източника с достъп до вътрешните системи на Ubisoft са потвърдили това; смята се за възможна връзка с планирания сериал по Assassin's Creed. Втори проект с кодово име „Pocket“ трябва да е мобилна игра с действие в Йерусалим. Insider Gaming казва, че също е чувал за кодовите имена, но не е успял да провери подробностите според своите стандарти. Поредицата напоследък преминава през бурен период, включително след напускането на Marc-Alexis Côté. Според по-ранни източници на Insider Gaming следващата голяма игра, Assassin's Creed Hexe, е отложена вътрешно с още една година, вероятно за 2028 г. Затова според доклада игра в Рим не би трябвало да се очаква преди 2029/2030 г. Ubisoft не коментира. Нищо не е потвърдено; проекти в ранен етап могат да се променят или да бъдат прекратени.", "zuverlaessigkeit_hinweis": "Непотвърдено: източникът е youtuber-ът J0nathan със смесена, но често точна история при Assassin's Creed. Insider Gaming знае кодовите имена, но не успя да провери подробностите. Няма изявление от Ubisoft.", "weitere_links": ["TheGamer: кодово име Mars"], "_src": "ef82e5b6"}, "2026-11-07-microsoft-gpu-patent-ki": {"titel": "Патентна заявка на Microsoft: неизползвана GPU мощ на лични устройства за AI обучение срещу кредити", "schlagzeile": "Пари за неактивната ти GPU? Патент на Microsoft описва AI обучение", "kurz": "Патентна заявка на Microsoft, публикувана на 5 ноември, описва система, която разделя AI обучението на малки подзадачи и ги разпределя към неизползвани GPU на крайни устройства. Потребителите трябва да се съгласят и биха могли да получават кредити. Microsoft не е обявила продукт.", "zusammenfassung": "Insider Gaming съобщава за патентна заявка на Microsoft със заглавие „Opportunistic Micro-training on Edge Devices Using Spare GPU Utilization“ (US-20260349820-A1), публикувана на 5 ноември 2026 г. Тя описва система, която разделя големи задачи за AI обучение на независимо обучаеми мини задачи и ги разпределя към устройства, чиято GPU в момента има малко работа. Дали едно устройство е свободно, трябва да се определя по натоварването на GPU и CPU, паметта, температурата и консумацията на ток. Според текста системата не бива да пречи на ползването, т.е. да забавя програми, да изтощава батерии или да прегрява устройства. Участват само потребители, които са съгласни. Извършената изчислителна работа трябва да се отчита и да се записва като кредит в профила, който може да се използва например за софтуер, достъп до модели или пари. Microsoft би била посредник между трети страни, нуждаещи се от изчислителна мощ, и собствениците на устройствата. Остават отворени въпроси за поверителността, разрешенията и допълнителното износване на видеокартата. Важно: патентната заявка не е обещание за продукт; много патенти никога не се реализират. Microsoft не е обявила подобна услуга.", "_src": "1f47cb8a"}, "2026-11-07-hwinfo-rx7500-razor-lake": {"titel": "Бета на HWiNFO разпознава необявената Radeon RX 7500 и Intel Razor Lake-H/HX/S", "schlagzeile": "Изтичане: HWiNFO познава RX 7500 и Razor Lake", "kurz": "Бета HWiNFO 8.55 Build 6115 изброява AMD Radeon RX 7500, която AMD още не е обявила. Същият билд подобрява разпознаването на Intel Razor Lake-H, -HX и -S, както и Nova Lake-E. Спецификациите и пускането на RX 7500 остават неизвестни; поддръжката на име в инструменти не е гаранция за пускане.", "zusammenfassung": "TechPowerUp и VideoCardz съобщават, че бета HWiNFO версия 8.55 Build 6115 за първи път разпознава „AMD Radeon RX 7500“. AMD не е представила официално картата; в changelog има само името, без спецификации или дата. TechPowerUp смята Navi 33 / RDNA 3 за най-вероятния кандидат за чип, защото тази архитектура вече захранва RX 7400 и RX 7600 – модел помежду им би бил тясно позициониран. Името RX 7500 или RX 7500 XT според доклади се е появявало още в по-стари слухове около 2024, без конкретен пуск. VideoCardz допълнително сочи към по-ранни прототипни следи за Navi 33 XE с 6 GB GDDR6 и Device-ID 749F; дали финалният продукт изглежда така, не е потвърдено. Същият билд на HWiNFO разширява поддръжката за Intel Nova Lake-E и Razor Lake-H/HX/S. Razor Lake се смята за следващо поколение след Nova Lake; retail чиповете са далеч, тъй като Nova Lake-S се очаква едва около Q1 2027. CPU-Z 3.02 вече добави Razor Lake в началото на седмицата; HWiNFO имаше временна поддръжка за Razor Lake-AX още през август. AMD и Intel не са потвърдили записите.", "zuverlaessigkeit_hinweis": "Непотвърдено: Само поддръжка на име/ID в бета HWiNFO 8.55-6115 и доклади от TechPowerUp и VideoCardz. Няма официално обявление от AMD или Intel; спецификациите и пускането на RX 7500 са неизвестни. Разпознаването от инструмент не е гаранция за пускане.", "weitere_links": ["VideoCardz: HWiNFO RX 7500 и Razor Lake", "Форум HWiNFO: Бета 8.55-6115"], "_src": "34935787"}, "2026-11-07-vulkan-1-4-368": {"titel": "Vulkan 1.4.368 с нови разширения от Valve и NVIDIA", "schlagzeile": "Vulkan 1.4.368: Valve и NVIDIA добавят нови разширения", "kurz": "Khronos Group пусна Vulkan 1.4.368. Седмичното обновление носи две нови разширения: едно от Mesa разработчика на Valve Mike Blumenkrantz за данни на върхове и разширение на NVIDIA за вътрешни драйверни хендъли. За играчите нищо не се променя веднага; това е градивен елемент за драйвери и енджини.", "zusammenfassung": "Vulkan 1.4.368 е най-новото седмично обновление на спецификацията на междуплатформения графичен и изчислителен интерфейс, както съобщи Phoronix на 7 ноември 2026 г. По съдържание обновлението е малко: отстранени са шест вътрешно докладвани проблема в спецификацията. Нови са две разширения. VK_EXT_vertex_address_binding_unrestricted е от Mike Blumenkrantz от Linux графичния екип на Valve, известен Mesa разработчик. То помага, когато данните за върховете при едно извикване за рисуване се изнасят в отделен буфер, за да се пести памет, и за целта изключва една проверка на адресите. Второто, VK_NV_internal_handle, е собствено разширение на NVIDIA: с него програми и енджини могат да получават вътрешни драйверни хендъли за определени Vulkan обекти и да ги подават към други интерфейси на NVIDIA. Двете разширения първо трябва да стигнат до драйверите и софтуера, преди да променят нещо в игрите. Vulkan е, наред с другото, основата на Proton в Linux и Steam Deck, където приносът на Valve е особено важен. Всички подробности са в хранилището Vulkan-Docs на Khronos Group в GitHub.", "weitere_links": ["Khronos Vulkan-Docs в GitHub"], "_src": "9f12e9de"}, "2026-11-07-razor-lake-lga1954-2028": {"titel": "Доклад: Intel Razor Lake-S трябва да излезе през 2028 г. върху сокета LGA 1954 на Nova Lake", "schlagzeile": "Изтичане: Razor Lake ще пасне ли на сокета на Nova Lake през 2028?", "kurz": "Според инсайдъра Jaykihn Razor Lake-S на Intel в момента е планиран за 2028 г. и трябва да използва същия сокет LGA 1954 като Nova Lake-S. Който премине на Nova Lake през 2027 г., би могъл да надгради с още едно поколение процесори без нова дънна платка. Intel не е потвърдила нищо от това.", "zusammenfassung": "На 7 ноември 2026 г. Wccftech и HotHardware обобщиха изказвания на инсайдъра за Intel Jaykihn: Razor Lake-S е „в момента планиран като продукт за 2028 г.“, а Intel официално не е казала нищо. Nova Lake-S, следващото настолно поколение, се очаква в началото на 2027 г. и въвежда новия сокет LGA 1954. Според докладите Razor Lake-S трябва да работи на същия сокет, така че Intel за първи път от доста време би имала две настолни поколения на една платформа. Още през юни Jaykihn писа, че LGA 1954 ще поддържа дори процесори след Razor Lake на платки с 64 MB BIOS флаш памет, включително всички Z платки. Като архитектура на P-ядрата на Razor Lake докладите посочват Griffin Cove, наследник на Coyote Cove от Nova Lake; настолните чипове няма да имат SMT. Освен това някои варианти, първоначално планирани за Nova Lake, като Nova Lake-AX, са преминали към семейството Razor Lake. Тримесечието през 2028 г. не е известно; Wccftech предполага Computex 2028 или втората половина на годината. Мениджърът на Intel Robert Hallock загатна през март, че компанията се вслушва в критиките за честата смяна на сокети, но конкретен ангажимент няма. Вижда се първа подготовка: CPU-Z 3.02 и бета версия на HWiNFO вече разпознават Razor Lake. Всички данни за срок и сокет са непотвърдени и може да се променят; решенията за покупка не бива да се основават на тях.", "zuverlaessigkeit_hinweis": "Непотвърдено: изказвания на инсайдъра Jaykihn (X), който често е бил прав за пътните карти на Intel; подхванати от Wccftech и HotHardware. Няма потвърждение от Intel; срокът и сокетът може да се променят.", "weitere_links": ["HotHardware: Razor Lake-S на LGA 1954", "VideoCardz: LGA 1954 и след Razor Lake (юни)"], "_src": "4d9282a2"}, "2026-11-07-cpuz-ram-rueckgang": {"titel": "Статистика на CPU-Z: делът на компютрите с 32 и 64 GB спада за първи път на годишна база", "schlagzeile": "За първи път по-малко RAM: CPU-Z отчита ръст на компютрите с 16 GB", "kurz": "Според статистиката на CPU-Z Validator делът на компютрите с 32 GB RAM спада с 2,5% на годишна база, а при 64 GB – дори с 18%. Системите с 16 GB и 8 GB обаче растат, а DDR4 печели дял пред DDR5. Данните отразяват само подадени валидации, не пазарни данни.", "zusammenfassung": "Doc TB, един от разработчиците на CPU-Z, публикува на 6 ноември 2026 г. нови данни от CPU-Z Validator, а VideoCardz ги разгледа на 7 ноември. Според тях обемът RAM в регистрираните компютри намалява за първи път на годишна база. 32 GB остава най-честата конфигурация с 37,2%, но губи 2,5% от дела си. При 64 GB спадът е 18%, а делът вече е 7,3%. Системите с 16 GB растат с 12,9% до 33,0% и са точно зад 32 GB. Растат и 8 GB – с 5,5% до 11,0%, както и 24 GB – с 19,7% до 2,3%. При поколението памет DDR4 расте с 6,0% до 54,5%, а DDR5 пада с 2,9% до 32,9%. Данните не посочват причина, но съвпадат със силно поскъпналата RAM през последните месеци, за която тикерът съобщава многократно. Важно: статистиката се базира само на системи, които потребителите активно подават във валидатора, и не е пазарно проучване. Промените са относителни дялове и не означават, че собствениците махат RAM.", "weitere_links": ["Doc TB (CPU-Z) в X, 06.11.2026"], "_src": "299d8b24"}, "2026-11-07-custom-engine-wald-rtx3080": {"titel": "Собствен енджин: разработчик рендерира гъста гора с около 130 fps на RTX 3080 – без хардуерен ray tracing", "schlagzeile": "130 fps на RTX 3080: любителски енджин рендерира гора без ray tracing", "kurz": "Разработчикът и модър Toni Macaroni показва собственоръчно написан енджин, който трябва да рендерира гъста гора в 1440p със средно около 130 fps на RTX 3080. Той разчита на геометрия, подобна на Nanite, воксели и вокселно осветление вместо хардуерен ray tracing. Стойностите идват от самия разработчик и става дума само за техническо демо.", "zusammenfassung": "PCGH и Wccftech съобщават за техническо демо на разработчика и модър Toni Macaroni, чието видео в YouTube според PCGH има над 500 000 гледания. По собствените му думи работи по енджина от около осем месеца, след като дълго е използвал енджина с отворен код Godot. Сцената показва хълмист пейзаж с гъста гора, около един милион инстанции и четири милиона триъгълника. На GeForce RTX 3080 в 1440p трябва да постига средно около 130 fps, до 200 при въздушни кадри и около 80 fps в гъстия подлес. Технически енджинът използва групирани нива на детайлност с виртуална геометрия, подобна на Nanite, вокселни представяния за далечната растителност и опростени проксита за много далечни обекти. Осветлението съчетава screen-space техники с вокселно глобално осветление и минава без хардуерно ускорен ray tracing, подобно на подхода в Kingdom Come: Deliverance II. Енджинът е умишлено специализиран: преди всичко трябва да показва добре много обекти с голям брой полигони, а системата за времето е готова само частично. Стойностите за fps са данни на разработчика; точните настройки и евентуален ъпскейлинг не са известни. Демо без персонажи, физика и AI не е сравнимо с готова игра, а публична версия засега няма.", "weitere_links": ["Wccftech: Custom Forest Engine"], "_src": "9e0e5944"}, "2026-11-07-windows-hello-pin-parallel": {"titel": "Windows 11 Insider: PIN успоредно със сканиране на лице или пръстов отпечатък от Windows Hello", "schlagzeile": "Windows 11: въвеждане на PIN докато Hello сканира", "kurz": "В експерименталния Insider билд на Windows 11 26340.9882 може да се въвежда PIN, докато Windows Hello още проверява лице или пръстов отпечатък. Заключеният екран показва „Look at the camera or enter your PIN“; печели методът, който заработи пръв. Разпространението е експериментално; няма retail дата.", "zusammenfassung": "Windows Latest тества Build 26340.9882 от 6 ноември 2026 (база Windows 11 26H2, Experimental канал): На екрана за вход полето за PIN се появява успоредно с проверката на Windows Hello. Вместо да се чака провал на лицевото разпознаване или неудобно да се избират опции за вход, бележките на Microsoft казват „whichever method works first“. След рестарт PIN-first остава от съображения за сигурност. Ако Face се провали, има директен намек „Retry face sign-in“. На устройства с IR камера и сензор за пръстов отпечатък подсказката може да спомене лице и отпечатък, с PIN отдолу. Новост: Event Log ID 4628 и 4629 под Security за настроени или неуспешни Hello методи; допълнителни Operational събития помагат на ИТ. Според теста функцията се е появила без ViVeTool. Експерименталните билдове могат да съдържат бъгове; Microsoft не каза кога поведението ще стигне стабилния канал.", "_src": "fc64848d"}, "2026-11-07-tsmc-3d-dram-nvidia": {"titel": "TSMC обмисля вход в 3D-DRAM – тласъкът се твърди, че е от NVIDIA", "schlagzeile": "TSMC обмисля 3D-DRAM: тласъкът се твърди, че е от NVIDIA", "kurz": "Според доклад на The Information от 6.11.2026 договорният производител TSMC обмисля вход в производството на 3D-DRAM. Тласъкът се твърди, че е дошъл от NVIDIA, най-големия клиент на TSMC. Докладът не посочва конкретни заводи, инвестиции или начална дата. TSMC не пожела да коментира пазарни слухове пред The Information и препрати към ролята си на логическа фабрика; NVIDIA според текста не е отговорила.", "zusammenfassung": "The Information съобщи на 6.11.2026, позовавайки се на двама души, запознати с разговорите, че TSMC обмисля вход в производството на 3D-DRAM. Отключващият фактор се твърди, че е била заявка от NVIDIA. igor'sLAB подхвана и коментира доклада на 7.11.2026. Според този разказ TSMC е започнала да изработва възможни производствени концепции за вертикално изградена DRAM; посочените варианти са строеж на нови заводи или придобиване на съществуващ завод и последващото му преобразуване. Не са посочени начало на производство, суми за инвестиции или планиран капацитет. Инициативата се твърди, че се води от Hsu Kuo-chin, вицепрезидент на TSMC за Advanced Packaging, който преди това е работил за Micron в Тайван. TSMC заяви пред The Information, че по принцип не коментира пазарни слухове, и посочи насочеността си като фабрика за логически чипове. Според доклада NVIDIA не е отговорила на запитване, а Reuters не успя независимо да потвърди сведенията. Технически 3D-DRAM е нещо различно от вече утвърдената High Bandwidth Memory: при HBM се подреждат няколко отделно произведени DRAM чипа, а при 3D-DRAM самите слоеве паметови клетки трябва да се интегрират вертикално, за да се увеличи плътността. Успешен вход би въвел TSMC на пазар, който досега се владее главно от Samsung, SK hynix и Micron. Същевременно от доклада не следва близък старт на масово производство, защото топлината, интеграцията на процесите и достатъчният добив се смятат за открити пречки, а разработката може да отнеме години. На фона на оскъдната и скъпа памет за компютри и центрове за данни допълнителен производител би бил съществен, но засега има само медиен доклад и възможни развойни обсъждания.", "weitere_links": ["The Verge (чрез The Information)", "Seoul Economic Daily", "Wccftech (обновление)"], "_src": "406e56e5"}, "2026-11-06-openai-gpt6-cyber-bugs": {"titel": "OpenAI представя GPT-6 Cyber: според фирмата 81 находки във Firefox и 948 Linux LPE", "schlagzeile": "OpenAI GPT-6 Cyber намира 81 бъга във Firefox и 948 в Linux", "kurz": "OpenAI представи GPT-6 Cyber, непубличен модел за сигурност. Според фирмата е открил 81 неизвестни досега high-severity уязвимости във Firefox и е разработил експлойти за 948 случая на локално повишаване на привилегии в Linux. Цифрите са от OpenAI и не са независимо пълно одитно потвърждение.", "zusammenfassung": "BleepingComputer, Phoronix и Golem съобщават за обявата на OpenAI за GPT-6 Cyber. Моделът не е публичен и в момента е ограничен до активирани клиенти в програмата Daybreak Red. OpenAI твърди, че е открил 81 неизвестни досега high-severity уязвимости във Firefox и е съразработил пачове; много вече били разгърнати в Mozilla. За изследване на Linux ядрото OpenAI цитира 2308 потенциални находки, 1724 възпроизведени уязвимости и 948 експлойта за локално повишаване на привилегии от unprivileged към root. В бенчмарка ExploitGym фирмата цитира 48,5% успех срещу 32,1% при предшественика GPT-5.6 Cyber. В Preparedness Framework OpenAI оценява cyber способността като „Critical“. Независимата дълбочина на одит за обхват и тежест е ограничена – цифрите са фирмени твърдения, не доказателство, че „Linux е общо взето несигурен“. OpenAI предупреждава за ограничен времеви прозорец, в който защитниците трябва да ползват frontier модели за укрепване, преди подобни способности да станат по-широко достъпни.", "weitere_links": ["Phoronix: OpenAI 948 Linux LPE Bugs", "Golem: OpenAI твърди, че е намерил почти 1000 root уязвимости"], "_src": "1b3a3edb"}, "2026-11-06-zen6-tee-riscv": {"titel": "AMD Zen 6: фирмуерен намек за TEE на база RISC-V вместо ARM PSP", "schlagzeile": "Zen 6: AMD преминава TEE от ARM към RISC-V", "kurz": "Commit в linux-firmware за AMD PMF Trusted Application на Zen 6 клиент (Family 1Ah M80h) споменава TEE на база RISC-V. Досега Secure Processor обикновено работеше на ARM Cortex-A5 с TrustZone. Дали RISC-V е наистина нов от Zen 6, или само за първи път е документиран, остава отворено.", "zusammenfassung": "Phoronix съобщава за commit в linux-firmware, който добавя PMF-TA firmware v4 за платформата 1AH_M80H – това съответства на предстоящите AMD Ryzen Zen 6 клиентски CPU. Текстът на commit-а казва, че Trusted Application вече работи на TEE на база RISC-V, използва по-голям shared-memory layout и разширени policy условия, включително до 20 персонализирани BIOS входа. Platform Management Framework управлява сред другото мощност, термика и системно поведение. Традиционно AMD Platform Security Processor / Secure Processor се базираше на ARM Cortex-A5 с TrustZone. Phoronix не намира по-стари публични намеци за RISC-V TEE в Ryzen/EPYC и оставя отворено дали функцията е нова за Zen 6, или при по-стари SoC просто никога не е споменавана. Commit-ът не назовава финален маркетингов етикет на поколението Ryzen. За Linux enablement и ентусиасти по сигурността архитектурната смяна все пак е рядък детайл за Zen 6 преди продуктовия пуск.", "_src": "73845857"}, "2026-11-06-epic-linux-launcher-distros": {"titel": "Epic Games Launcher Preview: широка поддръжка на Linux дистрибуции и планирано връщане на AppImage", "schlagzeile": "Epic: новият launcher ще поддържа много Linux дистрибуции", "kurz": "Epic потвърждава пред GamingOnLinux, че новият launcher в preview трябва да поддържа колкото се може повече Linux дистрибуции – изрично сред тях Fedora, SteamOS, Cachy и Omarchy. Опаковането още се променя; AppImage трябва да се върне още този месец. Preview не означава готова матрица от дистрибуции.", "zusammenfassung": "GamingOnLinux попита Jake Jones (Communications Director, Epic Games) за Linux поддръжката на новия Epic Games Launcher. Според изявлението Epic планира да поддържа „колкото се може повече Linux дистрибуции“, включително Fedora, SteamOS, Cachy, Omarchy и други. Preview започна с AppImage, по-късно премина към .deb за Debian/Ubuntu; FAQ посочваше Fedora като скоро. Epic тества и оценява формати за опаковане и иска да възстанови AppImage още този месец. Докато матрицата не е фиксирана, форматите могат да идват и да си отиват. Flatpak/Flathub остава отворено в съобщението. Статусът на launcher-а е Preview, не финален store rollout за всяка дистрибуция. Fortnite или Easy Anti-Cheat v2 са отделна тема и тук не се продават като „Fortnite идва на Linux“. Заедно с вече известния прозорец на GOG Galaxy за Linux през 2027 конкуренцията на store клиенти на Linux остава интересна.", "_src": "e2ba62e3"}, "2026-11-06-mindfactory-cyberangriff": {"titel": "Mindfactory съобщава за кибератака: паролите на клиенти са нулирани, органът е уведомен", "schlagzeile": "Mindfactory: хакерска атака – паролите са нулирани", "kurz": "Хардуерният магазин Mindfactory съобщи на 6 ноември 2026 за кибератака и уведоми клиенти и органа за защита на данните. Възможно засегнати: адрес, имейл, телефон и криптирани пароли; банковите данни според магазина не са в shop системата. Всички shop пароли са нулирани; нужна е предпазливост към фишинг.", "zusammenfassung": "heise online и Golem съобщават, че Mindfactory е станал жертва на кибератака и е уведомил клиентите с изявление. Компанията е подала сигнал до властите и е включила компетентния орган за защита на данните. Според актуалното състояние Mindfactory не може да изключи, че нападатели са получили достъп до адрес, имейл, телефон и криптирано съхранени пароли. Пароли в ясен текст и банкови или картови данни според компанията не са засегнати, защото платежните данни са при доставчици на услуги. Всички клиентски пароли за магазина са нулирани превантивно; следващият вход изисква нова парола, занапред с модерен hash метод. Управителят Marcel Kirchner говори за форензично разследване, без изнудване и за затворена уязвимост. Клиентите трябва да са внимателни към неочаквани имейли, SMS или обаждания, защото контактните данни могат да се злоупотребят за измами. Бележка за прозрачност: Mindfactory принадлежи към групата heise от средата на 2025; heise online е част от същата корпоративна група. Обхватът и точният момент на атаката все още се изясняваха към момента на съобщението.", "weitere_links": ["Golem: Хакери атакуват Mindfactory", "GameStar: Кибератака при Mindfactory"], "_src": "c989d014"}, "2026-11-06-nier-366gb-update": {"titel": "Ъпдейт на NieR: Automata по погрешка иска 366 GB – обявена е поправка", "schlagzeile": "Ъпдейт на NieR: Automata изяжда 366 GB – студиото се извинява", "kurz": "Steam ъпдейт за NieR: Automata от 6 ноември 2026 (JST) изисква много повече място от предвиденото — Insider Gaming сочи 366 GB срещу около 50 GB за базовата игра. Трябвало да добави езици; обявени са поправка и заобиколен път чрез махане на DLC.", "zusammenfassung": "Insider Gaming съобщава за дефектен Steam ъпдейт на NieR: Automata: след този от 6 ноември 2026 (японско време) размерът на инсталацията е далеч по-голям от предвидения — около 366 GB срещу ~50 GB за базовата игра. Бележките говореха за добавяне на опростен китайски, традиционен китайски и корейски. Акаунтът NieR Series в X се извини и обяви поправка. Заобиколен път: Properties → DLC, махане на DLC и продължаване с базовата игра. Няма ново сюжетно DLC от 2024; играта е надминала 10 млн. копия през февруари 2026. Кратката бележка не обяснява точната причина за раздутия даунлоуд.", "_src": "c9a67187"}, "2026-11-06-qnap-plex2shell": {"titel": "QNAP предупреждава: нападатели компрометират NAS през Plex2Shell в Plex Media Server", "schlagzeile": "QNAP: хакери атакуват NAS през Plex2Shell – обновете Plex", "kurz": "QNAP докладва компрометирания на NAS през веригата уязвимости Plex2Shell в Plex Media Server. Потребителите трябва да обновят Plex в App Center поне до 1.43.3.10861; при съмнение може да се наложи преинсталация на ОС. Самият QTS не е засегнат.", "zusammenfassung": "BleepingComputer отразява предупреждение за сигурност на QNAP: няколко потребители са докладвали, че Plex Media Server на техните NAS е компрометиран през уязвимостите Plex2Shell. Plex2Shell обхваща четири CVE (CVE-2026-96652, CVE-2026-96654, CVE-2026-96655, CVE-2026-96656), докладвани от Zach Main на 27 юли; експлоатацията е започнала след публикуване на техническите детайли на 16 октомври. CISA е добавила CVE в каталога Known Exploited на 20 октомври 2026 с кратък срок за агенциите. QNAP казва, че уязвимостите са само в Plex Media Server, не в QTS/QuTS hero. Препоръчва обновяване до Plex 1.43.3.10861 от App Center на QNAP. Който има уязвим Plex, достъпен от интернет, трябва да третира устройството като потенциално компрометирано: обновяването не премахва вече инсталирани payload-и. QNAP съветва чиста преинсталация на QTS/QuTS hero, нулиране на пароли и — ако трябва отдалечен достъп — VPN вместо препращане на порт 32400.", "_src": "48cb0d6c"}, "2026-11-06-ratchet-ranger-rumble": {"titel": "Ratchet & Clank: Ranger Rumble се спира – сървъри до май 2027", "schlagzeile": "Ratchet & Clank: Ranger Rumble свършва – сървъри на 1 май 2027", "kurz": "Мобилният спин-оф Ratchet & Clank: Ranger Rumble е отменен: финален ъпдейт на 6 ноември 2026, премахване от магазините на 21 ноември, спиране на сървърите на 1 май 2027. Играта все още беше в soft launch преди планираното глобално пускане.", "zusammenfassung": "IGN съобщава за спирането на Ratchet & Clank: Ranger Rumble. Според студиото последният планиран ъпдейт излиза на 6 ноември 2026; приложението напуска магазините на 21 ноември 2026. Който вече я има, може да играе до 1 май 2027, когато сървърите спират окончателно. Покупки в приложението са премахнати; възстановяванията сочат към Apple или Google. Arena shooter спин-офът е от Oh BiBi с Insomniac Games и PlayStation Studios и все още е бил в soft launch преди световна премиера, според IGN. Още през юли блогът на PlayStation говореше за скорошно глобално пускане след успешна тестова фаза. VGC също отразява отмяната на безплатния мобилен шутер.", "weitere_links": ["VGC: Sony’s Ratchet & Clank mobile shooter cancelled"], "_src": "99d65582"}, "2026-11-06-poe2-1-0-exilecon": {"titel": "Path of Exile 2 пълно пускане на 11 декември 2026: Shadow, Duelist и лига Conquerors of Wraeclast", "schlagzeile": "Path of Exile 2 1.0: Shadow, Duelist, старт 11.12.", "kurz": "Grinding Gear Games обяви на ExileCon пълното пускане на Path of Exile 2 за 11 декември 2026. Новости: класовете Shadow и Duelist, както и завършените кампанийни актове пет и шест. Идва и лигата „Conquerors of Wraeclast“ с изграждане на база и армия.", "zusammenfassung": "PC Gamer обобщава keynote на ExileCon за Path of Exile 2 версия 1.0: Пълното пускане след около две години Early Access е датирано за 11 декември 2026. Стартират два нови класа: Shadow, фокусиран върху кинжали и капани със stealth, и Duelist, ориентиран към мечове. Shadow според студиото може да ascend-не като Assassin или да избере новата Ascendancy Infiltrator; трета Ascendancy е планирана по-късно. Stealth предотвратява чудовищата да виждат героя от разстояние, се нулира при убийство и взаимодейства с капани, които от скривалището се задействат едва при разкриване. Кампанията получава актове пет и шест, включително завръщане в Oriath и въведение в лига механиката. „Conquerors of Wraeclast“ носи base building, армии, командири и по-късно фракционно обвързани Atlas битки. Endgame-ът силно стеснява Atlas skill tree, преработва gems и passive tree включително jewel слотове и добавя много нови bases и uniques. Точният час на пускане и още Ascendancy детайли може още да последват след текущия ExileCon.", "weitere_links": ["PC Gamer: клас Shadow за PoE2 1.0"], "_src": "6ec09cc3"}, "2026-11-06-nvidia-11mio-diebstahl": {"titel": "Хардуер на NVIDIA за 11,4 млн. долара откраднат при транспорт от Оукланд към Тексас", "schlagzeile": "11,4 млн. $ хардуер NVIDIA: шест палета изчезват по пътя", "kurz": "Полицията в Оукланд разследва кражбата на шест палета хардуер NVIDIA за 11,4 млн. долара. Камион с лого на хранителен транспорт е взел товара на 29 август и е изчезнал; следата свършва в окръг Сан Бернардино. Няма обявени арести.", "zusammenfassung": "Според VideoCardz и местната станция ABC7 News полицията в Оукланд (Калифорния) разследва голяма кражба на хардуер NVIDIA. Шест палета с декларирана стойност 11,4 млн. долара е трябвало да отидат от Оукланд до Форт Уърт, Тексас. На 29 август 2026 камион с лого на фирма за хранителен транспорт е взел товара според плана — след това превозното средство и шофьорите са изчезнали. Следователите са проследили няколко дълги спирания и са загубили следата в окръг Сан Бернардино. Сигналът към полицията е чак на 13 септември. Какви точно продукти е имало на палетите (AI ускорители, цели системи или потребителски GPU) не е публично потвърдено; средната стойност е около 1,9 млн. долара на палет. Професор Олаф Грот (UC Berkeley) каза пред ABC7, че такива чипове са много по-скъпи в чужбина и са риск за сигурността. VideoCardz споменава и по-ранни кражби, свързани с NVIDIA в Bay Area (над 7,5 млн. през 2025) и случай в Бразилия с откраднати ZOTAC RTX 5090. Засега няма арести и потвърждение, че товарът е открит.", "weitere_links": ["ABC7 News: $11.4M Nvidia cargo stolen from Oakland", "Wccftech: NVIDIA GPUs Worth $11.4 Million Stolen"], "_src": "8bfcec8e"}, "2026-11-06-micron-fab-stop": {"titel": "Micron уж спира строежа на RAM фабрика в Тайван заради спор със синдикати", "schlagzeile": "Micron спира RAM фабрика в Тайван – спор със синдикати", "kurz": "PCGH съобщава, позовавайки се на Bloomberg, че Micron е спряла строежа на фабрика в Таоюан и е замразила плановете за разширение. Фонът е конфликт с тайвански синдикати за дял от печалбите. Пълно излизане не е потвърдено.", "zusammenfassung": "Според PC Games Hardware и източници на Bloomberg на място Micron е спряла строежа на планирана полупроводникова фабрика в Таоюан (Тайван) и иска да замрази плановете за разширение. PCGH оценява инвестицията на около 4 млрд. евро. Стъпката се вписва в по-дълъг конфликт със синдикати, които искат дял на служителите от растящите печалби. В Тайчжун преди две седмици е постигнат компромис, чието приемане сред работниците е спорно; в Таоюан преговорите продължават, включително символична стачка — първата в тайванската полупроводникова индустрия. Синдикатът в Таоюан отхвърля вината и казва, че не иска да застраши печалбите на фирмата. Дали спирането е трайно или лост за преговори, остава отворено. За купувачите на PC е важно, защото повече RAM капацитет се вижда като изход от недостига — а този капацитет сега спира.", "_src": "2080eae5"}, "2026-11-06-switch2-verkauf-minus37": {"titel": "Switch 2: Nintendo отчита 37,4% по-малко хардуерни продажби за полугодието", "schlagzeile": "Switch 2: 37% по-малко продажби от рекордната година – софтът расте", "kurz": "Според данни на Nintendo и GameStar sell-in на Switch 2 от април до септември 2026 е паднал с 37,4% до 6,49 млн. броя (предишна година 10,36 млн.). Софтуерът е нараснал с 18,8%; годишната прогноза от 16,5 млн. остава.", "zusammenfassung": "GameStar обобщава полугодишните числа на Nintendo: от април до септември 2026 Nintendo е продала на търговията 6,49 млн. Switch 2 — с 37,4% по-малко от 10,36 млн. за същия период предната година. В първото тримесечие 3,82 млн., от юли до септември още 2,67 млн. Годишното сравнение е изкривено от премиерата на 5 юни 2025 и натрупаното търсене. От септември Switch 2 е по-скъпа (Европа официално 499,99 €). Nintendo сочи цени на памет, валутни курсове и петрол. Годишната прогноза от 16,5 млн. до март 2027 остава според GameStar и VGC. Софтуерът за Switch 2 е нараснал с 18,8% до 24,49 млн. броя за полугодието; нетната печалба — с единадесет процента. VGC добавя, че Switch 2 все още води оригиналната Switch и PS5 по кумулативна база от премиерата. Това са sell-in числа, не непременно продажби към крайни клиенти.", "weitere_links": ["Nintendo IR: Financial Results Explanatory Material", "VGC: Switch 2 sales down 37%, still beating original"], "_src": "9aaf69f1"}, "2026-11-06-rtx5070ti-doppel-msrp": {"titel": "GeForce RTX 5070 Ti почти достига двойната MSRP в американски онлайн магазини", "schlagzeile": "RTX 5070 Ti стига 1340 $ – почти двойна MSRP в САЩ", "kurz": "След RTX 5090 и 5080 скача и RTX 5070 Ti: най-евтината проследена онлайн оферта в САЩ е 1339,99 $, някои модели 1499,99 $. MSRP при старта беше 749 $. NVIDIA преди това отричаше слухове за прекратяване.", "zusammenfassung": "VideoCardz съобщава, че GeForce RTX 5070 Ti се продава доста над MSRP в големи американски онлайн магазини. Картата стартира през февруари 2025 с MSRP 749 $; най-евтината проследена оферта на 6 ноември 2026 е 1339,99 $ (около 79% над MSRP). Модели в B&H и Best Buy са около 1400–1499,99 $ — близо или двойно спрямо стартовата цена. За осем дни най-евтината проследена цена е нараснала със 160 $ (от 1179,99 $ на 29 октомври). Примери: GIGABYTE AERO OC в Newegg за 1339,99 $; ASUS PRIME OC и TUF GAMING OC в B&H за 1399,99 $ и 1499,99 $. През януари 2026 NVIDIA отрече слухове за край на 5070 Ti; ASUS тогава посочи недостиг на памет. Картата все още е налична, така че спиране на производството не е доказано — но ценовата спирала след 5090 и 5080 продължава при 5070 Ti.", "_src": "d18a0453"}, "2026-11-06-asus-xg-core-9060xt": {"titel": "ASUS XG Core: външна Radeon RX 9060 XT LP 16 GB през USB4 за лаптопи и хендхелди", "schlagzeile": "ASUS XG Core: външна RX 9060 XT LP 16 GB през USB4", "kurz": "ASUS представя XG Core: компактна външна графична кутия с Radeon RX 9060 XT LP 16 GB GDDR6 и USB4 за съвместими лаптопи, мини PC и хендхелди като ROG Ally X. Без официална цена; шведски магазин сочи около 1207 € с ДДС според TechPowerUp.", "zusammenfassung": "В прессъобщение, публикувано от TechPowerUp, ASUS обявява XG Core: външна графична единица с AMD Radeon RX 9060 XT LP (RDNA 4) и 16 GB GDDR6. Кутията е около 144 × 117 × 39 mm и се свързва през USB4 със съвместими хостове — ASUS споменава и Thunderbolt 3, както и ROG Ally X и ROG Xbox Ally X. HDMI и DisplayPort са вградени; настройката е през GPU Tweak III. ASUS цели игри, творчество и локални AI натоварвания (напр. ComfyUI, LM Studio, Ollama). Липсва официална MSRP; коментари в TechPowerUp цитират шведски магазин за около 1346 $ / 1207 € с 25% ДДС — не е потвърдена MSRP. Наличността в DE/AT остава неясна.", "_src": "e27a1951"}, "2026-11-06-medusa-point-6-8-kerne": {"titel": "Още Zen 6 Medusa Point семпли: 6 и 8 ядра в Geekbench записи на Lenovo", "schlagzeile": "Изтичане: Medusa Point 2/3 с 6 и 8 ядра се появява при Lenovo", "kurz": "След 10-ядрения семпъл в Geekbench 7 уж са се появили още два инженерни семпъла AMD Zen 6 Medusa Point: 8 ядра (2+6) и 6 ядра (1+5), и двата като Medusa Point 2/3 на системи Lenovo. Непотвърдено; тактове и резултати силно се люлеят.", "zusammenfassung": "VideoCardz съобщава за още два Geekbench 7 записа за AMD Zen 6 Medusa Point, този път с 6 и 8 ядра и етикет Medusa Point 2/3. И двата семпъла са тествани на системи Lenovo. 8-ядреният (100-000002152-50_Y) има 16 нишки в клъстери 2+6 и 8 MB L3; 6-ядреният (100-000001658-50_Y) 12 нишки в 1+5 и 4 MB L3. И двата споделят ID Family 26 Model 224 Stepping 0, за разлика от 10-ядрения Medusa Point 1. Резултати Geekbench 7: 8C по-късен рун 2889 / 15099 (макс. 5,28 GHz), по-ранен много по-слаб; 6C 1732 / 8340 при само ~2,04 GHz. VideoCardz подчертава, че тактове и резултати при инженерни семпли силно варират и не са финални. Мобилен дебют на Zen 6 се очаква около CES 2027. AMD не е потвърдила семплите.", "zuverlaessigkeit_hinweis": "Непотвърдено: Geekbench 7 записи на инженерни семпли на системи Lenovo, според VideoCardz. Тактове и резултати силно се различават между рунове. Не е финален продукт; AMD не е потвърдила.", "_src": "66dba83d"}, "2026-11-06-windows11-27h2": {"titel": "Windows 11 27H2 трябва за пръв път от три години да обнови техническата основа", "schlagzeile": "Windows 11 27H2: истински платформен ъпдейт, не само UI", "kurz": "Dr. Windows съобщава, цитирайки The Verge: версия 27H2 през 2027 трябва да обнови ядрото и модела на драйверите на Windows 11 — първа промяна от 24H2/25H2/26H2, които са технически еднакви. Според докладите Windows 12 не е планиран за 2027.", "zusammenfassung": "Според Dr. Windows (с позоваване на The Verge) Windows 11 през 2027 ще получи платформен ъпдейт с версия 27H2. От 24H2 насам 25H2 и 26H2 са еднакви на техническо ниво (ядро, модел на драйвери и базови елементи); новостите са засягали главно UI и сменяеми компоненти. 27H2 трябва да промени тази основа за пръв път от три години. Това може да изисква тестове за съвместимост, особено при системен софтуер като решения за сигурност. Дали някои функции ще бъдат изкуствено вързани към 27H2, остава отворено. Докладите подчертават и че това не обявява Windows 12 за 2027; остава Windows 11. Новината по същество потвърждава планове, вече очертани от Microsoft. The Verge е зад paywall; ядрото се потвърждава през Dr. Windows и Golem («без Windows 12»).", "weitere_links": ["Golem.de: Im nächsten Jahr kommt wohl kein Windows 12"], "_src": "76b75cda"}, "2026-11-06-msi-claw-fsr41": {"titel": "MSI иска FSR 4.1 за Claw A8 през декември чрез драйвер на производителя", "schlagzeile": "MSI Claw A8: FSR 4.1 се очаква през декември с OEM драйвер", "kurz": "MSI потвърждава, че Claw A8 (Ryzen Z2 Extreme / Radeon 890M) трябва да получи AMD FSR Upscaling 4.1 чрез собствен графичен драйвер — цел декември 2026, при успешна валидация. Текущ драйвер оправя бъгове в рендера, но още няма FSR 4.1.", "zusammenfassung": "VideoCardz съобщава с позоваване на MSI: хендхелдът Claw A8 трябва да получи AMD FSR Upscaling 4.1 чрез графичен драйвер на производителя. MSI цели декември 2026, ако валидацията мине. Claw A8 ползва Ryzen Z2 Extreme с Radeon 890M. AMD отвори FSR 4.1 за Ryzen Z2 Extreme и други handheld APU на 20 октомври; стандартните Adrenalin драйвери официално не поддържат хендхелди, затова MSI, ASUS или Lenovo трябва да разпространяват свои. Драйвер 32.0.32016.5 за Claw A8 BZ2EM вече е наличен: оправя грешни сенки, светлинни глитчове, FSR артефакти, частици и черни квадрати — но още без FSR 4.1. Това потвърждава официален път вместо неофициални модифицирани драйвери.", "_src": "fa2c559e"}, "2026-11-06-nvidia-dlss-override-19": {"titel": "NVIDIA App: DLSS Override за още 19 игри, включително Witcher 3 и PUBG", "schlagzeile": "NVIDIA App: DLSS Override за още 19 игри е отключен", "kurz": "Актуализация на NVIDIA App добавя DLSS Override профили за още 19 заглавия. Сред тях са по-стари игри като The Witcher 3 и PUBG както и предстоящи или обявени издания. Override позволява принудително ползване на по-нови DLSS модели и режими, където драйверът го поддържа.", "zusammenfassung": "TechPowerUp съобщава за NVIDIA App актуализация 11.0.9.585 с поддръжка на DLSS Override за още 19 игри и Optimal Settings профили за шест заглавия. В списъка Override са сред другите Honeycomb: The World Beyond, WARDOGS, PUBG: Battlegrounds, Aniimo, 007 First Light, Active Matter, Enlisted, Dragon's Dogma 2, The Witcher 3: Wild Hunt, AION 2, Halloween: The Game, HOT WHEELS Infinite Rush, Silent Hill: Townfall, Control Resonant, Ace Combat 8: Wings of Theve, Dynasty Warriors 3 Complete Edition Remastered, Star Wars: Galactic Racer, Gears of War: E-Day и Clive Barker's Hellraiser: Revival. Optimal Settings идват сред другите за AION 2, Aniimo, Control Resonant, EA Sports FC 27, Gears of War: E-Day и Star Wars: Galactic Racer. Някои заглавия вече са били в по-ранни builds според TechPowerUp; NVIDIA не обяснява дублиранията и не казва кои override опции получава всяка игра. DLSS Override е в настройките на графичната програма и може да принуждава по-нови DLSS модели или режими като DLAA, ако играта не ги предлага. Changelog-ът иначе споменава само общи поправки за стабилност и сигурност.", "weitere_links": ["VideoCardz: 19 DLSS Override профила"], "_src": "df35ce8c"}, "2026-11-06-unity-buyout-gespraeche": {"titel": "Доклади: Silver Lake и саудитският PIF са водили предварителни разговори за покупка на Unity", "schlagzeile": "Изтичане: Silver Lake и PIF говорили за покупка на Unity", "kurz": "Според доклад на Reuters Silver Lake и саудитският Public Investment Fund след сделката за EA са водили предварителни разговори за придобиване на Unity. Вторични доклади споменават оценки около около 25 милиарда долара. Сделка не е гарантирана; акциите скочиха от слуховете.", "zusammenfassung": "Няколко медии, цитирайки Reuters, съобщават, че Silver Lake и саудитският Public Investment Fund са водили предварителни разговори за възможна покупка на Unity. Същите участници наскоро бяха в голямата сделка за EA; Silver Lake вече имало миноритарен дял в Unity. Insider Gaming посочва оценка от порядъка на около 25 милиарда долара и пише, че Unity разглежда опции с банка. Това са изрично ранни разговори; сделка не е гарантирана. Само слуховете са вдигнали акциите осезаемо; един доклад говори за почти 15 процента. Unity е известна най-вече с едноименния engine и стои зад много големи игри. Ситуацията остава непотвърдена, докато Unity или инвеститорите не се произнесат официално. Надеждност: средна заради произход Reuters, но предварителен характер.", "zuverlaessigkeit_hinweis": "Непотвърдено: доклад на Reuters за предварителни разговори, поет от PC Gamer, Insider Gaming и IGN. Няма приключена сделка; Unity разглежда опции с банка. Цифри и изход отворени.", "ursprungsquelle": "Reuters", "weitere_links": ["Insider Gaming: Silver Lake и PIF искали Unity", "IGN: Silver Lake и PIF търсели да купят Unity"], "_src": "f1589ccc"}, "2026-11-06-amd-pc-markt-2027": {"titel": "AMD планира за 2027 двуцифрен спад на доставките на PC заради високи цени на паметта", "schlagzeile": "AMD: PC пазарът да спадне двуцифрено през 2027 – RAM тежи", "kurz": "На earnings call Лиса Су каза, че AMD планира двуцифрен спад на световните PC единици през 2027. Причината били по-високи цени на памет и компоненти, които тежат на търсенето. Това е планово допускане за целия пазар, не вече измерен спад.", "zusammenfassung": "На earnings call за третото тримесечие на 2026 CEO-то на AMD Лиса Су заяви, че компанията планира спад на единиците на PC пазара с двуцифрен процент през 2027. Като причина посочва по-високи разходи за памет и компоненти, които оскъпяват десктопи и лаптопи и тежат на търсенето. AMD ще изравни sell-in със sell-through, за да държи запасите здрави. Въпреки очакваната слабост AMD иска да се представи по-добре от пазара чрез Ryzen roadmap и растящия търговски бизнес. Успоредно AMD очаква Data Center да надхвърли 80 процента от приходите през 2027. Client нарасна със 7 процента през Q3 до 2,9 милиарда долара; Gaming падна с 40 процента до 773 милиона, главно заради по-слаби semi-custom продажби в конзолния цикъл. PCGH подчертава, че това е планово допускане, не вече измерен пазарен резултат. VideoCardz отразява същите изказвания. Цените на RAM почти не се появяват в Google Trends DE, но новината остава важна за купувачите на хардуер.", "weitere_links": ["VideoCardz: AMD очаква двуцифрен спад на PC пазара през 2027"], "_src": "093d57bb"}, "2026-11-06-rx9070xt-clustered-geometry": {"titel": "Microsoft Agility SDK: най-голямата актуализация на DirectX Raytracing от 2018 – Clustered Geometry и PTLAS", "schlagzeile": "DirectX: най-голямата raytracing актуализация от 2018 – Clustered Geometry", "kurz": "С Agility SDK 1.722 Preview Microsoft публикува най-обширното разширение на DirectX Raytracing от 2018. Clustered Geometry и Partitioned TLAS трябва да ускорят изграждането на структури и да намалят паметта. В независими измервания на PCGH RX 9070 XT расте от 1,7 до 91 fps; игрите трябва да внедрят API-тата.", "zusammenfassung": "Microsoft нарича новите DirectX Raytracing функции в Agility SDK 1.722 Preview най-обширното разширение от въвеждането на DXR през 2018. Ключови точки са Clustered Geometry (CLAS), Partitioned Top-Level Acceleration Structures (PTLAS) и индиректни builds на acceleration structures. Clustered Geometry разделя геометрията на преизползваеми клъстери до 256 триъгълника; това трябва силно да ускори изграждането в детайлни, динамични сцени и да позволи по-точни отражения и сенки без скъпа proxy геометрия. PTLAS трябва да обновява само променените области. Според ComputerBase и Microsoft в пример с Radeon RX 9070 кадрите са нараснали от 1,2 до 79 fps, а паметта за структури е паднала от около 7519 на 774 MB; scratch паметта е нараснала силно. PC Games Hardware независимо измери и демото D3D12RaytracingClusteredGeometry: RX 9070 XT от 1,7 до 91 fps при 1600×920 (около 54×), BVH памет от 7518 на 771 MiB; RTX 5080 от 1,4 до 310 fps. Без Clustered Geometry Radeon леко водеше; с функцията RTX 5080 беше ясно по-бърза. Preview работи на GeForce RTX, Radeon RX 9000, Intel Arc B-серия и поддържани Core Ultra iGPU; нов хардуер не е нужен, но драйверна поддръжка е. Съществуващите игри не печелят автоматично: студията трябва да интегрират API-тата. Advanced Shader Delivery и други функции от Agility SDK 1.620 са част от същия пакет, но не от числата на raytracing демото.", "weitere_links": ["Microsoft DirectX Blog: Agility SDK 1.620 / 1.722 Preview", "Microsoft: Преглед на Clustered Geometry и PTLAS", "PCGH: RX 9070 XT / RTX 5080 в демото Clustered Geometry"], "_src": "3d54cb6e"}, "2026-11-05-asrock-rx7900-vbios": {"titel": "ASRock VBIOS за RX 7900 XT/XTX: собственици докладват brick-нати GPU след официалната актуализация", "schlagzeile": "ASRock VBIOS brick-ва RX 7900 XT/XTX – свалянията уж са махнати", "kurz": "След официалния ASRock VBIOS от края на октомври собственици на Radeon RX 7900 XT и XTX Phantom Gaming както и Taichi докладват, че картите вече не стартират. Актуализацията трябваше да покрие AMD-SN-6023 и минаваше през ASRVBFlash 1.0.5. HTTP свалянията вече давали 404; някои карти са възстановени само с външен EEPROM програматор.", "zusammenfassung": "В края на октомври ASRock публикува нови VBIOS файлове за десет Radeon RX 7000 карти, включително като част от мярката за сигурност AMD-SN-6023. Няколко собственици съобщават, че след флаш с ASRVBFlash 1.0.5 системата вече не прави POST с инсталиран GPU. Споменават се RX 7900 XT Phantom Gaming както и RX 7900 XTX Phantom Gaming и Taichi, включително White изданието. Проблемът се появява на различни дънни платки, например ASRock и MSI. VideoCardz описва последователността: инструментът проверява съвместимост, Windows се рестартира, след това PC-то не стартира с картата. Поне двама потребители са възстановили RX 7900 XTX Phantom Gaming с външни EEPROM програматори, включително T48 с тестов клипс. Октомврийските сваляния вече отговаряли с HTTP 404, докато FTP връзките частично още работят. Потребител в Япония според Reddit е получил от ASRock Support потвърждение, че повредата ще е покрита от гаранцията; публично фирмено изявление или официална процедура за възстановяване според VideoCardz и Guru3D все още няма. Докато ASRock не изясни и не пусне коригиран фърмуер, собствениците на посочените модели не трябва да инсталират октомврийския фърмуер. Източник: VideoCardz, допълнително Guru3D.", "weitere_links": ["Guru3D: ASRock RX 7000 VBIOS и доклади за brick"], "_src": "1ae75289"}, "2026-11-05-gog-galaxy-linux-2027": {"titel": "Нов GOG Galaxy идва през 2027 – с пълна Linux поддръжка", "schlagzeile": "GOG Galaxy 2027: нов клиент с пълна Linux поддръжка", "kurz": "На първия GOG Showcase GOG потвърди, че през 2027 идва нов Galaxy клиент с пълна Linux поддръжка. Успоредно се преработва клиентът за Windows и Mac. Galaxy остава опционален; офлайн инсталаторите остават.", "zusammenfassung": "GamingOnLinux докладва от първия GOG Showcase: през 2027 трябва да дойде напълно нов GOG Galaxy клиент за всички платформи, за първи път с пълна Linux поддръжка. GOG още през юли е казал на GamingOnLinux, че работи по това; сега срокът е публичен. Според изявлението на GOG клиентът на Windows и Mac трябва да стане по-прост и по-бърз, с по-чиста библиотека. Основното обещание остава: Galaxy е опционален и игрите могат да се свалят и пазят през офлайн инсталатори. Заинтересованите могат да се запишат за бета на годишнишната страница на GOG, когато отвори. GOG работи и по GOG Social, модернизирана общност с нишки, медии и тагове по игри. Докладът не дава повече детайли за Linux клиента; тук не се спекулира.", "_src": "aa4b3b79"}, "2026-11-05-medusa-point-gb7": {"titel": "AMD Zen 6 Medusa Point се появява в Geekbench 7: 10 ядра, single-core над средното на 9950X3D", "schlagzeile": "Изтичане: Medusa Point в Geekbench 7 – ES 10C бие 9950X3D в SC?", "kurz": "Непотвърден резултат от Geekbench 7 показва инженерен образец AMD Medusa Point с 10 ядра и 20 нишки. Single-core е 3100 точки, малко над средното на Ryzen 9 9950X3D. Докладваните честоти около 2,0 GHz изглеждат неправдоподобни за краен продукт.", "zusammenfassung": "VideoCardz и TechPowerUp съобщават за Geekbench 7 запис на инженерния образец 100-000001713-32_Y на платформа Lenovo. Показва 10 ядра и 20 нишки в два клъстера от 4 плюс 6 ядра, плюс 16 MB L3. Single-core е 3100 точки, около 1,6 процента над средното на Ryzen 9 9950X3D от 3051 според VideoCardz. Multi-core достига 18313. База и максимум са около 2,0 GHz / 1996 MHz; това изглежда невероятно за retail честоти и се третира като типичен ES или грешен отчет. TechPowerUp описва клъстерите като възможна смес Zen 6 и Zen 6c и споменава AVX-512 в листинга. Това не е краен продукт; спецификации, честоти и дата остават отворени. По-ранни Geekbench 6 резултати не са пряко сравними. Надеждност: средна, защото има само публичен листинг през leak канали.", "zuverlaessigkeit_hinweis": "Непотвърдено: Geekbench 7 листинг на инженерен образец (100-000001713-32_Y) на платформа Lenovo, докладван от VideoCardz и TechPowerUp чрез HXL. Честотите изглеждат неправдоподобни (около 2,0 GHz). Не е краен продукт; AMD не е потвърдила нищо.", "ursprungsquelle": "Geekbench чрез HXL", "weitere_links": ["TechPowerUp: Medusa Point 10C/20T в Geekbench"], "_src": "ba3c17d9"}, "2026-11-05-switch2-keine-preiserhoehung": {"titel": "Nintendo изключва ново повишение на цената на Switch 2 – въпреки по-слаби продажби на конзоли", "schlagzeile": "Nintendo: не планира ново повишение на цената на Switch 2", "kurz": "Президентът на Nintendo Шунтаро Фурукава изключва нови повишения на цената на Switch 2. Компанията се вижда достатъчно снабдена с чипове памет. В същото време медиите докладват спад на продажбите на конзоли и на печалбата в последното тримесечие.", "zusammenfassung": "При представяне на последните резултати президентът на Nintendo Шунтаро Фурукава според PC Games, Eurogamer, VGC и IGN заяви, че не се планира ново повишение на цената на Switch 2. Nintendo е осигурила достатъчен капацитет на памет и в момента не вижда причина за нова корекция. Nintendo вече е повишавала цените на Switch 2 по-рано, включително с 50 долара / 30 евро в няколко региона. IGN цитира Bloomberg със спад на оперативната печалба от 16 процента до 73,9 милиарда йени в тримесечието до края на септември и 2,67 милиона продадени Switch 2 в този период. VGC говори за около 37-процентов спад на продажбите на Switch 2 в същия контекст, докато Nintendo твърди, че Switch 2 все още се продава по-добре от предшественика в сравнителния прозорец. До края на септември общо са продадени около 26 милиона Switch 2. Nintendo запазва прогнозите за текущата фискална година според PC Games. Недостигът на памет остава тема в бранша; Nintendo се позиционира различно от скорошните повишения на PS5 и Xbox.", "weitere_links": ["IGN: Nintendo изключва нови повишения на цената на Switch 2", "Eurogamer: No plans for more Switch 2 price hikes", "VGC: Nintendo not considering Switch 2 price hike"], "_src": "487162c1"}, "2026-11-05-dlss5-hogwarts-legacy": {"titel": "Hogwarts Legacy получава DLSS 5 с 3D-Guided Neural Rendering на GeForce RTX 50", "schlagzeile": "DLSS 5 Neural Rendering вече в Hogwarts Legacy", "kurz": "От 5 ноември 2026 Hogwarts Legacy на PC поддържа NVIDIA DLSS 5 с 3D-Guided Neural Rendering. Функцията изисква GeForce RTX 50 и актуален Game Ready драйвер; в Display настройките има превключвател „Neural Rendering“. Маркетинговите FPS числа не са ежедневно обещание.", "zusammenfassung": "NVIDIA и Portkey Games съобщават, че Hogwarts Legacy на PC е получил DLSS 5 с 3D-Guided Neural Rendering. Техниката трябва да обогатява осветлението и детайлите на материалите с AI, като запазва геометрията и текстурите на енджина като основа; разработчиците могат да управляват резултата чрез Artist Controls. Изискване според support статията: GeForce RTX 50 Series и GeForce Game Ready Driver 616.64 или по-нов. Активиране под Display настройки: Upscale Type на NVIDIA DLSS, после включване на Neural Rendering; пряк път Shift+Alt+B. Поддържани магазини: Steam, Epic Games Store и Windows Store. Според NVIDIA блога от 5 ноември 2026 War Thunder следва с DLSS 5 в средата на ноември, Where Winds Meet на 23 ноември. Функцията е обвързана с RTX 50 или съвместими cloud/Spark пътища и сама не замества класическото upscaling. Не приемаме FPS маркетинг от демота като практическо обещание.", "weitere_links": ["Portkey Games: активиране на DLSS 5 в Hogwarts Legacy", "NVIDIA Blog: GFN Thursday Hogwarts DLSS 5"], "_src": "beddaa04"}, "2026-11-05-xbox-pc-app-60": {"titel": "Xbox PC приложение: Microsoft обещава до 60 процента по-бърз старт за Insiders", "schlagzeile": "Xbox PC приложението стартира до 60 % по-бързо – първо за Insiders", "kurz": "Xbox Insiders могат от 05.11.2026 да тестват преработено Xbox PC приложение. Microsoft говори за до 60 процента по-бърз старт и забележимо по-пъргави страници и прозорци. Паралелно обновено уеб и cloud gaming изживяване достига до още играчи.", "zusammenfassung": "Jason Beaumont, VP Xbox Experiences, обяви на 05.11.2026 в Xbox Wire по-бързо и по-ясно Xbox изживяване за PC, уеб и облак. Xbox Insiders трябва да могат веднага да ползват актуализираното Xbox PC приложение. Според тестове на Microsoft приложението стартира до 60 процента по-бързо; страници като Home, Store и Game Pass се зареждат до 50 процента по-бързо, а прозорците в приложението се отварят до 65 процента по-бързо. Стойностите зависят от устройството, мрежата, конфигурацията и използването, според бележката. Библиотеката получава по-проста навигация, нови филтри и по-добро сортиране. Приятели и социални функции влизат в основната навигация. Търсенето покрива игри, включително инсталирани заглавия и add-ons, както и хора. Визуално има преработени карти на игри, Home, настройки и анимации. Уеб изживяването за Xbox Cloud Gaming, вече показано на Insiders, трябва в идните седмици автоматично да достигне до повече играчи; който иска да тества по-рано, може да отвори play.xbox.com. Там има раздел Library за облачни игри (закупени и Game Pass), десктоп режим за по-големи екрани, както и тъмен/светъл режим и пет high-contrast теми. Подобно обновяване започва и при облачни приложения на поддържани телевизори и VR слушалки. Който още не е Insider, може да се присъедини през Xbox Insider Hub за Series X|S, Xbox One или Windows. The Verge, Neowin и IGN отразяват обявата.", "weitere_links": ["The Verge: редизайн на Xbox PC приложението", "IGN: Xbox PC приложението 60 % по-бързо според Microsoft", "Neowin: редизайн и по-бързи стартове"], "_src": "f708d215"}, "2026-11-05-nova-lake-h-foto": {"titel": "Изтичане: снимка уж показва непубликуван Intel Nova Lake-H package с multi-tile дизайн", "schlagzeile": "Изтичане: показва ли вече тази снимка Nova Lake-H на Intel с 16 ядра?", "kurz": "Снимка, споделена от momomo_us, уж показва още непубликуван Intel процесорен package с няколко видими силициеви tile-а. Jaykihn потвърди при запитване Nova Lake-H конфигурация с 4+8+4 ядра. Intel не е потвърдил нищо; произходът на изображението остава неясен.", "zusammenfassung": "Хардуерният лийкър momomo_us (188号) сподели на 05.11.2026 в X изрязана снимка, която според VideoCardz уж показва още непубликуван Intel процесорен package с няколко видими силициеви tile-а. VideoCardz не успя да проследи индустриалния или embedded-дънния произход на изображението; видим е само package-ът. На въпроса дали става дума за Nova Lake-H с конфигурация 4+8+4, лийкърът Jaykihn отговори „Yes“. В ъпдейт momomo_us според VideoCardz посочи 16 CPU ядра, 4 Xe GPU ядра и 18 MB кеш. Този брой ядра пасва на коментирания Core Ultra 9 4970H с 4+8+4, т.е. 16 CPU ядра. В таблицата на VideoCardz обаче коментираният 4970H е с 12 Xe3P графични ядра – това се разминава с цифрата „4 Xe“ на momomo; коя GPU цифра е вярна, остава отворено. Дали сниманият екземпляр е конкретно 4970H, остава неясно; VideoCardz не споменава тактови честоти. За сравнение няколко Panther Lake-H модела също ползват 4+8+4. TechPowerUp и Wccftech отразяват изтичането. Intel не е потвърдил данните.", "zuverlaessigkeit_hinweis": "Непотвърдено: снимка от лийкъра momomo_us (@momomo_us / 188号); Jaykihn отговори „Yes“ на запитването за конфигурацията 4+8+4. VideoCardz не успя да проследи произхода на изрязаното изображение. Intel не е потвърдил нищо; тактовите честоти са неизвестни.", "ursprungsquelle": "momomo_us (@momomo_us) в X", "weitere_links": ["TechPowerUp: SoC Nova Lake-H се появява", "Wccftech: Nova Lake-H с six-tile setup"], "_src": "86f9c2aa"}, "2026-11-05-gta6-39-screenshots": {"titel": "Rockstar публикува около 39 нови официални скрийншота на GTA 6 – две седмици до старта в САЩ", "schlagzeile": "GTA 6: Rockstar показва 39 нови скрийншота – две седмици до launch", "kurz": "Rockstar Games публикува около 39 нови официални скрийншота на Grand Theft Auto VI. Поводът е отброяването: в САЩ остават около две седмици до старта на 19.11.2026. Изображенията включват сцени от Vice City / Leonida както и Jason и Lucia.", "zusammenfassung": "Rockstar Games официално пусна голям пакет нови скрийншоти на Grand Theft Auto VI. IGN и други медии говорят за 39 нови изображения за отбелязване на последните две седмици преди старта в САЩ. Американската дата 19.11.2026 се цитира като ориентир. Според IGN, IGN Германия и PC Gamer сред мотивите има сцени от Vice City / Leonida, героите Jason и Lucia, моменти на crime и nightlife, както и детайли като танцьори, бойни кучета и много детайлни пори на кожата. Скрийншотите идват от Rockstar / официалния сайт и X канала на Rockstar; това са потвърдени маркетингови изображения, не изтичания. Нищо отвъд описаното от източниците не се спекулира тук. Google Trends DE дава на GTA 6 стойност 60 като най-висока сред сравнените термини за седем дни; AT е 41.", "weitere_links": ["IGN Германия: 39 нови скрийншота на GTA 6", "PC Gamer: launch скрийншоти с танцьори, кучета и пори", "Rockstar Games (официален сайт)"], "_src": "eb8f6ed6"}, "2026-11-05-discord-native-windows": {"titel": "Discord преизгражда Windows клиента на Rust: ранен build с около 290 MB RAM вместо гигабайти Electron", "schlagzeile": "Discord напуска Electron: Rust клиентът цели край на апетита за RAM", "kurz": "Discord иска да премести Windows desktop клиента от Electron към нативно Rust приложение с GPUI. Ранен build на име Discord Phoenix показва около 290 MB RAM на скрийншот на CTO. Настоящото Electron приложение според доклади може да стигне до диапазона 4 GB.", "zusammenfassung": "CTO на Discord Станислав Вишневски обяви, че Discord изоставя Electron за desktop приложение на Rust с GPUI. ComputerBase и Windows Latest отразяват новината. Ранен Windows 11 скрийншот изброява Discord Phoenix с 290,2 MB RAM. Windows Latest припомня, че самият Discord е тествал рестарт на клиента при надхвърляне на 4 GB, и че нормалната употреба често е под 1 GB, докато idle лесно стига 1 до 2 GB. Discord вече ползва Rust за инфраструктура, глас и части от настоящия клиент; сега трябва да последва целият клиент. Кога започват тестовете или публичният rollout остава отворено. Стъпката пасва на дневния ред за ефективност на Windows 11 на Microsoft. Остава да се види дали паритет на функции и стабилност ще стигнат Electron версията.", "weitere_links": ["Windows Latest: Electron вън, Rust build с ~290 MB"], "_src": "5da0f5ef"}, "2026-11-05-fsr-412-xbox": {"titel": "AMD FSR Upscaling 4.1.2 е налично за разработчици на Xbox Series X|S в GDK от октомври 2026", "schlagzeile": "FSR 4.1.2 идва на Xbox – за пръв път с AI ъпскейлинг", "kurz": "С Microsoft GDK от октомври 2026 разработчиците могат да ползват AMD FSR Upscaling 4.1.2 на Xbox Series X и S. За пръв път на конзолите има ML-базиран AMD FSR upscaling. Съществуващите игри не го получават автоматично; студията трябва да интегрират.", "zusammenfassung": "AMD съобщи в GPUOpen, че FSR Upscaling 4.1.2 е налично за Xbox Series X|S чрез Microsoft Game Development Kit от октомври 2026. Alexander Blake-Davies пише, че така за пръв път на Xbox конзолите пристига ML-базиран AMD FSR upscaling; преди там е имало само аналитичен FSR. За Series X и Series S има два INT8 модела: Full и нов Lite. Според AMD Lite е с по-малко от половината размер и облекчава GPU-то повече. И двата работят на Series X и Series S. Паметта на upscaler-а зависи от render и изходната резолюция, не от модела – изборът е следователно компромис за производителност, не за памет. API-то съответства на FSR SDK под Windows; режимите за качество са Native AA, Quality, Balanced, Performance и Ultra Performance. Чрез FSR SDK 2.4 и ASUS preview драйвер техниката важи и за ROG Xbox Ally handhelds (първо Ally X и X20). Става дума за достъп за разработчици: студията трябва да интегрират, няма автоматични ъпдейти за съществуващи игри, а AMD не е посочила конкретни заглавия. VideoCardz, PC Gamer и TechPowerUp докладват за това.", "weitere_links": ["VideoCardz: FSR 4.1.2 с ML на Series X|S", "PC Gamer: FSR 4.1.2 на Xbox и handhelds", "TechPowerUp: FSR Upscaling 4.1.2 за Xbox"], "_src": "71d4e824"}, "2026-11-05-geforce-8800-gtx-demo": {"titel": "Безплатно Steam демо „GeForce 8800 GTX – 20 Years of a Legend“ чества 20 години CUDA GPU", "schlagzeile": "Nvidia те оставя да разопаковаш 8800 GTX – но иска RTX 4070", "kurz": "От 05.11.2026 в Steam има безплатното демо „GeForce 8800 GTX – 20 Years of a Legend“. То позволява да разопаковаш картата от 2006 и да я вградиш в тогавашен PC – рендерирано с path tracing и DLSS 4.5. Минимум се изисква RTX 4070.", "zusammenfassung": "По повод около 20-годишнината на GeForce 8800 GTX (пазарен старт на 08.11.2006) на 05.11.2026 излезе безплатното Steam демо „GeForce 8800 GTX – 20 Years of a Legend“. Създал го е Unreal Engine художникът Dylan Browne с подкрепа от NVIDIA. Полуинтерактивното демо позволява да разопаковаш картата, да я вградиш в PC от епохата и да разгледаш гейминг стая от 2006 с Easter eggs. Технически ползва path tracing, DLSS 4.5 с Ray Reconstruction и Dynamic Multi Frame Generation, както и RTX Mega Geometry. Системните изисквания в Steam посочват като минимум RTX 4070, 32 GB RAM, 30 GB място и драйвер 621.12 или по-нов; препоръчва се RTX 5080. 8800 GTX се смяташе за първата CUDA-съвместима GPU. Версия за GeForce NOW Ultimate трябва скоро да последва според доклади от eTeknix и The Verge. VideoCardz и Wccftech също отразяват акцията.", "weitere_links": ["eTeknix: Steam демо за 20-годишнината", "The Verge: демо за разопаковане на 8800 GTX", "VideoCardz: unboxing играта изисква RTX 4070", "Wccftech: GeForce 8800 GTX става на 20"], "_src": "16d23a91"}, "2026-11-05-openssh-musl-bypass": {"titel": "OpenSSH и musl: дълги пароли могат да разбият акаунти без парола – поправка в 10.6p2", "schlagzeile": "Дупка в OpenSSH: дълги пароли отварят заключени логини (musl)", "kurz": "На някои Linux системи с musl и без PAM нападатели могат да разбият акаунти без hash на парола с много дълга парола. OpenSSH 10.6p2 и актуализирани Alpine пакети затварят дупката; след това sshd трябва да се рестартира. Дотогава помага PasswordAuthentication no.", "zusammenfassung": "OpenSSH и Alpine Linux предупреждават за тежка, но нишова дупка в OpenSSH без PAM на системи на база musl. Според Alpine и heise засегнат е преди всичко Alpine пакетът openssh-server (без PAM) или openssh-server-pam с UsePAM no. Ако нападател достигне SSH порта и PasswordAuthentication е активен, може да влезе без да знае парола – ако поне един акаунт има „*“ в shadow полето (типично само с ключ) и едновременно поне един локален акаунт има $5$ или $6$ hash. Атаката изпраща много дълга парола от 257 до 1024 байта: musl-crypt() връща „*“ като грешна стойност за ключове над 256 байта, което съвпада със записаното „*“ и пуска проверката. Към момента на advisories още не е бил даден CVE. Поправката е в OpenSSH 10.6p2; Alpine е публикувал актуализирани пакети. След ъпгрейда sshd трябва да се рестартира. Workaround: задайте PasswordAuthentication no и рестартирайте sshd. OpenSSH разработчикът Damien Miller съветва веднага да се изключат логините с парола. Според heise проектът приема, че бъгът по-скоро не възниква в самия OpenSSH, но 10.6p2 го смекчава. Сигналът е от Özgün Kültekin от Wakefield; BleepingComputer и Alpine описват условията подробно.", "weitere_links": ["heise: OpenSSH и Alpine предупреждават за дупка", "BleepingComputer: дупка при акаунти заключени с парола"], "_src": "beadd996"}, "2026-11-04-gta6-vorbestellungen-750-mio": {"titel": "GTA 6: Sensor Tower оценява приходите от предварителни поръчки на над 750 милиона долара", "schlagzeile": "Анализатори: GTA 6 печели над 750 млн. долара още преди премиерата", "kurz": "Според оценка на анализаторската компания Sensor Tower до 03.11.2026 GTA 6 е бил предварително поръчан около 7,7 милиона пъти. Това се равнява на около 751 милиона долара приходи за PS5 и Xbox. Rockstar и Take-Two не са дали официални данни по темата.", "zusammenfassung": "Според IGN анализаторската компания Sensor Tower е проучила предварителните поръчки на Grand Theft Auto VI. До 03.11.2026 по оценка са поръчани 7,71 милиона копия, което се равнява на около 751 милиона долара приходи. По-голямата част идва от PlayStation 5: Sensor Tower отчита там около 74 процента от поръчките и около 559 милиона долара, а при Xbox около 26 процента и около 192 милиона долара. Ultimate Edition струва 100 долара, а стандартната версия 80 долара. Според IGN шефът на Take-Two Строс Зелник вижда в предварителните поръчки най-вече най-верните фенове. За сравнение: според IGN през 2013 г. GTA 5 е спечелила 800 милиона долара в първите 24 часа и е минала милиард след три дни. Дали GTA 6 ще счупи този рекорд, ще стане ясно чак след премиерата. Важно: става дума за оценка на фирма за пазарни проучвания, а не за данни от Rockstar или Take-Two. GTA 6 излиза на 19.11.2026 за PS5 и Xbox Series X|S, а версия за PC все още не е обявена.", "_src": "e55d6220"}, "2026-11-04-windows-paint-luecke": {"titel": "Windows 11: Уязвимост в Paint (CVE-2026-83844) – поправената версия не стига до много потребители", "schlagzeile": "Пробив в Paint на Windows: поправката я има, но не стига до много хора", "kurz": "Приложението Paint в Windows 11 има уязвимост, която нападатели биха могли да използват за отдалечено изпълнение на код. Microsoft вече разпространи поправка чрез Microsoft Store на 13.10.2026. Според съобщения обаче на много потребители и администратори поправената версия изобщо не се предлага.", "zusammenfassung": "Microsoft води уязвимостта в Paint под номер CVE-2026-83844 и я оценява с 8,1 от 10 точки. Самата Microsoft я класифицира като „Важна“, т.е. едно ниво под „Критична“. Става дума за четене извън разрешената област на паметта, което в най-лошия случай позволява изпълнение на зловреден код през мрежата, без потребителят да трябва да щраква каквото и да е. Според Microsoft обаче атаката е трудна за осъществяване и досега не са известни реални атаки. Тъй като Paint се обновява чрез Microsoft Store, обичайното обновяване на Windows само по себе си не защитава от уязвимостта. Според Windows Latest Paint се счита за безопасен от версия 11.2609.401.0, но тази версия не се появяваше в Store дори при включени автоматични обновявания. Администратори в Reddit и във форума на Microsoft също съобщават, че не получават посочената версия. Според Neowin страницата за сигурност на Microsoft първоначално е посочвала друг номер на версия, вероятно поради печатна грешка. Според Neowin е възможно и поетапно разпространение. Инсталираната версия може да се провери в PowerShell с командата „Get-AppxPackage Microsoft.Paint“. Който не използва Paint, може засега и да деинсталира приложението.", "weitere_links": ["Windows Latest: уязвимост в Paint и липсващо обновяване", "Microsoft Security Update Guide: CVE-2026-83844"], "_src": "2d5490bd"}, "2026-11-04-nova-lake-90-grad-limit": {"titel": "Изтичане: Intel Core Ultra 4000 „Nova Lake-S“ щели да работят на най-много 5,1 GHz над 90 °C", "schlagzeile": "Изтичане: Nova Lake на Intel щял да стига само 5,1 GHz над 90 °C", "kurz": "Според информатора Jaykihn всички настолни процесори от серията Nova Lake-S ще ограничават честотата си до най-много 5,1 GHz над 90 °C. Ограничението уж не може да се вдигне. Информацията е предварителна и не е потвърдена от Intel.", "zusammenfassung": "Информаторът за Intel Jaykihn написа на 04.11.2026 в X, че предстоящите настолни процесори Core Ultra 4000 „Nova Lake-S“ на Intel ще получат фиксирана температурна граница. Над 90 °C максималната честота на ядрата щяла да бъде ограничена до 5,1 GHz при всички модели. Това щяло да действа независимо от обичайната аварийна спирачка при 100 °C (TjMax), при която процесорът и без това намалява производителността. Според Jaykihn новата граница от 90 градуса също не може да бъде вдигната. Той самият изрично определя информацията като предварителна. Модели, които и без това не надхвърлят 5,1 GHz, не биха били засегнати. По-бързите модели биха могли да загубят част от буста си, ако охлаждането не е достатъчно. TechPowerUp припомня, че сегашният Core Ultra 9 285K достига до 5,7 GHz и има по-висок TjMax от 105 °C. Освен това според по-ранни съобщения топ моделът с 28 ядра щял за кратко да консумира до 296 W, което вероятно ще изисква мощен охладител. Според TechPowerUp Nova Lake-S се очаква през първото тримесечие на 2027 г. Intel не е потвърдила данните, така че това остава изтичане.", "zuverlaessigkeit_hinweis": "Непотвърдено: единственият източник е информаторът за Intel Jaykihn в X, който сам определя информацията като предварителна. VideoCardz и TechPowerUp предават публикацията. Intel не е потвърдила нищо, окончателните честоти не са известни.", "ursprungsquelle": "Jaykihn (@jaykihn0) в X", "weitere_links": ["Jaykihn в X (оригинална публикация)", "TechPowerUp: Nova Lake-S пада до 5,1 GHz над 90 °C"], "_src": "434bcacb"}, "2026-11-04-god-of-war-laufey-verschoben": {"titel": "God of War Laufey се отлага: новата дата е 20.05.2027", "schlagzeile": "God of War Laufey се отлага: феновете ще чакат три месеца повече", "kurz": "Sony Santa Monica официално отложи God of War Laufey. Вместо на 16.02.2027 играта вече ще излезе на 20.05.2027. Студиото иска да използва допълнителното време за последните щрихи.", "zusammenfassung": "Студиото на PlayStation Santa Monica обяви на 04.11.2026 в X, че God of War Laufey ще излезе по-късно. Досега премиерата беше планирана за 16.02.2027, а новата дата е 20.05.2027. Студиото обяснява отлагането с желанието да довърши играта и да разгърне пълния ѝ потенциал. От представянето през юни екипът е благодарен за огромния ентусиазъм на феновете, се казва в изявлението. Laufey е първата основна част от поредицата, в която главният герой не е Кратос. Вместо това играчите управляват Фей, съпругата на Кратос и майка на Атрей, която умира преди събитията в God of War от 2018 г. Според официалното описание след смъртта си тя се събужда в нещо като отвъдния свят на боговете, наречен „Everywhen“. Eurogamer отбелязва, че така играта избягва претъпкания февруари с много големи заглавия. Студиото планира скоро да сподели още новини.", "weitere_links": ["Eurogamer: God of War Laufey се отлага за май 2027", "Neowin: Sony отлага God of War Laufey"], "_src": "87a1ab5a"}, "2026-11-04-amd-rekord-gaming-einbruch": {"titel": "AMD: рекордни приходи от 13,4 млрд. долара, гейминг с 40 процента надолу – през четвъртото тримесечие вероятно за пръв път повече приходи от Intel", "schlagzeile": "AMD печели повече от всякога, но приходите от гейминг падат с 40 %", "kurz": "AMD постигна рекордни приходи от 13,4 милиарда долара през третото тримесечие на 2026 г., най-вече благодарение на центровете за данни. Приходите от гейминг обаче паднаха с 40 процента, защото скъпата памет спъва видеокартите, конзолите и компютрите. Според собствената си прогноза AMD вероятно за пръв път ще има повече приходи от Intel през четвъртото тримесечие.", "zusammenfassung": "AMD отчете рекордни приходи от 13,4 милиарда долара за третото тримесечие на 2026 г. Според ComputerBase 8,5 милиарда долара от тях идват от бизнеса с центрове за данни, който според TechPowerUp е нараснал с 97 процента на годишна база. В гейминга картината е съвсем различна: това направление се срина с 40 процента спрямо същото тримесечие на миналата година, до 773 милиона долара. Като причина AMD посочва недостига и поскъпването на паметта, които оскъпяват видеокартите, конзолите с чипове на AMD и цели компютри. За четвъртото тримесечие AMD очаква около 17 милиарда долара приходи, с отклонение плюс-минус три процента. Intel очаква за същия период само 15 до 16 милиарда долара. Дори долната граница на прогнозата на AMD е над горната граница на Intel, така че според TechPowerUp AMD за пръв път би имала повече приходи от Intel. Това важи само за приходите, не за печалбата. Същевременно шефката на AMD Лиса Су очаква двуцифрен спад в продажбите на компютри през 2027 г. За геймърите на PC това означава, че AMD продължава да измества фокуса си към центровете за данни и изкуствения интелект.", "weitere_links": ["TechPowerUp: AMD върви към първото си тримесечие с повече приходи от Intel", "PC Games Hardware: тримесечни резултати на AMD"], "_src": "0136260f"}, "2026-11-03-arc-b580-eol": {"titel": "Изтичане: Intel може да спре Arc B580 и да заложи на по-скъпите карти Arc Pro", "schlagzeile": "Изтичане: идва ли краят на бюджетната видеокарта Intel Arc B580?", "kurz": "Според лийкъра Haze2K1 Intel може да спре производството на видеокартата Arc B580. Причината били по-печелившите карти Arc Pro със същия графичен чип. Това е непотвърден слух, Intel не е коментирала.", "zusammenfassung": "Лийкърът Haze2K1 написа на 02.11.2026 в X, че Intel Arc B580 може да бъде спряна. Според публикацията Intel иска да се съсредоточи повече върху професионални карти и карти за работни станции като Arc Pro B50, които се продавали добре за AI приложения. TechPowerUp и Wccftech подхванаха публикацията. Arc B580 излезе през декември 2024 г. за 249 долара като достъпна геймърска карта с 12 GB графична памет. Според TechPowerUp Arc Pro B60 използва същия графичен чип, но има 24 GB памет и струва около 500 долара, което вероятно носи повече печалба на чип. Според TechPowerUp B580 вече е изчерпана при много търговци или се предлага само над първоначалната цена. Самият Haze2K1 се изразява предпазливо и казва само, че картата може да бъде спряна. От слуха не става ясно дали по-малката Arc B570 също би била засегната. Intel не е коментирала слуха, така че той е непотвърден.", "zuverlaessigkeit_hinweis": "Непотвърдено: единственият източник е публикация на лийкъра Haze2K1 в X, който сам казва само „might“ (може би). TechPowerUp и Wccftech преразказват публикацията; няма независим втори източник. Intel не е коментирала.", "ursprungsquelle": "Haze2K1 в X", "weitere_links": ["Haze2K1 в X (оригинална публикация)", "Wccftech: Intel може да спре Arc B580"], "_src": "115ef362"}, "2026-11-03-windows11-8gb-ram": {"titel": "Windows 11 работи осезаемо по-добре на компютри с 8 GB RAM – Microsoft дава подробности и условия", "schlagzeile": "Windows 11 на компютри с 8 GB: обещават до 40% по-бърз мултитаскинг", "kurz": "Microsoft оптимизира Windows 11 за компютри само с 8 GB RAM. Според Microsoft системата реагира до 20 процента по-бързо, а мултитаскингът е до 40 процента по-бърз в лабораторен тест. Нужни са Windows 11 26H2 от компилация 26300.9818 нагоре и обновени приложения.", "zusammenfassung": "На 03.11.2026 Microsoft обясни в Windows Experience Blog как Windows 11 трябва да работи по-добре на компютри с 8 GB RAM. Според шефа на Windows Павън Давулури менюто „Старт“, търсенето, контекстното меню, „Настройки“, Snipping Tool и File Explorer реагират до 20 процента по-бързо на такива устройства, измерено чрез телеметрични данни. До 40 процента по-бързият мултитаскинг идва от един-единствен лабораторен тест на лаптоп на HP със Snapdragon X Plus, а самата Microsoft казва, че това не е общ бенчмарк. Благодарение на по-добре настроената компресия на паметта Windows може да държи до 2 GB повече активни данни в RAM, вместо да ги премества на по-бавния SSD. Така отворените приложения и разделите в браузъра би трябвало по-рядко да се презареждат. Заедно с Edge и приложенията на Microsoft 365 допълнителната употреба на памет при мултитаскинг пада с до 900 MB, като само Word, Excel, PowerPoint и Outlook спестяват около 360 MB. На компютри с 8 GB уиджетите се зареждат едва когато отворите панела с уиджети, което спестява около 200 MB. Изискването е Windows 11 26H2 от компилация 26300.9818 нагоре, която идва първо с незадължителната актуализация от 28.10.2026, а според Windows Latest за всички на Patch Tuesday на 10.11.2026. Edge, Microsoft 365 и Teams също трябва да са обновени, защото част от подобренията идват с обновления на приложенията. За 3D моделиране, тежък видеомонтаж или големи обеми данни Microsoft продължава да препоръчва 16 GB или повече.", "weitere_links": ["Windows Experience Blog (Microsoft): Raising the bar for 8 GB Windows 11 PCs", "TechPowerUp: до 40% по-бърз мултитаскинг на компютри с 8 GB"], "_src": "dd699a8a"}, "2026-11-03-rtx50-preise-china": {"titel": "Изтичане: партньорите вдигат в Китай цените на GeForce RTX 50 – с до 3300 юана", "schlagzeile": "Изтичане: картите RTX 50 пак поскъпват – с до 3300 юана", "kurz": "Според китайската браншова платформа Channelgate партньорите на NVIDIA в Китай отново вдигат цените на GeForce RTX 50. Посочват се поскъпвания от около 100 до 3300 юана в зависимост от модела. Това не е потвърдено, а цифрите важат само за Китай.", "zusammenfassung": "Китайската браншова платформа Channelgate съобщава, че производителите на видеокарти в Китай отново вдигат цените на GeForce RTX 50 през ноември. Според PC Games Hardware Colorful вече е въвела новите цени, а Galax трябва да последва още тази седмица. Според TechPowerUp съобщените поскъпвания са от около 100 до 150 юана за RTX 5060 Ti с 8 GB до 2200–3300 юана за китайската версия RTX 5090 D V2. За RTX 5080 докладът посочва 2500–2800 юана, за RTX 5070 Ti около 1000 юана, а за RTX 5070 около 600–900 юана повече. Преизчислено това са приблизително от 15 до почти 500 щатски долара. Като причини докладът посочва недостига на графична памет и по-скъпите суровини като медта. Според TechPowerUp по-високите цени може да стигнат до магазините една-две седмици по-късно. Тъй като картите RTX 50 в Китай стават дефицитни, търговците според PCGH все повече се насочват към по-стари модели като RTX 3060 и към карти Radeon. NVIDIA и посочените партньори не са потвърдили официално поскъпванията. Дали и доколко това ще се отрази на цените в Европа, не е ясно.", "zuverlaessigkeit_hinweis": "Непотвърдено: всички публикации се основават на китайската браншова платформа Channelgate (кръга на Board Channels). NVIDIA, Colorful и Galax не са потвърдили нищо официално. Цените важат за Китай и не могат да се пренесат 1:1 за Европа.", "ursprungsquelle": "Channelgate (Board Channels), Китай", "weitere_links": ["TechPowerUp: RTX 50 поскъпват с до 500 долара"], "_src": "1fa9041b"}, "2026-11-03-elder-scrolls-6-sentinel": {"titel": "The Elder Scrolls 6 официално се казва „Sentinel“ – Bethesda показа заглавие и лого", "schlagzeile": "След 8 години мълчание The Elder Scrolls 6 най-после има име", "kurz": "По случай 40-годишнината си Bethesda разкри пълното заглавие на следващата ролева игра от Elder Scrolls: The Elder Scrolls VI: Sentinel. Sentinel е град в региона Hammerfell. Дата на излизане все още няма.", "zusammenfassung": "На 03.11.2026 във видео за 40-годишнината на студиото Bethesda официално потвърди, че The Elder Scrolls VI носи подзаглавието „Sentinel“. Във видеото се виждат заглавието и логото, а думата взима и Тод Хауърд. Sentinel е пристанищен град в провинция Hammerfell в северозападната част на Тамриел. Според IGN цитат във видеото е датиран във време след събитията от Skyrim. Играта беше обявена на E3 2018 и оттогава почти нямаше официална информация. Един доклад беше предсказал името още предишната седмица, а сега то е потвърдено. Bethesda не показа дата на излизане, нито геймплей. Според IGN платформите са Xbox и PC, а версия за PlayStation остава неясна. Eurogamer предполага, че повече може да бъде показано на The Game Awards през декември, но това не е потвърдено.", "weitere_links": ["IGN Германия: The Elder Scrolls 6 се казва Sentinel", "PC Gamer: The Elder Scrolls 6: Sentinel вече е официално"], "_src": "0e2f52ba"}, "2026-11-03-gta6-preload-212gb": {"titel": "GTA 6: Rockstar потвърждава предварително изтегляне от 10.11.2026 и до 212 GB", "schlagzeile": "GTA 6 заема до 212 GB – а предварителното изтегляне започва по-рано", "kurz": "Rockstar Games официално потвърди, че предварителното изтегляне на GTA 6 за PS5 и Xbox Series X|S започва на 10.11.2026. В зависимост от конзолата изтеглянето е до 212 GB. Играта все още трябва да излезе на 19.11.2026.", "zusammenfassung": "Rockstar Games публикува следобед на 03.11.2026 подробностите за предварителното изтегляне на Grand Theft Auto VI. На PS5 то започва на 10.11.2026 в полунощ местно време, а на Xbox Series X|S в същия ден в 0:00 GMT, тоест в 1:00 часа в Австрия и Германия. Според Rockstar изтеглянето е до 212 GB в зависимост от устройството, а PlayStation Blog също съветва да се освободят поне 212 GB място. Така по същество се потвърждава изтичане от края на октомври, според което играта заема около 210 GB на PS5. Според публикациите предварителното изтегляне първоначално беше обявено от 12.11.2026, така че дигиталните играчи могат да започнат два дни по-рано. Версиите в кутия идват в магазините на 12.11.2026 и според публикациите съдържат само код за изтегляне. Премиерата остава на 19.11.2026 за PS5 и Xbox Series X|S. За старта Rockstar ще предложи на сайта си и постер с корицата и карта на Леонида за разпечатване. От информацията не става ясно дали Xbox Series S има нужда от по-малко място.", "weitere_links": ["PlayStation Blog: предварителното изтегляне започва на 10 ноември", "IGN Германия: потвърдени часове и размер на инсталацията", "VGC: Rockstar съобщава дата и размер на предварителното изтегляне"], "_src": "91689255"}, "2026-11-03-fedora-45": {"titel": "Fedora Linux 45 излезе – с GNOME 51, KDE Plasma 6.8 и ядро Linux 7.2", "schlagzeile": "Fedora 45 е тук: нов работен плот, нов инсталатор и проверими билдове", "kurz": "Проектът Fedora пусна Fedora Linux 45. Изданието Workstation използва GNOME 51, а изданието KDE – Plasma 6.8, върху ядро Linux 7.2. Сред новостите са Stratis в инсталатора и възпроизводими билдове на пакетите.", "zusammenfassung": "Fedora Linux 45 излезе на 03.11.2026, около шест месеца след Fedora 44 и според Phoronix след две отлагания. Изданието Workstation идва с GNOME 51, а изданието KDE Plasma Desktop с Plasma 6.8. Като ядро се използва Linux 7.2. Според официалното Fedora Magazine една от най-големите новости е поддръжката на системата за съхранение Stratis директно в инсталатора Anaconda. Виртуалната текстова конзола по подразбиране вече се обслужва от KMSCON, а според 9to5Linux Fedora залага на напълно възпроизводими билдове на пакетите. Проверката на подписите на RPM пакетите е включена по подразбиране, а ptrace е ограничен по подразбиране, което трябва да повиши сигурността. Вариантите Atomic като Silverblue и Kinoite вече се инсталират с новия инсталатор WebUI. За разработчиците има между другото GCC 16.2, LLVM 23, Python 3.15, Go 1.27 и Podman 6. Старите VPN плъгини NetworkManager-vpnc и NetworkManager-fortisslvpn отпадат, затова който ги използва, трябва да прехвърли връзките си преди надграждането. Съществуващите инсталации на Fedora 44 могат да се надградят чрез DNF system-upgrade.", "weitere_links": ["Fedora Magazine (официално): Announcing Fedora Linux 45", "Phoronix: Fedora 45 Released"], "_src": "be19dcc2"}, "2026-11-02-zelda-oot-remake-puppenlook": {"titel": "Zelda: Ocarina of Time за Switch 2: Nintendo обяснява спорния кукления вид на римейка", "schlagzeile": "Римейкът на Zelda изглежда като куклен театър – Nintendo обяснява защо", "kurz": "Римейкът на The Legend of Zelda: Ocarina of Time излиза на 5 ноември за Nintendo Switch 2. Графичният стил с герои, наподобяващи кукли, разделя феновете. В интервю разработчиците обясняват, че нарочно са търсили „усещане за куклен театър“ вместо чист фотореализъм.", "zusammenfassung": "Според Polygon Nintendo коментира спорния графичен стил на римейка на The Legend of Zelda: Ocarina of Time. Link, Zelda и други герои изглеждат по-скоро като кукли, отколкото като фотореалистични хора, което предизвика дискусия сред дългогодишните фенове. Арт директорката Ая Шида казва в интервю с разработчиците, че целта не е била просто всичко да изглежда реалистично. Hyrule трябвало да се усеща като плътен свят, който би могъл наистина да съществува, а цветните, ексцентрични герои да създават контраст, както в оригинала. Според Шида ключовите думи на екипа били „усещане за куклен театър“ и „аналоговата атмосфера на филмите с практически ефекти“. Продуцентът на поредицата Еиджи Аонума обяснява, че екипът изпитва носталгия, когато гледа оригинала за Nintendo 64, а изразяването на тази носталгия довело до аналоговия куклен вид. Според Video Games Chronicle римейкът излиза в четвъртък, 5 ноември 2026 г., за Nintendo Switch 2. Разработва го вътрешното подразделение на Nintendo – Nintendo EPD, което създаде и Breath of the Wild и Tears of the Kingdom. Дали стилът ще убеди, ще покажат едва ревютата след излизането.", "weitere_links": ["Video Games Chronicle: Zelda: Ocarina of Time UK midnight launch"], "_src": "dda2e7e2"}, "2026-11-02-rtx5080-preis-heise": {"titel": "RTX 5080 почти не се намира под 2000 евро; според доклад версията с 24 GB може да закъснее", "schlagzeile": "RTX 5080 мина 2000 евро: над 30% по-скъпа само за две седмици", "kurz": "Според heise online GeForce RTX 5080 в момента почти не се намира под 2000 евро; цената ѝ се е повишила с над 30% за две седмици. heise посочва като причина слуховете за спиране на RTX 5090, която вече струва около 8000 евро. Според непотвърден доклад на BenchLife очакваната версия на RTX 5080 с 24 GB може да закъснее.", "zusammenfassung": "След RTX 5090 и RTX 5080 поскъпва осезаемо, съобщава heise online: втората най-бърза геймърска видеокарта на NVIDIA в момента почти не се намира под 2000 евро. Това е с над 30% повече, отколкото само преди две седмици. В средата на октомври се появиха слухове, че NVIDIA може да изтегли RTX 5090 от пазара, което според heise е повишило търсенето на 5080. Самата RTX 5090 вече струва около 8000 евро; последната препоръчителна цена на NVIDIA беше 2099 евро. NVIDIA опроверга спирането на 5090, но само с думите, че картата „ще продължи да се доставя“. Според heise от това не става ясно дали ще продължи да се произвежда. През октомври се говореше и че RTX 5080 с 24 вместо 16 GB GDDR7 ще бъде представена през януари 2027 г. Според тайванския сайт BenchLife обаче производителите на карти все още не са получили от NVIDIA нужната проектна документация, въпреки че тя е била планирана за октомври. Това е непотвърден доклад; NVIDIA не е коментирала. Освен това наличностите от чипове GB203 в Китай вече били разпродадени и щели да стигнат само за един-два месеца. heise посочва бума на ИИ като причина за недостига: същите чипове и оскъдната памет GDDR7 отиват и в скъпи карти за работни станции с по-висок марж. Който търси топ видеокарта, засега трябва да очаква високи цени.", "weitere_links": ["Wccftech: RTX 5080 24 GB may miss January 2027 launch"], "_src": "ecd4a72d"}, "2026-11-02-windows11-smart-app-control-fix": {"titel": "Microsoft поправя грешка: Smart App Control не можеше да се включи след октомврийската актуализация", "schlagzeile": "Windows 11: защитата бе блокирана след октомврийския ъпдейт – вече има поправка", "kurz": "След октомврийската актуализация за сигурност KB5127648 защитната функция Smart App Control в Windows 11 не можеше да се включи на някои компютри. Microsoft поправи грешката с актуализациите от 28 октомври 2026 г., включително незадължителната предварителна актуализация KB5127936. Там, където Smart App Control вече беше включен, защитата работеше през цялото време.", "zusammenfassung": "Според BleepingComputer Microsoft поправи известна грешка в Windows 11, появила се след актуализацията за сигурност KB5127648 от октомври 2026 г. На засегнатите устройства с Windows 11 24H2 или по-нова версия опцията Smart App Control в Защита на Windows беше сива и не можеше да се включи. Smart App Control блокира потенциално опасни приложения в допълнение към SmartScreen и Microsoft Defender. Засегнати бяха само компютри, на които функцията преди това е била изключена. Там, където вече е била включена, устройствата останаха защитени, според Microsoft. Грешката е поправена с актуализациите на Windows от 28 октомври 2026 г. и по-новите, включително незадължителната предварителна актуализация KB5127936. Microsoft препоръчва да се инсталира най-новата актуализация. За фирмени компютри, които не искат да чакат следващия Patch Tuesday, Microsoft предлага временно решение чрез два записа в регистъра или специални групови политики, и в двата случая с рестарт. Според BleepingComputer KB5127936 поправя и проблеми с Отдалечения работен плот при включена „Администраторска защита“, както и грешки с VPN след актуализациите от септември 2026 г. Домашните потребители трябва само да инсталират актуализацията.", "_src": "2c58e168"}, "2026-11-02-raspberry-pi5-16gb-preis": {"titel": "Raspberry Pi 5 с 16 GB RAM поскъпва за четвърти път: 385 вместо 305 долара", "schlagzeile": "Raspberry Pi 5 с 16 GB вече струва 385 долара – три пъти повече от началото", "kurz": "Raspberry Pi вдига каталожната цена на Raspberry Pi 5 с 16 GB RAM от 305 на 385 долара. Това е четвъртото поскъпване от декември 2025 г.; при излизането цената беше 120 долара. Причината е растящата цена на RAM паметта, но този път Raspberry Pi 500+ не поскъпва.", "zusammenfassung": "Според heise online Raspberry Pi 5 с 16 GB LPDDR4 RAM отново поскъпва. Каталожната цена се повишава с 80 долара до 385 долара. Това вече е четвъртото поскъпване след декември 2025 г., февруари 2026 г. и април 2026 г. При излизането тази версия струваше 120 долара, около 135 евро, според heise. Производителят обяснява поскъпването с постоянно растящите цени на RAM паметта. Шефът на Raspberry Pi Ебен Ъптън обяснява, че за 16-гигабайтовия чип памет няма алтернативен доставчик. Същият чип се използва и в Compute Module 5 и Raspberry Pi 500+. Версията на Compute Module 5 с 16 GB поскъпва с 40 долара, а Raspberry Pi 500+ този път не. Според heise поскъпват и някои други модели Raspberry Pi. Заради недостига производителят е въвел допълнителни варианти на сглобяване за няколко продукта, за да може да използва чипове памет от други производители. Golem.de съобщава, че един Pi 5 вече струва почти 350 евро. Колко ще се вдигнат цените в магазините, зависи от търговеца.", "weitere_links": ["Golem.de: Pi 5 und Compute Module – Raspberry Pi kostet mittlerweile fast 350 Euro"], "_src": "7815dfa5"}, "2026-11-02-rtx5090-pro5500-igorslab": {"titel": "RTX 5090 срещу RTX PRO 5500: igor'sLAB проверява дали професионалната карта на NVIDIA отнема чиповете на геймърската видеокарта", "schlagzeile": "Над 8000 евро за RTX 5090: Професионалната карта на NVIDIA ли ѝ взима чиповете?", "kurz": "Според igor'sLAB RTX 5090 с наличност веднага е струвала 8059 евро в германски магазин на 1 ноември 2026 г., докато препоръчителната цена на Founders Edition е 2099 евро. Анализът проверява дали NVIDIA предпочита да влага подходящите чипове GB202 в предстоящата професионална карта RTX PRO 5500, която има същия брой изчислителни блокове. Изводът: икономически правдоподобно, но публично недоказано.", "zusammenfassung": "igor'sLAB е проучил защо GeForce RTX 5090 почти не може да се намери на първоначалната си цена. При проверка на магазини от 1 ноември 2026 г. INNO3D RTX 5090 iCHILL X3 с наличност веднага е струвала 8059 евро в ALTERNATE, а ZOTAC Solid OC White – 8499 евро в Caseking. Германската препоръчителна цена на Founders Edition е 2099 евро, но там тя е обявена като неналична. Във фокуса е предстоящата RTX PRO 5500 Blackwell Workstation Edition: според данни на партньори тя също използва големия чип GB202 със 170 активни стрийминг мултипроцесора и 21 760 CUDA ядра, но има 84 GB GDDR7 с ECC вместо 32 GB. Позовавайки се на анонимни източници, Reuters съобщи на 20 октомври 2026 г. за над три милиона поръчани от Китай карти PRO 5500 на цена около 11 400 долара за брой. Това би дало на NVIDIA стимул да влага подходящите чипове по-скоро в скъпата професионална карта, отколкото в геймърската. igor'sLAB обаче подчертава, че това не е публично доказано: няма данни нито за добива на чипове, нито за разпределението им между двата продукта. Освен това доставките на геймърски карти бяха оскъдни още преди съобщените поръчки за PRO 5500, а редовните доставки на професионалната карта се очаква да започнат едва през първото тримесечие на 2027 г. Като друго тясно място анализът посочва паметта GDDR7, която според TrendForce все повече се заделя за AI и сървърни приложения. Примерните изчисления за разходи и маржове в статията изрично се основават на свободно избрани допускания и не са реални данни на NVIDIA. Изводът на igor'sLAB: професионалната карта е сериозен конкурент за чипове и памет, но измеримо изместване на RTX 5090 не е доказано.", "_src": "bff68b5d"}, "2026-11-01-linux-7-4-rc1": {"titel": "Излезе Linux 7.4-rc1: най-големият merge прозорец в историята на ядрото, до голяма степен задвижен от AI", "schlagzeile": "Linux 7.4: рекорден ъпдейт заради лавина от AI – и Торвалдс е доволен", "kurz": "Линус Торвалдс пусна първата тестова версия на Linux 7.4. С почти 20 000 commit-а merge прозорецът беше най-големият в историята на ядрото, а голяма част от промените са предизвикани от AI инструменти. Сред новостите са подготовката за процесорите Zen 6 на AMD и HDMI 2.1, включен по подразбиране в драйвера AMDGPU.", "zusammenfassung": "Линус Торвалдс пусна Linux 7.4-rc1 в неделя вечерта и така затвори merge прозореца по план. Според Торвалдс той е бил необичайно голям – почти 20 000 commit-а вместо обичайните около 15 000, а според Phoronix най-големият в историята на ядрото. Като главна причина Торвалдс посочва лавината от промени, предизвикани от AI. Той го приема положително: много повече предпочита тази работа да влиза в merge прозореца, отколкото като вълна от поправки в тестовата фаза. Според Торвалдс друга причина може да е, че Linux 7.4 се очаква да стане следващата версия с дългосрочна поддръжка. По думите му една трета от пача са само дефиниции на регистри на GPU на AMD. Според Phoronix новостите включват поддръжка за предстоящите процесори Ryzen със Zen 6, HDMI 2.1 по подразбиране в драйвера AMDGPU и функцията AMD PerfOpt за по-добра AI производителност на интегрираните Radeon GPU. Освен това има поддръжка на Intel IPU8 за предстоящите лаптопи с Nova Lake, повече поддръжка за лаптопи със Snapdragon X2, първи основи за Apple M4 (още не е готово за ежедневна употреба) и по-бързо компилиране на ядрото. До финалната версия предстоят няколко тестови версии. Ако всичко върви по план, Linux 7.4 ще излезе на 20 декември 2026 г., според Phoronix. За обикновените потребители е най-добре да изчакат, докато дистрибуцията им достави новото ядро.", "weitere_links": ["LWN.net: prepatch на ядрото 7.4-rc1"], "_src": "4f089b1b"}, "2026-11-01-gta6-210gb-download": {"titel": "GTA 6: появи се размер за изтегляне от 210 GB за PS5", "schlagzeile": "Изтичане: Наистина ли GTA 6 ще заеме цели 210 GB на PS5?", "kurz": "Според акаунта за данни PlayStation Game Size изтеглянето на GTA 6 за PS5 ще е около 210 GB, а Insider Gaming твърди, че може да го потвърди. Rockstar официално не е посочил размер, така че цифрата е непотвърдена. Сигурно е, че дигиталните предварителни поръчки могат да се изтеглят предварително от 12 ноември 2026 г., а играта излиза на 19 ноември 2026 г.", "zusammenfassung": "Специализираният в данни от магазина акаунт в X PlayStation Game Size (@PlaystationSize) посочи на 27 октомври 2026 г. размер за изтегляне от 210 GB за стандартното издание на Grand Theft Auto VI за PlayStation. Insider Gaming писа за това на 1 ноември 2026 г. и твърди, че може да потвърди информацията. Според Insider Gaming това би направило GTA 6 една от най-големите игри за всички времена. Нито Rockstar Games, нито Take-Two са потвърдили официално размера, затова цифрата се смята за непотвърдена. Insider Gaming също отбелязва, че размерът може да се промени до излизането и че пач за първия ден може да заеме допълнително място. Източникът не дава цифра за версията за Xbox. Датите обаче са официално потвърдени: според Rockstar дигиталните предварителни поръчки могат да се изтеглят предварително от 12 ноември 2026 г., а играта излиза на 19 ноември 2026 г. за PlayStation 5 и Xbox Series X|S. Според Rockstar версията в кутия съдържа само код за изтегляне и също ще се продава от 12 ноември 2026 г. Според Rockstar стандартното издание струва 79,99 долара, а Ultimate Edition – 99,99 долара. Който иска да играе от първия ден, трябва навреме да си освободи доста място на конзолата.", "zuverlaessigkeit_hinweis": "Идва от акаунта за данни @PlaystationSize (анализира данни от магазина); Insider Gaming твърди, че може да потвърди цифрата. Не е потвърдено официално от Rockstar или Take-Two; размерът може да се промени до излизането и с пач за първия ден.", "ursprungsquelle": "PlayStation Game Size (@PlaystationSize) в X, 27 октомври 2026 г.", "weitere_links": ["Take-Two/Rockstar: предварителни поръчки, предварително изтегляне от 12 ноември 2026 г., излизане на 19 ноември 2026 г. (официално)"], "_src": "386ea700"}, "2026-11-01-windows11-26h2-alle": {"titel": "Windows 11 26H2 вече е достъпен за всички съвместими компютри, включително директно от Windows 10", "schlagzeile": "Windows 11 26H2 вече е за всички – включително за компютри с Windows 10", "kurz": "Microsoft приключи поетапното разпространение на Windows 11 26H2: според Microsoft ъпдейтът е достъпен за всички съвместими устройства от 28 октомври 2026 г. Според Neowin вече се предлага и директно чрез Windows Update на съвместими компютри с Windows 10. Условието остава компютърът да отговаря на хардуерните изисквания на Windows 11.", "zusammenfassung": "Microsoft пусна Windows 11 26H2 за всички в края на септември 2026 г., но както обикновено го разпространяваше поетапно. Така сериозни проблеми не засягат изведнъж много устройства, което е важно най-вече за фирмите. Според Neowin разпространението първо достигна пълна наличност за устройства с Windows 11 25H2 и 24H2. Сега Microsoft пише, че към 28 октомври 2026 г. Windows 11 26H2 е достъпен за всички съвместими устройства. Според Neowin това важи и за съвместими компютри с Windows 10, на които ъпдейтът вече се предлага директно чрез Windows Update. Редакцията твърди, че го е видяла на един от собствените си компютри с Windows 10. Който вече ползва Windows 11 24H2 или 25H2 и още не е получил ъпдейта, може според Neowin да инсталира ръчно активиращия пакет eKB5121794. Това обаче не работи от Windows 10 или от по-стари версии на Windows 11. За чиста инсталация има актуални ISO файлове чрез Media Creation Tool на Microsoft. Според Neowin 26H2 използва по-малко RAM памет и работи по-пъргаво, но това е оценка на самата редакция. Остава едно условие: предложението получават само компютри, които отговарят на хардуерните изисквания на Windows 11.", "_src": "7b79cfea"}, "2026-11-01-rtx2080ti-22gb-pcgh": {"titel": "Употребявана RTX 2080 Ti с 22 GB: PCGH тества китайския мод на паметта", "schlagzeile": "22 GB в стара RTX 2080 Ti: колко добър е китайският мод всъщност?", "kurz": "PC Games Hardware тества RTX 2080 Ti, чиято видеопамет е удвоена в Китай от 11 на 22 GB. При 1440p разликата обикновено е малка, но при 4K и при AI задачи модифицираната карта ясно изпреварва оригинала. За такова преустройство няма гаранция.", "zusammenfassung": "PC Games Hardware тества модифицирана GeForce RTX 2080 Ti с удвоена видеопамет, която читател е купил през Alibaba. Вместо 11 GB платката носи единадесет чипа Samsung по 2 GB, т.е. 22 GB GDDR6 върху непроменения 352-битов интерфейс с 616 GB/s. Благодарение на променен конфигурационен резистор (strap) картата работи без модифициран BIOS и с нормални драйвери. При 1440p с DLSS Quality разликите спрямо версията с 11 GB обикновено са малки, но времената на кадрите са по-равномерни. В Microsoft Flight Simulator 2024 и Spider-Man 2 оригиналната карта според теста изостава с около 20 процента. При 4K с DLSS Performance и FSR Frame Generation картата с 11 GB накъсваше силно, а Indiana Jones дори се срина. В Spider-Man 2 е измерено използване на памет до 13,9 GB. В AI теста с ComfyUI картата с 22 GB се нуждаеше от около 315 секунди вместо около 540 – RTX 5070 Ti се справи със същото за около 85 секунди. За купувачите на употребяван хардуер това означава: модът може да си струва, но е намеса без гаранция от производителя, а качеството на такива преустройства е различно.", "weitere_links": ["Тест на PCGH (оригинал)"], "_src": "03eb821d"}, "2026-11-01-larrabee-fund": {"titel": "Пълна система за разработка на Intel Larrabee открита в склад под наем", "schlagzeile": "Находка в склад: неизлизал GPU на Intel се появи заедно с компютър за разработка", "kurz": "Потребител в Reddit откри в склад, купен на търг, пълна система за разработка за GPU-то Larrabee на Intel, което така и не излезе на пазара. Компютърът зарежда Windows 7 и според твърденията дори пуска Crysis, но стойностите на FPS не са проверени независимо. Оригиналният софтуер вече е в Internet Archive.", "zusammenfassung": "Потребител в Reddit намери при търга на склад под наем пълна система за разработка за никога неизлизалото GPU Larrabee на Intel. В компютъра има дънна платка Intel DX58SO с инженерна мостра в степинг C0, означена като „Intel Visual Adrenaline“. Към нея имаше две USB флашки с оригиналния софтуер, който откривателят вече качи в Internet Archive. Системата зарежда Windows 7 и поддържа Direct3D. Според собственика Crysis е вървял на 720p със средни детайли с около 17 FPS, а с друг драйвер уж с около 36 FPS – тези стойности не са проверени независимо. Intel спря Larrabee като видеокарта през 2010 г.; технологията по-късно продължи да живее в ускорителите Xeon Phi. За колекционерите на хардуер толкова пълна система със софтуер е истинска рядкост.", "_src": "e8e20545"}, "2026-10-31-nv-uefi-unlocker": {"titel": "Инструмент с отворен код отключва повече AI производителност при RTX 20, 30 и 40", "schlagzeile": "Безплатен инструмент вади до 75% повече AI мощ от RTX карти – с уловка", "kurz": "Инструментът с отворен код „nv-uefi-unlocker“ отключва ограничени изчислителни блокове за AI задачи при картите RTX 20, 30 и 40. В цитираните тестове производителността се е повишила с около 29 до 75 процента в зависимост от картата и задачата. Полза в игрите не е доказана, Secure Boot трябва да е изключен, а използването е на собствен риск.", "zusammenfassung": "Разработчикът physicsdolphin публикува „nv-uefi-unlocker“ – инструмент с отворен код, който трябва да отключва ограничени изчислителни блокове в картите GeForce за AI натоварвания. Инструментът стартира от USB флашка преди самия драйвер и след това работи и под Windows. Промяната не е постоянна и трябва да се прилага отново след всяко студено стартиране. Поддържат се RTX 20, 30 и 40, GTX 16 само експериментално, а RTX 50 изобщо не. Secure Boot трябва да е изключен, а картите Turing допълнително се нуждаят от GSP фърмуер. Цитирани резултати: RTX 2070 печели 67 до 75 процента във FP32 GEMM, а лаптопен GPU RTX 4060 се покачва във FP16 от 29,89 на 49,33 TFLOPS. Потребител с RTX 3080 LHR съобщава за около 29 процента по-висока скорост в ComfyUI със SDXL; при генерирането на текст с LLM обаче инструментът носи малко. Който го пробва, го прави на собствен риск – полза за производителността в игрите не е доказана.", "_src": "111abea6"}, "2026-10-31-amd-adrenalin-26-10-2": {"titel": "AMD Adrenalin 26.10.2: незадължителният драйвер за Radeon поправя десет грешки, няколко проблема остават", "schlagzeile": "Сривове при Radeon: новият драйвер на AMD поправя десет грешки – но не всички", "kurz": "AMD пусна незадължителния графичен драйвер Adrenalin 26.10.2, който поправя десет грешки, сред които таймаути на драйвера, сривове и изключвания на системата при Radeon RX 7000 и RX 9000. Той не добавя поддръжка за нови игри. Няколко известни проблема, например в Cyberpunk 2077 и Assassin's Creed Black Flag Resynced, остават нерешени.", "zusammenfassung": "AMD пусна на 30 октомври 2026 г. незадължителния графичен драйвер Adrenalin Edition 26.10.2 за Windows. Според официалните бележки към версията това е ъпдейт само с поправки – общо десет. Наред с другото той поправя сривове или таймаути на драйвера при отваряне или затваряне на други наслагвания като Xbox Game Bar, докато е активно наслагването за производителност на AMD. Клиентът на Steam също понякога се сриваше при стартиране на карти Radeon, което вече би трябвало да е поправено. При RX 7600 драйверът премахва изключванията на системата във Valor Mortis, а при останалите RX 7000 – таймаутите на драйвера в същата игра. За серията RX 9000 AMD поправя забиванията в Death Stranding 2 с включен FSR и сривовете при превключване между приложения с FSR Frame Generation. Добавени са и поправки при възпроизвеждане на видео под Windows 11 с хардуерно ускорено планиране на GPU (HAGS) и за грешка в AMD Install Manager. Не всичко е решено: в Assassin's Creed Black Flag Resynced при RX 7000 все още може да има сривове, а във War Thunder при RX 5000 – таймаути. За War Thunder AMD засега препоръчва по-стария драйвер 26.9.1. В Cyberpunk 2077 някои карти RX 9000 може да се сриват, когато са активни FSR upscaling, Anti-Lag и генериране на кадри, докато на втори екран върви видео; тогава AMD съветва да се изключи генерирането на кадри в играта. Според AMD освен това под Windows 10 след инсталацията Smart Access Memory може да се окаже изключен, затова при съмнение си струва да се провери в драйвера. Ако нямате нито един от поправените проблеми, не е нужно веднага да инсталирате незадължителния драйвер.", "weitere_links": ["AMD: бележки към версията Adrenalin Edition 26.10.2 (официално)"], "_src": "f1d0f566"}, "2026-10-31-altman-pc-ram": {"titel": "Сам Алтман: RAM в компютрите е „доста ужасно“ използване на оскъдния DRAM капацитет", "schlagzeile": "Сам Алтман: RAM паметта в компютъра ви е „доста ужасно“ използвана", "kurz": "В подкаста „Cheeky Pint“ главният изпълнителен директор на OpenAI Сам Алтман нарече „quite terrible“ това, че DRAM стои в компютри, които по негова груба оценка работят само около пет процента от времето. Фонът е недостигът на памет, тъй като производителите правят все повече памет за сървъри и AI. За сглобяващите компютри това означава, че RAM едва ли ще поевтинее скоро.", "zusammenfassung": "Главният изпълнителен директор на OpenAI Сам Алтман говори за сегашния недостиг на памет в подкаста „Cheeky Pint“ със съоснователя на Stripe Джон Колисън. Там той нарече „quite terrible“ (доста ужасно) това, че DRAM стои в компютри, които се използват само около пет процента от времето. Тези пет процента са негова собствена груба оценка, а не проверена цифра. Фонът е, че производителите на памет все повече пренасочват производството към памет за сървъри и AI, което вдига цените на RAM за потребителите. VideoCardz ясно не е съгласен с Алтман в коментара си. За сглобяващите компютри изказването е преди всичко знак, че цените на RAM едва ли скоро ще паднат отново.", "_src": "be0c42aa"}, "2026-10-30-linux-kernel-tcp-luecke": {"titel": "Ядро на Linux: сериозна пробойна в TCP кода позволява отдалечени root атаки срещу MPTCP сървъри", "schlagzeile": "Linux: пробойна в ядрото дава отдалечен root достъп – обновете сега", "kurz": "Пробойна тип use-after-free в IPv4 TCP кода на ядрото на Linux (CVE-2026-98432) засяга ядра чак до версия 4.4. Изследователи демонстрираха отдалечен root достъп на сървъри, които предлагат Multipath TCP (MPTCP). Debian вече има обновления, другите дистрибуции следват.", "zusammenfassung": "Според BleepingComputer IPv4 TCP кодът на ядрото на Linux съдържа пробойна тип use-after-free, причинена от състояние на надпревара (CVE-2026-98432). Засегнати са ядра чак до версия 4.4. Екипът за CVE на ядрото оценява пробойната с 9,8 от 10, а Red Hat – само с 5,9, защото експлоатацията е сложна и основният риск са сривовете. Изследователи от Anthropic демонстрираха отдалечен root достъп на сървъри с MPTCP listener; според публикацията експлойтът е създаден от неиздаден модел Claude за около 53 минути. Обикновеният TCP също е засегнат, но там изпълнение на код не е показано. Реални атаки не са потвърдени. Неприятното: програмите, компилирани с Go 1.24 или по-нова версия, включват MPTCP под Linux по подразбиране. Въпреки това екипът по сигурност на Go препоръчва обновяване на ядрото вместо изключване на MPTCP за всяка програма поотделно – а и според публикацията самото изключване на MPTCP не е достатъчно. Debian пусна поправени ядра за Bookworm и Trixie; за Ubuntu обновленията бяха в процес на подготовка на 30 октомври. Засегнати са RHEL 8 до 10; SUSE, Oracle и Amazon Linux към онзи момент имаха частично обновления. Пробойната е поправена, наред с други, във версиите на ядрото 6.1.190, 6.6.159, 6.12.113, 6.18.56 и 7.3. Който поддържа Linux сървъри, трябва бързо да обнови ядрото и да рестартира.", "weitere_links": ["oss-security: съобщение от екипа по сигурност на Go за MPTCP", "LWN.net: нови стабилни ядра"], "_src": "d946d2fe"}, "2026-10-30-windows-insider-suche": {"titel": "Insider компилации на Windows: ново търсене с плъзгачи и действия с телефона, Beta задава разрешения за всяко приложение", "schlagzeile": "Windows 11 тества ново търсене с плъзгачи и действия с телефона", "kurz": "В нови Insider компилации Microsoft тества преработено търсене в Windows. То показва плъзгачи, например за сила на звука и яркост, директно в резултатите и може да започва обаждания или SMS чрез Phone Link. Beta компилацията 26220.9836 позволява и разрешения за камера, микрофон и местоположение за всяко настолно приложение.", "zusammenfassung": "На 30 октомври Microsoft пусна нови Insider компилации на Windows 11, сред тях Beta 26220.9836 и Experimental 26340.9843. В каналите Experimental стартира ново търсене в Windows. То показва плъзгачи за сила на звука, яркост или размер на курсора на мишката директно в резултатите. Чрез Phone Link ще може да се управляват обаждания, SMS и режимът „Не безпокойте“ на телефона – първо с Android, а поддръжката на iPhone трябва да дойде в началото на следващата година. Добавят се и по-подробни резултати с преглед на файлове, отговори от мрежата, например за времето и борсата, и приложения от Store; това може да се изключи в Поверителност и защита > Търсене. Резултатите могат да се филтрират и оценяват с палец нагоре или надолу. Засега търсенето се отваря долу в средата; според Microsoft се работи по адаптирането му към позицията на лентата на задачите. Според Windows Report Beta компилацията носи и разрешения за камера, микрофон и местоположение за отделни настолни приложения, като досегашните решения се запазват. Както при всички Insider функции, не е ясно дали и кога ще стигнат до нормалната версия на Windows.", "weitere_links": ["Windows Report: Beta компилация 26220.9836 с разрешения за отделни приложения"], "_src": "bbfec2ce"}, "2026-10-30-nova-lake-28c-prognose": {"titel": "Nova Lake-S с 28 ядра: вътрешна прогноза говори за 16 до 33% повече производителност в игри", "schlagzeile": "Изтичане: следващият геймърски процесор на Intel ще е до 33% по-бърз", "kurz": "Според VideoCardz вътрешни прогнози на Intel обещават на Nova Lake-S, в зависимост от варианта, 16 до 33 процента повече производителност в игри от Core Ultra 9 285K. Част от преднината обаче идва от по-бързата памет DDR5-8000, използвана в сравнението. Това са непотвърдени целеви стойности, които може още да се променят до пускането.", "zusammenfassung": "Според VideoCardz вътрешни прогнози на Intel от август 2026 г. показват колко по-бърз трябва да е Nova Lake-S в игрите. Основа е собственият „Gaming Index“ на Intel, а сравнението е с Core Ultra 9 285K. 28-ядрен вариант с PL1 285 W трябва да е до 1,16 пъти по-бърз от 285K при 250 W. Вариант с два compute tile-а и 296 W трябва да е до 1,33 пъти по-бърз. Важно: Nova Lake е работил с DDR5-8000 чрез XMP, а Arrow Lake – само с DDR5-6400, така че част от преднината идва от по-бързата памет. Допълнителни данни от потребителя в X Haze, като +8 процента в една нишка без и +17 процента с голям кеш от последно ниво, според VideoCardz не са проверени. Такива ранни прогнози са целеви стойности и може още да се променят до пускането. Официално Intel досега е потвърдил само, че Nova Lake се базира на процеса 18A-P и че повече подробности ще има на CES през януари.", "zuverlaessigkeit_hinweis": "Предполагаеми вътрешни слайдове на Intel, разпространени от трети лица; не са проверени независимо, целите може да са се променили.", "ursprungsquelle": "Haze (@Haze2K1) / предполагаеми слайдове на Intel", "_src": "6e13f4ff"}, "2026-10-30-rtx5080-marketplace": {"titel": "RTX 5080 изчезна от американския магазин на NVIDIA – след RTX 5090", "schlagzeile": "Първо RTX 5090, сега RTX 5080: американският магазин на NVIDIA се изпразва", "kurz": "GeForce RTX 5080 изчезна от официалния marketplace на NVIDIA в САЩ, малко повече от две седмици след RTX 5090. При търговците в САЩ най-евтината RTX 5080 струва около два пъти повече от препоръчителната си цена от 999 долара. Това не доказва край на производството, но предлагането е видимо ограничено.", "zusammenfassung": "GeForce RTX 5080 изчезна от официалния marketplace на NVIDIA в САЩ; потребители в Reddit забелязаха това първо в списъка с филтри. RTX 5090 беше премахната още на 16 октомври, за кратко се появи отново за 5599 долара и пак изчезна – препоръчителната ѝ цена е 1999 долара. На 28 октомври най-евтината RTX 5080 струваше 1979,99 долара при търговците в САЩ и 1999,99 долара в Best Buy при препоръчителна цена 999 долара. NVIDIA преди това отрече, че RTX 5090 е спряна. Всички карти от серията RTX 50 в момента се продават доста над препоръчителната цена. Премахването на карта от магазина само по себе си не доказва край на производството – но показва колко ограничено е предлагането.", "_src": "99a9c410"}, "2026-10-30-witcher4-sprecher": {"titel": "The Witcher 4: изказвания на актьори от дублажа подхранват слуховете за познати герои", "schlagzeile": "Изтичане: завръщат ли се Лютичето и Йенефер в The Witcher 4?", "kurz": "Няколко актьори, които озвучават герои, коментираха The Witcher 4 и разпалиха спекулации за познати персонажи. Полският глас на Лютичето казва, че е записал няколко реплики, а гласът на Гералт, Дъг Кокъл, все още нищо. CD Projekt RED не коментира.", "zusammenfassung": "Според ixbt.games гласът на Гералт, Дъг Кокъл, е казал в края на октомври в подкаста Kinda Funny Games, че все още не е записал нищо за The Witcher 4 и не знае какъв ще е обемът на ролята на Гералт. По-скоро очаква поддържаща, отколкото главна роля. Според VGTimes Яцек Копчински, полският глас на Лютичето, е казал на PSX Extreme Party на 5 септември, че вече е записал няколко реплики за The Witcher 4 – „не много“. За също обявения проект „Songs of the Past“ обаче още не е записал нищо. Според Notebookcheck потребител в Reddit е разказал, че актрисата, озвучаваща Йенефер, Дениз Гоф, споделила на автограф сесия, че е записала нови диалози, свързани с Цири; не е ясно за кой проект. През 2025 г. Гоф беше казала пред Eurogamer, че участието ѝ в The Witcher 4 е несигурно. CD Projekt RED не коментира нито едно от тези изказвания. Официално потвърдено: Цири е главната героиня, а играта излиза за PC, PS5 и Xbox Series X|S. През август съизпълнителният директор Михал Новаковски посочи 2028 г. като целеви период за излизане. CD Projekt ще представи следващите си тримесечни резултати на 24 ноември.", "zuverlaessigkeit_hinweis": "Изказвания на актьори от дублажа, отчасти само от втора ръка (Reddit, репортажи от събития) и отчасти без яснота за кой проект са записвали; CD Projekt RED не е потвърдил нищо.", "ursprungsquelle": "Изказвания на актьорите (подкаст Kinda Funny Games, PSX Extreme Party 2026, автограф сесия според потребител в Reddit)", "weitere_links": ["VGTimes: гласът на Лютичето е записал реплики за The Witcher 4", "Notebookcheck: изтичане за Witcher 4 намеква за завръщане на популярен герой"], "_src": "9d06ea0f"}, "2026-10-30-amd-preiserhoehung": {"titel": "AMD отново ще вдигне цените на Radeon и GDDR6 през ноември", "schlagzeile": "Изтичане: картите Radeon може пак да поскъпнат още през ноември", "kurz": "Според китайския форум на търговци Board Channels AMD е вдигнала през октомври цените на едро на Radeon и може да ги вдигне отново през ноември. Отделно от това, според Hardware Unboxed цените на видеокартите са се повишили с около 35 процента за три месеца. AMD не е потвърдила планираното повишение.", "zusammenfassung": "Според информация от китайския форум на търговци Board Channels AMD е вдигнала на 1 октомври цените на едро на GPU-тата Radeon и може да ги вдигне отново през ноември. AMD уж преразглежда цените си всяко тримесечие. Паметта GDDR6 също е поскъпнала с около 8 до 10 процента през третото тримесечие. Отделно Hardware Unboxed е следил цените на видеокартите в десет държави: за три месеца те са се повишили с около 35 процента, само през октомври – с 10 процента. Според данните RX 9060 XT 16GB е поскъпнала със 17 процента, а RX 9070 и RX 9070 XT – с около 12 процента всяка. AMD не е потвърдила планираното повишение. Който има нужда от видеокарта, трябва да следи цените – пазарът на употребявани вероятно също ще бъде засегнат.", "zuverlaessigkeit_hinweis": "Форум на търговци Board Channels; ценовите данни на Hardware Unboxed са документирани, планираното повишение от AMD – не.", "ursprungsquelle": "Board Channels", "_src": "61551511"}, "2026-10-30-intel-q3-nova-lake-18a-p": {"titel": "Тримесечни резултати на Intel: Nova Lake на 18A-P изпреварва графика, подробности на CES", "schlagzeile": "Intel натиска газта: Nova Lake изпреварва графика", "kurz": "На конферентния разговор за третото тримесечие Intel потвърди, че Nova Lake ще е първият клиентски продукт на процеса 18A-P и че разработката изпреварва графика. Подробности ще има на CES през януари. Intel обаче вижда пазара на компютри в корекция заради високите цени на паметта.", "zusammenfassung": "На конферентния разговор за резултатите от третото тримесечие на 2026 г. (29 октомври, американско време) Intel потвърди, че Nova Lake ще е първият клиентски продукт на процеса 18A-P. Разработката изпреварва графика, а Intel очаква два пъти повече design wins, отколкото при Panther Lake. Повече подробности ще има на CES през януари. Според Intel добивът при 18A се подобрява с двуцифрени проценти, а 18A-P е в график до края на годината. При същата консумация 18A-P трябва да дава около 9 процента по-висока честота или при същата честота около 18 процента по-ниска консумация. За 14A през октомври излезе PDK 0.9, версия 1.0 следва през първото тримесечие на 2027 г., а производството е планирано за 2028 г. При сървърите Diamond Rapids идва през 2027 г. на 18A-P, а Coral Rapids – през 2028 г. на 14A. Intel обаче вижда пазара на компютри в корекция, докато цените на паметта не се нормализират – компанията очаква общият пазар да е с около 10 процента по-малък. Според Tom's Hardware Intel освен това изтегля капацитет от Panther Lake, за да произвежда повече сървърни процесори Granite Rapids.", "datum_hinweis": "Часът е приблизителен (публикувано сутринта на 30.10)", "weitere_links": ["Стенограма (The Motley Fool)", "Бележки на harukaze5719 в X"], "_src": "728b9684"}, "2026-10-30-rtx5080-24gb": {"titel": "RTX 5080 с 24 GB ще дойде до януари 2027 г. и ще замени версията с 16 GB", "schlagzeile": "Изтичане: RTX 5080 с 24 GB ще дойде още около Нова година", "kurz": "Според Board Channels NVIDIA планира GeForce RTX 5080 с 24 вместо 16 GB, която да излезе първо в Китай между декември 2026 и януари 2027 г. Там версията с 16 GB ще бъде изведена от продажба. Името, честотите и цената са неизвестни, а NVIDIA не е потвърдила нищо.", "zusammenfassung": "Според публикация на китайския форум на търговци Board Channels (ChannelGate) NVIDIA планира GeForce RTX 5080 с 24 GB памет. Тя трябва да излезе в Китай най-рано през декември 2026 г. и най-късно през януари 2027 г. Сегашната версия с 16 GB и RTX 5090 D V2 там ще бъдат изведени от продажба; оставащите наличности от GPU с 16 GB уж ще стигнат за още около два месеца. BenchLife вече на 12 октомври писа за пускане през първото тримесечие на 2027 г., но партньорите уж са получили само устни намеци. 50-те процента повече памет вероятно ще дойдат от 3 GB модули GDDR7 на същия интерфейс. Името, честотите и цената са неизвестни. В началото на октомври профилите в X hongxing2020 и MEGAsizeGPU също спекулираха съответно за края на варианта с 16 GB и за края на доставките на GB202 за RTX 5090. NVIDIA не е потвърдила нищо от това.", "zuverlaessigkeit_hinweis": "Форум на търговци Board Channels (Китай) плюс BenchLife; няколко източника, но без потвърждение от NVIDIA.", "ursprungsquelle": "Board Channels / BenchLife", "weitere_links": ["harukaze5719 в X", "hongxing2020 в X (10.10)", "MEGAsizeGPU в X (10.10)"], "_src": "60b93d53"}, "2026-10-29-windows11-kb5127936": {"titel": "Windows 11: незадължителната актуализация KB5127936 носи ново контекстно меню и преинсталиране от облака", "schlagzeile": "Windows 11: предварителна актуализация с ново контекстно меню и облачен ремонт", "kurz": "Microsoft пусна за Windows 11 25H2 и 26H2 незадължителната предварителна актуализация KB5127936 с 41 промени. Сред тях са по-бързо и персонализируемо контекстно меню във File Explorer и преинсталиране чрез Windows Update без USB флашка. Новостите трябва да стигнат до всички от Patch Tuesday на 10 ноември.", "zusammenfassung": "На 28 октомври Microsoft пусна незадължителната предварителна актуализация KB5127936 за Windows 11 25H2 и 26H2; тя не съдържа корекции за сигурност. Според BleepingComputer компилациите се повишават съответно до 26200.9818 и 26300.9818, с общо 41 промени и поправки. Контекстното меню във File Explorer трябва да се отваря по-бързо и да може да се персонализира. С „Cloud Rebuild“ Windows може да се преинсталира чрез Windows Update без USB флашка или ISO файл – дори ако системата вече не стартира. Режимът Xbox получава преработен изглед на задачите с лента за навигация, например за „Към работния плот“ и опциите за захранване. Страницата с настройки „Поверителност и защита“ групира камера, микрофон и местоположение, а средата за възстановяване WinRE може да използва запазени Wi-Fi профили. Хибернацията става адаптивна: над 80 процента батерия се включва по-рядко, под 10 процента – по-рано. Тъй като сертификатите на Secure Boot се обновяват, може да е нужно допълнително рестартиране. Актуализацията се инсталира през Настройки > Windows Update или от каталога на Microsoft Update. Microsoft пуска функциите постепенно, така че няма да се появят веднага на всеки компютър. Според Thurrott новостите трябва да стигнат до всички от Patch Tuesday на 10 ноември.", "weitere_links": ["Поддръжка на Microsoft: KB5127936 (компилации 26300.9818 и 26200.9818)", "Thurrott: предварителни актуализации от седмица D за Windows 11"], "_src": "b3b29ee6"}, "2026-10-29-gta6-edge-polizei": {"titel": "GTA 6: Rockstar показва полиция с K-9 отряд, автобуси по разписание и динамично време", "schlagzeile": "GTA 6: полиция с кучета следотърсачи, автобуси и влакове по разписание", "kurz": "В статия от корицата на британското списание Edge Rockstar разкри нови подробности за GTA 6. Полицията проследява играчите чрез камери, тракери в колите и сигнали от свидетели, а има и K-9 отряд. GTA 6 излиза на 19 ноември 2026 г. за PS5 и Xbox Series X|S.", "zusammenfassung": "Според Polygon Роб Нелсън, съръководител на студиото Rockstar North, е дал ексклузивно на британското списание Edge нови подробности за Grand Theft Auto VI. Полицията ще проследява играчите по последното им забелязване, камерите за наблюдение, тракери в колите и сигнали от минувачи. Новост е K-9 отряд: в показаното демо немска овчарка хваща Джейсън след катастрофа с мотор. Минувачите ще имат собствени черти на характера – едни бягат, други нападат. Автобусите и влаковете се движат по фиксирани маршрути по разписание; директорът по разработката Фил Хукър каза, че за него е най-важно винаги да пристигат навреме. Времето е динамично, като облаците се оформят от вятъра, влажността, мъглата, часа от денонощието и сезона. Самият Rockstar насочи вниманието в X към статията от корицата на брой 430 на Edge. Според Take-Two GTA 6 излиза на 19 ноември 2026 г. за PlayStation 5 и Xbox Series X|S. Standard Edition струва 79,99 долара в САЩ, а Ultimate Edition – 99,99 долара. Дигиталното предварително изтегляне и физическото издание са планирани от 12 ноември.", "weitere_links": ["Rockstar Games в X: насочване към статията от корицата на Edge (30.10.2026)", "Take-Two: предварителни поръчки, дата и цени на GTA VI"], "_src": "e7ef25df"}, "2026-10-28-galax-dementi": {"titel": "Слух опроверган: GALAX не напуска бизнеса с видеокарти", "schlagzeile": "Край на GALAX? Производителят казва ясно: не", "kurz": "Испански сайт съобщи „ексклузивно“, че GALAX напуска бизнеса с видеокарти. GALAX и партньорът Palit официално опровергаха това, а производството продължава нормално. За купувачите на карти KFA2, както се нарича GALAX в Европа, нищо не се променя.", "zusammenfassung": "Испанският сайт El Chapuzas Informático съобщи „ексклузивно“, че GALAX напуска пазара на GPU заради липса на чипове от NVIDIA и че Palit затваря съответната фабрика. GALAX опроверга това в официално изявление: нито един производствен обект не е затворен и работата продължава нормално. Palit, която дели фабрики с GALAX, също потвърди пред медиите, че производството продължава. Подобен слух се появи още през април във връзка с преструктуриране под централата на Palit в Тайван. Едва на 22 октомври GALAX представи RTX 5080 HOF Extreme. За купувачите на карти KFA2 – както се нарича GALAX в Европа – засега нищо не се променя по отношение на гаранцията или поддръжката. Случаят показва защо отбелязваме „ексклузивни“ единични съобщения без втори източник като непотвърдени.", "datum_hinweis": "Часът е приблизителен", "weitere_links": ["VideoCardz", "Tom's Hardware", "Първоначален слух (El Chapuzas Informático)"], "_src": "cf83f08b"}, "2026-10-25-ddr6-camm2": {"titel": "DDR6: 192-битови интерфейси на паметта и CAMM2 вместо класически DIMM модули", "schlagzeile": "DDR6 идва – и класическите RAM модули може да изчезнат", "kurz": "Според наличната информация DDR6 ще използва плоския формат CAMM2 вместо класическите DIMM модули, а настолните процесори ще получат 192-битов интерфейс на паметта. Споменават се скорости от 8800 до над 17 600 MT/s. Според пътна карта на SK Hynix обаче потребителите не бива да очакват DDR6 преди 2030 г.", "zusammenfassung": "3DCenter събра известното за предстоящия стандарт DDR6 и го допълни с актуализация на 25 октомври. DDR6 ще използва PAM4 сигнализация и ще работи с 24-битови чипове памет. Един модул ще се състои от четири 24-битови канала, а интерфейсите на паметта на процесорите растат на стъпки от 96 бита – при настолните компютри обикновено до 192 бита. Като формат е предвиден CAMM2 вместо днешните UDIMM и SO-DIMM модули. Споменават се скорости от 8800 до над 17 600 MT/s. Според пътна карта на SK Hynix DDR6 не се очаква преди 2029 г. в сървърите и преди 2030 г. за потребителите. Спецификацията на JEDEC още не е окончателна, обсъжда се и алтернативно предложение с 16-битови канали.", "datum_hinweis": "Дата на актуализацията; часът е приблизителен", "_src": "eef0b055"}, "2026-10-02-core-ultra-4000-lineup": {"titel": "Core Ultra 4000 „Nova Lake-S“: гамата начело с Core Ultra 9 4970K BFC", "schlagzeile": "Изтичане: 28-ядреният флагман на Intel с огромен кеш се цели в X3D на AMD", "kurz": "Изтекъл списък посочва седем настолни процесора от серията Core Ultra 4000, начело с Core Ultra 9 4970K с 28 ядра и голям кеш. Допълнителният кеш се смята за отговора на Intel на процесорите X3D на AMD. Intel не е потвърдил имена на модели, а подробностите може още да се променят.", "zusammenfassung": "В началото на октомври се появи списък със седем настолни процесора от предстоящата серия Core Ultra 4000. Начело трябва да е Core Ultra 9 4970K „BFC“ с 28 ядра, голям кеш от последно ниво (bLLC) и базова мощност 125 W, подреден дори над 4950K. bLLC се смята за отговора на Intel на процесорите X3D на AMD с 3D V-Cache. Известният източник на изтичания kopite7kimi коментира съобщението на 13 октомври: големият кеш трябва да спаси производителността на Nova Lake в игрите, защото обикновените модели без bLLC са в игрите приблизително толкова бързи, колкото Arrow Lake. Самият Intel досега не е посочил модели – официално са известни само процесът 18A-P и представяне на CES. Имената на моделите, броят ядра и стойностите на TDP може още да се променят до пускането.", "zuverlaessigkeit_hinweis": "Изтичане за гамата, коментирано от kopite7kimi (висока надеждност); не е потвърдено от Intel.", "weitere_links": ["kopite7kimi в X (13.10)"], "_src": "53d234c7"}, "2026-09-21-kopite-gr20x-2028": {"titel": "kopite7kimi: поколението GR20x на NVIDIA чак през 2028 г.", "schlagzeile": "Изтичане: следващите геймърски GPU на NVIDIA вероятно чак през 2028 г.", "kurz": "Известният източник на изтичания kopite7kimi пише, че чиповете GR20x на NVIDIA са продукт за 2028 г. – тоест следващото поколение се отлага. За 2027 г. тогава по-вероятни биха били обновени версии на серията RTX 50. NVIDIA не е потвърдила този график.", "zusammenfassung": "Известният източник на изтичания за NVIDIA kopite7kimi пише в X, че чиповете GR20x са продукт за 2028 г. – тоест NVIDIA отново е отложила. Според общоприетото тълкуване става дума за геймърското поколение след Blackwell, което вероятно ще носи името на архитектурата за центрове за данни на NVIDIA „Rubin“. Той освен това обяви, че ще публикува по-малко актуализации, докато няма сигурни новини, позовавайки се на „lessons learned“ (научени уроци) – очевидно реакция на променени планове при по-ранни изтичания. Нашата оценка: за 2027 г. тогава по-вероятни биха били обновени версии на серията RTX 50, например с повече памет като споменатата RTX 5080 24GB. Самата NVIDIA не е потвърдила нищо за този график. Дори при надеждни източници датите се местят по-често от техническите данни.", "zuverlaessigkeit_hinweis": "kopite7kimi има дълга история с изтичания за NVIDIA; данните за срокове обаче са по-несигурни от техническите подробности.", "ursprungsquelle": "kopite7kimi", "_src": "89b4f8c9"}};
